pub enum CleanExecutionResourceKind {
    HostService,
    PersistentContainer,
    DependencyIsolationVolume,
    StaleContainers,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CleanExecutionFailureReason {
    EngineUnavailable,
    Other,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CleanExecutionFailure {
    pub engine: String,
    pub action: String,
    pub resource_kind: CleanExecutionResourceKind,
    pub resource_name: Option<String>,
    pub reason: CleanExecutionFailureReason,
    pub details: String,
}

#[derive(Debug, thiserror::Error)]
pub enum CleanExecutionError {
    #[error("{0}")]
    Cleanup(CleanExecutionFailure),
    #[error("{0}")]
    Other(RunError),
}

impl std::fmt::Display for CleanExecutionFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match (&self.resource_kind, self.resource_name.as_deref()) {
            (CleanExecutionResourceKind::HostService, Some(name)) => write!(
                f,
                "task `clean` could not {} host-managed service `{}`: {}",
                self.action, name, self.details
            ),
            (CleanExecutionResourceKind::PersistentContainer, Some(name)) => write!(
                f,
                "task `clean` could not {} persistent container `{}` using container engine `{}`: {}",
                self.action, name, self.engine, self.details
            ),
            (CleanExecutionResourceKind::DependencyIsolationVolume, Some(name)) => write!(
                f,
                "task `clean` could not {} dependency-isolation volume `{}` using container engine `{}`: {}",
                self.action, name, self.engine, self.details
            ),
            (CleanExecutionResourceKind::StaleContainers, _) => write!(
                f,
                "container backend `{}` could not {} stale ota containers: {}",
                self.engine, self.action, self.details
            ),
            _ => write!(
                f,
                "task `clean` could not {} repo state using container engine `{}`: {}",
                self.action, self.engine, self.details
            ),
        }
    }
}

#[derive(Debug, Default, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CleanExecutionReport {
    pub stopped_host_services: usize,
    pub removed_current_persistent_containers: usize,
    pub removed_drift_persistent_containers: usize,
    pub removed_drift_attached_containers: usize,
    pub removed_current_dependency_isolation_volumes: usize,
    pub removed_drift_dependency_isolation_volumes: usize,
    pub skipped_ambiguous_persistent_containers: usize,
    pub skipped_ambiguous_dependency_isolation_volumes: usize,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub host_services: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub queried_engines: Vec<String>,
}

impl CleanExecutionReport {
    pub fn cleaned_any(&self) -> bool {
        self.total_removed() > 0
    }

    pub fn total_removed(&self) -> usize {
        self.stopped_host_services
            + self.removed_current_persistent_containers
            + self.removed_drift_persistent_containers
            + self.removed_drift_attached_containers
            + self.removed_current_dependency_isolation_volumes
            + self.removed_drift_dependency_isolation_volumes
    }

    pub fn total_skipped_ambiguous(&self) -> usize {
        self.skipped_ambiguous_persistent_containers
            + self.skipped_ambiguous_dependency_isolation_volumes
    }
}

