fn format_repo_execution_lock_timestamp(now: OffsetDateTime) -> String {
    now.format(&format_description!(
        "[year]-[month]-[day]T[hour]:[minute]:[second]Z"
    ))
    .unwrap_or_else(|_| now.unix_timestamp().to_string())
}

fn repo_execution_lock_owner_for_backend(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
    backend: &ResolvedExecutionBackend,
) -> RepoExecutionLockOwner {
    let backend_kind = resolved_execution_backend_kind(backend);
    let persistent_backend_families = persistent_backend_family_ownership(task_name, backend);
    let compose_projects = contract
        .tasks
        .get(task_name)
        .and_then(|task| task.compose_adapter_project_name_for_backend(backend_kind))
        .map(|value| vec![value.to_string()])
        .unwrap_or_default();
    let env_materialization_paths = contract
        .tasks
        .get(task_name)
        .map(task_env_materialization_ownership)
        .unwrap_or_default();
    let lifecycle = match backend {
        ResolvedExecutionBackend::Native {
            shared_local_backend: Some(shared_local_backend),
        } => Some(format_lifecycle(shared_local_backend.lifecycle).to_string()),
        ResolvedExecutionBackend::Container { lifecycle, .. } => {
            Some(format_lifecycle(*lifecycle).to_string())
        }
        _ => None,
    };
    RepoExecutionLockOwner {
        task: task_name.to_string(),
        requested_mode: overrides
            .backend
            .map(|backend| format_backend(backend).to_string()),
        execution_mode: format_backend(resolved_execution_backend_kind(backend)).to_string(),
        lifecycle,
        host_services: required_service_closure(
            contract,
            &contract
                .tasks
                .get(task_name)
                .map(|task| task.requires_services.clone())
                .unwrap_or_default(),
        )
        .into_iter()
        .filter(|service_name| {
            contract
                .services
                .get(service_name.as_str())
                .and_then(|service| service.manager.as_ref())
                .is_some_and(|manager| manager.kind == crate::schema::ServiceManagerKind::Host)
        })
        .collect(),
        compose_projects,
        persistent_backend_families,
        env_materialization_paths,
        service_task: contract
            .tasks
            .get(task_name)
            .and_then(|task| task.service_runtime_for_backend(backend_kind))
            .is_some(),
        pid: std::process::id(),
        started_at: format_repo_execution_lock_timestamp(OffsetDateTime::now_utc()),
    }
}

fn persistent_backend_family_ownership(
    task_name: &str,
    backend: &ResolvedExecutionBackend,
) -> Vec<String> {
    match backend {
        ResolvedExecutionBackend::Container {
            context_name,
            shared_local_backend,
            lifecycle,
            ..
        } if *lifecycle == Lifecycle::Persistent => vec![persistent_container_family_token(
            task_name,
            context_name.as_deref(),
            shared_local_backend
                .as_ref()
                .map(|shared| shared.name.as_str()),
        )],
        ResolvedExecutionBackend::Native {
            shared_local_backend: Some(shared_local_backend),
        }
        | ResolvedExecutionBackend::Remote {
            shared_local_backend: Some(shared_local_backend),
            ..
        }
        | ResolvedExecutionBackend::BackendProvider {
            shared_local_backend: Some(shared_local_backend),
            ..
        } if shared_local_backend.lifecycle == Lifecycle::Persistent => {
            vec![persistent_container_family_token(
                task_name,
                shared_local_backend.context_name.as_deref(),
                Some(shared_local_backend.name.as_str()),
            )]
        }
        _ => Vec::new(),
    }
}

fn task_env_materialization_ownership(task: &TaskSpec) -> Vec<String> {
    let mut paths = task.projected_env_materialization_paths.clone();
    if let Some(action) = task.action.as_ref() {
        collect_action_env_materialization_paths(action, &mut paths);
    }
    paths
}

fn collect_action_env_materialization_paths(
    action: &crate::schema::TaskActionSpec,
    paths: &mut Vec<String>,
) {
    match action {
        crate::schema::TaskActionSpec::EnsureEnvFile(spec) => {
            push_unique_owned_path(paths, spec.path.as_str());
        }
        crate::schema::TaskActionSpec::EnsureBundle(spec) => {
            for step in &spec.steps {
                if let crate::schema::TaskEnsureBundleStepSpec::EnsureEnvFile(step_spec) = step {
                    push_unique_owned_path(paths, step_spec.path.as_str());
                }
            }
        }
        _ => {}
    }
}

fn push_unique_owned_path(paths: &mut Vec<String>, value: &str) {
    let trimmed = value.trim();
    if trimmed.is_empty() || paths.iter().any(|existing| existing == trimmed) {
        return;
    }
    paths.push(trimmed.to_string());
}

fn clean_engine_timeout_cache() -> &'static Mutex<BTreeMap<String, String>> {
    CLEAN_ENGINE_TIMEOUT_CACHE.get_or_init(|| Mutex::new(BTreeMap::new()))
}

pub fn plan_task_execution(contract: &Contract, task_name: &str) -> Result<RunPlan, RunError> {
    plan_task_execution_with_overrides(contract, task_name, ExecutionOverrides::default())
}

pub fn plan_task_execution_with_overrides(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> Result<RunPlan, RunError> {
    if !contract.tasks.contains_key(task_name) {
        return Err(RunError::UnknownTask {
            task: task_name.to_string(),
        });
    }

    let mut ordered = Vec::new();
    let mut steps = Vec::new();
    let mut visited = BTreeSet::new();
    visit_task_with_overrides(
        contract,
        task_name,
        overrides,
        overrides.backend.is_some(),
        None,
        None,
        &mut visited,
        &mut ordered,
        &mut steps,
    );

    Ok(RunPlan {
        tasks: ordered,
        steps,
    })
}

pub fn resolve_task_env(
    contract: &Contract,
    contract_path: &Path,
    task_env: Option<&BTreeMap<String, String>>,
) -> Result<BTreeMap<String, String>, RunError> {
    let resolved = resolve_task_env_details_with_policy(contract, contract_path, task_env, None)?;
    let mut overrides = BTreeMap::new();

    for (name, resolved) in resolved {
        if matches!(
            resolved.source,
            EnvResolutionSource::Default
                | EnvResolutionSource::Policy(_)
                | EnvResolutionSource::Task
                | EnvResolutionSource::Source(_)
        ) {
            overrides.insert(name, resolved.value);
        }
    }

    Ok(overrides)
}

fn host_uid_template_value(working_dir: &Path) -> Option<String> {
    #[cfg(unix)]
    {
        fs::metadata(working_dir)
            .ok()
            .map(|metadata| metadata.uid().to_string())
    }
    #[cfg(not(unix))]
    {
        let _ = working_dir;
        None
    }
}

fn host_home_template_value() -> Option<String> {
    #[cfg(windows)]
    {
        env::var("USERPROFILE").ok().filter(|value| !value.trim().is_empty())
    }
    #[cfg(not(windows))]
    {
        env::var("HOME").ok().filter(|value| !value.trim().is_empty())
    }
}

fn expand_task_env_templates(
    value: &str,
    ota_workspace: &str,
    host_workspace: &str,
    host_home: Option<&str>,
    host_uid: Option<&str>,
) -> String {
    let mut expanded = value
        .replace("${OTA_WORKSPACE}", ota_workspace)
        .replace("$OTA_WORKSPACE", ota_workspace)
        .replace("${OTA_HOST_WORKSPACE}", host_workspace)
        .replace("$OTA_HOST_WORKSPACE", host_workspace);
    let host_home = host_home.unwrap_or("");
    expanded = expanded
        .replace("${OTA_HOST_HOME}", host_home)
        .replace("$OTA_HOST_HOME", host_home);
    let host_uid = host_uid.unwrap_or("");
    expanded = expanded
        .replace("${OTA_HOST_UID}", host_uid)
        .replace("$OTA_HOST_UID", host_uid);
    expanded
}

fn url_component_encode(value: &str) -> String {
    let mut encoded = String::new();
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                encoded.push(byte as char);
            }
            _ => encoded.push_str(&format!("%{byte:02X}")),
        }
    }
    encoded
}

fn service_endpoint_address_for_task_env(
    address: &str,
    endpoint_view: &str,
    backend: Backend,
    engine_hint: Option<&str>,
) -> String {
    if backend != Backend::Container
        || endpoint_view != "host"
        || !is_loopback_only_host_address(address)
    {
        return address.to_string();
    }

    match engine_hint.unwrap_or("docker") {
        "podman" => String::from("host.containers.internal"),
        _ => String::from("host.docker.internal"),
    }
}

fn render_service_env_binding_url(
    binding: &TaskServiceEnvBindingSpec,
    address: &str,
    port: u16,
    password_env_values: Option<&BTreeMap<String, ResolvedEnvValue>>,
) -> String {
    match binding.format.unwrap_or(TaskServiceEnvBindingFormat::Url) {
        TaskServiceEnvBindingFormat::Host => return address.to_string(),
        TaskServiceEnvBindingFormat::Port => return port.to_string(),
        TaskServiceEnvBindingFormat::HostPort => return format!("{address}:{port}"),
        TaskServiceEnvBindingFormat::Url => {}
    }

    let host_port = format!("{address}:{port}");
    let Some(scheme) = binding
        .scheme
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return host_port;
    };

    let auth = binding
        .username
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|username| {
            let username = url_component_encode(username);
            let password = service_env_binding_password(binding, password_env_values)
                .map(|password| format!(":{}", url_component_encode(password.as_str())))
                .unwrap_or_default();
            format!("{username}{password}@")
        })
        .unwrap_or_default();
    let path = binding
        .database
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(url_component_encode)
        .map(|database| format!("/{database}"))
        .unwrap_or_default();

    format!("{scheme}://{auth}{host_port}{path}")
}

fn service_env_binding_password(
    binding: &TaskServiceEnvBindingSpec,
    password_env_values: Option<&BTreeMap<String, ResolvedEnvValue>>,
) -> Option<String> {
    binding
        .password
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .or_else(|| {
            let password_env = binding
                .password_env
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())?;
            password_env_values
                .and_then(|values| values.get(password_env))
                .map(|resolved| resolved.value.clone())
                .or_else(|| std::env::var(password_env).ok())
        })
}

fn service_env_bindings_for_task(
    contract: &Contract,
    task: &TaskSpec,
    backend: Backend,
    context_name: Option<&str>,
    engine_hint: Option<&str>,
    password_env_values: Option<&BTreeMap<String, ResolvedEnvValue>>,
) -> BTreeMap<String, String> {
    task.env_bindings_for_backend_with_context_name(
        contract.execution.as_ref(),
        backend,
        context_name,
    )
    .into_iter()
    .filter_map(|(name, binding)| {
        let service_name = binding.from_service.service.trim();
        let service = contract.services.get(service_name)?;
        let requested_view = binding
            .from_service
            .view
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .or(context_name)
            .unwrap_or("host");
        let selected_endpoint = binding
            .from_service
            .endpoint
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .and_then(|endpoint_name| {
                service
                    .endpoint_named(endpoint_name)
                    .map(|endpoint| (endpoint_name, endpoint))
            });
        let (endpoint_view, endpoint) = selected_endpoint
            .map(|(endpoint_name, endpoint)| (endpoint.context_name(endpoint_name), endpoint))
            .or_else(|| {
                service
                    .endpoint_for_context(requested_view)
                    .map(|endpoint| (requested_view, endpoint))
            })
            .or_else(|| {
                service
                    .endpoint_for_context("host")
                    .map(|endpoint| ("host", endpoint))
            })?;
        let address = service_endpoint_address_for_task_env(
            endpoint.address.as_str(),
            endpoint_view,
            backend,
            engine_hint,
        );
        Some((
            name,
            render_service_env_binding_url(
                &binding.from_service,
                address.as_str(),
                endpoint.port,
                password_env_values,
            ),
        ))
    })
    .collect()
}

fn ota_workspace_for_backend(working_dir: &Path, backend: &ResolvedExecutionBackend) -> String {
    match backend {
        ResolvedExecutionBackend::Native { .. } => working_dir.display().to_string(),
        ResolvedExecutionBackend::Container { .. } => String::from("/workspace"),
        ResolvedExecutionBackend::Remote { cwd, .. }
        | ResolvedExecutionBackend::BackendProvider { cwd, .. } => {
            cwd.clone().unwrap_or_else(|| String::from("."))
        }
    }
}

fn derived_attachment_env_for_backend(
    backend: &ResolvedExecutionBackend,
    ota_workspace: &str,
) -> BTreeMap<String, String> {
    let ResolvedExecutionBackend::Container {
        dependency_isolation_paths,
        ..
    } = backend
    else {
        return BTreeMap::new();
    };

    derived_attachment_env_for_isolation_paths(dependency_isolation_paths, ota_workspace)
}

fn derived_attachment_env_for_isolation_paths(
    dependency_isolation_paths: &[String],
    ota_workspace: &str,
) -> BTreeMap<String, String> {
    let mut derived = BTreeMap::new();
    for path in dependency_isolation_paths {
        match path.as_str() {
            ".m2" => {
                derived.insert(
                    String::from("MAVEN_OPTS"),
                    format!("-Dmaven.repo.local={ota_workspace}/.m2/repository"),
                );
            }
            ".npm" => {
                derived.insert(
                    String::from("NPM_CONFIG_CACHE"),
                    format!("{ota_workspace}/.npm"),
                );
            }
            ".pnpm-store" => {
                derived.insert(
                    String::from("PNPM_STORE_DIR"),
                    format!("{ota_workspace}/.pnpm-store"),
                );
            }
            ".gradle" => {
                derived.insert(
                    String::from("GRADLE_USER_HOME"),
                    format!("{ota_workspace}/.gradle"),
                );
            }
            ".pip-cache" => {
                derived.insert(
                    String::from("PIP_CACHE_DIR"),
                    format!("{ota_workspace}/.pip-cache"),
                );
            }
            ".pypoetry-cache" => {
                derived.insert(
                    String::from("POETRY_CACHE_DIR"),
                    format!("{ota_workspace}/.pypoetry-cache"),
                );
            }
            _ => {}
        }
    }
    derived
}

fn resolved_backend_context_name(backend: &ResolvedExecutionBackend) -> Option<&str> {
    match backend {
        ResolvedExecutionBackend::Native {
            shared_local_backend,
        } => shared_local_backend
            .as_ref()
            .and_then(|shared| shared.context_name.as_deref()),
        ResolvedExecutionBackend::Container { context_name, .. } => context_name.as_deref(),
        ResolvedExecutionBackend::Remote {
            shared_local_backend,
            ..
        }
        | ResolvedExecutionBackend::BackendProvider {
            shared_local_backend,
            ..
        } => shared_local_backend
            .as_ref()
            .and_then(|shared| shared.context_name.as_deref()),
    }
}

pub(crate) fn effective_task_env_for_backend(
    contract: &Contract,
    task: &TaskSpec,
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
) -> BTreeMap<String, String> {
    effective_task_env_for_backend_with_resolved_env(contract, task, backend, working_dir, None)
}

fn effective_task_env_for_backend_with_resolved_env(
    contract: &Contract,
    task: &TaskSpec,
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
    password_env_values: Option<&BTreeMap<String, ResolvedEnvValue>>,
) -> BTreeMap<String, String> {
    let ota_workspace = ota_workspace_for_backend(working_dir, backend);
    let host_workspace = host_workspace_template_value(working_dir);
    let host_home = host_home_template_value();
    let host_uid = host_uid_template_value(working_dir);
    let backend_kind = resolved_execution_backend_kind(backend);
    let engine_hint = match backend {
        ResolvedExecutionBackend::Container { engine, .. } => Some(engine.as_str()),
        _ => None,
    };
    let context_name = resolved_backend_context_name(backend);
    let mut env = derived_attachment_env_for_backend(backend, ota_workspace.as_str());
    env.extend(load_task_env_file_values(task, backend_kind, working_dir));
    env.extend(
        task.env_for_backend_with_context_name(
            contract.execution.as_ref(),
            backend_kind,
            context_name,
        )
        .into_iter()
        .map(|(name, value)| {
            (
                name,
                expand_task_env_templates(
                    &value,
                    ota_workspace.as_str(),
                    host_workspace.as_str(),
                    host_home.as_deref(),
                    host_uid.as_deref(),
                ),
            )
        }),
    );
    env.extend(task_adapter_env_bindings(task, backend_kind));
    env.extend(service_env_bindings_for_task(
        contract,
        task,
        backend_kind,
        context_name,
        engine_hint,
        password_env_values,
    ));
    env.insert(String::from("OTA_WORKSPACE"), ota_workspace);
    env.insert(String::from("OTA_HOST_WORKSPACE"), host_workspace);
    if let Some(host_home) = host_home {
        env.insert(String::from("OTA_HOST_HOME"), host_home);
    }
    if let Some(host_uid) = host_uid {
        env.insert(String::from("OTA_HOST_UID"), host_uid);
    }
    env
}

pub(crate) fn effective_task_env_for_selection(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
    working_dir: &Path,
) -> Option<BTreeMap<String, String>> {
    let task = contract.tasks.get(task_name)?;
    let effective = effective_task_execution(contract, task_name, overrides);
    let backend = effective.backend;
    let shared_context_name = resolve_task_shared_local_backend(contract, task_name, backend)
        .ok()
        .flatten()
        .and_then(|shared| shared.context_name);
    let context_name = shared_context_name
        .as_deref()
        .or_else(|| task.context_for_backend(contract.execution.as_ref(), backend));
    let ota_workspace = match backend {
        Backend::Native => working_dir.display().to_string(),
        Backend::Container => String::from("/workspace"),
        Backend::Remote => effective
            .remote
            .and_then(|remote| remote.cwd.clone())
            .unwrap_or_else(|| String::from(".")),
    };
    let dependency_isolation_paths = if backend == Backend::Container {
        context_name
            .and_then(|name| {
                contract
                    .execution
                    .as_ref()
                    .and_then(|execution| execution.contexts.get(name))
            })
            .map(context_dependency_isolation_paths)
            .unwrap_or_default()
    } else {
        Vec::new()
    };
    let mut env = derived_attachment_env_for_isolation_paths(
        &dependency_isolation_paths,
        ota_workspace.as_str(),
    );
    let host_workspace = host_workspace_template_value(working_dir);
    let host_home = host_home_template_value();
    let host_uid = host_uid_template_value(working_dir);
    env.extend(load_task_env_file_values(task, backend, working_dir));
    let engine_hint = if backend == Backend::Container {
        effective_task_container_backend_for_target_resolution(contract, task_name, overrides)
            .and_then(|container| {
                container_engine_candidates_from_backend(Some(container))
                    .into_iter()
                    .next()
            })
    } else {
        None
    };
    env.extend(
        task.env_for_backend_with_context_name(contract.execution.as_ref(), backend, context_name)
            .into_iter()
            .map(|(name, value)| {
                (
                    name,
                    expand_task_env_templates(
                        &value,
                        ota_workspace.as_str(),
                        host_workspace.as_str(),
                        host_home.as_deref(),
                        host_uid.as_deref(),
                    ),
                )
            }),
    );
    env.extend(task_adapter_env_bindings(task, backend));
    env.extend(service_env_bindings_for_task(
        contract,
        task,
        backend,
        context_name,
        engine_hint.as_deref(),
        None,
    ));
    env.insert(String::from("OTA_WORKSPACE"), ota_workspace);
    env.insert(String::from("OTA_HOST_WORKSPACE"), host_workspace);
    if let Some(host_home) = host_home {
        env.insert(String::from("OTA_HOST_HOME"), host_home);
    }
    if let Some(host_uid) = host_uid {
        env.insert(String::from("OTA_HOST_UID"), host_uid);
    }
    Some(env)
}

fn load_task_env_file_values(
    task: &TaskSpec,
    backend: Backend,
    working_dir: &Path,
) -> BTreeMap<String, String> {
    let mut merged = BTreeMap::new();
    for path in task.env_files_for_backend(backend) {
        let trimmed = path.trim();
        if trimmed.is_empty() {
            continue;
        }
        let source_path = working_dir.join(trimmed);
        let file = match File::open(&source_path) {
            Ok(file) => file,
            Err(_) => continue,
        };
        let mut values = BTreeMap::new();
        for entry in dotenvy::from_read_iter(file) {
            match entry {
                Ok((name, value)) => {
                    values.insert(name, value);
                }
                Err(_) => return BTreeMap::new(),
            }
        }
        merged.extend(values);
    }
    merged
}

pub(crate) fn ensure_task_env_files_ready(
    task_name: &str,
    task: &TaskSpec,
    backend: Backend,
    working_dir: &Path,
) -> Result<(), RunError> {
    for path in task.env_files_for_backend(backend) {
        let trimmed = path.trim();
        if trimmed.is_empty() {
            continue;
        }
        let source_path = working_dir.join(trimmed);
        let file = File::open(&source_path).map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "env file `{trimmed}` declared in `env_files` is not readable: {source}"
            ),
        })?;
        for entry in dotenvy::from_read_iter(file) {
            entry.map_err(|source| RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "env file `{trimmed}` declared in `env_files` is not valid dotenv content: {source}"
                ),
            })?;
        }
    }
    Ok(())
}

pub(crate) fn ensure_task_adapter_inputs_ready(
    _task_name: &str,
    task: &TaskSpec,
    backend: Backend,
    working_dir: &Path,
) -> Result<(), RunError> {
    for field in ADAPTER_INPUT_FIELDS {
        let Some(kind) = field.runtime_file_kind() else {
            continue;
        };
        let label = field
            .runtime_file_label()
            .expect("file-backed adapter-input field should have a runtime label");
        let location = field.task_location(_task_name);
        for path in field.backend_paths(task, backend) {
            let trimmed = path.trim();
            if trimmed.is_empty() {
                continue;
            }
            let full_path = working_dir.join(trimmed);
            fs::metadata(&full_path).map_err(|source| RunError::InvalidEnvSource {
                kind: kind.to_string(),
                path: trimmed.to_string(),
                details: format!(
                    "{label} `{trimmed}` declared in `{location}` is not readable: {source}"
                ),
            })?;
        }
    }
    Ok(())
}

fn effective_task_execution_working_dir(
    task: &TaskSpec,
    backend: Backend,
    working_dir: &Path,
) -> PathBuf {
    task_effective_adapter_cwd(task, backend)
        .map(|cwd| working_dir.join(cwd))
        .unwrap_or_else(|| working_dir.to_path_buf())
}

fn apply_prepared_execution_cwd(working_dir: PathBuf, cwd: Option<&str>) -> PathBuf {
    cwd.map(str::trim)
        .filter(|cwd| !cwd.is_empty())
        .map(|cwd| working_dir.join(cwd))
        .unwrap_or(working_dir)
}

fn projected_structured_command_for_task(
    task: &TaskSpec,
    backend: Backend,
    command: &crate::schema::TaskCommandSpec,
) -> crate::schema::TaskCommandSpec {
    if !command.exe.trim().eq_ignore_ascii_case("helm") {
        return command.clone();
    }
    project_helm_adapter_inputs(task, backend, command)
}

fn projected_compose_command_for_task(
    task: &TaskSpec,
    backend: Backend,
    compose: &crate::schema::TaskComposeExecutionSpec,
) -> crate::schema::TaskCommandSpec {
    projected_compose_invocation_command_for_task(
        task,
        backend,
        &compose.invocation,
        compose.exe.as_str(),
        compose.args.as_slice(),
    )
}

fn projected_compose_invocation_command_for_task(
    task: &TaskSpec,
    backend: Backend,
    compose: &crate::schema::TaskComposeInvocationSpec,
    exe: &str,
    args: &[String],
) -> crate::schema::TaskCommandSpec {
    let mut projected_args = vec![String::from("compose"), String::from(compose.kind.label())];
    if compose.detach {
        projected_args.push(String::from("-d"));
    }
    if !compose.tty {
        projected_args.push(String::from("-T"));
    }
    if compose.rm {
        projected_args.push(String::from("--rm"));
    }
    if let Some(workdir) = compose
        .workdir
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        projected_args.push(String::from("-w"));
        projected_args.push(workdir.to_string());
    }
    projected_args.push(compose.service.trim().to_string());
    projected_args.push(exe.trim().to_string());
    projected_args.extend(args.iter().cloned());
    crate::schema::TaskCommandSpec {
        exe: compose.engine.as_str().to_string(),
        args: projected_args,
        cwd: task.compose_adapter_cwd_for_backend(backend),
    }
}

fn compose_wrapped_hydration_workdir(
    compose: &crate::schema::TaskComposeInvocationSpec,
    source_cwd: &str,
) -> Option<String> {
    let source_cwd = source_cwd.trim();
    let source_cwd = if source_cwd.is_empty() {
        "."
    } else {
        source_cwd
    };
    let base = compose.workdir.as_deref().map(str::trim).unwrap_or("");

    match (base.is_empty(), source_cwd == ".") {
        (true, true) => None,
        (true, false) => Some(source_cwd.to_string()),
        (false, true) => Some(base.to_string()),
        (false, false) => Some(format!(
            "{}/{}",
            base.trim_end_matches('/'),
            source_cwd.trim_start_matches("./").trim_start_matches('/')
        )),
    }
}

fn dependency_hydration_command_specs(
    source: &crate::schema::TaskDependencyHydrationSourceSpec,
) -> Vec<crate::schema::TaskCommandSpec> {
    match source {
        crate::schema::TaskDependencyHydrationSourceSpec::DockerCompose(source) => {
            vec![crate::schema::TaskCommandSpec {
                exe: source.engine.as_str().to_string(),
                args: Vec::new(),
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::NodePackageManager(source) => {
            let mut args = vec![source.mode.label().to_string()];
            if let Some(flag) = source.lockfile_flag() {
                args.push(String::from(flag));
            }
            if let Some(flag) = source.inline_builds_flag() {
                args.push(String::from(flag));
            }
            if let Some(flag) = source.force_flag() {
                args.push(String::from(flag));
            }
            vec![crate::schema::TaskCommandSpec {
                exe: source.manager.label().to_string(),
                args,
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::Bundler(source) => vec![
            crate::schema::TaskCommandSpec {
                exe: String::from("bundle"),
                args: vec![
                    String::from("config"),
                    String::from("set"),
                    String::from("path"),
                    source.path.clone(),
                ],
                cwd: Some(source.cwd.clone()),
            },
            crate::schema::TaskCommandSpec {
                exe: String::from("bundle"),
                args: vec![String::from("install")],
                cwd: Some(source.cwd.clone()),
            },
        ],
        crate::schema::TaskDependencyHydrationSourceSpec::Uv(source) => {
            vec![crate::schema::TaskCommandSpec {
                exe: String::from("uv"),
                args: vec![String::from("sync")],
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::Poetry(source) => {
            let mut args = vec![String::from("install")];
            if !source.groups.is_empty() {
                args.push(source.group_mode.flag().to_string());
                args.push(source.groups.join(","));
            }
            if source.no_root {
                args.push(String::from("--no-root"));
            }
            vec![crate::schema::TaskCommandSpec {
                exe: String::from("poetry"),
                args,
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::GoModules(source) => {
            vec![crate::schema::TaskCommandSpec {
                exe: String::from("go"),
                args: vec![String::from("mod"), String::from("download")],
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::Helm(source) => {
            vec![crate::schema::TaskCommandSpec {
                exe: String::from("helm"),
                args: vec![
                    String::from("dependency"),
                    String::from("build"),
                    String::from("."),
                ],
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::Maven(source) => {
            let mut args = vec![String::from("-q")];
            if source.skip_tests {
                args.push(String::from("-DskipTests"));
            }
            args.push(source.mode.goal().to_string());
            vec![crate::schema::TaskCommandSpec {
                exe: if source.wrapper {
                    String::from("./mvnw")
                } else {
                    String::from("mvn")
                },
                args,
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::Gradle(source) => {
            vec![crate::schema::TaskCommandSpec {
                exe: if source.wrapper {
                    String::from("./gradlew")
                } else {
                    String::from("gradle")
                },
                args: vec![String::from("dependencies")],
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::Cargo(source) => {
            vec![crate::schema::TaskCommandSpec {
                exe: String::from("cargo"),
                args: vec![String::from("fetch")],
                cwd: Some(source.cwd.clone()),
            }]
        }
        crate::schema::TaskDependencyHydrationSourceSpec::DotnetRestore(source) => {
            vec![crate::schema::TaskCommandSpec {
                exe: String::from("dotnet"),
                args: vec![String::from("restore")],
                cwd: Some(source.cwd.clone()),
            }]
        }
    }
}

fn compose_wrapped_dependency_hydration_commands(
    task: &TaskSpec,
    backend: Backend,
    source: &crate::schema::TaskDependencyHydrationSourceSpec,
    compose: &crate::schema::TaskComposeInvocationSpec,
) -> Vec<crate::schema::TaskCommandSpec> {
    dependency_hydration_command_specs(source)
        .into_iter()
        .map(|base| {
            let mut compose_invocation = compose.clone();
            compose_invocation.workdir =
                compose_wrapped_hydration_workdir(compose, base.cwd.as_deref().unwrap_or("."));
            projected_compose_invocation_command_for_task(
                task,
                backend,
                &compose_invocation,
                base.exe.as_str(),
                base.args.as_slice(),
            )
        })
        .collect()
}

fn project_helm_adapter_inputs(
    task: &TaskSpec,
    backend: Backend,
    command: &crate::schema::TaskCommandSpec,
) -> crate::schema::TaskCommandSpec {
    let subcommand = helm_subcommand(command.args.as_slice());
    let Some(subcommand) = subcommand else {
        return command.clone();
    };
    let adapter_cwd = task.helm_adapter_cwd_for_backend(backend);
    let values_files = rebase_repo_relative_adapter_paths(
        &task.helm_adapter_values_files_for_backend(backend),
        adapter_cwd.clone(),
    );
    let chart = task
        .helm_adapter_chart_for_backend(backend)
        .map(|value| rebase_repo_relative_adapter_paths(&[value], adapter_cwd.clone()))
        .and_then(|values| values.into_iter().next());
    let release_name = task.helm_adapter_release_name_for_backend(backend);
    let namespace = task.helm_adapter_namespace_for_backend(backend);
    if values_files.is_empty() && chart.is_none() && release_name.is_none() && namespace.is_none() {
        return command.clone();
    }

    let mut projected = command.clone();
    if let Some(namespace) = namespace
        && !helm_has_flag(projected.args.as_slice(), &["-n", "--namespace"])
    {
        projected
            .args
            .extend([String::from("--namespace"), namespace]);
    }
    if !values_files.is_empty() && !helm_has_flag(projected.args.as_slice(), &["-f", "--values"]) {
        for path in values_files {
            projected.args.push(String::from("-f"));
            projected.args.push(path);
        }
    }
    match subcommand {
        HelmProjectedSubcommand::Lint | HelmProjectedSubcommand::DependencyBuild => {
            let prefix_len = match subcommand {
                HelmProjectedSubcommand::DependencyBuild => 2,
                _ => 1,
            };
            if let Some(chart) = chart
                && !helm_has_positional_after_prefix(projected.args.as_slice(), prefix_len, 1)
            {
                projected.args.push(chart);
            }
        }
        HelmProjectedSubcommand::Template => {
            if let Some(release_name) = release_name
                && !helm_has_positional_after_prefix(projected.args.as_slice(), 1, 1)
            {
                projected.args.push(release_name);
            }
            if let Some(chart) = chart
                && !helm_has_positional_after_prefix(projected.args.as_slice(), 1, 2)
            {
                projected.args.push(chart);
            }
        }
        HelmProjectedSubcommand::Install | HelmProjectedSubcommand::Upgrade => {
            if let Some(release_name) = release_name
                && !helm_has_positional_after_prefix(projected.args.as_slice(), 1, 1)
            {
                projected.args.push(release_name);
            }
            if let Some(chart) = chart
                && !helm_has_positional_after_prefix(projected.args.as_slice(), 1, 2)
            {
                projected.args.push(chart);
            }
        }
        HelmProjectedSubcommand::Uninstall => {
            if let Some(release_name) = release_name
                && !helm_has_positional_after_prefix(projected.args.as_slice(), 1, 1)
            {
                projected.args.push(release_name);
            }
        }
    }
    projected
}

#[derive(Clone, Copy)]
enum HelmProjectedSubcommand {
    Lint,
    Template,
    Install,
    Upgrade,
    Uninstall,
    DependencyBuild,
}

fn helm_subcommand(args: &[String]) -> Option<HelmProjectedSubcommand> {
    let first = args.first()?.trim();
    if first.eq_ignore_ascii_case("lint") {
        return Some(HelmProjectedSubcommand::Lint);
    }
    if first.eq_ignore_ascii_case("template") {
        return Some(HelmProjectedSubcommand::Template);
    }
    if first.eq_ignore_ascii_case("install") {
        return Some(HelmProjectedSubcommand::Install);
    }
    if first.eq_ignore_ascii_case("upgrade") {
        return Some(HelmProjectedSubcommand::Upgrade);
    }
    if first.eq_ignore_ascii_case("uninstall") {
        return Some(HelmProjectedSubcommand::Uninstall);
    }
    if first.eq_ignore_ascii_case("dependency")
        && args
            .get(1)
            .is_some_and(|value| value.trim().eq_ignore_ascii_case("build"))
    {
        return Some(HelmProjectedSubcommand::DependencyBuild);
    }
    None
}

fn helm_has_flag(args: &[String], flags: &[&str]) -> bool {
    args.iter().any(|arg| {
        let trimmed = arg.trim();
        flags.iter().any(|flag| trimmed.eq_ignore_ascii_case(flag))
    })
}

fn helm_has_positional_after_prefix(
    args: &[String],
    prefix_len: usize,
    required_positionals: usize,
) -> bool {
    let mut positionals = 0usize;
    let mut skip_value_for_flag = false;
    for arg in args.iter().skip(prefix_len) {
        let trimmed = arg.trim();
        if skip_value_for_flag {
            skip_value_for_flag = false;
            continue;
        }
        if trimmed.starts_with('-') {
            skip_value_for_flag = matches!(
                trimmed,
                "-f" | "--values" | "-n" | "--namespace" | "--kube-context"
            );
            continue;
        }
        positionals += 1;
        if positionals >= required_positionals {
            return true;
        }
    }
    false
}

fn join_backend_cwd_with_adapter_cwd(
    backend_cwd: Option<&str>,
    task: Option<&TaskSpec>,
    backend: Backend,
) -> Option<String> {
    let backend_cwd = backend_cwd.map(str::trim).filter(|cwd| !cwd.is_empty());
    let adapter_cwd_value = task.and_then(|task| task_effective_adapter_cwd(task, backend));
    let adapter_cwd = adapter_cwd_value
        .as_deref()
        .map(str::trim)
        .filter(|cwd| !cwd.is_empty());

    match (backend_cwd, adapter_cwd) {
        (Some(base), Some(adapter)) => Some(format!(
            "{}/{}",
            base.trim_end_matches('/'),
            adapter.trim_start_matches("./")
        )),
        (Some(base), None) => Some(base.to_string()),
        (None, Some(adapter)) => Some(adapter.to_string()),
        (None, None) => None,
    }
}

pub fn resolve_task_env_details(
    contract: &Contract,
    contract_path: &Path,
    task_env: Option<&BTreeMap<String, String>>,
) -> Result<BTreeMap<String, ResolvedEnvValue>, RunError> {
    resolve_task_env_details_with_policy_and_required_env_names(
        contract,
        contract_path,
        task_env,
        None,
        None,
    )
}

pub fn resolve_task_env_details_for_task(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    task_env: Option<&BTreeMap<String, String>>,
) -> Result<BTreeMap<String, ResolvedEnvValue>, RunError> {
    resolve_task_env_details_for_task_with_policy(
        contract,
        contract_path,
        task_name,
        task_env,
        None,
    )
}

pub fn resolve_task_env_details_with_policy(
    contract: &Contract,
    contract_path: &Path,
    task_env: Option<&BTreeMap<String, String>>,
    policy_env: Option<&BTreeMap<String, String>>,
) -> Result<BTreeMap<String, ResolvedEnvValue>, RunError> {
    resolve_task_env_details_with_policy_and_required_env_names(
        contract,
        contract_path,
        task_env,
        policy_env,
        None,
    )
}

pub fn resolve_task_env_details_for_task_with_policy(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    task_env: Option<&BTreeMap<String, String>>,
    policy_env: Option<&BTreeMap<String, String>>,
) -> Result<BTreeMap<String, ResolvedEnvValue>, RunError> {
    let required_env_names = contract.task_required_env_names(task_name);
    resolve_task_env_details_with_policy_and_required_env_names(
        contract,
        contract_path,
        task_env,
        policy_env,
        (!required_env_names.is_empty()).then_some(&required_env_names),
    )
}

fn resolve_task_env_details_with_policy_and_required_env_names(
    contract: &Contract,
    contract_path: &Path,
    task_env: Option<&BTreeMap<String, String>>,
    policy_env: Option<&BTreeMap<String, String>>,
    selected_required_env_names: Option<&BTreeSet<String>>,
) -> Result<BTreeMap<String, ResolvedEnvValue>, RunError> {
    let mut resolved_values = BTreeMap::new();
    let repo_policy =
        load_policy_env_overlay(contract_path).map_err(|error| RunError::InvalidPolicyPack {
            details: error.to_string(),
        })?;
    let declared_sources = load_declared_env_sources(contract, contract_path);
    ensure_declared_env_sources_ready(&declared_sources)?;

    for (name, requirement) in contract.env.iter() {
        if requirement.secret && requirement.default.is_some() {
            return Err(RunError::SecretEnvCannotHaveDefault { name: name.clone() });
        }
        let required_for_selected_path = requirement.required
            || selected_required_env_names.is_some_and(|names| names.contains(name));
        let process_value = std::env::var(name).ok();
        let task_value = task_env.and_then(|values| values.get(name)).cloned();
        let resolved = task_value
            .map(|value| (value, EnvResolutionSource::Task))
            .or_else(|| {
                policy_env
                    .and_then(|values| values.get(name))
                    .cloned()
                    .map(|value| {
                        (
                            value,
                            EnvResolutionSource::Policy(String::from("workspace policy")),
                        )
                    })
            })
            .or_else(|| {
                repo_policy.values.get(name).cloned().map(|value| {
                    (
                        value,
                        EnvResolutionSource::Policy(repo_policy.label.clone()),
                    )
                })
            })
            .or_else(|| process_value.map(|value| (value, EnvResolutionSource::Process)))
            .or_else(|| resolve_declared_env_source_value(name, &declared_sources))
            .or_else(|| {
                requirement
                    .default
                    .clone()
                    .map(|value| (value, EnvResolutionSource::Default))
            });

        match resolved {
            Some((value, source)) => {
                let value = if name == "PATH" {
                    compose_path_value(name, &value, requirement)?
                } else {
                    value
                };

                if !requirement.allowed.is_empty()
                    && !requirement.allowed.iter().any(|v| v == &value)
                {
                    return Err(RunError::InvalidEnvValue {
                        name: name.clone(),
                        value,
                        allowed: requirement.allowed.join(", "),
                    });
                }

                resolved_values.insert(
                    name.clone(),
                    ResolvedEnvValue {
                        value,
                        source,
                        secret: requirement.secret,
                    },
                );
            }
            None if required_for_selected_path => {
                return Err(RunError::MissingRequiredEnv { name: name.clone() });
            }
            None => {}
        }
    }

    if let Some(task_env) = task_env {
        for (name, value) in task_env {
            if contract.env.contains_key(name) {
                continue;
            }
            resolved_values.insert(
                name.clone(),
                ResolvedEnvValue {
                    value: value.clone(),
                    source: EnvResolutionSource::Task,
                    secret: false,
                },
            );
        }
    }

    Ok(resolved_values)
}

pub fn load_declared_env_sources(
    contract: &Contract,
    contract_path: &Path,
) -> Vec<LoadedDeclaredEnvSource> {
    let contract_dir = contract_path
        .parent()
        .unwrap_or_else(|| Path::new("."))
        .to_path_buf();

    contract
        .env
        .sources
        .iter()
        .map(|source| {
            load_declared_env_source(&contract_dir, source.kind, &source.path, source.must_exist)
        })
        .collect()
}

fn load_declared_env_source(
    contract_dir: &Path,
    kind: EnvSourceKind,
    path: &str,
    must_exist: bool,
) -> LoadedDeclaredEnvSource {
    let source_path = contract_dir.join(path);
    match kind {
        EnvSourceKind::Dotenv => load_dotenv_source(kind, path, must_exist, &source_path),
        EnvSourceKind::Properties => load_text_declared_env_source(
            kind,
            path,
            must_exist,
            &source_path,
            parse_properties_declared_env_source,
        ),
        EnvSourceKind::Json => load_text_declared_env_source(
            kind,
            path,
            must_exist,
            &source_path,
            parse_json_declared_env_source,
        ),
        EnvSourceKind::Yaml => load_text_declared_env_source(
            kind,
            path,
            must_exist,
            &source_path,
            parse_yaml_declared_env_source,
        ),
        EnvSourceKind::Toml => load_text_declared_env_source(
            kind,
            path,
            must_exist,
            &source_path,
            parse_toml_declared_env_source,
        ),
    }
}

#[derive(Debug, Clone)]
enum StructuredDeclaredEnvValue {
    String(String),
    Number(String),
    Bool(bool),
    Null,
    Array,
    Object(BTreeMap<String, StructuredDeclaredEnvValue>),
}

fn load_text_declared_env_source(
    kind: EnvSourceKind,
    path: &str,
    must_exist: bool,
    source_path: &Path,
    parser: fn(&str) -> Result<BTreeMap<String, String>, DeclaredEnvSourceLoadError>,
) -> LoadedDeclaredEnvSource {
    let contents = match fs::read_to_string(source_path) {
        Ok(contents) => contents,
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            return LoadedDeclaredEnvSource {
                kind,
                path: path.to_string(),
                must_exist,
                status: if must_exist {
                    DeclaredEnvSourceStatus::MissingRequired
                } else {
                    DeclaredEnvSourceStatus::MissingOptional
                },
                details: None,
                values: BTreeMap::new(),
            };
        }
        Err(error) => {
            return LoadedDeclaredEnvSource {
                kind,
                path: path.to_string(),
                must_exist,
                status: DeclaredEnvSourceStatus::ParseFailed,
                details: Some(error.to_string()),
                values: BTreeMap::new(),
            };
        }
    };

    match parser(&contents) {
        Ok(values) => LoadedDeclaredEnvSource {
            kind,
            path: path.to_string(),
            must_exist,
            status: DeclaredEnvSourceStatus::Loaded,
            details: None,
            values,
        },
        Err(error) => LoadedDeclaredEnvSource {
            kind,
            path: path.to_string(),
            must_exist,
            status: match error.kind {
                DeclaredEnvSourceLoadErrorKind::ParseFailed => DeclaredEnvSourceStatus::ParseFailed,
                DeclaredEnvSourceLoadErrorKind::InvalidStructure => {
                    DeclaredEnvSourceStatus::InvalidStructure
                }
                DeclaredEnvSourceLoadErrorKind::Collision => DeclaredEnvSourceStatus::Collision,
            },
            details: Some(error.details),
            values: BTreeMap::new(),
        },
    }
}

fn load_dotenv_source(
    kind: EnvSourceKind,
    path: &str,
    must_exist: bool,
    source_path: &Path,
) -> LoadedDeclaredEnvSource {
    let file = match File::open(source_path) {
        Ok(file) => file,
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            return LoadedDeclaredEnvSource {
                kind,
                path: path.to_string(),
                must_exist,
                status: if must_exist {
                    DeclaredEnvSourceStatus::MissingRequired
                } else {
                    DeclaredEnvSourceStatus::MissingOptional
                },
                details: None,
                values: BTreeMap::new(),
            };
        }
        Err(error) => {
            return LoadedDeclaredEnvSource {
                kind,
                path: path.to_string(),
                must_exist,
                status: DeclaredEnvSourceStatus::ParseFailed,
                details: Some(error.to_string()),
                values: BTreeMap::new(),
            };
        }
    };

    let mut values = BTreeMap::new();
    for entry in dotenvy::from_read_iter(file) {
        match entry {
            Ok((name, value)) => {
                values.insert(name, value);
            }
            Err(error) => {
                return LoadedDeclaredEnvSource {
                    kind,
                    path: path.to_string(),
                    must_exist,
                    status: DeclaredEnvSourceStatus::ParseFailed,
                    details: Some(error.to_string()),
                    values: BTreeMap::new(),
                };
            }
        }
    }

    LoadedDeclaredEnvSource {
        kind,
        path: path.to_string(),
        must_exist,
        status: DeclaredEnvSourceStatus::Loaded,
        details: None,
        values,
    }
}

fn parse_properties_declared_env_source(
    contents: &str,
) -> Result<BTreeMap<String, String>, DeclaredEnvSourceLoadError> {
    let mut values = BTreeMap::new();
    let logical_lines = properties_logical_lines(contents)?;
    let mut normalized_keys = BTreeMap::new();

    for line in logical_lines {
        let trimmed = line.trim_start();
        if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with('!') {
            continue;
        }
        let (raw_key, raw_value) = split_properties_entry(trimmed);
        let key = properties_unescape(raw_key).map_err(|details| {
            DeclaredEnvSourceLoadError::parse_failed(format!(
                "invalid properties key `{raw_key}`: {details}"
            ))
        })?;
        let value = properties_unescape(raw_value).map_err(|details| {
            DeclaredEnvSourceLoadError::parse_failed(format!(
                "invalid properties value for `{raw_key}`: {details}"
            ))
        })?;
        insert_normalized_declared_env_value(&mut values, &mut normalized_keys, &key, value)?;
    }

    Ok(values)
}

fn properties_logical_lines(contents: &str) -> Result<Vec<String>, DeclaredEnvSourceLoadError> {
    let mut logical_lines = Vec::new();
    let mut current = String::new();

    for raw_line in contents.lines() {
        let mut line = raw_line.trim_end_matches('\r').to_string();
        if current.is_empty() {
            current.push_str(&line);
        } else {
            line = line.trim_start_matches(char::is_whitespace).to_string();
            current.push_str(&line);
        }

        if properties_line_continues(&current) {
            current.pop();
            continue;
        }

        logical_lines.push(std::mem::take(&mut current));
    }

    if properties_line_continues(&current) {
        return Err(DeclaredEnvSourceLoadError::parse_failed(
            "properties source ends with an unterminated line continuation",
        ));
    }
    if !current.is_empty() {
        logical_lines.push(current);
    }

    Ok(logical_lines)
}

fn properties_line_continues(line: &str) -> bool {
    let slash_count = line
        .chars()
        .rev()
        .take_while(|character| *character == '\\')
        .count();
    slash_count % 2 == 1
}

fn split_properties_entry(line: &str) -> (&str, &str) {
    let mut escaped = false;
    for (index, character) in line.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if character == '\\' {
            escaped = true;
            continue;
        }
        if character == '=' || character == ':' {
            let mut value_index = index + character.len_utf8();
            while let Some(next_character) = line[value_index..].chars().next() {
                if !next_character.is_whitespace() {
                    break;
                }
                value_index += next_character.len_utf8();
            }
            return (&line[..index], &line[value_index..]);
        }
        if character.is_whitespace() {
            let mut value_index = index;
            let mut separator_seen = false;
            for (offset, trailing) in line[index..].char_indices() {
                if trailing.is_whitespace() {
                    value_index = index + offset + trailing.len_utf8();
                    continue;
                }
                if !separator_seen && (trailing == '=' || trailing == ':') {
                    separator_seen = true;
                    value_index = index + offset + trailing.len_utf8();
                    continue;
                }
                break;
            }
            return (&line[..index], &line[value_index..]);
        }
    }
    (line, "")
}

fn properties_unescape(value: &str) -> Result<String, String> {
    let mut output = String::new();
    let mut characters = value.chars();
    while let Some(character) = characters.next() {
        if character != '\\' {
            output.push(character);
            continue;
        }
        let escaped = characters
            .next()
            .ok_or_else(|| String::from("dangling escape sequence"))?;
        match escaped {
            't' => output.push('\t'),
            'n' => output.push('\n'),
            'r' => output.push('\r'),
            'f' => output.push('\u{000C}'),
            '\\' => output.push('\\'),
            'u' => {
                let mut hex = String::new();
                for _ in 0..4 {
                    hex.push(
                        characters
                            .next()
                            .ok_or_else(|| String::from("truncated unicode escape"))?,
                    );
                }
                let code_point = u32::from_str_radix(&hex, 16)
                    .map_err(|_| format!("invalid unicode escape `\\u{hex}`"))?;
                let decoded = char::from_u32(code_point)
                    .ok_or_else(|| format!("invalid unicode scalar `\\u{hex}`"))?;
                output.push(decoded);
            }
            other => output.push(other),
        }
    }
    Ok(output)
}

fn parse_json_declared_env_source(
    contents: &str,
) -> Result<BTreeMap<String, String>, DeclaredEnvSourceLoadError> {
    let parsed: serde_json::Value = serde_json::from_str(contents)
        .map_err(|error| DeclaredEnvSourceLoadError::parse_failed(error.to_string()))?;
    let structured = structured_env_value_from_json(parsed);
    parse_structured_declared_env_source("json", "object", structured)
}

fn parse_yaml_declared_env_source(
    contents: &str,
) -> Result<BTreeMap<String, String>, DeclaredEnvSourceLoadError> {
    let parsed: serde_yaml::Value = serde_yaml::from_str(contents)
        .map_err(|error| DeclaredEnvSourceLoadError::parse_failed(error.to_string()))?;
    let structured = structured_env_value_from_yaml(parsed)?;
    parse_structured_declared_env_source("yaml", "object", structured)
}

fn parse_toml_declared_env_source(
    contents: &str,
) -> Result<BTreeMap<String, String>, DeclaredEnvSourceLoadError> {
    let parsed: toml::Value = toml::from_str(contents)
        .map_err(|error| DeclaredEnvSourceLoadError::parse_failed(error.to_string()))?;
    let structured = structured_env_value_from_toml(parsed)?;
    parse_structured_declared_env_source("toml", "table", structured)
}

fn parse_structured_declared_env_source(
    source_kind: &str,
    root_label: &str,
    root: StructuredDeclaredEnvValue,
) -> Result<BTreeMap<String, String>, DeclaredEnvSourceLoadError> {
    let StructuredDeclaredEnvValue::Object(root) = root else {
        return Err(DeclaredEnvSourceLoadError::invalid_structure(format!(
            "{source_kind} source root must be an {root_label}"
        )));
    };
    let mut values = BTreeMap::new();
    let mut normalized_keys = BTreeMap::new();
    for (key, value) in &root {
        flatten_structured_declared_env_value(
            source_kind,
            key.as_str(),
            value,
            &mut values,
            &mut normalized_keys,
        )?;
    }
    Ok(values)
}

fn flatten_structured_declared_env_value(
    source_kind: &str,
    path: &str,
    value: &StructuredDeclaredEnvValue,
    values: &mut BTreeMap<String, String>,
    normalized_keys: &mut BTreeMap<String, String>,
) -> Result<(), DeclaredEnvSourceLoadError> {
    match value {
        StructuredDeclaredEnvValue::String(text) => {
            insert_normalized_declared_env_value(values, normalized_keys, path, text.clone())
        }
        StructuredDeclaredEnvValue::Number(number) => {
            insert_normalized_declared_env_value(values, normalized_keys, path, number.to_string())
        }
        StructuredDeclaredEnvValue::Bool(boolean) => {
            insert_normalized_declared_env_value(values, normalized_keys, path, boolean.to_string())
        }
        StructuredDeclaredEnvValue::Null => Err(DeclaredEnvSourceLoadError::invalid_structure(
            format!("{source_kind} key `{path}` resolves to null; null is not supported"),
        )),
        StructuredDeclaredEnvValue::Array => Err(DeclaredEnvSourceLoadError::invalid_structure(
            format!("{source_kind} key `{path}` resolves to an array; arrays are not supported"),
        )),
        StructuredDeclaredEnvValue::Object(map) => {
            if map.is_empty() {
                return Err(DeclaredEnvSourceLoadError::invalid_structure(format!(
                    "{source_kind} key `{path}` resolves to an object; object leaf values are not supported"
                )));
            }
            for (child_key, child_value) in map {
                let child_path = format!("{path}.{child_key}");
                flatten_structured_declared_env_value(
                    source_kind,
                    &child_path,
                    child_value,
                    values,
                    normalized_keys,
                )?;
            }
            Ok(())
        }
    }
}

fn structured_env_value_from_json(value: serde_json::Value) -> StructuredDeclaredEnvValue {
    match value {
        serde_json::Value::String(text) => StructuredDeclaredEnvValue::String(text),
        serde_json::Value::Number(number) => StructuredDeclaredEnvValue::Number(number.to_string()),
        serde_json::Value::Bool(boolean) => StructuredDeclaredEnvValue::Bool(boolean),
        serde_json::Value::Null => StructuredDeclaredEnvValue::Null,
        serde_json::Value::Array(_) => StructuredDeclaredEnvValue::Array,
        serde_json::Value::Object(map) => StructuredDeclaredEnvValue::Object(
            map.into_iter()
                .map(|(key, value)| (key, structured_env_value_from_json(value)))
                .collect(),
        ),
    }
}

fn structured_env_value_from_yaml(
    value: serde_yaml::Value,
) -> Result<StructuredDeclaredEnvValue, DeclaredEnvSourceLoadError> {
    match value {
        serde_yaml::Value::String(text) => Ok(StructuredDeclaredEnvValue::String(text)),
        serde_yaml::Value::Number(number) => {
            Ok(StructuredDeclaredEnvValue::Number(number.to_string()))
        }
        serde_yaml::Value::Bool(boolean) => Ok(StructuredDeclaredEnvValue::Bool(boolean)),
        serde_yaml::Value::Null => Ok(StructuredDeclaredEnvValue::Null),
        serde_yaml::Value::Sequence(_) => Ok(StructuredDeclaredEnvValue::Array),
        serde_yaml::Value::Tagged(tagged) => structured_env_value_from_yaml(tagged.value),
        serde_yaml::Value::Mapping(map) => {
            let mut values = BTreeMap::new();
            for (key, value) in map {
                let key = match key {
                    serde_yaml::Value::String(text) => text,
                    serde_yaml::Value::Number(number) => number.to_string(),
                    serde_yaml::Value::Bool(boolean) => boolean.to_string(),
                    other => {
                        return Err(DeclaredEnvSourceLoadError::invalid_structure(format!(
                            "yaml object key `{}` is not supported; only string, number, and bool keys are supported",
                            render_yaml_value_for_error(&other)
                        )));
                    }
                };
                values.insert(key, structured_env_value_from_yaml(value)?);
            }
            Ok(StructuredDeclaredEnvValue::Object(values))
        }
    }
}

fn structured_env_value_from_toml(
    value: toml::Value,
) -> Result<StructuredDeclaredEnvValue, DeclaredEnvSourceLoadError> {
    match value {
        toml::Value::String(text) => Ok(StructuredDeclaredEnvValue::String(text)),
        toml::Value::Integer(number) => Ok(StructuredDeclaredEnvValue::Number(number.to_string())),
        toml::Value::Float(number) => Ok(StructuredDeclaredEnvValue::Number(number.to_string())),
        toml::Value::Boolean(boolean) => Ok(StructuredDeclaredEnvValue::Bool(boolean)),
        toml::Value::Array(_) => Ok(StructuredDeclaredEnvValue::Array),
        toml::Value::Table(map) => {
            let mut values = BTreeMap::new();
            for (key, value) in map {
                values.insert(key, structured_env_value_from_toml(value)?);
            }
            Ok(StructuredDeclaredEnvValue::Object(values))
        }
        toml::Value::Datetime(_) => Err(DeclaredEnvSourceLoadError::invalid_structure(
            "toml datetime values are not supported; only string, number, and bool leaves are allowed",
        )),
    }
}

fn render_yaml_value_for_error(value: &serde_yaml::Value) -> String {
    match value {
        serde_yaml::Value::String(text) => text.clone(),
        serde_yaml::Value::Number(number) => number.to_string(),
        serde_yaml::Value::Bool(boolean) => boolean.to_string(),
        serde_yaml::Value::Null => String::from("null"),
        other => serde_yaml::to_string(other)
            .unwrap_or_else(|_| format!("{other:?}"))
            .trim()
            .to_string(),
    }
}

fn insert_normalized_declared_env_value(
    values: &mut BTreeMap<String, String>,
    normalized_keys: &mut BTreeMap<String, String>,
    raw_key: &str,
    value: String,
) -> Result<(), DeclaredEnvSourceLoadError> {
    let normalized = normalize_declared_env_source_key(raw_key)?;
    if let Some(previous) = normalized_keys.get(&normalized) {
        return Err(DeclaredEnvSourceLoadError::collision(format!(
            "keys `{previous}` and `{raw_key}` both normalize to `{normalized}`"
        )));
    }
    normalized_keys.insert(normalized.clone(), raw_key.to_string());
    values.insert(normalized, value);
    Ok(())
}

fn normalize_declared_env_source_key(raw_key: &str) -> Result<String, DeclaredEnvSourceLoadError> {
    let trimmed = raw_key.trim();
    let mut normalized = String::new();
    let mut last_was_separator = false;

    for character in trimmed.chars() {
        let is_separator = character == '.'
            || character == '-'
            || character == '/'
            || character == ':'
            || character == '_'
            || character.is_whitespace();
        if is_separator {
            if !last_was_separator && !normalized.is_empty() {
                normalized.push('_');
            }
            last_was_separator = true;
            continue;
        }
        normalized.extend(character.to_uppercase());
        last_was_separator = false;
    }

    if normalized.ends_with('_') {
        normalized.pop();
    }

    if normalized.is_empty() {
        return Err(DeclaredEnvSourceLoadError::collision(format!(
            "key `{raw_key}` normalizes to an empty env name"
        )));
    }

    Ok(normalized)
}

fn ensure_declared_env_sources_ready(sources: &[LoadedDeclaredEnvSource]) -> Result<(), RunError> {
    for source in sources {
        match source.status {
            DeclaredEnvSourceStatus::Loaded => {}
            DeclaredEnvSourceStatus::MissingOptional => {}
            DeclaredEnvSourceStatus::MissingRequired => {
                return Err(RunError::MissingRequiredEnvSource {
                    kind: source.kind.to_string(),
                    path: source.path.clone(),
                });
            }
            DeclaredEnvSourceStatus::ParseFailed
            | DeclaredEnvSourceStatus::InvalidStructure
            | DeclaredEnvSourceStatus::Collision => {
                return Err(RunError::InvalidEnvSource {
                    kind: source.kind.to_string(),
                    path: source.path.clone(),
                    details: source
                        .details
                        .clone()
                        .unwrap_or_else(|| String::from("unknown parse error")),
                });
            }
        }
    }

    Ok(())
}

pub fn resolve_declared_env_source_value(
    name: &str,
    sources: &[LoadedDeclaredEnvSource],
) -> Option<(String, EnvResolutionSource)> {
    sources.iter().find_map(|source| {
        if source.status != DeclaredEnvSourceStatus::Loaded {
            return None;
        }

        source
            .values
            .get(name)
            .cloned()
            .map(|value| (value, EnvResolutionSource::Source(source.label())))
    })
}

pub fn env_resolution_source_label(source: &EnvResolutionSource) -> String {
    match source {
        EnvResolutionSource::Process => String::from("process"),
        EnvResolutionSource::Default => String::from("default"),
        EnvResolutionSource::Policy(label) => label.clone(),
        EnvResolutionSource::Task => String::from("task"),
        EnvResolutionSource::Source(label) => label.clone(),
    }
}

pub fn blocking_declared_env_source_label(sources: &[LoadedDeclaredEnvSource]) -> Option<String> {
    sources.iter().find_map(|source| match source.status {
        DeclaredEnvSourceStatus::Loaded => None,
        DeclaredEnvSourceStatus::MissingOptional => None,
        DeclaredEnvSourceStatus::MissingRequired => {
            Some(format!("missing required {}", source.label()))
        }
        DeclaredEnvSourceStatus::ParseFailed => Some(format!("parse failed {}", source.label())),
        DeclaredEnvSourceStatus::InvalidStructure => {
            Some(format!("invalid structure {}", source.label()))
        }
        DeclaredEnvSourceStatus::Collision => Some(format!("collision {}", source.label())),
    })
}

fn compose_path_value(
    name: &str,
    base: &str,
    requirement: &EnvRequirement,
) -> Result<String, RunError> {
    if requirement.prepend.is_empty() && requirement.append.is_empty() {
        return Ok(base.to_string());
    }

    let mut entries = Vec::with_capacity(1 + requirement.prepend.len() + requirement.append.len());
    entries.extend(requirement.prepend.iter().map(OsString::from));
    entries.extend(env::split_paths(base).map(|path| path.into_os_string()));
    entries.extend(requirement.append.iter().map(OsString::from));

    env::join_paths(entries)
        .map(|joined| joined.to_string_lossy().into_owned())
        .map_err(|source| RunError::InvalidPathComposition {
            name: name.to_string(),
            source,
        })
}

fn command_with_path_export(command: &str, path_export: Option<&str>) -> String {
    signal_forwarding_shell_script(command_with_optional_path_export(command, path_export))
}

fn render_path_export_value(path: &str) -> String {
    if !path.contains("$PATH") {
        return shell_quote(path);
    }

    let mut rendered = String::new();
    let mut remaining = path;
    while let Some(index) = remaining.find("$PATH") {
        let (before, after) = remaining.split_at(index);
        if !before.is_empty() {
            rendered.push_str(&shell_quote(before));
        }
        rendered.push_str("\"$PATH\"");
        remaining = &after["$PATH".len()..];
    }
    if !remaining.is_empty() {
        rendered.push_str(&shell_quote(remaining));
    }
    if rendered.is_empty() {
        String::from("\"$PATH\"")
    } else {
        rendered
    }
}

fn command_with_optional_path_export(command: &str, path_export: Option<&str>) -> String {
    match path_export {
        Some(path) => format!("export PATH={}; {command}", render_path_export_value(path)),
        None => command.to_string(),
    }
}

fn persistent_service_workload_pidfile_path(task_name: &str) -> String {
    let mut hasher = DefaultHasher::new();
    task_name.hash(&mut hasher);
    format!("/tmp/ota-service-{:x}.pid", hasher.finish())
}

fn persistent_service_workload_statusfile_path(task_name: &str) -> String {
    let mut hasher = DefaultHasher::new();
    task_name.hash(&mut hasher);
    format!("/tmp/ota-service-{:x}.status", hasher.finish())
}

fn persistent_service_workload_logfile_path(task_name: &str) -> String {
    let mut hasher = DefaultHasher::new();
    task_name.hash(&mut hasher);
    format!("/tmp/ota-service-{:x}.log", hasher.finish())
}

fn persistent_service_command_with_path_export(
    task_name: &str,
    command: &str,
    path_export: Option<&str>,
) -> String {
    let pidfile = persistent_service_workload_pidfile_path(task_name);
    let statusfile = persistent_service_workload_statusfile_path(task_name);
    let logfile = persistent_service_workload_logfile_path(task_name);
    let interruptfile = format!("{pidfile}.interrupted");
    let command = command_with_optional_path_export(command, path_export)
        .trim()
        .to_owned();
    let command = if command.is_empty() {
        String::from(":")
    } else {
        command
    };
    format!(
        "pidfile={pidfile}; \
statusfile={statusfile}; \
logfile={logfile}; \
interruptfile={interruptfile}; \
cleanup() {{ rm -f \"$pidfile\" \"$statusfile\" \"$logfile\" \"$interruptfile\"; }}; \
	read_pidfile() {{ [ -s \"$pidfile\" ] || return 1; read pid < \"$pidfile\" || return 1; [ -n \"$pid\" ] || return 1; parent=$(ps -p \"$pid\" -o ppid= 2>/dev/null | tr -d '[:space:]'); [ -n \"$parent\" ] || return 1; [ \"$parent\" = \"$$\" ] || return 1; ps -p \"$pid\" >/dev/null 2>&1; }}; \
kill_workload() {{ \
  read_pidfile || return 0; \
  kill \"$pid\" 2>/dev/null || true; \
  i=0; \
  while read_pidfile && [ \"$i\" -lt 30 ]; do i=$((i + 1)); sleep 0.1; done; \
  read_pidfile || return 0; \
  kill -KILL \"$pid\" 2>/dev/null || true; \
  i=0; \
  while read_pidfile && [ \"$i\" -lt 20 ]; do i=$((i + 1)); sleep 0.1; done; \
  return 0; \
}}; \
cleanup; : > \"$logfile\"; \
tailpid=; \
trap ': > \"$interruptfile\"; kill_workload; [ -n \"$tailpid\" ] && kill \"$tailpid\" 2>/dev/null || true; cleanup; exit 130' INT TERM; \
nohup sh -c {wrapped_command} </dev/null >> \"$logfile\" 2>&1 & child=$!; \
printf '%s\\n' \"$child\" > \"$pidfile\"; \
tail -n +1 -F \"$logfile\" & tailpid=$!; \
while read_pidfile; do sleep 0.2; done; \
kill \"$tailpid\" 2>/dev/null || true; \
wait \"$tailpid\" 2>/dev/null || true; \
[ -f \"$interruptfile\" ] && {{ cleanup; exit 130; }}; \
[ -f \"$statusfile\" ] || {{ cleanup; exit 1; }}; \
status=$(cat \"$statusfile\" 2>/dev/null || printf '1'); \
cleanup; exit \"$status\"",
        pidfile = shell_quote(&pidfile),
        statusfile = shell_quote(&statusfile),
        logfile = shell_quote(&logfile),
        interruptfile = shell_quote(&interruptfile),
        wrapped_command = shell_quote(&format!(
            "trap 'kill 0' INT TERM; {command}; status=$?; printf '%s\\n' \"$status\" > {statusfile}; exit \"$status\"",
            statusfile = shell_quote(&statusfile),
            command = command,
        )),
    )
}

fn remote_activation_service_command_with_path_export(
    task_name: &str,
    command: &str,
    path_export: Option<&str>,
    ready_port: u16,
) -> String {
    let pidfile = persistent_service_workload_pidfile_path(task_name);
    let statusfile = persistent_service_workload_statusfile_path(task_name);
    let logfile = persistent_service_workload_logfile_path(task_name);
    let interruptfile = format!("{pidfile}.interrupted");
    let command = command_with_optional_path_export(command, path_export)
        .trim()
        .to_owned();
    let command = if command.is_empty() {
        String::from(":")
    } else {
        command
    };
    format!(
        "pidfile={pidfile}; \
statusfile={statusfile}; \
logfile={logfile}; \
interruptfile={interruptfile}; \
port={port}; \
cleanup_failed_start() {{ rm -f \"$pidfile\" \"$statusfile\" \"$logfile\" \"$interruptfile\"; }}; \
read_pidfile() {{ [ -s \"$pidfile\" ] || return 1; read pid started < \"$pidfile\" || return 1; [ -n \"$pid\" ] || return 1; if [ -z \"$started\" ]; then kill -0 \"$pid\" 2>/dev/null; return $?; fi; current=$(cut -d' ' -f22 \"/proc/$pid/stat\" 2>/dev/null || true); [ -n \"$current\" ] && [ \"$current\" = \"$started\" ]; }}; \
kill_workload() {{ \
  read_pidfile || return 0; \
  kill \"$pid\" 2>/dev/null || true; \
  i=0; \
  while read_pidfile && [ \"$i\" -lt 30 ]; do i=$((i + 1)); sleep 0.1; done; \
  read_pidfile || return 0; \
  kill -KILL \"$pid\" 2>/dev/null || true; \
  i=0; \
  while read_pidfile && [ \"$i\" -lt 20 ]; do i=$((i + 1)); sleep 0.1; done; \
  return 0; \
}}; \
port_listening() {{ target=\"$1\"; awk -v port=\"$target\" 'BEGIN {{ found = 0 }} NR > 1 {{ split($2, a, \":\"); if (($4 == \"0A\" || $4 == \"0a\") && (toupper(a[2]) == toupper(port) || a[2] == port)) {{ found = 1; exit }} }} END {{ exit(found ? 0 : 1) }}' /proc/net/tcp /proc/net/tcp6 2>/dev/null; }}; \
cleanup_failed_start; : > \"$logfile\"; \
trap ': > \"$interruptfile\"; kill_workload; cleanup_failed_start; exit 130' INT TERM; \
nohup sh -c {wrapped_command} </dev/null >> \"$logfile\" 2>&1 & child=$!; \
started=$(cut -d' ' -f22 \"/proc/$child/stat\" 2>/dev/null || true); \
printf '%s %s\\n' \"$child\" \"$started\" > \"$pidfile\"; \
while read_pidfile; do \
  hex=$(printf '%04X' \"$port\"); \
  if port_listening \"$hex\"; then exit 0; fi; \
  sleep 0.1; \
done; \
[ -f \"$interruptfile\" ] && {{ cleanup_failed_start; exit 130; }}; \
[ -f \"$statusfile\" ] || {{ cleanup_failed_start; exit 1; }}; \
status=$(cat \"$statusfile\" 2>/dev/null || printf '1'); \
cleanup_failed_start; exit \"$status\"",
        pidfile = shell_quote(&pidfile),
        statusfile = shell_quote(&statusfile),
        logfile = shell_quote(&logfile),
        interruptfile = shell_quote(&interruptfile),
        port = ready_port,
        wrapped_command = shell_quote(&format!(
            "trap 'kill 0' INT TERM; {command}; status=$?; printf '%s\\n' \"$status\" > {statusfile}; exit \"$status\"",
            statusfile = shell_quote(&statusfile),
            command = command,
        )),
    )
}

fn remote_activation_readiness_port(runtime: &crate::schema::TaskRuntimeSpec) -> Option<u16> {
    let readiness = runtime.readiness.as_ref()?;
    let listener_name = readiness.listener.as_deref()?.trim();
    if listener_name.is_empty() {
        return None;
    }
    let listener = runtime.listeners.get(listener_name)?;
    if listener.bind.port.mode != crate::schema::TaskRuntimePortMode::Fixed {
        return None;
    }
    listener.bind.port.value
}

#[cfg(unix)]
