fn install_run_interrupt_handler() {
    RUN_INTERRUPT_HANDLER.call_once(|| {
        ctrlc::set_handler(|| {
            RUN_INTERRUPT_REQUESTED.store(true, Ordering::Relaxed);
            RUN_INTERRUPT_EPOCH.fetch_add(1, Ordering::Relaxed);
        })
        .expect("run interrupt handler should install successfully");
        #[cfg(unix)]
        {
            use signal_hook::consts::signal::{SIGHUP, SIGQUIT, SIGTERM};
            use signal_hook::low_level;
            unsafe {
                low_level::register(SIGTERM, || {
                    RUN_INTERRUPT_REQUESTED.store(true, Ordering::Relaxed);
                    RUN_INTERRUPT_EPOCH.fetch_add(1, Ordering::Relaxed);
                })
                .expect("run interrupt handler should install SIGTERM");
                low_level::register(SIGHUP, || {
                    RUN_INTERRUPT_REQUESTED.store(true, Ordering::Relaxed);
                    RUN_INTERRUPT_EPOCH.fetch_add(1, Ordering::Relaxed);
                })
                .expect("run interrupt handler should install SIGHUP");
                low_level::register(SIGQUIT, || {
                    RUN_INTERRUPT_REQUESTED.store(true, Ordering::Relaxed);
                    RUN_INTERRUPT_EPOCH.fetch_add(1, Ordering::Relaxed);
                })
                .expect("run interrupt handler should install SIGQUIT");
            }
        }
    });
}

fn is_interrupt_exit_code(exit_code: i32) -> bool {
    exit_code == 129 || exit_code == 130 || exit_code == 131 || exit_code == 143
}

fn current_run_interrupt_epoch() -> u64 {
    RUN_INTERRUPT_EPOCH.load(Ordering::Relaxed)
}

fn interruption_observed_since(epoch: u64) -> bool {
    current_run_interrupt_epoch() != epoch
}

#[cfg(test)]
pub(crate) fn simulate_run_interrupt_for_test() {
    RUN_INTERRUPT_REQUESTED.store(true, Ordering::Relaxed);
    RUN_INTERRUPT_EPOCH.fetch_add(1, Ordering::Relaxed);
}

fn interruption_execution_note(interrupted: bool, exit_code: i32) -> Option<String> {
    (interrupted && (is_interrupt_exit_code(exit_code) || exit_code == 0))
        .then(|| String::from("task interrupted by user"))
}

fn task_command_output_reports_user_interruption(command_output: &TaskCommandOutput) -> bool {
    if let Some(service_termination) = command_output.service_termination.as_ref() {
        return match service_termination.cause {
            ServiceTerminationCause::Interrupted => true,
            ServiceTerminationCause::Exited => false,
            ServiceTerminationCause::ReadinessTimedOut => false,
            ServiceTerminationCause::ExitedNonZero
            | ServiceTerminationCause::OomKilled
            | ServiceTerminationCause::Unknown => false,
        };
    }

    is_interrupt_exit_code(command_output.exit_code)
        || (command_output.interrupted && command_output.exit_code == 0)
}

const NATIVE_SERVICE_POST_EXIT_READINESS_GRACE_FLOOR_MILLIS: u64 = 5_000;
const NATIVE_SERVICE_POST_EXIT_READINESS_GRACE_CEILING_SECS: u64 = 30;

fn native_service_post_exit_readiness_grace(runtime_spec: Option<&TaskRuntimeSpec>) -> Duration {
    let floor = Duration::from_millis(NATIVE_SERVICE_POST_EXIT_READINESS_GRACE_FLOOR_MILLIS);
    let ceiling = Duration::from_secs(NATIVE_SERVICE_POST_EXIT_READINESS_GRACE_CEILING_SECS);
    let Some(readiness) = runtime_spec.and_then(|runtime| runtime.readiness.as_ref()) else {
        return floor;
    };
    let grace = readiness
        .start_period
        .as_deref()
        .and_then(parse_readiness_duration_spec)
        .unwrap_or(Duration::ZERO)
        .saturating_add(
            readiness
                .timeout
                .as_deref()
                .and_then(parse_readiness_duration_spec)
                .unwrap_or(Duration::from_millis(200)),
        )
        .saturating_add(
            readiness
                .interval
                .as_deref()
                .and_then(parse_readiness_duration_spec)
                .unwrap_or(Duration::from_millis(200)),
        );
    grace.max(floor).min(ceiling)
}

fn final_runtime_readiness_probe_observed(
    contract: Option<&Contract>,
    task: Option<&crate::schema::TaskSpec>,
    backend: Backend,
    runtime_spec: Option<&TaskRuntimeSpec>,
    resolved_runtime: Option<&ResolvedTaskRuntime>,
) -> bool {
    if let (Some(contract), Some(task), Some(runtime_spec)) = (contract, task, runtime_spec) {
        let listener_name = runtime_spec
            .readiness
            .as_ref()
            .and_then(|readiness| readiness.listener.as_deref())
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .or_else(|| runtime_spec.listeners.keys().next().map(String::as_str));
        if let Some(listener_name) = listener_name
            && let Ok(probe) = task_runtime_host_readiness_probe_for_backend(
                contract,
                task,
                backend,
                listener_name,
            )
        {
            if host_runtime_readiness_observed(&probe, probe.default_timeout) {
                return true;
            }
        }
    }
    let (Some(runtime_spec), Some(resolved_runtime)) = (runtime_spec, resolved_runtime) else {
        return false;
    };
    let Some(targets) = runtime_readiness_targets(contract, runtime_spec, resolved_runtime) else {
        return false;
    };
    let timeout = readiness_timing_policy(contract, runtime_spec.readiness.as_ref()).timeout;
    readiness_targets_observed_with_timeout(targets.as_slice(), timeout)
}

fn collect_runtime_readiness_after_command_exit(
    contract: Option<&Contract>,
    task: Option<&crate::schema::TaskSpec>,
    backend: Backend,
    readiness_probe: Option<RuntimeReadinessProbe>,
    runtime_spec: Option<&TaskRuntimeSpec>,
    resolved_runtime: Option<&ResolvedTaskRuntime>,
    command_exit_code: i32,
    interrupted: bool,
) -> RuntimeReadinessProbeOutcome {
    let Some(probe) = readiness_probe else {
        return RuntimeReadinessProbeOutcome {
            observed: false,
            budget_exhausted: false,
            report: None,
        };
    };
    let service_requires_readiness = runtime_spec.is_some_and(|spec| {
        spec.kind == TaskRuntimeKind::Service
            && resolved_runtime.is_some_and(resolved_runtime_has_public_endpoint)
    });
    if service_requires_readiness && command_exit_code == 0 && !interrupted {
        let observed = probe
            .wait_then_stop_and_collect(native_service_post_exit_readiness_grace(runtime_spec));
        return RuntimeReadinessProbeOutcome {
            observed: observed.observed
                || final_runtime_readiness_probe_observed(
                    contract,
                    task,
                    backend,
                    runtime_spec,
                    resolved_runtime,
                ),
            budget_exhausted: observed.budget_exhausted,
            report: observed.report,
        };
    }
    probe.stop_and_collect()
}

fn task_effects_mutate_external_state(task: Option<&crate::schema::TaskSpec>) -> bool {
    task.is_some_and(|task| !task.effects.external_state.is_empty())
}

fn normalize_native_service_startup_exit_code(
    task: Option<&crate::schema::TaskSpec>,
    runtime_spec: Option<&TaskRuntimeSpec>,
    resolved_runtime: Option<&ResolvedTaskRuntime>,
    command_exit_code: i32,
    interrupted: bool,
    readiness_outcome: RuntimeReadinessProbeOutcome,
) -> (i32, Option<String>) {
    let interruption_note = interruption_execution_note(interrupted, command_exit_code);
    let service_requires_readiness = runtime_spec.is_some_and(|spec| {
        spec.kind == TaskRuntimeKind::Service
            && resolved_runtime.is_some_and(resolved_runtime_has_public_endpoint)
    });
    if service_requires_readiness
        && readiness_outcome.budget_exhausted
        && !readiness_outcome.observed
        && !interrupted
    {
        return (
            1,
            merge_execution_note(
                interruption_note,
                Some(String::from(
                    "service failed to start; readiness budget exhausted before the declared runtime endpoint became reachable",
                )),
            ),
        );
    }
    if service_requires_readiness
        && !readiness_outcome.observed
        && command_exit_code == 0
        && !interrupted
    {
        if task_effects_mutate_external_state(task) {
            return (
                0,
                merge_execution_note(
                    interruption_note,
                    Some(String::from(
                        "starter exited cleanly before local readiness was observed; use workflow/runtime proof to confirm the declared endpoint",
                    )),
                ),
            );
        }
        return (
            1,
            merge_execution_note(
                interruption_note,
                Some(String::from(
                    "service failed to start; declared runtime endpoint did not become reachable before process exit",
                )),
            ),
        );
    }
    (command_exit_code, interruption_note)
}

fn propagate_step_result_to_run_state(
    state: &mut TaskRunState,
    relation: &TaskExecutionRelation,
    command_output: &TaskCommandOutput,
) {
    let requested_relation = matches!(relation, TaskExecutionRelation::Requested);
    if requested_relation {
        state.runtime = command_output.runtime.clone();
        state.service_termination = command_output.service_termination.clone();
        state.interrupted = task_command_output_reports_user_interruption(command_output);
        return;
    }

    if task_command_output_reports_user_interruption(command_output) {
        state.interrupted = true;
        if state.service_termination.is_none() {
            state.service_termination = command_output.service_termination.clone();
            if state.runtime.is_none() {
                state.runtime = command_output.runtime.clone();
            }
        }
    }
}

pub fn clean_execution(
    contract: &Contract,
    contract_path: &Path,
) -> Result<bool, CleanExecutionError> {
    clean_execution_report(contract, contract_path).map(|report| report.cleaned_any())
}

pub fn clean_execution_report(
    contract: &Contract,
    contract_path: &Path,
) -> Result<CleanExecutionReport, CleanExecutionError> {
    clean_execution_report_inner(contract, contract_path, None)
        .map_err(classify_clean_execution_error)
}

pub fn clean_execution_report_for_workflow(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
) -> Result<CleanExecutionReport, CleanExecutionError> {
    let scope = persistent_cleanup_scope_for_workflow(contract, workflow_name);
    clean_execution_report_inner(contract, contract_path, Some(&scope))
        .map_err(classify_clean_execution_error)
}

fn clean_execution_report_inner(
    contract: &Contract,
    contract_path: &Path,
    cleanup_scope: Option<&PersistentCleanupScope>,
) -> Result<CleanExecutionReport, RunError> {
    let clean_task_name = OTA_CLEAN_INTERNAL_TASK_NAME;
    let working_dir = contract_working_dir(contract_path);
    ensure_no_active_repo_execution_conflicts(clean_task_name, working_dir, cleanup_scope)?;
    let host_services_to_stop = host_managed_services_for_cleanup(contract, cleanup_scope);
    let cleanup_targets = persistent_cleanup_targets(contract, cleanup_scope)?;
    let repo_ownership_token = repo_ownership_token("clean", contract_path)?;
    let mut report = CleanExecutionReport::default();
    for service_name in host_services_to_stop {
        let service = contract
            .services
            .get(service_name.as_str())
            .expect("selected host-managed cleanup service should exist");
        if service.stop_command(service_name.as_str()).is_none() {
            continue;
        }
        match run_service_stop_command(
            service_name.as_str(),
            service,
            working_dir,
            TaskExecutionMode::CaptureActivation,
        ) {
            Ok(output) if output.exit_code == 0 => {
                report.stopped_host_services += 1;
                report.host_services.push(service_name);
            }
            Ok(output) => {
                return Err(RunError::HostServiceCleanupFailure {
                    task: clean_task_name.to_string(),
                    action: String::from("stop"),
                    service: service_name,
                    details: format!(
                        "stop command exited with code {}{}",
                        output.exit_code,
                        render_cleanup_command_output_detail(&output)
                    ),
                });
            }
            Err(error) => {
                return Err(RunError::HostServiceCleanupFailure {
                    task: clean_task_name.to_string(),
                    action: String::from("stop"),
                    service: service_name,
                    details: error,
                });
            }
        }
    }
    let mut visited = BTreeSet::new();
    let mut current_target_engines = BTreeSet::new();
    let mut relevant_engines = BTreeSet::new();
    relevant_engines.extend(repo_managed_engines("clean", working_dir)?);
    let mut current_dependency_isolation_volumes_to_remove =
        BTreeMap::<String, BTreeSet<String>>::new();
    let mut drift_dependency_isolation_volumes_to_remove =
        BTreeMap::<String, BTreeSet<String>>::new();
    for (
        context_name,
        shared_local_backend_name,
        image,
        engine,
        publications,
        dependency_isolation_paths,
        memory_bytes,
        cleanup_container,
    ) in cleanup_targets
    {
        current_target_engines.insert(engine.clone());
        relevant_engines.insert(engine.clone());
        let identity_seed = container_identity_seed(
            context_name.as_deref(),
            shared_local_backend_name.as_deref(),
            &publications,
            &dependency_isolation_paths,
            memory_bytes,
        );
        let container_name = persistent_container_name_for_seed(
            working_dir,
            &image,
            &engine,
            identity_seed.as_deref(),
        );
        if !visited.insert((engine.clone(), container_name.clone())) {
            continue;
        }

        let dependency_volume_names = container_dependency_isolation_volume_names(
            working_dir,
            context_name.as_deref(),
            &image,
            &engine,
            &repo_ownership_token,
            &dependency_isolation_paths,
        );
        for volume_name in dependency_volume_names {
            current_dependency_isolation_volumes_to_remove
                .entry(engine.clone())
                .or_default()
                .insert(volume_name);
        }
        if !cleanup_container {
            continue;
        }

        if remove_persistent_container_if_present(clean_task_name, &engine, &container_name)? {
            report.removed_current_persistent_containers += 1;
        }
    }

    let mut first_discovery_error = None;
    let has_recorded_relevant_engines = !relevant_engines.is_empty();
    let discovery_engines = if has_recorded_relevant_engines {
        relevant_engines.into_iter().collect::<Vec<_>>()
    } else if !current_target_engines.is_empty() {
        current_target_engines.iter().cloned().collect::<Vec<_>>()
    } else {
        available_container_engines()
    };
    let strict_discovery = has_recorded_relevant_engines || !current_target_engines.is_empty();
    let mut engines_to_track = BTreeSet::new();
    report.queried_engines = discovery_engines.clone();
    for engine in discovery_engines {
        let mut engine_query_succeeded = false;
        match persistent_container_names_for_repo(clean_task_name, &engine, &repo_ownership_token) {
            Ok(container_names) => {
                engine_query_succeeded = true;
                for container_name in container_names {
                    if !visited.insert((engine.clone(), container_name.clone())) {
                        continue;
                    }
                    if remove_persistent_container_if_present(
                        clean_task_name,
                        &engine,
                        &container_name,
                    )? {
                        report.removed_drift_persistent_containers += 1;
                    }
                }
            }
            Err(error) => {
                first_discovery_error.get_or_insert(error);
                engines_to_track.insert(engine.clone());
            }
        }
        match dependency_isolation_volume_names_for_repo(
            clean_task_name,
            &engine,
            &repo_ownership_token,
        ) {
            Ok(volume_names) => {
                engine_query_succeeded = true;
                for volume_name in volume_names {
                    drift_dependency_isolation_volumes_to_remove
                        .entry(engine.clone())
                        .or_default()
                        .insert(volume_name);
                }
            }
            Err(error) => {
                first_discovery_error.get_or_insert(error);
                engines_to_track.insert(engine.clone());
            }
        }

        if engine_query_succeeded {
            match repo_scoped_legacy_persistent_container_names(
                clean_task_name,
                &engine,
                working_dir,
            ) {
                Ok(legacy) => {
                    if !legacy.is_empty() {
                        engines_to_track.insert(engine.clone());
                    }
                }
                Err(error) => {
                    first_discovery_error.get_or_insert(error);
                    engines_to_track.insert(engine.clone());
                }
            }
        }
    }

    let mut dependency_isolation_volumes_to_remove =
        current_dependency_isolation_volumes_to_remove.clone();
    for (engine, volume_names) in &drift_dependency_isolation_volumes_to_remove {
        dependency_isolation_volumes_to_remove
            .entry(engine.clone())
            .or_default()
            .extend(volume_names.iter().cloned());
    }

    for (engine, volume_names) in &dependency_isolation_volumes_to_remove {
        for container_name in containers_attached_to_dependency_isolation_volumes(
            clean_task_name,
            engine,
            volume_names,
        )? {
            if !visited.insert((engine.clone(), container_name.clone())) {
                continue;
            }
            if remove_persistent_container_if_present(clean_task_name, engine, &container_name)? {
                report.removed_drift_attached_containers += 1;
            }
        }
    }

    if let Some(error) = first_discovery_error
        && strict_discovery
    {
        return Err(error);
    }

    for (engine, volume_names) in current_dependency_isolation_volumes_to_remove {
        for volume_name in volume_names {
            if remove_dependency_isolation_volume(clean_task_name, &engine, &volume_name)? {
                report.removed_current_dependency_isolation_volumes += 1;
            }
        }
    }

    for (engine, volume_names) in drift_dependency_isolation_volumes_to_remove {
        for volume_name in volume_names {
            if remove_dependency_isolation_volume(clean_task_name, &engine, &volume_name)? {
                report.removed_drift_dependency_isolation_volumes += 1;
            }
        }
    }

    write_repo_managed_engines("clean", working_dir, &engines_to_track)?;

    Ok(report)
}

pub fn clean_stale_execution(
    dry_run: bool,
) -> Result<StaleContainerCleanupReport, CleanExecutionError> {
    clean_stale_execution_inner(dry_run).map_err(classify_clean_execution_error)
}

fn clean_stale_execution_inner(dry_run: bool) -> Result<StaleContainerCleanupReport, RunError> {
    let engines = available_container_engines();
    let mut containers = Vec::new();
    let mut query_error = None;
    let mut queried_engines = 0usize;

    for engine in &engines {
        match list_stale_ota_containers(engine) {
            Ok(found) => {
                queried_engines += 1;
                containers.extend(found);
            }
            Err(error) => {
                query_error.get_or_insert(error);
            }
        }
    }

    if !dry_run {
        for container in &containers {
            let _ = remove_persistent_container(&container.engine, &container.name, "clean")?;
        }
    }

    if queried_engines == 0
        && let Some(error) = query_error
    {
        return Err(error);
    }

    Ok(StaleContainerCleanupReport {
        engines,
        containers,
    })
}

fn classify_clean_execution_error(error: RunError) -> CleanExecutionError {
    match error {
        RunError::PersistentContainerCleanupFailure {
            action,
            container,
            engine,
            details,
            ..
        } => CleanExecutionError::Cleanup(CleanExecutionFailure {
            action,
            resource_kind: CleanExecutionResourceKind::PersistentContainer,
            resource_name: Some(container),
            reason: classify_clean_execution_failure_reason(details.as_str()),
            engine,
            details,
        }),
        RunError::HostServiceCleanupFailure {
            action,
            service,
            details,
            ..
        } => CleanExecutionError::Cleanup(CleanExecutionFailure {
            action,
            resource_kind: CleanExecutionResourceKind::HostService,
            resource_name: Some(service),
            reason: CleanExecutionFailureReason::Other,
            engine: String::from("host"),
            details,
        }),
        RunError::DependencyIsolationVolumeFailure {
            action,
            volume,
            engine,
            details,
            ..
        } => CleanExecutionError::Cleanup(CleanExecutionFailure {
            action,
            resource_kind: CleanExecutionResourceKind::DependencyIsolationVolume,
            resource_name: Some(volume),
            reason: classify_clean_execution_failure_reason(details.as_str()),
            engine,
            details,
        }),
        RunError::StaleContainerQueryFailed { engine, details } => {
            CleanExecutionError::Cleanup(CleanExecutionFailure {
                action: String::from("list"),
                resource_kind: CleanExecutionResourceKind::StaleContainers,
                resource_name: None,
                reason: classify_clean_execution_failure_reason(details.as_str()),
                engine,
                details,
            })
        }
        other => CleanExecutionError::Other(other),
    }
}

fn classify_clean_execution_failure_reason(details: &str) -> CleanExecutionFailureReason {
    let lowered = details.to_ascii_lowercase();
    if lowered.contains("cannot connect to podman")
        || lowered.contains("unable to connect to podman socket")
        || lowered.contains("docker daemon is not running")
        || lowered.contains("cannot connect to the docker daemon")
        || lowered.contains("failed to connect to the docker api")
        || lowered.contains("is the docker daemon running")
        || lowered.contains("if the daemon is running")
        || lowered.contains("pipe/docker_engine")
        || lowered.contains("error while dialing")
        || lowered.contains("connection refused")
    {
        return CleanExecutionFailureReason::EngineUnavailable;
    }
    CleanExecutionFailureReason::Other
}

fn remove_persistent_container_if_present(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Result<bool, RunError> {
    let inspect = container_command_output(engine, &["inspect", container_name], None, task_name)?;
    if inspect.exit_code != 0 {
        return Ok(false);
    }

    let remove = remove_persistent_container(engine, container_name, task_name)?;
    if remove.exit_code == 0 {
        return Ok(true);
    }

    Err(RunError::PersistentContainerCleanupFailure {
        task: task_name.to_string(),
        action: String::from("remove"),
        container: container_name.to_string(),
        engine: engine.to_string(),
        details: container_command_failure_details(engine, &["rm", "-f", container_name], &remove),
    })
}

fn persistent_cleanup_targets(
    contract: &Contract,
    cleanup_scope: Option<&PersistentCleanupScope>,
) -> Result<
    Vec<(
        Option<String>,
        Option<String>,
        String,
        String,
        Vec<ContainerPortPublication>,
        Vec<String>,
        Option<u64>,
        bool,
    )>,
    RunError,
> {
    let mut targets = Vec::new();
    if let Some(execution) = contract.execution.as_ref() {
        for (name, context) in &execution.contexts {
            if cleanup_scope.is_some_and(|scope| !scope.context_names.contains(name.as_str())) {
                continue;
            }
            if context.backend != Backend::Container {
                continue;
            }
            let Some(container) = context.container.as_ref() else {
                return Err(RunError::MissingContainerImage {
                    task: format!("context:{name}"),
                });
            };
            let engine =
                selected_container_engine_from_backend(Some(container)).ok_or_else(|| {
                    RunError::MissingContainerBackendCli {
                        task: format!("context:{name}"),
                        engines: container_engine_candidates_from_backend(Some(container))
                            .join(", "),
                    }
                })?;
            let dependency_isolation_paths = context_dependency_isolation_paths(context);
            if context.lifecycle == Some(Lifecycle::Persistent) {
                for publications in
                    task_container_publication_sets_for_context(contract, Some(name))
                {
                    let memory_field_prefix = format!("execution.contexts.{name}.container");
                    let memory_bytes = container_memory_override_or_default(
                        "clean",
                        container,
                        memory_field_prefix.as_str(),
                        None,
                    )?;
                    targets.push((
                        Some(name.clone()),
                        None,
                        container.image.clone(),
                        engine.clone(),
                        publications,
                        dependency_isolation_paths.clone(),
                        memory_bytes,
                        true,
                    ));
                }
            } else if !dependency_isolation_paths.is_empty() {
                let memory_field_prefix = format!("execution.contexts.{name}.container");
                let memory_bytes = container_memory_override_or_default(
                    "clean",
                    container,
                    memory_field_prefix.as_str(),
                    None,
                )?;
                targets.push((
                    Some(name.clone()),
                    None,
                    container.image.clone(),
                    engine.clone(),
                    Vec::new(),
                    dependency_isolation_paths.clone(),
                    memory_bytes,
                    false,
                ));
            }
        }

        for (shared_backend_name, shared_backend) in &execution.shared_backends {
            if shared_backend.backend != Backend::Container {
                continue;
            }

            let context_name = shared_backend.context.clone().or_else(|| {
                contract.tasks.iter().find_map(|(task_name, task)| {
                    (task.backend_binding_for_backend(Backend::Container)
                        == Some(shared_backend_name.as_str()))
                    .then(|| {
                        selected_task_context_for_backend(contract, task_name, Backend::Container)
                            .map(|(name, _)| name.to_string())
                    })
                    .flatten()
                })
            });
            if let Some(scope) = cleanup_scope {
                let scoped_by_backend = scope
                    .shared_backend_names
                    .contains(shared_backend_name.as_str());
                let scoped_by_context = context_name
                    .as_deref()
                    .is_some_and(|context_name| scope.context_names.contains(context_name));
                if !scoped_by_backend && !scoped_by_context {
                    continue;
                }
            }
            let context = context_name.as_deref().and_then(|context_name| {
                execution
                    .contexts
                    .get(context_name)
                    .filter(|context| context.backend == Backend::Container)
            });
            let container = context
                .and_then(|context| context.container.as_ref())
                .or_else(|| {
                    execution
                        .backends
                        .as_ref()
                        .and_then(|backends| backends.container.as_ref())
                })
                .ok_or_else(|| RunError::MissingContainerImage {
                    task: format!("shared_backend:{shared_backend_name}"),
                })?;
            let engine =
                selected_container_engine_from_backend(Some(container)).ok_or_else(|| {
                    RunError::MissingContainerBackendCli {
                        task: format!("shared_backend:{shared_backend_name}"),
                        engines: container_engine_candidates_from_backend(Some(container))
                            .join(", "),
                    }
                })?;
            let dependency_isolation_paths = context
                .map(context_dependency_isolation_paths)
                .unwrap_or_default();
            let memory_field_prefix = context_name
                .as_deref()
                .map(|context_name| format!("execution.contexts.{context_name}.container"))
                .unwrap_or_else(|| String::from("execution.backends.container"));
            let memory_bytes = container_memory_override_or_default(
                "clean",
                container,
                memory_field_prefix.as_str(),
                None,
            )?;

            if shared_backend.lifecycle == Lifecycle::Persistent {
                let target = (
                    context_name.clone(),
                    Some(shared_backend_name.clone()),
                    container.image.clone(),
                    engine.clone(),
                    shared_local_backend_publications(contract, shared_backend_name),
                    dependency_isolation_paths.clone(),
                    memory_bytes,
                    true,
                );
                if !targets.contains(&target) {
                    targets.push(target);
                }
            } else if !dependency_isolation_paths.is_empty() {
                let target = (
                    context_name.clone(),
                    Some(shared_backend_name.clone()),
                    container.image.clone(),
                    engine.clone(),
                    Vec::new(),
                    dependency_isolation_paths,
                    memory_bytes,
                    false,
                );
                if !targets.contains(&target) {
                    targets.push(target);
                }
            }
        }
    }

    let (backend, lifecycle) = effective_execution(contract, ExecutionOverrides::default());
    if backend == Backend::Container && lifecycle == Some(Lifecycle::Persistent) {
        let image = execution_image(contract, Backend::Container).ok_or(
            RunError::MissingContainerImage {
                task: String::from("clean"),
            },
        )?;
        let engine = selected_container_engine(contract).ok_or_else(|| {
            RunError::MissingContainerBackendCli {
                task: String::from("clean"),
                engines: container_engine_candidates(contract).join(", "),
            }
        })?;
        for publications in task_container_publication_sets_for_context(contract, None) {
            let memory_bytes = contract
                .execution
                .as_ref()
                .and_then(|execution| execution.backends.as_ref())
                .and_then(|backends| backends.container.as_ref())
                .map(|container| {
                    container_memory_override_or_default(
                        "clean",
                        container,
                        "execution.backends.container",
                        None,
                    )
                })
                .transpose()?
                .flatten();
            let target = (
                Some(LEGACY_EXECUTION_CONTEXT_NAME.to_string()),
                None,
                image.clone(),
                engine.clone(),
                publications,
                Vec::new(),
                memory_bytes,
                true,
            );
            if !targets.contains(&target) {
                targets.push(target);
            }
        }
    }
    Ok(targets)
}

#[derive(Debug, Default)]
struct PersistentCleanupScope {
    task_names: BTreeSet<String>,
    context_names: BTreeSet<String>,
    shared_backend_names: BTreeSet<String>,
    service_names: BTreeSet<String>,
    compose_projects: BTreeSet<String>,
    persistent_backend_families: BTreeSet<String>,
    env_materialization_paths: BTreeSet<String>,
}

fn persistent_cleanup_scope_for_workflow(
    contract: &Contract,
    workflow_name: Option<&str>,
) -> PersistentCleanupScope {
    let mut scope = PersistentCleanupScope::default();
    scope.service_names = required_service_closure(
        contract,
        &contract.selected_workflow_required_service_names(workflow_name),
    );
    for task_name in contract.selected_workflow_task_closure_names(workflow_name) {
        scope.task_names.insert(task_name.clone());
        let effective =
            effective_task_execution(contract, task_name.as_str(), ExecutionOverrides::default());
        let backend =
            resolve_execution_backend(contract, task_name.as_str(), ExecutionOverrides::default())
                .ok();
        if let Some(backend) = backend.as_ref() {
            let owner = repo_execution_lock_owner_for_backend(
                contract,
                task_name.as_str(),
                ExecutionOverrides::default(),
                backend,
            );
            scope.compose_projects.extend(owner.compose_projects);
            scope
                .persistent_backend_families
                .extend(owner.persistent_backend_families);
            scope
                .env_materialization_paths
                .extend(owner.env_materialization_paths);
        }
        if effective.backend != Backend::Container {
            continue;
        }
        if let Some(task) = contract.tasks.get(task_name.as_str())
            && let Some(binding_name) = task.backend_binding_for_backend(Backend::Container)
        {
            scope.shared_backend_names.insert(binding_name.to_string());
        }
        if let Some(context_name) = effective.context_name {
            scope.context_names.insert(context_name.to_string());
        }
    }
    scope
}

fn host_managed_services_for_cleanup(
    contract: &Contract,
    cleanup_scope: Option<&PersistentCleanupScope>,
) -> Vec<String> {
    let mut names = match cleanup_scope {
        Some(scope) => scope.service_names.iter().cloned().collect::<Vec<_>>(),
        None => contract.services.keys().cloned().collect::<Vec<_>>(),
    };
    names.retain(|service_name| {
        contract
            .services
            .get(service_name.as_str())
            .is_some_and(crate::schema::ServiceSpec::uses_host_lifecycle_owner)
    });
    names
}

fn list_stale_ota_containers(engine: &str) -> Result<Vec<StaleContainerCleanupTarget>, RunError> {
    let mut containers = Vec::new();
    let mut seen = BTreeSet::new();

    for name in container_ps_names(
        engine,
        &[
            "ps",
            "-a",
            "--filter",
            &format!("label={OTA_MANAGED_CONTAINER_LABEL}"),
            "--filter",
            "status=exited",
            "--filter",
            "status=dead",
            "--format",
            "{{.Names}}",
        ],
    )? {
        if seen.insert(name.clone()) {
            containers.push(StaleContainerCleanupTarget {
                engine: engine.to_string(),
                name,
                ownership: StaleContainerOwnership::Label,
            });
        }
    }

    for name in container_ps_names(
        engine,
        &[
            "ps",
            "-a",
            "--filter",
            "status=exited",
            "--filter",
            "status=dead",
            "--format",
            "{{.Names}}",
        ],
    )? {
        if !name.starts_with("ota-") || !seen.insert(name.clone()) {
            continue;
        }
        containers.push(StaleContainerCleanupTarget {
            engine: engine.to_string(),
            name,
            ownership: StaleContainerOwnership::LegacyName,
        });
    }

    Ok(containers)
}

fn container_ps_names(engine: &str, args: &[&str]) -> Result<Vec<String>, RunError> {
    let output = container_command_output(engine, args, None, OTA_ENGINE_CLEAN_QUERY_TASK_NAME)?;
    if output.exit_code != 0 {
        let details = if !output.stderr.trim().is_empty() {
            output.stderr.trim().to_string()
        } else if !output.stdout.trim().is_empty() {
            output.stdout.trim().to_string()
        } else {
            format!(
                "`{engine} {}` exited with status {}",
                args.join(" "),
                output.exit_code
            )
        };
        return Err(RunError::StaleContainerQueryFailed {
            engine: engine.to_string(),
            details,
        });
    }

    Ok(output
        .stdout
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(String::from)
        .collect())
}

fn persistent_container_names_for_repo(
    task_name: &str,
    engine: &str,
    repo_ownership_token: &str,
) -> Result<Vec<String>, RunError> {
    let repo_label = format!("{OTA_REPO_CONTAINER_LABEL_KEY}={repo_ownership_token}");
    let repo_owned = container_names_for_label(task_name, engine, &repo_label)?;
    let managed = container_names_for_label(task_name, engine, OTA_MANAGED_CONTAINER_LABEL)?;
    let persistent = container_names_for_label(task_name, engine, OTA_PERSISTENT_CONTAINER_LABEL)?;

    Ok(repo_owned
        .into_iter()
        .filter(|name| managed.contains(name) && persistent.contains(name))
        .collect())
}

fn container_names_for_label(
    task_name: &str,
    engine: &str,
    label: &str,
) -> Result<BTreeSet<String>, RunError> {
    let filter = format!("label={label}");
    let args = [
        "ps",
        "-a",
        "--filter",
        filter.as_str(),
        "--format",
        "{{.Names}}",
    ];
    let output = container_command_output(engine, &args, None, task_name)?;
    if output.exit_code != 0 {
        return Err(RunError::PersistentContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("list"),
            container: label.to_string(),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &output),
        });
    }

    Ok(output
        .stdout
        .lines()
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(String::from)
        .collect())
}

