fn execute_ensure_env_file_action(
    contract: Option<&Contract>,
    task_name: &str,
    spec: &crate::schema::TaskEnsureEnvFileActionSpec,
    working_dir: &Path,
    env_overrides: &BTreeMap<String, String>,
) -> Result<TaskCommandOutput, RunError> {
    let path = working_dir.join(spec.path.trim());
    let mut created = false;
    let mut reseeded = false;
    if !path.exists() {
        if let Some(parent) = path.parent()
            && !parent.exists()
        {
            std::fs::create_dir_all(parent).map_err(|source| RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "could not create parent directory for `{}`: {source}",
                    spec.path.trim()
                ),
            })?;
        }
        if let Some(template) = spec.template.as_deref() {
            let template_path = working_dir.join(template.trim());
            if !template_path.is_file() {
                return Err(RunError::FileActionFailed {
                    task: task_name.to_string(),
                    message: format!("template `{}` is not a file", template.trim()),
                });
            }
            std::fs::copy(&template_path, &path).map_err(|source| RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "could not copy template `{}` to `{}`: {source}",
                    template.trim(),
                    spec.path.trim()
                ),
            })?;
        } else {
            std::fs::write(&path, "").map_err(|source| RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!("could not create `{}`: {source}", spec.path.trim()),
            })?;
        }
        created = true;
    } else if matches!(
        spec.template_mode,
        crate::schema::TaskEnsureEnvFileTemplateMode::Replace
    ) {
        let Some(template) = spec.template.as_deref() else {
            return Err(RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "action `ensure_env_file` for `{}` must declare `template` when `template_mode: replace` is used",
                    spec.path.trim()
                ),
            });
        };
        let template_path = working_dir.join(template.trim());
        if !template_path.is_file() {
            return Err(RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!("template `{}` is not a file", template.trim()),
            });
        }
        std::fs::copy(&template_path, &path).map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not recopy template `{}` to `{}`: {source}",
                template.trim(),
                spec.path.trim(),
            ),
        })?;
        reseeded = true;
    }

    let content = std::fs::read_to_string(&path).map_err(|source| RunError::FileActionFailed {
        task: task_name.to_string(),
        message: format!("could not read `{}`: {source}", spec.path.trim()),
    })?;
    let existing_keys = parse_env_keys(content.as_str());
    let declared_env = if spec
        .vars
        .values()
        .any(|value_spec| value_spec.from_env.is_some())
    {
        let Some(contract) = contract else {
            return Err(RunError::FileActionFailed {
                task: task_name.to_string(),
                message: String::from(
                    "action `ensure_env_file` with `from_env` requires contract-backed env resolution",
                ),
            });
        };
        Some(resolve_task_env_details_for_task(
            contract,
            working_dir,
            task_name,
            Some(env_overrides),
        )?)
    } else {
        None
    };
    let mut updates = Vec::<(String, Option<String>, crate::schema::TaskEnsureEnvVarMode)>::new();
    for (key, value_spec) in &spec.vars {
        match value_spec.mode {
            crate::schema::TaskEnsureEnvVarMode::Missing => {
                if existing_keys.contains(key.as_str()) {
                    continue;
                }
            }
            crate::schema::TaskEnsureEnvVarMode::Remove => {
                updates.push((key.clone(), None, value_spec.mode));
                continue;
            }
            crate::schema::TaskEnsureEnvVarMode::Replace => {}
        }
        let value = resolve_ensure_env_var_value(
            task_name,
            key.as_str(),
            value_spec,
            declared_env.as_ref(),
        )?;
        updates.push((key.clone(), Some(value), value_spec.mode));
    }

    let (next_content, replaced_count, appended_count, removed_count) =
        apply_ensure_env_updates(content.as_str(), &updates);
    if next_content != content {
        std::fs::write(&path, next_content).map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not update `{}`: {source}", spec.path.trim()),
        })?;
    }

    let summary = if created {
        format!(
            "ensured `{}` (created), appended {} env key(s), replaced {} env key(s), removed {} env key(s)\n",
            spec.path.trim(),
            appended_count,
            replaced_count,
            removed_count
        )
    } else if reseeded {
        format!(
            "ensured `{}` (reseeded from template), appended {} env key(s), replaced {} env key(s), removed {} env key(s)\n",
            spec.path.trim(),
            appended_count,
            replaced_count,
            removed_count
        )
    } else {
        format!(
            "ensured `{}`, appended {} env key(s), replaced {} env key(s), removed {} env key(s)\n",
            spec.path.trim(),
            appended_count,
            replaced_count,
            removed_count
        )
    };
    Ok(file_action_output(summary))
}

fn execute_ensure_file_action(
    task_name: &str,
    spec: &crate::schema::TaskEnsureFileActionSpec,
    working_dir: &Path,
) -> Result<TaskCommandOutput, RunError> {
    let path = working_dir.join(spec.path.trim());
    if path.exists() {
        return Ok(file_action_output(format!(
            "`{}` already exists; no write needed\n",
            spec.path.trim()
        )));
    }
    if let Some(parent) = path.parent()
        && !parent.exists()
    {
        std::fs::create_dir_all(parent).map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not create parent directory for `{}`: {source}",
                spec.path.trim()
            ),
        })?;
    }

    let created_message = if let Some(template) = spec.template.as_deref() {
        let template_path = working_dir.join(template.trim());
        if !template_path.is_file() {
            return Err(RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!("template `{}` is not a file", template.trim()),
            });
        }
        std::fs::copy(&template_path, &path).map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not copy template `{}` to `{}`: {source}",
                template.trim(),
                spec.path.trim()
            ),
        })?;
        format!(
            "ensured `{}` from template `{}`\n",
            spec.path.trim(),
            template.trim()
        )
    } else {
        let content = if let Some(value) = spec.value.as_deref() {
            value.to_string()
        } else if let Some(random) = spec.random.as_ref() {
            let mut buffer = vec![0_u8; random.bytes];
            getrandom::getrandom(&mut buffer).map_err(|source| RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "could not generate random content for `{}`: {source}",
                    spec.path.trim()
                ),
            })?;
            match random.encoding {
                crate::schema::TaskEnsureEnvRandomEncoding::Hex => encode_hex(buffer.as_slice()),
                crate::schema::TaskEnsureEnvRandomEncoding::Base64 => {
                    encode_base64(buffer.as_slice())
                }
            }
        } else {
            return Err(RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "action `ensure_file` for `{}` must declare one of `template`, `value`, or `random`",
                    spec.path.trim()
                ),
            });
        };
        std::fs::write(&path, content).map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not write `{}`: {source}", spec.path.trim()),
        })?;
        format!("ensured `{}`\n", spec.path.trim())
    };

    Ok(file_action_output(created_message))
}

fn execute_ensure_directory_action(
    task_name: &str,
    spec: &crate::schema::TaskEnsureDirectoryActionSpec,
    working_dir: &Path,
) -> Result<TaskCommandOutput, RunError> {
    let path = working_dir.join(spec.path.trim());
    if path.exists() {
        if path.is_dir() {
            return Ok(file_action_output(format!(
                "`{}` already exists; no directory create needed\n",
                spec.path.trim()
            )));
        }
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not ensure directory `{}` because a non-directory entry already exists at that path",
                spec.path.trim()
            ),
        });
    }
    std::fs::create_dir_all(&path).map_err(|source| RunError::FileActionFailed {
        task: task_name.to_string(),
        message: format!(
            "could not create directory `{}`: {source}",
            spec.path.trim()
        ),
    })?;
    Ok(file_action_output(format!(
        "ensured directory `{}`\n",
        spec.path.trim()
    )))
}

fn execute_ensure_container_network_action(
    task_name: &str,
    spec: &crate::schema::TaskEnsureContainerNetworkActionSpec,
) -> Result<TaskCommandOutput, RunError> {
    let name = spec.name.trim();
    if name.is_empty() {
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: String::from(
                "action `ensure_container_network` must declare a non-empty `name`",
            ),
        });
    }

    let provider = spec.provider.label();
    let inspect_output = Command::new(provider)
        .args(["network", "inspect", name])
        .output()
        .map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not inspect {provider} container network `{name}`: {source}"),
        })?;
    if inspect_output.status.success() {
        return Ok(file_action_output(format!(
            "{provider} container network `{name}` already exists; no create needed\n"
        )));
    }

    let create_output = Command::new(provider)
        .args(["network", "create", name])
        .output()
        .map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not create {provider} container network `{name}`: {source}"),
        })?;
    if !create_output.status.success() {
        let stderr = String::from_utf8_lossy(&create_output.stderr)
            .trim()
            .to_string();
        let stdout = String::from_utf8_lossy(&create_output.stdout)
            .trim()
            .to_string();
        let details = if !stderr.is_empty() {
            stderr
        } else if !stdout.is_empty() {
            stdout
        } else {
            format!("exit status {}", create_output.status)
        };
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not create {provider} container network `{name}`: {details}"),
        });
    }

    Ok(file_action_output(format!(
        "ensured {provider} container network `{name}`\n"
    )))
}

fn execute_reset_compose_service_volume_action(
    task_name: &str,
    spec: &crate::schema::TaskResetComposeServiceVolumeActionSpec,
    working_dir: &Path,
) -> Result<TaskCommandOutput, RunError> {
    let service = spec.service.trim();
    if service.is_empty() {
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: String::from(
                "action `reset_compose_service_volume` must declare a non-empty `service`",
            ),
        });
    }
    let volume = spec.volume.trim();
    if volume.is_empty() {
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: String::from(
                "action `reset_compose_service_volume` must declare a non-empty `volume`",
            ),
        });
    }

    let provider = spec.provider.label();
    let compose_env = compose_action_env_bindings(&spec.compose);
    let compose_dir = compose_action_working_dir(working_dir, &spec.compose);
    let mut stdout = String::new();

    if let Some(message) = run_compose_service_reset_step(
        task_name,
        provider,
        &compose_dir,
        &compose_env,
        ["compose", "stop", service],
        format!("stop compose service `{service}`"),
        true,
    )? {
        stdout.push_str(message.as_str());
    }
    if let Some(message) = run_compose_service_reset_step(
        task_name,
        provider,
        &compose_dir,
        &compose_env,
        ["compose", "rm", "-f", service],
        format!("remove compose service `{service}`"),
        false,
    )? {
        stdout.push_str(message.as_str());
    }
    if let Some(message) = remove_remaining_compose_service_containers(
        task_name,
        provider,
        &compose_dir,
        &compose_env,
        service,
    )? {
        stdout.push_str(message.as_str());
    }
    if let Some(message) = remove_remaining_volume_attached_containers(task_name, provider, volume)?
    {
        stdout.push_str(message.as_str());
    }

    let inspect_output = Command::new(provider)
        .args(["volume", "inspect", volume])
        .output()
        .map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not inspect {provider} volume `{volume}`: {source}"),
        })?;
    if inspect_output.status.success() {
        let remove_output = Command::new(provider)
            .args(["volume", "rm", "-f", volume])
            .output()
            .map_err(|source| RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!("could not remove {provider} volume `{volume}`: {source}"),
            })?;
        if !remove_output.status.success() {
            return Err(RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "could not remove {provider} volume `{volume}`: {}",
                    rendered_process_failure(&remove_output)
                ),
            });
        }
        stdout.push_str(format!("removed {provider} volume `{volume}`\n").as_str());
    } else {
        stdout.push_str(
            format!("{provider} volume `{volume}` was absent; no volume remove needed\n").as_str(),
        );
    }

    let up_output = Command::new(provider)
        .current_dir(&compose_dir)
        .envs(&compose_env)
        .args(["compose", "up", "-d", service])
        .output()
        .map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not restart {provider} compose service `{service}`: {source}"),
        })?;
    if !up_output.status.success() {
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not restart {provider} compose service `{service}`: {}",
                rendered_process_failure(&up_output)
            ),
        });
    }
    stdout.push_str(format!("restarted {provider} compose service `{service}`\n").as_str());

    Ok(file_action_output(stdout))
}

fn remove_remaining_compose_service_containers(
    task_name: &str,
    provider: &str,
    compose_dir: &Path,
    compose_env: &BTreeMap<String, String>,
    service: &str,
) -> Result<Option<String>, RunError> {
    let output = Command::new(provider)
        .current_dir(compose_dir)
        .envs(compose_env)
        .args(["compose", "ps", "-aq", service])
        .output()
        .map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not inspect remaining compose service containers for `{service}`: {source}"
            ),
        })?;
    if !output.status.success() {
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not inspect remaining compose service containers for `{service}`: {}",
                rendered_process_failure(&output)
            ),
        });
    }
    let container_ids = String::from_utf8_lossy(&output.stdout)
        .lines()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect::<Vec<_>>();
    if container_ids.is_empty() {
        return Ok(None);
    }

    let mut removed = Vec::new();
    for container_id in container_ids {
        let rm_output = Command::new(provider)
            .args(["container", "rm", "-f", &container_id])
            .output()
            .map_err(|source| RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "could not remove remaining {provider} container `{container_id}` for compose service `{service}`: {source}"
                ),
            })?;
        if !rm_output.status.success() {
            return Err(RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "could not remove remaining {provider} container `{container_id}` for compose service `{service}`: {}",
                    rendered_process_failure(&rm_output)
                ),
            });
        }
        removed.push(container_id);
    }

    Ok(Some(format!(
        "removed remaining {provider} compose service containers for `{service}`: {}\n",
        removed.join(", ")
    )))
}

fn remove_remaining_volume_attached_containers(
    task_name: &str,
    provider: &str,
    volume: &str,
) -> Result<Option<String>, RunError> {
    let output = Command::new(provider)
        .args(["ps", "-aq", "--filter", &format!("volume={volume}")])
        .output()
        .map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not inspect remaining {provider} containers attached to volume `{volume}`: {source}"
            ),
        })?;
    if !output.status.success() {
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not inspect remaining {provider} containers attached to volume `{volume}`: {}",
                rendered_process_failure(&output)
            ),
        });
    }
    let container_ids = String::from_utf8_lossy(&output.stdout)
        .lines()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect::<Vec<_>>();
    if container_ids.is_empty() {
        return Ok(None);
    }

    let mut removed = Vec::new();
    for container_id in container_ids {
        let rm_output = Command::new(provider)
            .args(["container", "rm", "-f", &container_id])
            .output()
            .map_err(|source| RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "could not remove remaining {provider} container `{container_id}` attached to volume `{volume}`: {source}"
                ),
            })?;
        if !rm_output.status.success() {
            return Err(RunError::FileActionFailed {
                task: task_name.to_string(),
                message: format!(
                    "could not remove remaining {provider} container `{container_id}` attached to volume `{volume}`: {}",
                    rendered_process_failure(&rm_output)
                ),
            });
        }
        removed.push(container_id);
    }

    Ok(Some(format!(
        "removed remaining {provider} containers attached to volume `{volume}`: {}\n",
        removed.join(", ")
    )))
}

fn compose_action_working_dir(
    working_dir: &Path,
    compose: &crate::schema::TaskComposeAdapterInputsSpec,
) -> std::path::PathBuf {
    compose
        .cwd
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|cwd| working_dir.join(cwd))
        .unwrap_or_else(|| working_dir.to_path_buf())
}

fn compose_action_env_bindings(
    compose: &crate::schema::TaskComposeAdapterInputsSpec,
) -> BTreeMap<String, String> {
    let mut env = BTreeMap::new();
    let adapter_cwd = compose
        .cwd
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let rebase = |value: &str| {
        if let Some(cwd) = adapter_cwd {
            Path::new(value)
                .strip_prefix(cwd)
                .ok()
                .map(|path| path.to_string_lossy().replace('\\', "/"))
                .unwrap_or_else(|| value.trim().to_string())
        } else {
            value.trim().to_string()
        }
    };
    if !compose.env_files.is_empty() {
        env.insert(
            String::from("COMPOSE_ENV_FILES"),
            compose
                .env_files
                .iter()
                .map(|value| rebase(value))
                .collect::<Vec<_>>()
                .join(","),
        );
    }
    if !compose.files.is_empty() {
        let separator = if cfg!(windows) { ";" } else { ":" };
        env.insert(
            String::from("COMPOSE_FILE"),
            compose
                .files
                .iter()
                .map(|value| rebase(value))
                .collect::<Vec<_>>()
                .join(separator),
        );
    }
    if !compose.profiles.is_empty() {
        env.insert(
            String::from("COMPOSE_PROFILES"),
            compose
                .profiles
                .iter()
                .map(|value| value.trim())
                .filter(|value| !value.is_empty())
                .collect::<Vec<_>>()
                .join(","),
        );
    }
    if let Some(project_name) = compose
        .project_name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        env.insert(
            String::from("COMPOSE_PROJECT_NAME"),
            project_name.to_string(),
        );
    }
    env
}

fn run_compose_service_reset_step<const N: usize>(
    task_name: &str,
    provider: &str,
    compose_dir: &Path,
    compose_env: &BTreeMap<String, String>,
    args: [&str; N],
    label: String,
    best_effort: bool,
) -> Result<Option<String>, RunError> {
    let output = Command::new(provider)
        .current_dir(compose_dir)
        .envs(compose_env)
        .args(args)
        .output()
        .map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not {label}: {source}"),
        })?;
    if output.status.success() {
        return Ok(Some(format!("{label}\n")));
    }
    if !best_effort {
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not {label}: {}", rendered_process_failure(&output)),
        });
    }
    Ok(Some(format!(
        "{label} returned non-zero and was treated as best-effort: {}\n",
        rendered_process_failure(&output)
    )))
}

fn rendered_process_failure(output: &std::process::Output) -> String {
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if !stderr.is_empty() {
        stderr
    } else if !stdout.is_empty() {
        stdout
    } else {
        format!("exit status {}", output.status)
    }
}

fn parse_env_keys(content: &str) -> BTreeSet<String> {
    let mut keys = BTreeSet::new();
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let Some((raw_key, _)) = trimmed.split_once('=') else {
            continue;
        };
        let key = raw_key.trim();
        if !key.is_empty() {
            keys.insert(key.to_string());
        }
    }
    keys
}

pub(crate) fn apply_ensure_env_updates(
    content: &str,
    updates: &[(String, Option<String>, crate::schema::TaskEnsureEnvVarMode)],
) -> (String, usize, usize, usize) {
    if updates.is_empty() {
        return (content.to_string(), 0, 0, 0);
    }

    let mut lines = content.lines().map(str::to_string).collect::<Vec<_>>();
    let had_trailing_newline = content.ends_with('\n');
    let mut replaced = 0;
    let mut appended = 0;
    let mut removed = 0;

    for (key, value, mode) in updates {
        let mut matched_index = None;
        for (index, line) in lines.iter().enumerate() {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            let Some((raw_key, _)) = trimmed.split_once('=') else {
                continue;
            };
            if raw_key.trim() == key {
                matched_index = Some(index);
                break;
            }
        }

        match (mode, matched_index) {
            (crate::schema::TaskEnsureEnvVarMode::Replace, Some(index)) => {
                lines[index] = format!("{key}={}", value.as_deref().unwrap_or_default());
                replaced += 1;
            }
            (crate::schema::TaskEnsureEnvVarMode::Remove, Some(index)) => {
                lines.remove(index);
                removed += 1;
            }
            (crate::schema::TaskEnsureEnvVarMode::Remove, None) => {}
            (_, Some(_)) => {}
            _ => {
                lines.push(format!("{key}={}", value.as_deref().unwrap_or_default()));
                appended += 1;
            }
        }
    }

    let mut next = lines.join("\n");
    if had_trailing_newline || !next.is_empty() {
        next.push('\n');
    }
    (next, replaced, appended, removed)
}

fn resolve_ensure_env_var_value(
    task_name: &str,
    key: &str,
    value_spec: &crate::schema::TaskEnsureEnvVarSpec,
    declared_env: Option<&BTreeMap<String, ResolvedEnvValue>>,
) -> Result<String, RunError> {
    if let Some(value) = value_spec.value.as_deref() {
        return Ok(value.to_string());
    }
    if let Some(random) = value_spec.random.as_ref() {
        let bytes = random.bytes;
        let mut buffer = vec![0_u8; bytes];
        getrandom::getrandom(&mut buffer).map_err(|source| RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!("could not generate random value for env key `{key}`: {source}"),
        })?;
        return Ok(match random.encoding {
            crate::schema::TaskEnsureEnvRandomEncoding::Hex => encode_hex(buffer.as_slice()),
            crate::schema::TaskEnsureEnvRandomEncoding::Base64 => encode_base64(buffer.as_slice()),
        });
    }
    if let Some(from_env) = value_spec.from_env.as_deref() {
        if let Some(resolved) = declared_env.and_then(|values| values.get(from_env)) {
            return Ok(resolved.value.clone());
        }
        return Err(RunError::FileActionFailed {
            task: task_name.to_string(),
            message: format!(
                "could not resolve env source `{from_env}` for env key `{key}` while ensuring env file"
            ),
        });
    }
    Err(RunError::FileActionFailed {
        task: task_name.to_string(),
        message: format!(
            "env key `{key}` must declare one of `value`, `random`, or `from_env` in `action.vars`"
        ),
    })
}

fn encode_hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        use std::fmt::Write as _;
        let _ = write!(&mut out, "{byte:02x}");
    }
    out
}

fn encode_base64(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    let mut index = 0;
    while index + 3 <= bytes.len() {
        let chunk = ((bytes[index] as u32) << 16)
            | ((bytes[index + 1] as u32) << 8)
            | (bytes[index + 2] as u32);
        out.push(TABLE[((chunk >> 18) & 0x3f) as usize] as char);
        out.push(TABLE[((chunk >> 12) & 0x3f) as usize] as char);
        out.push(TABLE[((chunk >> 6) & 0x3f) as usize] as char);
        out.push(TABLE[(chunk & 0x3f) as usize] as char);
        index += 3;
    }
    let rem = bytes.len() - index;
    if rem == 1 {
        let chunk = (bytes[index] as u32) << 16;
        out.push(TABLE[((chunk >> 18) & 0x3f) as usize] as char);
        out.push(TABLE[((chunk >> 12) & 0x3f) as usize] as char);
        out.push('=');
        out.push('=');
    } else if rem == 2 {
        let chunk = ((bytes[index] as u32) << 16) | ((bytes[index + 1] as u32) << 8);
        out.push(TABLE[((chunk >> 18) & 0x3f) as usize] as char);
        out.push(TABLE[((chunk >> 12) & 0x3f) as usize] as char);
        out.push(TABLE[((chunk >> 6) & 0x3f) as usize] as char);
        out.push('=');
    }
    out
}

fn file_action_output(stdout: String) -> TaskCommandOutput {
    TaskCommandOutput {
        exit_code: 0,
        stdout,
        stderr: String::new(),
        target: None,
        runtime: None,
        service_termination: None,
        execution_note: None,
        interrupted: false,
    }
}

pub(crate) fn run_backend_command_captured(
    task_name: &str,
    command: &str,
    working_dir: &Path,
    backend: &ResolvedExecutionBackend,
) -> Result<TaskCommandOutput, RunError> {
    execute_task_command(
        None,
        None,
        task_name,
        None,
        &PreparedTaskExecution::Shell {
            command: command.to_string(),
            cwd: None,
        },
        working_dir,
        &BTreeMap::new(),
        None,
        &BTreeSet::new(),
        backend,
        None,
        None,
        TaskExecutionMode::Capture,
    )
}

// Runs a command by argv (no shell) on native backends, shell on container/remote backends.
// This avoids login-shell PATH reordering (e.g. macOS path_helper) for probe and
// toolchain-fulfillment commands that are simple binary invocations.
pub(crate) fn run_backend_argv_command_captured(
    task_name: &str,
    exe: &str,
    args: &[String],
    working_dir: &Path,
    backend: &ResolvedExecutionBackend,
) -> Result<TaskCommandOutput, RunError> {
    run_backend_argv_command_captured_with_env(
        task_name,
        exe,
        args,
        working_dir,
        &BTreeMap::new(),
        backend,
    )
}

pub(crate) fn run_backend_argv_command_captured_with_env(
    task_name: &str,
    exe: &str,
    args: &[String],
    working_dir: &Path,
    env_overrides: &BTreeMap<String, String>,
    backend: &ResolvedExecutionBackend,
) -> Result<TaskCommandOutput, RunError> {
    let execution = match backend {
        ResolvedExecutionBackend::Native { .. } => PreparedTaskExecution::NativeCommand {
            exe: exe.to_string(),
            args: args.to_vec(),
            cwd: None,
        },
        _ => PreparedTaskExecution::Shell {
            command: shell_quote_command_argv(backend, exe, args),
            cwd: None,
        },
    };
    execute_task_command(
        None,
        None,
        task_name,
        None,
        &execution,
        working_dir,
        env_overrides,
        None,
        &BTreeSet::new(),
        backend,
        None,
        None,
        TaskExecutionMode::Capture,
    )
}

#[derive(Debug, Clone, Default)]
struct BackendFulfillmentPreparation {
    evidence: Option<BackendFulfillmentEvidence>,
    deferred_ephemeral_container: Option<DeferredContainerBackendFulfillment>,
    source_managed_actions: Vec<ProvisioningAction>,
}

#[derive(Debug, Clone)]
struct BackendFulfillmentPlan {
    backend_unit: String,
    cache_key: String,
    backend_label: String,
    mode: BackendFulfillmentMode,
    strategy: BackendFulfillmentStrategy,
    target_os: String,
    declared_runtimes: BTreeMap<String, String>,
    declared_tools: BTreeMap<String, String>,
    source_managed_tools: BTreeSet<String>,
    probe_backend: ResolvedExecutionBackend,
    provisioning_target: Option<ProvisioningExecutionTarget>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BackendFulfillmentStrategy {
    Immediate,
    DeferredEphemeralContainer,
}

#[derive(Debug, Clone)]
struct DeferredContainerBackendFulfillment {
    evidence: BackendFulfillmentEvidence,
    actions: Vec<ProvisioningAction>,
    adapter_bootstrap: ProvisioningBackendRequest,
    target_os: String,
    policy_pack: Option<Arc<OrgPolicyPack>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BackendRequirementGap {
    kind: ProvisioningTargetKind,
    name: String,
    required_version: String,
    details: String,
}

impl BackendRequirementGap {
    fn key(&self) -> String {
        format!(
            "{}:{}",
            self.kind.to_string().to_ascii_lowercase(),
            self.name.trim()
        )
    }

    fn description(&self) -> String {
        format!(
            "{} `{}` requires `{}` ({})",
            self.kind, self.name, self.required_version, self.details
        )
    }
}

fn select_direct_tool_acquisition_actions_for_backend_gaps(
    contract: &Contract,
    target_os: &str,
    missing: &[BackendRequirementGap],
) -> Vec<ProvisioningAction> {
    let mut actions = Vec::new();
    let mut seen = BTreeSet::new();

    for gap in missing {
        if gap.kind != ProvisioningTargetKind::Tool || !seen.insert(gap.key()) {
            continue;
        }
        let Some(requirement) = contract.tools.get(gap.name.as_str()) else {
            continue;
        };
        let Some(acquisition) = requirement.acquisition_for_os(target_os) else {
            continue;
        };
        let Some(source) = acquisition.provider.provisioning_source() else {
            continue;
        };
        let requested_version = requirement.version_for_os(target_os).trim();
        let requested_version = if requested_version.is_empty() || requested_version == "*" {
            gap.required_version.clone()
        } else {
            requested_version.to_string()
        };
        actions.push(ProvisioningAction {
            kind: if matches!(acquisition.provider, ToolAcquisitionProvider::ReleaseAsset) {
                crate::policy_pack::ProvisioningActionKind::SelectSource
            } else {
                crate::policy_pack::ProvisioningActionKind::Install
            },
            target_kind: ProvisioningTargetKind::Tool,
            name: gap.name.clone(),
            requested_version,
            normalized_requirement: None,
            resolved_version: None,
            package: acquisition.package.clone().or_else(|| {
                (!matches!(acquisition.provider, ToolAcquisitionProvider::ReleaseAsset))
                    .then(|| gap.name.clone())
            }),
            source: source.to_string(),
            source_config: acquisition.source_config.clone(),
            approved_version: None,
            policy_match: None,
        });
    }

    actions
}

fn maybe_fulfill_backend_requirements_on_run_path(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    backend: &ResolvedExecutionBackend,
    host_port_override: Option<u16>,
    mode: TaskExecutionMode,
    state: &mut TaskRunState,
) -> Result<BackendFulfillmentPreparation, RunError> {
    let Some(plan) = backend_fulfillment_plan(
        contract,
        contract_path,
        task_name,
        backend,
        host_port_override,
    )?
    else {
        return Ok(BackendFulfillmentPreparation::default());
    };
    let loaded_policy = load_org_policy_pack_auto_details(contract_path).map_err(|error| {
        RunError::InvalidPolicyPack {
            details: error.to_string(),
        }
    })?;
    let active_policy = loaded_policy
        .as_ref()
        .map(|loaded_policy| &loaded_policy.pack);

    if plan.strategy == BackendFulfillmentStrategy::Immediate
        && let Some(existing) = state.fulfilled_backend_units.get(plan.cache_key.as_str())
    {
        return Ok(BackendFulfillmentPreparation {
            evidence: Some(existing.clone()),
            deferred_ephemeral_container: None,
            source_managed_actions: state
                .fulfilled_backend_source_managed_actions
                .get(plan.cache_key.as_str())
                .cloned()
                .unwrap_or_default(),
        });
    }

    let mut evidence = BackendFulfillmentEvidence {
        backend_unit: plan.backend_unit.clone(),
        backend: plan.backend_label.clone(),
        mode: plan.mode,
        declared_runtimes: plan.declared_runtimes.clone(),
        declared_tools: plan.declared_tools.clone(),
        missing: Vec::new(),
        actions: Vec::new(),
        result: BackendFulfillmentResult::RequirementsSatisfied,
        task_executed: false,
    };

    let working_dir = contract_working_dir(contract_path);
    let missing = detect_missing_backend_requirements(
        &plan.declared_runtimes,
        &plan.declared_tools,
        &plan.probe_backend,
        working_dir,
        active_policy,
        plan.target_os.as_str(),
    )
    .into_iter()
    .filter(|gap| {
        !(gap.kind == ProvisioningTargetKind::Tool
            && plan.source_managed_tools.contains(gap.name.as_str()))
    })
    .collect::<Vec<_>>();
    if missing.is_empty() {
        if plan.strategy == BackendFulfillmentStrategy::Immediate {
            state
                .fulfilled_backend_units
                .insert(plan.cache_key.clone(), evidence.clone());
            state
                .fulfilled_backend_source_managed_actions
                .remove(plan.cache_key.as_str());
        }
        return Ok(BackendFulfillmentPreparation {
            evidence: Some(evidence),
            deferred_ephemeral_container: None,
            source_managed_actions: Vec::new(),
        });
    }

    evidence.missing = missing
        .iter()
        .map(BackendRequirementGap::description)
        .collect();

    match plan.mode {
        BackendFulfillmentMode::None => {
            evidence.result = BackendFulfillmentResult::MissingRequirements;
            return Err(RunError::BackendRequirementsMissing {
                task: task_name.to_string(),
                backend_unit: plan.backend_unit,
                mode: String::from("none"),
                missing: evidence.missing.join("; "),
                evidence,
            });
        }
        BackendFulfillmentMode::Run => {}
    }

    let mut actions = select_direct_tool_acquisition_actions_for_backend_gaps(
        contract,
        plan.target_os.as_str(),
        &missing,
    );
    if let Some(loaded_policy) = loaded_policy.as_ref() {
        let policy_actions = select_provisioning_actions_for_backend_gaps(
            &loaded_policy.pack,
            plan.target_os.as_str(),
            &missing,
        )
        .map_err(|details| RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: plan.backend_unit.clone(),
            details,
            evidence: evidence.clone(),
        })?;
        for action in policy_actions {
            let duplicate = actions.iter().any(|existing| {
                existing.target_kind == action.target_kind
                    && existing.name == action.name
                    && existing.requested_version == action.requested_version
                    && existing.source == action.source
            });
            if !duplicate {
                actions.push(action);
            }
        }
    } else if actions.is_empty() {
        evidence.result = BackendFulfillmentResult::Failed;
        return Err(RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: plan.backend_unit,
            details: String::from(
                "no active org policy pack is available to select approved provisioning sources",
            ),
            evidence,
        });
    }

    evidence.actions = actions
        .iter()
        .map(render_backend_fulfillment_action)
        .collect();

    if actions.is_empty() {
        evidence.result = BackendFulfillmentResult::Failed;
        return Err(RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: plan.backend_unit,
            details: format!(
                "no approved provisioning actions were selected for missing requirements: {}",
                evidence.missing.join("; ")
            ),
            evidence,
        });
    }

    let output_mode = backend_fulfillment_output_mode(mode);
    let request = ProvisioningBackendRequest { actions };
    let adapter_bootstrap = loaded_policy
        .as_ref()
        .map(|loaded| adapter_bootstrap_request_for_provisioning_sources(&loaded.pack, &request))
        .unwrap_or_else(|| ProvisioningBackendRequest {
            actions: Vec::new(),
        });
    if plan.strategy == BackendFulfillmentStrategy::DeferredEphemeralContainer {
        return Ok(BackendFulfillmentPreparation {
            evidence: Some(evidence.clone()),
            deferred_ephemeral_container: Some(DeferredContainerBackendFulfillment {
                evidence,
                actions: request.actions,
                adapter_bootstrap,
                target_os: plan.target_os,
                policy_pack: None,
            }),
            source_managed_actions: Vec::new(),
        });
    }
    let provisioning = apply_run_path_provisioning_request_with_bootstrap(
        &request,
        &adapter_bootstrap,
        working_dir,
        plan.provisioning_target
            .as_ref()
            .expect("immediate backend fulfillment requires a provisioning target"),
        output_mode,
    );
    match provisioning {
        Ok(output) => {
            state.stdout.push_str(&output.stdout);
            state.stderr.push_str(&output.stderr);
        }
        Err(error) => {
            evidence.result = BackendFulfillmentResult::Failed;
            return Err(RunError::BackendFulfillmentFailed {
                task: task_name.to_string(),
                backend_unit: plan.backend_unit,
                details: render_backend_fulfillment_failure(error),
                evidence,
            });
        }
    }

    let source_managed_actions = source_managed_actions(&request.actions);
    if let Some(ProvisioningExecutionTarget::Container {
        engine,
        container_name: Some(container_name),
        ..
    }) = plan.provisioning_target.as_ref()
    {
        install_source_managed_tool_wrappers(
            engine,
            container_name,
            task_name,
            &source_managed_actions,
        )?;
    }

    let remaining = detect_missing_backend_requirements(
        &plan.declared_runtimes,
        &plan.declared_tools,
        &plan.probe_backend,
        working_dir,
        active_policy,
        plan.target_os.as_str(),
    );
    let remaining = remaining
        .into_iter()
        .filter(|gap| !source_managed_remaining_gap_covered(gap, &source_managed_actions))
        .collect::<Vec<_>>();
    if !remaining.is_empty() {
        evidence.result = BackendFulfillmentResult::Failed;
        evidence.missing = remaining
            .iter()
            .map(BackendRequirementGap::description)
            .collect();
        return Err(RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: plan.backend_unit,
            details: format!(
                "provisioning finished but requirements are still missing: {}",
                evidence.missing.join("; ")
            ),
            evidence,
        });
    }

    evidence.result = BackendFulfillmentResult::Fulfilled;
    state
        .fulfilled_backend_units
        .insert(plan.cache_key.clone(), evidence.clone());
    state
        .fulfilled_backend_source_managed_actions
        .insert(plan.cache_key, source_managed_actions.clone());
    Ok(BackendFulfillmentPreparation {
        evidence: Some(evidence),
        deferred_ephemeral_container: None,
        source_managed_actions,
    })
}

fn maybe_fulfill_toolchains_on_run_path(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    task: &TaskSpec,
    backend: &ResolvedExecutionBackend,
    env_overrides: &BTreeMap<String, String>,
    _mode: TaskExecutionMode,
    current_os: &str,
    state: &mut TaskRunState,
) -> Result<(), RunError> {
    for toolchain_name in
        task_toolchain_names_for_resolved_backend(contract, task, backend).into_iter()
    {
        let Some(toolchain) = contract.toolchains.get(toolchain_name.as_str()) else {
            continue;
        };
        let target_os = target_os_for_toolchain_backend(backend, current_os);
        if !toolchain.active_for_os(target_os)
            || toolchain.fulfillment_mode() != ToolchainFulfillmentMode::Run
        {
            continue;
        }

        let cache_key = toolchain_fulfillment_cache_key(toolchain_name.as_str(), backend);
        if !state.fulfilled_toolchain_keys.insert(cache_key) {
            continue;
        }

        let mut executed_commands = Vec::new();
        for command_spec in
            toolchain_fulfillment_command_specs(toolchain_name.as_str(), toolchain, target_os)
        {
            let command_display = render_toolchain_command(backend, command_spec.clone());
            let task_label = format!("toolchain-fulfill:{toolchain_name}");
            let output = run_backend_argv_command_captured_with_env(
                &task_label,
                command_spec.program,
                &command_spec.args,
                contract_working_dir(contract_path),
                env_overrides,
                backend,
            )?;
            state.stdout.push_str(&output.stdout);
            state.stderr.push_str(&output.stderr);
            if output.exit_code != 0 {
                return Err(RunError::ToolchainFulfillmentFailed {
                    task: task_name.to_string(),
                    toolchain: toolchain_name,
                    details: command_failure_detail(&command_display, &output),
                });
            }
            executed_commands.push(command_display);
        }
        if !executed_commands.is_empty() {
            state
                .fulfilled_toolchains
                .insert(toolchain_name, executed_commands);
        }
    }

    Ok(())
}

fn maybe_activate_corepack_shims_on_run_path(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    task: &TaskSpec,
    backend: &ResolvedExecutionBackend,
    env_overrides: &BTreeMap<String, String>,
    current_os: &str,
    state: &mut TaskRunState,
) -> Result<(), RunError> {
    if probe_backend_command_version(backend, contract_working_dir(contract_path), "node")
        .ok()
        .flatten()
        .is_none()
    {
        return Ok(());
    }

    for toolchain_name in
        task_toolchain_names_for_resolved_backend(contract, task, backend).into_iter()
    {
        let Some(toolchain) = contract.toolchains.get(toolchain_name.as_str()) else {
            continue;
        };
        if toolchain.fulfillment_source()
            != Some(crate::schema::ToolchainFulfillmentSource::Corepack)
        {
            continue;
        }
        let target_os = target_os_for_toolchain_backend(backend, current_os);
        if !toolchain.active_for_os(target_os) {
            continue;
        }
        let backend_kind = resolved_execution_backend_kind(backend);
        if task_invokes_corepack_directly(task, backend_kind, current_os) {
            continue;
        }
        let cache_key = format!(
            "corepack-enable:{}",
            toolchain_fulfillment_cache_key(toolchain_name.as_str(), backend)
        );
        if !state.fulfilled_toolchain_keys.insert(cache_key) {
            continue;
        }

        for command_spec in corepack_activation_command_specs(toolchain, target_os) {
            let command_display = render_toolchain_command(backend, command_spec.clone());
            let task_label = format!("toolchain-activate:{toolchain_name}");
            let output = run_backend_argv_command_captured_with_env(
                &task_label,
                command_spec.program,
                &command_spec.args,
                contract_working_dir(contract_path),
                env_overrides,
                backend,
            )?;
            state.stdout.push_str(&output.stdout);
            state.stderr.push_str(&output.stderr);
            if output.exit_code != 0 {
                return Err(RunError::ToolchainFulfillmentFailed {
                    task: task_name.to_string(),
                    toolchain: toolchain_name,
                    details: command_failure_detail(&command_display, &output),
                });
            }
        }
    }

    Ok(())
}

fn maybe_prepare_task_orchestrator_on_run_path(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    task: &TaskSpec,
    backend_kind: Backend,
    backend: &ResolvedExecutionBackend,
    env_overrides: &BTreeMap<String, String>,
    state: &mut TaskRunState,
) -> Result<(), RunError> {
    let Some(orchestrator_selection) = task.orchestrator_for_backend(backend_kind) else {
        return Ok(());
    };
    let Some(orchestrator) = contract
        .orchestrators
        .get(orchestrator_selection.ref_name.as_str())
    else {
        return Ok(());
    };

    let cache_key = format!(
        "orchestrator:{}:{}",
        orchestrator_selection.ref_name,
        toolchain_fulfillment_cache_key(orchestrator_selection.ref_name.as_str(), backend)
    );
    if !state.fulfilled_toolchain_keys.insert(cache_key) {
        return Ok(());
    }

    for command_spec in orchestrator_command_specs(orchestrator) {
        let command_display = render_toolchain_command(backend, command_spec.clone());
        let step_label = format!("orchestrator-prepare:{}", orchestrator_selection.ref_name);
        let output = run_backend_argv_command_captured_with_env(
            &step_label,
            command_spec.program,
            &command_spec.args,
            contract_working_dir(contract_path),
            env_overrides,
            backend,
        )?;
        state.stdout.push_str(&output.stdout);
        state.stderr.push_str(&output.stderr);
        if output.exit_code != 0 {
            return Err(RunError::OrchestratorPreparationFailed {
                task: task_name.to_string(),
                orchestrator: orchestrator_selection.ref_name.clone(),
                details: command_failure_detail(&command_display, &output),
            });
        }
    }

    Ok(())
}

fn orchestrator_command_specs(
    orchestrator: &crate::schema::OrchestratorSpec,
) -> Vec<ToolchainCommandSpec> {
    match orchestrator.kind {
        crate::schema::OrchestratorKind::Mise => {
            let mut commands = Vec::new();
            if orchestrator.activation.trust {
                commands.push(ToolchainCommandSpec {
                    program: "mise",
                    args: vec![String::from("trust")],
                });
            }
            if orchestrator.prepare.install {
                commands.push(ToolchainCommandSpec {
                    program: "mise",
                    args: vec![String::from("install")],
                });
            }
            commands
        }
    }
}

fn wrap_prepared_execution_for_orchestrator(
    execution: PreparedTaskExecution,
    backend: &ResolvedExecutionBackend,
    selection: &crate::schema::TaskExecutionOrchestratorSpec,
    orchestrator: &crate::schema::OrchestratorSpec,
) -> Result<PreparedTaskExecution, RunError> {
    match orchestrator.kind {
        crate::schema::OrchestratorKind::Mise => {
            wrap_prepared_execution_for_mise(execution, backend, selection)
        }
    }
}

fn wrap_prepared_execution_for_mise(
    execution: PreparedTaskExecution,
    backend: &ResolvedExecutionBackend,
    selection: &crate::schema::TaskExecutionOrchestratorSpec,
) -> Result<PreparedTaskExecution, RunError> {
    match selection.mode {
        crate::schema::TaskExecutionOrchestratorMode::Task => match execution {
            PreparedTaskExecution::Shell { command, cwd } => Ok(PreparedTaskExecution::Shell {
                command: wrap_mise_task_command(backend, command.as_str()),
                cwd,
            }),
            _ => Err(RunError::InvalidTaskExecution {
                task: selection.ref_name.clone(),
            }),
        },
        crate::schema::TaskExecutionOrchestratorMode::Exec => match execution {
            PreparedTaskExecution::Shell { command, cwd } => Ok(PreparedTaskExecution::Shell {
                command: wrap_mise_exec_shell_command(command.as_str()),
                cwd,
            }),
            PreparedTaskExecution::NativeCommand { exe, args, cwd } => {
                Ok(PreparedTaskExecution::Shell {
                    command: wrap_mise_exec_argv_command(backend, exe.as_str(), &args),
                    cwd,
                })
            }
            _ => Err(RunError::InvalidTaskExecution {
                task: selection.ref_name.clone(),
            }),
        },
    }
}

#[cfg(unix)]
fn mise_command_prefix() -> String {
    String::from(
        r#"if command -v mise >/dev/null 2>&1; then __ota_mise="$(command -v mise)"; elif [ -x "$HOME/.local/bin/mise" ]; then __ota_mise="$HOME/.local/bin/mise"; else __ota_mise="mise"; fi; "$__ota_mise""#,
    )
}

#[cfg(windows)]
fn mise_command_prefix() -> String {
    String::from(
        r#"cmd /C set "__OTA_MISE=mise" && if exist "%LOCALAPPDATA%\mise\bin\mise.exe" set "__OTA_MISE=%LOCALAPPDATA%\mise\bin\mise.exe" && if exist "%USERPROFILE%\.local\bin\mise.exe" set "__OTA_MISE=%USERPROFILE%\.local\bin\mise.exe" && "%__OTA_MISE%""#,
    )
}

fn wrap_mise_task_command(backend: &ResolvedExecutionBackend, task_name: &str) -> String {
    let mut wrapped = mise_command_prefix();
    wrapped.push_str(" run ");
    wrapped.push_str(&shell_quote_command_word(
        task_name,
        shell_quote_style_for_backend(backend),
    ));
    wrapped
}

fn wrap_mise_exec_shell_command(command: &str) -> String {
    let mut wrapped = mise_command_prefix();
    #[cfg(windows)]
    {
        wrapped.push_str(" exec -- cmd /C ");
        wrapped.push_str(&cmd_quote(command));
    }
    #[cfg(not(windows))]
    {
        wrapped.push_str(" exec -- sh -lc ");
        wrapped.push_str(&shell_quote(command));
    }
    wrapped
}

fn wrap_mise_exec_argv_command(
    backend: &ResolvedExecutionBackend,
    exe: &str,
    args: &[String],
) -> String {
    let mut wrapped = mise_command_prefix();
    wrapped.push_str(" exec -- ");
    wrapped.push_str(&shell_quote_command_argv(backend, exe, args));
    wrapped
}

fn shell_quote_style_for_backend(backend: &ResolvedExecutionBackend) -> ShellQuoteStyle {
    match backend {
        #[cfg(windows)]
        ResolvedExecutionBackend::Native { .. } => ShellQuoteStyle::WindowsCmd,
        _ => ShellQuoteStyle::Posix,
    }
}

fn task_invokes_corepack_directly(task: &TaskSpec, backend: Backend, current_os: &str) -> bool {
    let Some(execution) = task.resolved_execution_for_backend(backend, current_os) else {
        return false;
    };

    if let Some(crate::schema::TaskLaunchSpec::Command(command)) = execution.launch() {
        return command.exe == "corepack";
    }

    execution
        .shell_body()
        .map(shell_body_invokes_corepack_directly)
        .unwrap_or(false)
}

fn shell_body_invokes_corepack_directly(command: &str) -> bool {
    let trimmed = command.trim_start();
    trimmed == "corepack"
        || trimmed
            .strip_prefix("corepack")
            .and_then(|remaining| remaining.chars().next())
            .is_some_and(char::is_whitespace)
}

fn command_failure_detail(command_display: &str, output: &TaskCommandOutput) -> String {
    let mut detail = format!("`{command_display}` exited with code {}", output.exit_code);
    let stderr = output.stderr.trim();
    if !stderr.is_empty() {
        let excerpt = stderr.lines().take(3).collect::<Vec<_>>().join("; ");
        detail.push_str(&format!(": {excerpt}"));
    }
    detail
}

fn corepack_activation_command_specs(
    toolchain: &ToolchainSpec,
    target_os: &str,
) -> Vec<ToolchainCommandSpec> {
    let mut commands = Vec::new();
    if !crate::doctor::command_available("corepack") && crate::doctor::command_available("npm") {
        commands.push(ToolchainCommandSpec {
            program: "npm",
            args: vec![
                String::from("install"),
                String::from("-g"),
                String::from("corepack"),
            ],
        });
    }
    commands.push(ToolchainCommandSpec {
        program: "corepack",
        args: vec![String::from("enable")],
    });
    commands.extend(
        toolchain
            .package_managers_for_os(target_os)
            .into_iter()
            .map(|(package_name, version)| ToolchainCommandSpec {
                program: "corepack",
                args: vec![
                    String::from("prepare"),
                    format!("{package_name}@{version}"),
                    String::from("--activate"),
                ],
            }),
    );
    commands
}

fn wrap_container_command_for_corepack_activation(
    contract: Option<&Contract>,
    task_name: &str,
    command: &str,
) -> String {
    let Some(contract) = contract else {
        return command.to_string();
    };
    let Some(task) = contract.tasks.get(task_name) else {
        return command.to_string();
    };

    let mut command_parts = Vec::new();
    for toolchain_name in contract
        .task_toolchain_names_for_execution(
            task,
            Backend::Container,
            task.context_for_backend(contract.execution.as_ref(), Backend::Container),
        )
        .into_iter()
    {
        let Some(toolchain) = contract.toolchains.get(toolchain_name.as_str()) else {
            continue;
        };
        if toolchain.fulfillment_source()
            != Some(crate::schema::ToolchainFulfillmentSource::Corepack)
            || !toolchain.active_for_os("linux")
        {
            continue;
        }
        command_parts.push(String::from(
            "mkdir -p \"$HOME/.local/bin\" && corepack enable --install-directory \"$HOME/.local/bin\" && export PATH=\"$HOME/.local/bin:$PATH\"",
        ));
        for (package_name, version) in toolchain.package_managers_for_os("linux") {
            command_parts.push(format!(
                "corepack prepare {package_name}@{version} --activate"
            ));
        }
    }
    if command_parts.is_empty() {
        return command.to_string();
    }
    command_parts.push(command.to_string());

    command_parts.join(" && ")
}

fn toolchain_fulfillment_cache_key(
    toolchain_name: &str,
    backend: &ResolvedExecutionBackend,
) -> String {
    match backend {
        ResolvedExecutionBackend::Native { .. } => format!("native:{toolchain_name}"),
        ResolvedExecutionBackend::Container {
            context_name,
            image,
            engine,
            ..
        } => format!(
            "container:{}:{}:{}:{toolchain_name}",
            context_name.as_deref().unwrap_or_default(),
            image,
            engine
        ),
        ResolvedExecutionBackend::Remote {
            provider,
            target,
            cwd,
            ..
        } => format!(
            "remote:{provider}:{target}:{}:{toolchain_name}",
            cwd.as_deref().unwrap_or_default()
        ),
        ResolvedExecutionBackend::BackendProvider {
            provider,
            command,
            target,
            cwd,
            ..
        } => format!(
            "backend_provider:{provider}:{command}:{target}:{}:{toolchain_name}",
            cwd.as_deref().unwrap_or_default()
        ),
    }
}

fn task_toolchain_names_for_resolved_backend(
    contract: &Contract,
    task: &TaskSpec,
    backend: &ResolvedExecutionBackend,
) -> Vec<String> {
    let backend_kind = resolved_execution_backend_kind(backend);
    let context_name = task.context_for_backend(contract.execution.as_ref(), backend_kind);
    contract.task_toolchain_names_for_execution(task, backend_kind, context_name)
}

#[cfg(test)]
fn toolchain_fulfillment_commands(
    toolchain_name: &str,
    toolchain: &ToolchainSpec,
    target_os: &str,
    backend: &ResolvedExecutionBackend,
) -> Vec<String> {
    declared_toolchain_contract(toolchain_name, toolchain)
        .map(|provider| {
            provider
                .fulfillment_commands(toolchain, target_os)
                .into_iter()
                .map(|command| render_toolchain_command(backend, command))
                .collect()
        })
        .unwrap_or_default()
}

fn toolchain_fulfillment_command_specs(
    toolchain_name: &str,
    toolchain: &ToolchainSpec,
    target_os: &str,
) -> Vec<ToolchainCommandSpec> {
    declared_toolchain_fulfillment_commands(toolchain_name, toolchain, target_os)
}

fn render_toolchain_command(
    backend: &ResolvedExecutionBackend,
    command: ToolchainCommandSpec,
) -> String {
    shell_quote_command_argv(backend, command.program, &command.args)
}

fn target_os_for_toolchain_backend<'a>(
    backend: &ResolvedExecutionBackend,
    current_os: &'a str,
) -> &'a str {
    match backend {
        ResolvedExecutionBackend::Container { .. } => "linux",
        ResolvedExecutionBackend::Remote { .. }
        | ResolvedExecutionBackend::BackendProvider { .. }
        | ResolvedExecutionBackend::Native { .. } => current_os,
    }
}

fn backend_fulfillment_plan(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    backend: &ResolvedExecutionBackend,
    host_port_override: Option<u16>,
) -> Result<Option<BackendFulfillmentPlan>, RunError> {
    let task = contract
        .tasks
        .get(task_name)
        .ok_or_else(|| RunError::UnknownTask {
            task: task_name.to_string(),
        })?;

    if let ResolvedExecutionBackend::Native {
        shared_local_backend: Some(shared_local_backend),
    } = backend
    {
        let Some(fulfillment) = shared_local_backend.fulfillment else {
            return Ok(None);
        };
        let mode = match fulfillment {
            ExecutionSharedBackendFulfillment::None => BackendFulfillmentMode::None,
            ExecutionSharedBackendFulfillment::Run => BackendFulfillmentMode::Run,
        };
        let target_os = current_os().to_string();
        let (declared_runtimes, declared_tools) = shared_local_backend_requirement_versions(
            contract,
            shared_local_backend.name.as_str(),
            Backend::Native,
            target_os.as_str(),
        )
        .map_err(|details| RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: format!("shared_local_backend:{}", shared_local_backend.name),
            details,
            evidence: BackendFulfillmentEvidence {
                backend_unit: format!("shared_local_backend:{}", shared_local_backend.name),
                backend: String::from("native"),
                mode,
                declared_runtimes: BTreeMap::new(),
                declared_tools: BTreeMap::new(),
                missing: Vec::new(),
                actions: Vec::new(),
                result: BackendFulfillmentResult::Failed,
                task_executed: false,
            },
        })?;
        let backend_unit = format!("shared_local_backend:{}", shared_local_backend.name);
        let provisioning_target = Some(provisioning_target_for_resolved_backend(
            contract_path,
            backend,
        )?);
        return Ok(Some(BackendFulfillmentPlan {
            cache_key: backend_fulfillment_cache_key(
                backend_unit.clone(),
                provisioning_target.as_ref(),
            ),
            backend_unit,
            backend_label: String::from("native"),
            mode,
            strategy: BackendFulfillmentStrategy::Immediate,
            target_os: target_os.clone(),
            declared_runtimes,
            declared_tools,
            source_managed_tools: BTreeSet::new(),
            probe_backend: backend.clone(),
            provisioning_target,
        }));
    }

    if matches!(backend, ResolvedExecutionBackend::Native { .. }) {
        let target_os = current_os().to_string();
        let (declared_runtimes, declared_tools) =
            direct_task_requirement_versions(contract, task, task_name, target_os.as_str())
                .map_err(|details| RunError::BackendFulfillmentFailed {
                    task: task_name.to_string(),
                    backend_unit: format!("task:{task_name}:native"),
                    details,
                    evidence: BackendFulfillmentEvidence {
                        backend_unit: format!("task:{task_name}:native"),
                        backend: String::from("native"),
                        mode: BackendFulfillmentMode::Run,
                        declared_runtimes: BTreeMap::new(),
                        declared_tools: BTreeMap::new(),
                        missing: Vec::new(),
                        actions: Vec::new(),
                        result: BackendFulfillmentResult::Failed,
                        task_executed: false,
                    },
                })?;
        if declared_runtimes.is_empty() && declared_tools.is_empty() {
            return Ok(None);
        }
        let backend_unit = format!("task:{task_name}:native");
        let provisioning_target = Some(provisioning_target_for_resolved_backend(
            contract_path,
            backend,
        )?);
        return Ok(Some(BackendFulfillmentPlan {
            cache_key: backend_fulfillment_cache_key(
                backend_unit.clone(),
                provisioning_target.as_ref(),
            ),
            backend_unit,
            backend_label: String::from("native"),
            mode: BackendFulfillmentMode::Run,
            strategy: BackendFulfillmentStrategy::Immediate,
            target_os: target_os.clone(),
            declared_runtimes,
            declared_tools,
            source_managed_tools: source_managed_tool_names_for_execution(
                contract,
                task,
                Backend::Native,
                task.context_for_backend(contract.execution.as_ref(), Backend::Native),
                target_os.as_str(),
            ),
            probe_backend: backend.clone(),
            provisioning_target,
        }));
    }

    if let ResolvedExecutionBackend::Remote {
        shared_local_backend: Some(shared_local_backend),
        ..
    }
    | ResolvedExecutionBackend::BackendProvider {
        shared_local_backend: Some(shared_local_backend),
        ..
    } = backend
    {
        let Some(fulfillment) = shared_local_backend.fulfillment else {
            return Ok(None);
        };
        let mode = match fulfillment {
            ExecutionSharedBackendFulfillment::None => BackendFulfillmentMode::None,
            ExecutionSharedBackendFulfillment::Run => BackendFulfillmentMode::Run,
        };
        let target_os = current_os().to_string();
        let (declared_runtimes, declared_tools) = shared_local_backend_requirement_versions(
            contract,
            shared_local_backend.name.as_str(),
            Backend::Remote,
            target_os.as_str(),
        )
        .map_err(|details| RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: format!("shared_local_backend:{}", shared_local_backend.name),
            details,
            evidence: BackendFulfillmentEvidence {
                backend_unit: format!("shared_local_backend:{}", shared_local_backend.name),
                backend: String::from("remote"),
                mode,
                declared_runtimes: BTreeMap::new(),
                declared_tools: BTreeMap::new(),
                missing: Vec::new(),
                actions: Vec::new(),
                result: BackendFulfillmentResult::Failed,
                task_executed: false,
            },
        })?;
        let backend_unit = format!("shared_local_backend:{}", shared_local_backend.name);
        let provisioning_target = Some(provisioning_target_for_resolved_backend(
            contract_path,
            backend,
        )?);
        return Ok(Some(BackendFulfillmentPlan {
            cache_key: backend_fulfillment_cache_key(
                backend_unit.clone(),
                provisioning_target.as_ref(),
            ),
            backend_unit,
            backend_label: String::from("remote"),
            mode,
            strategy: BackendFulfillmentStrategy::Immediate,
            target_os,
            declared_runtimes,
            declared_tools,
            source_managed_tools: BTreeSet::new(),
            probe_backend: backend.clone(),
            provisioning_target,
        }));
    }

    let ResolvedExecutionBackend::Container {
        context_name,
        shared_local_backend,
        lifecycle,
        ..
    } = backend
    else {
        return Ok(None);
    };
    let target_os = String::from("linux");
    let probe_backend = effective_immediate_container_fulfillment_backend(
        contract,
        task_name,
        backend,
        host_port_override,
    )?;
    if let Some(shared_local_backend) = shared_local_backend {
        let Some(fulfillment) = shared_local_backend.fulfillment else {
            return Ok(None);
        };
        let mode = match fulfillment {
            ExecutionSharedBackendFulfillment::None => BackendFulfillmentMode::None,
            ExecutionSharedBackendFulfillment::Run => BackendFulfillmentMode::Run,
        };
        let (declared_runtimes, declared_tools) = shared_local_backend_requirement_versions(
            contract,
            shared_local_backend.name.as_str(),
            Backend::Container,
            target_os.as_str(),
        )
        .map_err(|details| RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: format!("shared_local_backend:{}", shared_local_backend.name),
            details,
            evidence: BackendFulfillmentEvidence {
                backend_unit: format!("shared_local_backend:{}", shared_local_backend.name),
                backend: String::from("container"),
                mode,
                declared_runtimes: BTreeMap::new(),
                declared_tools: BTreeMap::new(),
                missing: Vec::new(),
                actions: Vec::new(),
                result: BackendFulfillmentResult::Failed,
                task_executed: false,
            },
        })?;
        let backend_unit = format!("shared_local_backend:{}", shared_local_backend.name);
        let strategy = match shared_local_backend.lifecycle {
            Lifecycle::Persistent => BackendFulfillmentStrategy::Immediate,
            Lifecycle::Ephemeral => BackendFulfillmentStrategy::DeferredEphemeralContainer,
        };
        let provisioning_target = if strategy == BackendFulfillmentStrategy::Immediate {
            Some(provisioning_target_for_resolved_backend(
                contract_path,
                &probe_backend,
            )?)
        } else {
            None
        };
        return Ok(Some(BackendFulfillmentPlan {
            backend_unit: backend_unit.clone(),
            cache_key: backend_fulfillment_cache_key(backend_unit, provisioning_target.as_ref()),
            backend_label: String::from("container"),
            mode,
            strategy,
            target_os,
            declared_runtimes,
            declared_tools,
            source_managed_tools: BTreeSet::new(),
            probe_backend,
            provisioning_target,
        }));
    }

    let Some(context_name) = context_name.as_deref() else {
        return Ok(None);
    };
    let Some((_, context)) =
        selected_task_context_for_backend(contract, task_name, Backend::Container)
    else {
        return Ok(None);
    };
    let Some(fulfillment) = context.fulfillment else {
        return Ok(None);
    };
    let mode = match fulfillment {
        ExecutionSharedBackendFulfillment::None => BackendFulfillmentMode::None,
        ExecutionSharedBackendFulfillment::Run => BackendFulfillmentMode::Run,
    };
    let (declared_runtimes, declared_tools) = direct_task_requirement_versions_for_backend(
        contract,
        task,
        task_name,
        Backend::Container,
        Some(context_name),
        target_os.as_str(),
    )
    .map_err(|details| RunError::BackendFulfillmentFailed {
        task: task_name.to_string(),
        backend_unit: format!("context:{context_name}"),
        details,
        evidence: BackendFulfillmentEvidence {
            backend_unit: format!("context:{context_name}"),
            backend: String::from("container"),
            mode,
            declared_runtimes: BTreeMap::new(),
            declared_tools: BTreeMap::new(),
            missing: Vec::new(),
            actions: Vec::new(),
            result: BackendFulfillmentResult::Failed,
            task_executed: false,
        },
    })?;
    let strategy = match lifecycle {
        Lifecycle::Persistent => BackendFulfillmentStrategy::Immediate,
        Lifecycle::Ephemeral => BackendFulfillmentStrategy::DeferredEphemeralContainer,
    };
    let provisioning_target = if strategy == BackendFulfillmentStrategy::Immediate {
        Some(provisioning_target_for_resolved_backend(
            contract_path,
            &probe_backend,
        )?)
    } else {
        None
    };
    let backend_unit = format!("context:{context_name}");
    Ok(Some(BackendFulfillmentPlan {
        backend_unit: backend_unit.clone(),
        cache_key: backend_fulfillment_cache_key(backend_unit, provisioning_target.as_ref()),
        backend_label: String::from("container"),
        mode,
        strategy,
        target_os: target_os.clone(),
        declared_runtimes,
        declared_tools,
        source_managed_tools: source_managed_tool_names_for_execution(
            contract,
            task,
            Backend::Container,
            Some(context_name),
            target_os.as_str(),
        ),
        probe_backend,
        provisioning_target,
    }))
}

fn effective_immediate_container_fulfillment_backend(
    contract: &Contract,
    task_name: &str,
    backend: &ResolvedExecutionBackend,
    host_port_override: Option<u16>,
) -> Result<ResolvedExecutionBackend, RunError> {
    let ResolvedExecutionBackend::Container {
        shared_local_backend,
        lifecycle,
        publications,
        ..
    } = backend
    else {
        return Ok(backend.clone());
    };

    if *lifecycle != Lifecycle::Persistent {
        return Ok(backend.clone());
    }

    let runtime = contract
        .tasks
        .get(task_name)
        .and_then(|task| task.service_runtime_for_backend(Backend::Container));
    let runtime_listener_publications = task_runtime_listener_publications(runtime);
    if runtime_listener_publications.is_empty() && host_port_override.is_none() {
        return Ok(backend.clone());
    }

    let projection = prepare_container_runtime_projection(
        task_name,
        runtime,
        shared_backend_publications_or_current(shared_local_backend.as_ref(), publications),
        &runtime_listener_publications,
        false,
        host_port_override,
    )?;

    let mut effective_backend = backend.clone();
    if let ResolvedExecutionBackend::Container {
        shared_local_backend,
        publications,
        ..
    } = &mut effective_backend
    {
        *publications = projection.publications.clone();
        if let Some(shared_local_backend) = shared_local_backend.as_mut() {
            shared_local_backend.publications = projection.publications;
        }
    }
    Ok(effective_backend)
}

fn backend_fulfillment_cache_key(
    backend_unit: String,
    provisioning_target: Option<&ProvisioningExecutionTarget>,
) -> String {
    match provisioning_target {
        Some(ProvisioningExecutionTarget::Container {
            container_name: Some(container_name),
            ..
        }) => format!("{backend_unit}::container:{container_name}"),
        _ => backend_unit,
    }
}

fn source_managed_tool_names_for_execution(
    contract: &Contract,
    task: &TaskSpec,
    backend: Backend,
    context_name: Option<&str>,
    target_os: &str,
) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for toolchain_name in contract.task_toolchain_names_for_execution(task, backend, context_name) {
        let Some(toolchain) = contract.toolchains.get(toolchain_name.as_str()) else {
            continue;
        };
        if toolchain.fulfillment_source() != Some(crate::schema::ToolchainFulfillmentSource::Corepack)
        {
            continue;
        }
        if !toolchain.active_for_os(target_os) {
            continue;
        }
        names.extend(toolchain.package_managers_for_os(target_os).into_keys());
    }
    names
}

fn shared_local_backend_requirement_versions(
    contract: &Contract,
    binding_name: &str,
    backend: Backend,
    target_os: &str,
) -> Result<(BTreeMap<String, String>, BTreeMap<String, String>), String> {
    let mut runtimes = BTreeMap::<String, (String, String)>::new();
    let mut tools = BTreeMap::<String, (String, String)>::new();

    merge_requirement_versions(
        &mut runtimes,
        &contract.runtimes,
        target_os,
        "contract.runtimes",
    )?;
    merge_requirement_versions(&mut tools, &contract.tools, target_os, "contract.tools")?;

    for (task_name, task) in &contract.tasks {
        if task.backend_binding_for_backend(backend) != Some(binding_name) {
            continue;
        }
        let Some((context_name, context)) =
            selected_task_context_for_backend(contract, task_name, backend)
        else {
            continue;
        };
        let runtime_source = format!("task `{task_name}` context `{context_name}` runtimes");
        let tool_source = format!("task `{task_name}` context `{context_name}` tools");
        merge_requirement_versions(
            &mut runtimes,
            &context.requirements.runtimes,
            target_os,
            runtime_source.as_str(),
        )?;
        merge_requirement_versions(
            &mut tools,
            &context.requirements.tools,
            target_os,
            tool_source.as_str(),
        )?;
        let context_surface =
            requirement_surface_with_toolchain_owned_capabilities_for_required_tools(
                contract,
                &crate::schema::RequirementSurface {
                    runtimes: context.requirements.runtimes.clone(),
                    tools: context.requirements.tools.clone(),
                    presence_only_tools: BTreeSet::new(),
                },
                &context.requirements.toolchains.iter().cloned().collect(),
                target_os,
                None,
            );
        merge_requirement_versions(
            &mut runtimes,
            &context_surface.runtimes,
            target_os,
            "task context toolchain-owned runtimes",
        )?;
        merge_requirement_versions(
            &mut tools,
            &context_surface.tools,
            target_os,
            "task context toolchain-owned tools",
        )?;
    }

    Ok((
        runtimes
            .into_iter()
            .map(|(name, (version, _))| (name, version))
            .collect(),
        tools
            .into_iter()
            .map(|(name, (version, _))| (name, version))
            .collect(),
    ))
}

fn direct_task_requirement_versions(
    contract: &Contract,
    task: &TaskSpec,
    task_name: &str,
    target_os: &str,
) -> Result<(BTreeMap<String, String>, BTreeMap<String, String>), String> {
    direct_task_requirement_versions_for_backend(
        contract,
        task,
        task_name,
        Backend::Native,
        task.context_for_backend(contract.execution.as_ref(), Backend::Native),
        target_os,
    )
}

fn direct_task_requirement_versions_for_backend(
    contract: &Contract,
    task: &TaskSpec,
    task_name: &str,
    backend: Backend,
    context_name: Option<&str>,
    target_os: &str,
) -> Result<(BTreeMap<String, String>, BTreeMap<String, String>), String> {
    let mut runtimes = BTreeMap::<String, (String, String)>::new();
    let mut tools = BTreeMap::<String, (String, String)>::new();
    merge_requirement_versions(
        &mut runtimes,
        &contract.runtimes,
        target_os,
        "contract.runtimes",
    )?;
    merge_requirement_versions(&mut tools, &contract.tools, target_os, "contract.tools")?;

    let runtime_source = format!("task `{task_name}` runtimes");
    let tool_source = format!("task `{task_name}` tools");
    let scoped_surface = task.scoped_requirement_surface_for_execution(backend, context_name);
    merge_requirement_versions(
        &mut runtimes,
        &scoped_surface.runtimes,
        target_os,
        runtime_source.as_str(),
    )?;
    merge_requirement_versions(
        &mut tools,
        &scoped_surface.tools,
        target_os,
        tool_source.as_str(),
    )?;
    let scoped_surface = requirement_surface_with_toolchain_owned_capabilities_for_required_tools(
        contract,
        &scoped_surface,
        &contract
            .task_toolchain_names_for_execution(task, backend, context_name)
            .into_iter()
            .collect(),
        target_os,
        None,
    );
    merge_requirement_versions(
        &mut runtimes,
        &scoped_surface.runtimes,
        target_os,
        "task toolchain-owned runtimes",
    )?;
    merge_requirement_versions(
        &mut tools,
        &scoped_surface.tools,
        target_os,
        "task toolchain-owned tools",
    )?;
    if backend == Backend::Native {
        let scoped_native = task.scoped_native_requirements_for_execution(backend, context_name);
        let native_surface =
            contract.native_prerequisite_requirement_surface_for_os(scoped_native, target_os);
        merge_requirement_versions(
            &mut runtimes,
            &native_surface.runtimes,
            target_os,
            "task native prerequisite runtimes",
        )?;
        merge_requirement_versions(
            &mut tools,
            &native_surface.tools,
            target_os,
            "task native prerequisite tools",
        )?;
    }

    Ok((
        runtimes
            .into_iter()
            .map(|(name, (version, _))| (name, version))
            .collect(),
        tools
            .into_iter()
            .map(|(name, (version, _))| (name, version))
            .collect(),
    ))
}

fn merge_requirement_versions<T>(
    target: &mut BTreeMap<String, (String, String)>,
    entries: &BTreeMap<String, T>,
    target_os: &str,
    source: &str,
) -> Result<(), String>
where
    T: RequirementVersionView,
{
    for (name, requirement) in entries {
        if !requirement.required_for_os(target_os) {
            continue;
        }
        let version = requirement.version_for_os(target_os).trim().to_string();
        if version.is_empty() {
            continue;
        }
        if let Some((existing, existing_source)) = target.get(name.as_str()) {
            if existing == &version {
                continue;
            }
            if existing == "*" && version != "*" {
                target.insert(name.clone(), (version, source.to_string()));
                continue;
            }
            if version == "*" {
                continue;
            }
            return Err(format!(
                "conflicting requirement for `{name}`: `{existing}` from {existing_source} vs `{version}` from {source}"
            ));
        }
        target.insert(name.clone(), (version, source.to_string()));
    }
    Ok(())
}

trait RequirementVersionView {
    fn version_for_os<'a>(&'a self, os: &str) -> &'a str;
    fn required_for_os(&self, os: &str) -> bool;
}

impl RequirementVersionView for RuntimeRequirement {
    fn version_for_os<'a>(&'a self, os: &str) -> &'a str {
        RuntimeRequirement::version_for_os(self, os)
    }

    fn required_for_os(&self, os: &str) -> bool {
        RuntimeRequirement::required_for_os(self, os)
    }
}

impl RequirementVersionView for ToolRequirement {
    fn version_for_os<'a>(&'a self, os: &str) -> &'a str {
        ToolRequirement::version_for_os(self, os)
    }

    fn required_for_os(&self, os: &str) -> bool {
        ToolRequirement::required_for_os(self, os)
    }
}

fn detect_missing_backend_requirements(
    runtimes: &BTreeMap<String, String>,
    tools: &BTreeMap<String, String>,
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
    policy_pack: Option<&OrgPolicyPack>,
    target_os: &str,
) -> Vec<BackendRequirementGap> {
    let mut missing = Vec::new();

    for (name, required_version) in runtimes {
        match probe_backend_runtime_requirement_version(backend, working_dir, name.as_str()) {
            Ok(None) => missing.push(BackendRequirementGap {
                kind: ProvisioningTargetKind::Runtime,
                name: name.clone(),
                required_version: required_version.clone(),
                details: String::from("command is not available"),
            }),
            Ok(Some(actual_version))
                if !version_matches_requirement(required_version, &actual_version) =>
            {
                missing.push(BackendRequirementGap {
                    kind: ProvisioningTargetKind::Runtime,
                    name: name.clone(),
                    required_version: required_version.clone(),
                    details: format!("resolved version is `{actual_version}`"),
                });
            }
            Ok(Some(actual_version)) => {
                if let Some(gap) = strict_policy_backend_gap(
                    policy_pack,
                    target_os,
                    ProvisioningTargetKind::Runtime,
                    name,
                    required_version,
                    &actual_version,
                ) {
                    missing.push(gap);
                }
            }
            Err(details) => missing.push(BackendRequirementGap {
                kind: ProvisioningTargetKind::Runtime,
                name: name.clone(),
                required_version: required_version.clone(),
                details,
            }),
        }
    }

    for (name, required_version) in tools {
        let executable = task_tool_executable_name(name.as_str());
        match probe_backend_command_version(backend, working_dir, executable) {
            Ok(None) => missing.push(BackendRequirementGap {
                kind: ProvisioningTargetKind::Tool,
                name: name.clone(),
                required_version: required_version.clone(),
                details: format!("command `{executable}` is not available"),
            }),
            Ok(Some(actual_version))
                if !version_matches_requirement(required_version, &actual_version) =>
            {
                missing.push(BackendRequirementGap {
                    kind: ProvisioningTargetKind::Tool,
                    name: name.clone(),
                    required_version: required_version.clone(),
                    details: format!("resolved version is `{actual_version}`"),
                });
            }
            Ok(Some(actual_version)) => {
                if let Some(gap) = strict_policy_backend_gap(
                    policy_pack,
                    target_os,
                    ProvisioningTargetKind::Tool,
                    name,
                    required_version,
                    &actual_version,
                ) {
                    missing.push(gap);
                }
            }
            Err(details) => missing.push(BackendRequirementGap {
                kind: ProvisioningTargetKind::Tool,
                name: name.clone(),
                required_version: required_version.clone(),
                details,
            }),
        }
    }

    missing
}

fn detect_missing_named_container_requirements(
    runtimes: &BTreeMap<String, String>,
    tools: &BTreeMap<String, String>,
    engine: &str,
    container_name: &str,
    task_name: &str,
    policy_pack: Option<&OrgPolicyPack>,
    target_os: &str,
) -> Vec<BackendRequirementGap> {
    let mut missing = Vec::new();

    for (name, required_version) in runtimes {
        match probe_named_container_runtime_requirement_version(
            engine,
            container_name,
            task_name,
            name.as_str(),
        ) {
            Ok(None) => missing.push(BackendRequirementGap {
                kind: ProvisioningTargetKind::Runtime,
                name: name.clone(),
                required_version: required_version.clone(),
                details: String::from("command is not available"),
            }),
            Ok(Some(actual_version))
                if !version_matches_requirement(required_version, &actual_version) =>
            {
                missing.push(BackendRequirementGap {
                    kind: ProvisioningTargetKind::Runtime,
                    name: name.clone(),
                    required_version: required_version.clone(),
                    details: format!("resolved version is `{actual_version}`"),
                });
            }
            Ok(Some(actual_version)) => {
                if let Some(gap) = strict_policy_backend_gap(
                    policy_pack,
                    target_os,
                    ProvisioningTargetKind::Runtime,
                    name,
                    required_version,
                    &actual_version,
                ) {
                    missing.push(gap);
                }
            }
            Err(details) => missing.push(BackendRequirementGap {
                kind: ProvisioningTargetKind::Runtime,
                name: name.clone(),
                required_version: required_version.clone(),
                details,
            }),
        }
    }

    for (name, required_version) in tools {
        let executable = task_tool_executable_name(name.as_str());
        match probe_named_container_command_version(engine, container_name, task_name, executable) {
            Ok(None) => missing.push(BackendRequirementGap {
                kind: ProvisioningTargetKind::Tool,
                name: name.clone(),
                required_version: required_version.clone(),
                details: format!("command `{executable}` is not available"),
            }),
            Ok(Some(actual_version))
                if !version_matches_requirement(required_version, &actual_version) =>
            {
                missing.push(BackendRequirementGap {
                    kind: ProvisioningTargetKind::Tool,
                    name: name.clone(),
                    required_version: required_version.clone(),
                    details: format!("resolved version is `{actual_version}`"),
                });
            }
            Ok(Some(actual_version)) => {
                if let Some(gap) = strict_policy_backend_gap(
                    policy_pack,
                    target_os,
                    ProvisioningTargetKind::Tool,
                    name,
                    required_version,
                    &actual_version,
                ) {
                    missing.push(gap);
                }
            }
            Err(details) => missing.push(BackendRequirementGap {
                kind: ProvisioningTargetKind::Tool,
                name: name.clone(),
                required_version: required_version.clone(),
                details,
            }),
        }
    }

    missing
}

fn strict_policy_backend_gap(
    policy_pack: Option<&OrgPolicyPack>,
    target_os: &str,
    kind: ProvisioningTargetKind,
    name: &str,
    required_version: &str,
    actual_version: &str,
) -> Option<BackendRequirementGap> {
    let details = policy_pack?.strict_version_compliance_violation_for_actual_version_os(
        target_os,
        kind,
        name,
        actual_version,
    )?;
    Some(BackendRequirementGap {
        kind,
        name: name.to_string(),
        required_version: required_version.to_string(),
        details,
    })
}

fn select_provisioning_actions_for_backend_gaps(
    policy_pack: &OrgPolicyPack,
    target_os: &str,
    missing: &[BackendRequirementGap],
) -> Result<Vec<ProvisioningAction>, String> {
    let mut actions = Vec::new();
    let mut seen = BTreeSet::new();

    for gap in missing {
        if !seen.insert(gap.key()) {
            continue;
        }
        let decision = match policy_pack.resolve_provisioning_for_os(
            target_os,
            gap.kind,
            gap.name.as_str(),
            gap.required_version.as_str(),
        ) {
            Ok(Some(decision)) => Some(decision),
            Ok(None) => resolve_strict_policy_backend_gap_fallback(policy_pack, target_os, gap)?,
            Err(_) => resolve_strict_policy_backend_gap_fallback(policy_pack, target_os, gap)?,
        };
        let Some(decision) = decision else {
            continue;
        };
        actions.push(ProvisioningAction {
            kind: crate::policy_pack::ProvisioningActionKind::SelectSource,
            target_kind: decision.kind,
            name: decision.name,
            requested_version: decision.requested_version,
            normalized_requirement: decision.normalized_requirement,
            resolved_version: decision.resolved_version,
            package: decision.package,
            source: decision.source,
            source_config: decision.source_config,
            approved_version: decision.approved_version,
            policy_match: decision.policy_match,
        });
    }

    Ok(actions)
}

fn resolve_strict_policy_backend_gap_fallback(
    policy_pack: &OrgPolicyPack,
    target_os: &str,
    gap: &BackendRequirementGap,
) -> Result<Option<crate::policy_pack::ProvisioningDecision>, String> {
    let Some(approved_versions) = policy_pack.effective_version_policy_versions_for_os(
        target_os,
        gap.kind,
        gap.name.as_str(),
    ) else {
        return Ok(None);
    };

    for approved_version in approved_versions {
        if !version_matches_requirement(gap.required_version.as_str(), approved_version.as_str()) {
            continue;
        }
        if let Some(decision) = policy_pack.resolve_provisioning_for_os(
            target_os,
            gap.kind,
            gap.name.as_str(),
            approved_version.as_str(),
        )? {
            return Ok(Some(decision));
        }
    }

    Ok(None)
}

fn version_matches_requirement(requirement: &str, actual: &str) -> bool {
    crate::doctor::version_matches(requirement, actual)
}

fn task_tool_executable_name(name: &str) -> &str {
    match name {
        "maven" => "mvn",
        "bundler" => "bundle",
        _ => name,
    }
}

fn task_runtime_executable_candidates(name: &str) -> Vec<String> {
    match name {
        "python" => vec![String::from("python3"), String::from("python")],
        "rust" => vec![String::from("rustc")],
        _ => vec![name.to_string()],
    }
}

fn probe_backend_runtime_requirement_version(
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
    runtime_name: &str,
) -> Result<Option<String>, String> {
    let mut last_error = None;
    for executable in task_runtime_executable_candidates(runtime_name) {
        match probe_backend_command_version(backend, working_dir, executable.as_str()) {
            Ok(Some(version)) => return Ok(Some(version)),
            Ok(None) => continue,
            Err(error) => {
                if last_error.is_none() {
                    last_error = Some(error);
                }
            }
        }
    }

    if let Some(error) = last_error {
        Err(error)
    } else {
        Ok(None)
    }
}

fn probe_named_container_runtime_requirement_version(
    engine: &str,
    container_name: &str,
    task_name: &str,
    runtime_name: &str,
) -> Result<Option<String>, String> {
    let mut last_error = None;
    for executable in task_runtime_executable_candidates(runtime_name) {
        match probe_named_container_command_version(
            engine,
            container_name,
            task_name,
            executable.as_str(),
        ) {
            Ok(Some(version)) => return Ok(Some(version)),
            Ok(None) => continue,
            Err(error) => {
                if last_error.is_none() {
                    last_error = Some(error);
                }
            }
        }
    }

    if let Some(error) = last_error {
        Err(error)
    } else {
        Ok(None)
    }
}

fn probe_backend_command_version(
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
    command_name: &str,
) -> Result<Option<String>, String> {
    if matches!(backend, ResolvedExecutionBackend::Native { .. }) {
        return probe_native_backend_command_version(working_dir, command_name);
    }
    let probe_command = backend_runtime_version_probe_command(command_name, backend);
    let output = run_backend_command_captured(
        "__ota_backend_requirement_probe__",
        probe_command.as_str(),
        working_dir,
        backend,
    )
    .map_err(|error| error.to_string())?;
    if output.exit_code == 127 {
        return Ok(None);
    }
    let combined = format!("{} {}", output.stdout, output.stderr);
    if let Some(version) = extract_probe_version_token(combined.as_str()) {
        return Ok(Some(version));
    }
    if output.exit_code != 0 {
        return Err(format!(
            "version probe command exited with code {}",
            output.exit_code
        ));
    }
    Err(String::from(
        "version probe did not return a parseable version",
    ))
}

fn probe_native_backend_command_version(
    working_dir: &Path,
    command_name: &str,
) -> Result<Option<String>, String> {
    let resolved_path = crate::doctor::resolve_command_path(command_name);
    if resolved_path.is_none() {
        return Ok(None);
    }

    let mut attempted_exit_code = None;
    let mut attempted_error = None;
    let mut parseable_attempt_observed = false;
    let probe_program = native_backend_probe_program(command_name, resolved_path.as_deref());

    for args in tool_version_probe_arg_sets(command_name) {
        let output = native_backend_probe_output(probe_program, args, working_dir);
        match output {
            Ok(output) => {
                if output.status.success() {
                    let combined = format!(
                        "{} {}",
                        String::from_utf8_lossy(&output.stdout),
                        String::from_utf8_lossy(&output.stderr)
                    );
                    if let Some(version) = extract_probe_version_token(combined.as_str()) {
                        return Ok(Some(version));
                    }
                    parseable_attempt_observed = true;
                    continue;
                }
                attempted_exit_code = output.status.code();
            }
            Err(error) => {
                attempted_error = Some(error.to_string());
            }
        }
    }

    if parseable_attempt_observed {
        return Err(String::from(
            "version probe did not return a parseable version",
        ));
    }

    if let Some(error) = attempted_error {
        return Err(format!("version probe command could not execute: {error}"));
    }

    if let Some(exit_code) = attempted_exit_code {
        return Err(format!(
            "version probe command exited with code {exit_code}"
        ));
    }

    Err(String::from(
        "version probe command failed before ota could read a version",
    ))
}

pub(crate) fn tool_version_probe_arg_sets(
    command_name: &str,
) -> &'static [&'static [&'static str]] {
    match command_name {
        "go" => &[&["version"]],
        "helm" => &[
            &["version", "--short"],
            &["version"],
            &["--version"],
            &["-version"],
        ],
        "kubectl" => &[
            &["version", "--client"],
            &["--version"],
            &["version"],
            &["-version"],
        ],
        _ => &[&["--version"], &["version"], &["-version"]],
    }
}

fn native_backend_probe_output(
    command_name: &OsStr,
    args: &[&str],
    working_dir: &Path,
) -> std::io::Result<std::process::Output> {
    let mut command = native_backend_probe_command(command_name);
    command
        .args(args)
        .current_dir(working_dir)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
}

#[cfg(windows)]
fn native_backend_probe_command(command_name: &OsStr) -> Command {
    let is_wrapper = Path::new(command_name)
        .extension()
        .and_then(|value| value.to_str())
        .is_some_and(|value| {
            value.eq_ignore_ascii_case("cmd") || value.eq_ignore_ascii_case("bat")
        });
    if is_wrapper {
        let mut command = Command::new("cmd");
        command.arg("/C").arg(command_name);
        return command;
    }
    Command::new(command_name)
}

#[cfg(not(windows))]
fn native_backend_probe_command(command_name: &OsStr) -> Command {
    Command::new(command_name)
}

fn native_backend_probe_program<'a>(
    command_name: &'a str,
    resolved_path: Option<&'a Path>,
) -> &'a OsStr {
    #[cfg(windows)]
    if let Some(path) = resolved_path
        && path
            .extension()
            .and_then(|value| value.to_str())
            .is_some_and(|value| {
                value.eq_ignore_ascii_case("cmd") || value.eq_ignore_ascii_case("bat")
            })
    {
        return path.as_os_str();
    }

    #[cfg(not(windows))]
    let _ = resolved_path;

    OsStr::new(command_name)
}

fn backend_runtime_version_probe_command(
    command_name: &str,
    backend: &ResolvedExecutionBackend,
) -> String {
    let quoted = shell_quote(command_name);
    let version_probe_commands = tool_runtime_version_probe_commands(command_name, quoted.as_str());
    if cfg!(windows) && matches!(backend, ResolvedExecutionBackend::Native { .. }) {
        return format!("where {quoted} >NUL 2>&1 && ({version_probe_commands}) || exit /B 127");
    }
    format!(
        "if command -v {quoted} >/dev/null 2>&1; then ({version_probe_commands}); else exit 127; fi"
    )
}

fn probe_named_container_command_version(
    engine: &str,
    container_name: &str,
    task_name: &str,
    command_name: &str,
) -> Result<Option<String>, String> {
    let quoted = shell_quote(command_name);
    let version_probe_commands = tool_runtime_version_probe_commands(command_name, quoted.as_str());
    let probe_command = format!(
        "if command -v {quoted} >/dev/null 2>&1; then ({version_probe_commands}); else exit 127; fi"
    );
    let path_export = container_task_path_export(engine, container_name, task_name, None)
        .map_err(|error| error.to_string())?;
    let probe_command =
        command_with_optional_path_export(probe_command.as_str(), path_export.as_deref());
    let output = container_command_output(
        engine,
        &[
            "exec",
            "-i",
            container_name,
            "sh",
            "-lc",
            probe_command.as_str(),
        ],
        None,
        task_name,
    )
    .map_err(|error| error.to_string())?;
    if output.exit_code == 127 {
        return Ok(None);
    }
    let combined = format!("{} {}", output.stdout, output.stderr);
    if let Some(version) = extract_probe_version_token(combined.as_str()) {
        return Ok(Some(version));
    }
    if output.exit_code != 0 {
        return Err(format!(
            "version probe command exited with code {}",
            output.exit_code
        ));
    }
    Err(String::from(
        "version probe did not return a parseable version",
    ))
}

pub(crate) fn tool_runtime_version_probe_commands(
    command_name: &str,
    quoted_command: &str,
) -> String {
    tool_version_probe_arg_sets(command_name)
        .into_iter()
        .map(|args| {
            let suffix = args
                .iter()
                .map(|arg| shell_quote(arg))
                .collect::<Vec<_>>()
                .join(" ");
            format!("{quoted_command} {suffix} 2>&1")
        })
        .collect::<Vec<_>>()
        .join(" || ")
}

fn extract_probe_version_token(output: &str) -> Option<String> {
    output
        .split_whitespace()
        .find(|token| token.chars().any(|ch| ch.is_ascii_digit()))
        .map(|token| {
            let normalized = token
                .trim_matches(|ch: char| !ch.is_ascii_alphanumeric() && ch != '.' && ch != '-')
                .trim_start_matches('v')
                .to_string();
            if let Some(first_digit) = normalized.find(|ch: char| ch.is_ascii_digit()) {
                normalized[first_digit..].to_string()
            } else {
                normalized
            }
        })
        .filter(|token| !token.is_empty())
}

fn provisioning_target_for_resolved_backend(
    contract_path: &Path,
    backend: &ResolvedExecutionBackend,
) -> Result<ProvisioningExecutionTarget, RunError> {
    match backend {
        ResolvedExecutionBackend::Native { .. } => Ok(ProvisioningExecutionTarget::Native),
        ResolvedExecutionBackend::Container {
            context_name,
            shared_local_backend,
            image,
            engine,
            lifecycle,
            memory_bytes,
            publications,
            dependency_isolation_paths,
            ..
        } => {
            let working_dir = contract_working_dir(contract_path);
            let identity_seed = container_identity_seed(
                context_name.as_deref(),
                shared_local_backend
                    .as_ref()
                    .map(|shared| shared.name.as_str()),
                shared_backend_publications_or_current(shared_local_backend.as_ref(), publications),
                dependency_isolation_paths,
                *memory_bytes,
            );
            let container_name = matches!(lifecycle, Lifecycle::Persistent).then(|| {
                persistent_container_name_for_seed(
                    working_dir,
                    image.as_str(),
                    engine.as_str(),
                    identity_seed.as_deref(),
                )
            });
            Ok(ProvisioningExecutionTarget::Container {
                image: image.clone(),
                engine: engine.clone(),
                lifecycle: *lifecycle,
                container_name,
            })
        }
        ResolvedExecutionBackend::Remote {
            shared_local_backend: _,
            provider,
            target,
            cwd,
            ssh,
        } => Ok(ProvisioningExecutionTarget::Remote {
            provider: provider.clone(),
            provider_command: None,
            target: target.clone(),
            cwd: cwd.clone(),
            ssh: ssh.clone(),
            context_name: None,
        }),
        ResolvedExecutionBackend::BackendProvider {
            shared_local_backend: _,
            provider,
            command,
            target,
            cwd,
        } => Ok(ProvisioningExecutionTarget::Remote {
            provider: provider.clone(),
            provider_command: Some(command.clone()),
            target: target.clone(),
            cwd: cwd.clone(),
            ssh: None,
            context_name: None,
        }),
    }
}

fn backend_fulfillment_output_mode(mode: TaskExecutionMode) -> ProvisioningOutputMode {
    match mode {
        TaskExecutionMode::Capture | TaskExecutionMode::CaptureActivation => {
            ProvisioningOutputMode::Capture
        }
        TaskExecutionMode::Stream { .. } => ProvisioningOutputMode::StreamAndCapture,
    }
}

fn render_backend_fulfillment_action(action: &ProvisioningAction) -> String {
    format!(
        "{} {} {} via {}{}",
        action.target_kind,
        action.display_name(),
        action.version_display(),
        action.source,
        action.policy_display_suffix()
    )
}

fn adapter_bootstrap_request_for_provisioning_sources(
    policy_pack: &OrgPolicyPack,
    provisioning_request: &ProvisioningBackendRequest,
) -> ProvisioningBackendRequest {
    let mut adapters = provisioning_request
        .actions
        .iter()
        .map(|action| action.source.trim())
        .filter(|source| !source.is_empty() && !source.ends_with("-bootstrap"))
        .collect::<Vec<_>>();
    adapters.sort_unstable();
    adapters.dedup();
    policy_pack.adapter_bootstrap_backend_request(&adapters)
}

fn apply_run_path_provisioning_request_with_bootstrap(
    request: &ProvisioningBackendRequest,
    adapter_bootstrap: &ProvisioningBackendRequest,
    working_dir: &Path,
    target: &ProvisioningExecutionTarget,
    output_mode: ProvisioningOutputMode,
) -> Result<crate::provisioning::ProvisioningBackendOutput, ProvisioningBackendError> {
    match apply_provisioning_request_with_target(request, working_dir, target, output_mode) {
        Ok(output) => Ok(output),
        Err(error)
            if !adapter_bootstrap.actions.is_empty()
                && run_path_provisioning_error_supports_adapter_bootstrap(&error) =>
        {
            let bootstrap_output = apply_provisioning_request_with_target(
                adapter_bootstrap,
                working_dir,
                target,
                output_mode,
            )?;
            let mut output =
                apply_provisioning_request_with_target(request, working_dir, target, output_mode)?;
            output.stdout = format!("{}{}", bootstrap_output.stdout, output.stdout);
            output.stderr = format!("{}{}", bootstrap_output.stderr, output.stderr);
            Ok(output)
        }
        Err(error) => Err(error),
    }
}

fn mise_tool_wrapper_dir() -> &'static str {
    "/tmp/ota-managed-tools/bin"
}

fn source_managed_binary_dir() -> &'static str {
    ".ota/state/source-managed/bin"
}

fn source_managed_path_export_segments(actions: &[ProvisioningAction]) -> Vec<String> {
    let mut segments = Vec::new();
    if actions.iter().any(|action| {
        action.source == "release-asset" && action.target_kind == ProvisioningTargetKind::Tool
    }) {
        segments.push(source_managed_binary_dir().to_string());
    }
    if actions
        .iter()
        .any(|action| action.source == "mise" && action.target_kind == ProvisioningTargetKind::Tool)
    {
        segments.push(mise_tool_wrapper_dir().to_string());
    }
    segments
}

fn source_managed_tool_path_export_required(actions: &[ProvisioningAction]) -> bool {
    !source_managed_path_export_segments(actions).is_empty()
}

fn source_managed_actions(actions: &[ProvisioningAction]) -> Vec<ProvisioningAction> {
    actions
        .iter()
        .filter(|action| action.source == "mise" || action.source == "release-asset")
        .cloned()
        .collect()
}

#[cfg(test)]
fn source_managed_tool_wrapper_path_export(path_export: Option<&str>) -> String {
    match path_export {
        Some(path) => format!("{}:{path}", mise_tool_wrapper_dir()),
        None => format!("{}:$PATH", mise_tool_wrapper_dir()),
    }
}

fn source_managed_tool_path_export(
    actions: &[ProvisioningAction],
    path_export: Option<&str>,
) -> String {
    let mut segments = source_managed_path_export_segments(actions);
    if let Some(path) = path_export {
        segments.push(path.to_string());
        return segments.join(":");
    }
    segments.push(String::from("$PATH"));
    segments.join(":")
}

fn merge_path_export_with_container_path(
    path_export: Option<&str>,
    container_path: Option<&str>,
) -> Option<String> {
    match (path_export, container_path) {
        (Some(path_export), Some(container_path)) => Some(
            path_export
                .replace("${PATH}", container_path)
                .replace("$PATH", container_path),
        ),
        (Some(path_export), None) => Some(path_export.to_string()),
        (None, Some(container_path)) => Some(container_path.to_string()),
        (None, None) => None,
    }
}

fn declared_container_path(
    engine: &str,
    container_name: &str,
    task_name: &str,
) -> Result<Option<String>, RunError> {
    let inspect = container_command_output(
        engine,
        &[
            "inspect",
            "--format",
            "{{json .Config.Env}}",
            container_name,
        ],
        None,
        task_name,
    )?;
    if inspect.exit_code != 0 {
        return Ok(None);
    }
    let env_entries = serde_json::from_str::<Vec<String>>(inspect.stdout.trim()).ok();
    Ok(env_entries.and_then(|entries| {
        entries
            .into_iter()
            .find_map(|entry| entry.strip_prefix("PATH=").map(str::to_string))
    }))
}

fn container_task_path_export(
    engine: &str,
    container_name: &str,
    task_name: &str,
    path_export: Option<&str>,
) -> Result<Option<String>, RunError> {
    let container_path = declared_container_path(engine, container_name, task_name)?;
    Ok(merge_path_export_with_container_path(
        path_export,
        container_path.as_deref(),
    ))
}

fn source_managed_remaining_gap_covered(
    gap: &BackendRequirementGap,
    actions: &[ProvisioningAction],
) -> bool {
    actions.iter().any(|action| {
        (action.source == "mise" || action.source == "release-asset")
            && action.name == gap.name
            && matches!(
                (&gap.kind, action.target_kind),
                (ProvisioningTargetKind::Tool, ProvisioningTargetKind::Tool)
                    | (
                        ProvisioningTargetKind::Runtime,
                        ProvisioningTargetKind::Runtime
                    )
            )
    })
}

fn provisioning_action_effective_version(action: &ProvisioningAction) -> &str {
    action
        .resolved_version
        .as_deref()
        .or(action.approved_version.as_deref())
        .unwrap_or(action.requested_version.as_str())
}

fn source_managed_mise_targets(actions: &[ProvisioningAction]) -> Vec<String> {
    actions
        .iter()
        .filter(|action| action.source == "mise")
        .map(|action| {
            format!(
                "{}@{}",
                action.install_name(),
                provisioning_action_effective_version(action)
            )
        })
        .collect::<Vec<_>>()
}

#[cfg(unix)]
fn wrap_command_for_source_managed_actions(
    command: &str,
    actions: &[ProvisioningAction],
) -> String {
    let mise_targets = source_managed_mise_targets(actions);
    if mise_targets.is_empty() {
        return command.to_string();
    }

    let mut wrapped = String::from(
        r#"if command -v mise >/dev/null 2>&1; then __ota_mise="$(command -v mise)"; elif [ -x "$HOME/.local/bin/mise" ]; then __ota_mise="$HOME/.local/bin/mise"; else __ota_mise="mise"; fi; "$__ota_mise" exec"#,
    );
    for target in &mise_targets {
        wrapped.push(' ');
        wrapped.push_str(&shell_quote(target));
    }
    wrapped.push_str(" -- sh -lc ");
    wrapped.push_str(&shell_quote(command));
    wrapped
}

#[cfg(windows)]
fn wrap_command_for_source_managed_actions(
    command: &str,
    actions: &[ProvisioningAction],
) -> String {
    let mise_targets = source_managed_mise_targets(actions);
    if mise_targets.is_empty() {
        return command.to_string();
    }

    let mut wrapped = String::from(
        r#"cmd /C set "__OTA_MISE=mise" && if exist "%LOCALAPPDATA%\mise\bin\mise.exe" set "__OTA_MISE=%LOCALAPPDATA%\mise\bin\mise.exe" && if exist "%USERPROFILE%\.local\bin\mise.exe" set "__OTA_MISE=%USERPROFILE%\.local\bin\mise.exe" && "%__OTA_MISE%" exec"#,
    );
    for target in &mise_targets {
        wrapped.push(' ');
        wrapped.push_str(&cmd_quote(target));
    }
    wrapped.push_str(" -- cmd /C ");
    wrapped.push_str(&cmd_quote(command));
    wrapped
}

fn install_source_managed_tool_wrappers(
    engine: &str,
    container_name: &str,
    task_name: &str,
    actions: &[ProvisioningAction],
) -> Result<(), RunError> {
    for action in actions {
        if action.source != "mise" || action.target_kind != ProvisioningTargetKind::Tool {
            continue;
        }
        let tool = action.install_name();
        let version = provisioning_action_effective_version(action);
        let wrapper = format!(
            "mkdir -p {wrapper_dir}\ncat > {wrapper_dir}/{tool} <<'EOF'\n#!/bin/sh\nif command -v mise >/dev/null 2>&1; then __ota_mise=\"$(command -v mise)\"; elif [ -x \"$HOME/.local/bin/mise\" ]; then __ota_mise=\"$HOME/.local/bin/mise\"; else __ota_mise=\"mise\"; fi\nexec \"$__ota_mise\" exec {target} -- {tool} \"$@\"\nEOF\nchmod +x {wrapper_dir}/{tool}",
            tool = tool,
            wrapper_dir = mise_tool_wrapper_dir(),
            target = shell_quote(&format!("{tool}@{version}")),
        );
        let output = container_command_output(
            engine,
            &["exec", "-i", container_name, "sh", "-lc", wrapper.as_str()],
            None,
            task_name,
        )?;
        if output.exit_code != 0 {
            return Err(RunError::BackendFulfillmentFailed {
                task: task_name.to_string(),
                backend_unit: format!("context-wrapper:{container_name}"),
                details: format!("failed to materialize source-managed tool wrapper for `{tool}`"),
                evidence: BackendFulfillmentEvidence {
                    backend_unit: format!("context-wrapper:{container_name}"),
                    backend: String::from("container"),
                    mode: BackendFulfillmentMode::Run,
                    declared_runtimes: BTreeMap::new(),
                    declared_tools: BTreeMap::new(),
                    missing: vec![format!("tool `{tool}` wrapper installation failed")],
                    actions: vec![format!(
                        "tool {tool} {} via {}",
                        action.requested_version, action.source
                    )],
                    result: BackendFulfillmentResult::Failed,
                    task_executed: false,
                },
            });
        }
    }
    Ok(())
}

fn run_path_provisioning_error_supports_adapter_bootstrap(
    error: &ProvisioningBackendError,
) -> bool {
    match error {
        ProvisioningBackendError::MissingCommand { .. } => true,
        ProvisioningBackendError::CommandFailed {
            exit_code, stderr, ..
        }
        | ProvisioningBackendError::DiagnosedCommandFailed {
            exit_code, stderr, ..
        } => {
            *exit_code == 127
                && stderr.lines().any(|line| {
                    let normalized = line.trim().to_ascii_lowercase();
                    normalized.contains("not found") || normalized.contains("command not found")
                })
        }
        _ => false,
    }
}

fn render_backend_fulfillment_failure(error: ProvisioningBackendError) -> String {
    match error {
        ProvisioningBackendError::DiagnosedCommandFailed {
            command,
            exit_code,
            diagnosis,
            ..
        } => format!(
            "backend `{command}` exited with status {exit_code}: {:?} `{}` `{}`",
            diagnosis.kind, diagnosis.target_kind, diagnosis.name
        ),
        other => other.to_string(),
    }
}

fn render_backend_fulfillment_note(evidence: &BackendFulfillmentEvidence) -> String {
    let mode = match evidence.mode {
        BackendFulfillmentMode::None => "none",
        BackendFulfillmentMode::Run => "run",
    };
    match evidence.result {
        BackendFulfillmentResult::RequirementsSatisfied => format!(
            "backend `{}` requirements already satisfied (fulfillment mode `{mode}`)",
            evidence.backend_unit
        ),
        BackendFulfillmentResult::Fulfilled => format!(
            "backend `{}` fulfilled on run path via {} action(s)",
            evidence.backend_unit,
            evidence.actions.len()
        ),
        BackendFulfillmentResult::MissingRequirements => format!(
            "backend `{}` is missing requirements (fulfillment mode `{mode}`)",
            evidence.backend_unit
        ),
        BackendFulfillmentResult::Failed => {
            format!(
                "backend `{}` run-path fulfillment failed",
                evidence.backend_unit
            )
        }
    }
}

#[derive(Debug, Default, Clone, PartialEq, Eq)]
struct ResolvedTaskInputs {
    env_overrides: BTreeMap<String, String>,
    target_resolutions: Vec<TaskTargetResolutionEvidence>,
}

fn resolve_task_inputs(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    task: &TaskSpec,
    input_args: &[String],
    caller_backend: Backend,
    execution_overrides: ExecutionOverrides,
    enforce_required_inputs: bool,
) -> Result<ResolvedTaskInputs, RunError> {
    let mut provided = BTreeMap::new();
    let mut explicit_inputs = BTreeSet::new();
    if let Some(input_name) = single_task_input_name(task)
        && let Some(value) = single_task_input_shorthand_value(input_args)
    {
        insert_task_input_value(
            task_name,
            task,
            &mut provided,
            input_name.to_string(),
            value,
        )?;
        explicit_inputs.insert(input_name.to_string());
    } else {
        let mut index = 0;

        while index < input_args.len() {
            let token = &input_args[index];
            if token == "--" {
                index += 1;
                continue;
            }
            if !token.starts_with("--") || token.len() <= 2 {
                return Err(RunError::InvalidTaskInputSyntax {
                    task: task_name.to_string(),
                    input: token.trim_start_matches('-').to_string(),
                    flag: token.clone(),
                });
            }

            let remainder = &token[2..];
            let (flag, inline_value) = if let Some((flag, value)) = remainder.split_once('=') {
                (flag, Some(value.to_string()))
            } else {
                (remainder, None)
            };

            if flag.is_empty() {
                return Err(RunError::InvalidTaskInputSyntax {
                    task: task_name.to_string(),
                    input: String::new(),
                    flag: token.clone(),
                });
            }

            let input_name = flag.replace('-', "_");
            let Some(_spec) = task.inputs.get(&input_name) else {
                return Err(RunError::UnknownTaskInput {
                    task: task_name.to_string(),
                    input: input_name,
                });
            };

            let value = match inline_value {
                Some(value) => value,
                None => {
                    index += 1;
                    let Some(next) = input_args.get(index) else {
                        return Err(RunError::MissingTaskInputValue {
                            task: task_name.to_string(),
                            input: input_name,
                        });
                    };
                    next.clone()
                }
            };

            insert_task_input_value(task_name, task, &mut provided, input_name, value)?;
            explicit_inputs.insert(flag.replace('-', "_"));

            index += 1;
        }
    }

    let target_resolutions = resolve_task_target_bindings(
        contract,
        contract_path,
        task_name,
        task,
        &explicit_inputs,
        &mut provided,
        caller_backend,
        execution_overrides,
    )?;

    for (name, spec) in &task.inputs {
        if provided.contains_key(name) {
            continue;
        }
        if let Some(default) = spec.default.clone() {
            if !spec.allowed.is_empty() && !spec.allowed.iter().any(|allowed| allowed == &default) {
                return Err(RunError::InvalidTaskInputValue {
                    task: task_name.to_string(),
                    input: name.clone(),
                    value: default,
                    allowed: spec.allowed.join(", "),
                });
            }
            provided.insert(name.clone(), default);
        } else if spec.required && enforce_required_inputs {
            return Err(RunError::MissingRequiredTaskInput {
                task: task_name.to_string(),
                input: name.clone(),
            });
        }
    }

    Ok(ResolvedTaskInputs {
        env_overrides: provided
            .into_iter()
            .map(|(name, value)| (task_input_env_name(&name), value))
            .chain(
                target_resolutions
                    .iter()
                    .filter(|resolution| resolution.override_input.is_none())
                    .map(|resolution| {
                        (
                            task_target_env_name(resolution.target.as_str()),
                            resolution.effective_url.clone(),
                        )
                    }),
            )
            .collect(),
        target_resolutions,
    })
}

fn apply_task_target_activations(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    task: &TaskSpec,
    caller_backend: Backend,
    policy_env: Option<&BTreeMap<String, String>>,
    mode: TaskExecutionMode,
    working_dir: &Path,
    current_os: &str,
    generation: usize,
    input_resolution: &mut ResolvedTaskInputs,
    state: &mut TaskRunState,
) -> Result<(), RunError> {
    for resolution in &mut input_resolution.target_resolutions {
        let Some(target_spec) = task.targets.get(resolution.target.as_str()) else {
            continue;
        };
        let activation = match target_spec.activation.mode {
            TaskTargetActivationMode::Manual => TaskTargetActivationEvidence {
                mode: TaskTargetActivationMode::Manual,
                status: TaskTargetActivationStatus::Manual,
            },
            TaskTargetActivationMode::EnsureStarted
            | TaskTargetActivationMode::RestartReady
            | TaskTargetActivationMode::EnsureReady
            | TaskTargetActivationMode::EnsureRunning => {
                let status = match resolution.source {
                    TaskTargetResolutionSource::ExplicitOverride => {
                        TaskTargetActivationStatus::SkippedExplicitOverride
                    }
                    TaskTargetResolutionSource::CompatibilityLiteralDefault => {
                        return Err(RunError::TaskTargetResolutionFailed {
                            task: task_name.to_string(),
                            target: resolution.target.clone(),
                            details: format!(
                                "target activation `{}` requires a resolvable local producer service target; target `{}` fell back to compatibility literal default instead",
                                target_spec.activation.mode.as_str(),
                                resolution.target
                            ),
                        });
                    }
                    TaskTargetResolutionSource::TargetBinding => ensure_target_producer_state(
                        contract,
                        contract_path,
                        task_name,
                        resolution.target.as_str(),
                        target_spec,
                        caller_backend,
                        policy_env,
                        mode.clone(),
                        working_dir,
                        current_os,
                        generation,
                        state,
                    )?,
                };
                TaskTargetActivationEvidence {
                    mode: target_spec.activation.mode,
                    status,
                }
            }
        };
        resolution.activation = Some(activation);
    }

    Ok(())
}

fn ensure_target_producer_state(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    target_name: &str,
    target_spec: &TaskTargetSpec,
    caller_backend: Backend,
    policy_env: Option<&BTreeMap<String, String>>,
    mode: TaskExecutionMode,
    _working_dir: &Path,
    current_os: &str,
    generation: usize,
    state: &mut TaskRunState,
) -> Result<TaskTargetActivationStatus, RunError> {
    let activation_mode = target_spec.activation.mode;
    let service = target_spec.service.as_ref().ok_or_else(|| {
        RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` requires a `service` target; `url` targets only support `manual`",
                activation_mode.as_str()
            ),
        }
    })?;
    let service_member = service
        .member
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let service_repo = service
        .repo
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let producer_task_name = service.task.trim();
    let (producer_contract, producer_contract_path) = load_target_service_contract_with_path(
        contract,
        contract_path,
        task_name,
        target_name,
        service_member.as_deref(),
        service_repo.as_deref(),
    )?;
    let producer_listener_name = resolve_service_target_listener_name(
        &producer_contract,
        task_name,
        target_name,
        service_member.as_deref(),
        service_repo.as_deref(),
        producer_task_name,
        service.listener.as_deref(),
    )?;
    let producer_key = (
        service_member.clone(),
        service_repo.clone(),
        producer_task_name.to_string(),
        producer_listener_name.clone(),
    );
    if let Some(status) = state.ensured_target_producers.get(&producer_key).copied() {
        return Ok(status);
    }
    let producer_working_dir = contract_working_dir(producer_contract_path.as_path()).to_path_buf();
    let producer_backend = resolve_execution_backend_with_contract_path(
        &producer_contract,
        producer_task_name,
        ExecutionOverrides::default(),
        Some(producer_contract_path.as_path()),
    )?;
    let producer_backend_kind = resolved_execution_backend_kind(&producer_backend);
    let producer_task = producer_contract.tasks.get(producer_task_name).ok_or_else(|| {
        RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: match service_member.as_deref() {
                Some(member) => format!(
                    "target references unknown `service.task: {producer_task_name}` in member `{member}`"
                ),
                None => match service_repo.as_deref() {
                    Some(repo) => format!(
                        "target references unknown `service.task: {producer_task_name}` in workspace repo `{repo}`"
                    ),
                    None => format!("target references unknown `service.task: {producer_task_name}`"),
                },
            },
        }
    })?;
    let producer_task_command = producer_task
        .resolved_execution_for_backend(producer_backend_kind, current_os)
        .map(|execution| execution.preview())
        .ok_or_else(|| RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` requires producer task `{producer_task_name}` to declare one execution body for backend `{}`",
                activation_mode.as_str(),
                match producer_backend_kind {
                    Backend::Native => "native",
                    Backend::Container => "container",
                    Backend::Remote => "remote",
                }
            ),
        })?;
    let producer_runtime_spec = producer_task
        .service_runtime_for_backend(producer_backend_kind)
        .ok_or_else(|| RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` requires producer task `{producer_task_name}` to resolve to a service runtime",
                activation_mode.as_str()
            ),
        })?;
    if !producer_runtime_spec
        .listeners
        .contains_key(producer_listener_name.as_str())
    {
        return Err(RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` references unknown listener `{producer_listener_name}` on producer task `{producer_task_name}`",
                activation_mode.as_str()
            ),
        });
    }
    let readiness_target = declared_target_probe_target(
        contract,
        task_name,
        target_name,
        target_spec,
        caller_backend,
        producer_working_dir.as_path(),
        &producer_backend,
        contract
            .tasks
            .get(task_name)
            .expect("validated task execution should only reference known tasks"),
        producer_task,
        producer_task_name,
        producer_listener_name.as_str(),
        producer_runtime_spec,
    )?;
    let mut loader = match &mode {
        TaskExecutionMode::Stream {
            emit_progress: true,
            ..
        } => StreamPhaseLoader::start_with_policy(
            &activation_loader_label(activation_mode, producer_task_name, &readiness_target),
            StreamPhaseLoaderPolicy::Delayed,
        ),
        _ => None,
    };
    let readiness_timing =
        readiness_timing_policy(Some(contract), producer_runtime_spec.readiness.as_ref());

    let producer_initially_observed =
        readiness_target_observed_with_timeout(&readiness_target, readiness_timing.timeout);
    let producer_is_non_persistent_container = producer_backend_kind == Backend::Container
        && !matches!(
            producer_backend,
            ResolvedExecutionBackend::Container {
                lifecycle: Lifecycle::Persistent,
                ..
            }
        );

    if producer_is_non_persistent_container {
        if let Some(loader) = loader.take() {
            loader.stop();
        }
        return Err(RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` currently supports only persistent container producer services; `{producer_task_name}` resolves to `container`",
                activation_mode.as_str()
            ),
        });
    }

    if producer_initially_observed && activation_mode != TaskTargetActivationMode::RestartReady {
        if let Some(loader) = loader.take() {
            loader.stop();
        }
        let reused_status = match activation_mode {
            TaskTargetActivationMode::Manual => TaskTargetActivationStatus::Manual,
            TaskTargetActivationMode::EnsureStarted => TaskTargetActivationStatus::ReusedStarted,
            TaskTargetActivationMode::RestartReady => TaskTargetActivationStatus::RestartedReady,
            TaskTargetActivationMode::EnsureReady => TaskTargetActivationStatus::ReusedReady,
            TaskTargetActivationMode::EnsureRunning => TaskTargetActivationStatus::ReusedRunning,
        };
        state
            .ensured_target_producers
            .insert(producer_key, reused_status);
        return Ok(reused_status);
    }

    let producer_activation_mode = match &producer_backend {
        ResolvedExecutionBackend::Native { .. } => {
            #[cfg(not(unix))]
            {
                if let Some(loader) = loader.take() {
                    loader.stop();
                }
                return Err(RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` currently supports native producer services only on unix-like hosts; `{producer_task_name}` resolves to `native`",
                        activation_mode.as_str()
                    ),
                });
            }
            #[cfg(unix)]
            TaskExecutionMode::CaptureActivation
        }
        ResolvedExecutionBackend::Container {
            lifecycle: Lifecycle::Persistent,
            ..
        } => TaskExecutionMode::Capture,
        ResolvedExecutionBackend::Remote { .. } => TaskExecutionMode::CaptureActivation,
        ResolvedExecutionBackend::BackendProvider { provider, .. } => {
            if let Some(loader) = loader.take() {
                loader.stop();
            }
            let Some(extension) = backend_provider_extension(&producer_contract, provider) else {
                return Err(RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` cannot use backend provider `{provider}` because it is not declared in ota.yaml",
                        activation_mode.as_str()
                    ),
                });
            };
            if !extension
                .activation
                .as_ref()
                .is_some_and(|activation| activation.provider_managed_cleanup)
            {
                return Err(RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` requires backend provider `{provider}` to declare `activation.provider_managed_cleanup: true`",
                        activation_mode.as_str()
                    ),
                });
            }
            TaskExecutionMode::CaptureActivation
        }
        ResolvedExecutionBackend::Container { .. } => {
            if let Some(loader) = loader.take() {
                loader.stop();
            }
            return Err(RunError::TaskTargetResolutionFailed {
                task: task_name.to_string(),
                target: target_name.to_string(),
                details: format!(
                    "target activation `{}` currently supports only persistent container producer services; `{producer_task_name}` resolves to `container`",
                    activation_mode.as_str()
                ),
            });
        }
    };
    if producer_backend_kind == Backend::Container
        && !matches!(
            producer_backend,
            ResolvedExecutionBackend::Container {
                lifecycle: Lifecycle::Persistent,
                ..
            }
        )
    {
        if let Some(loader) = loader.take() {
            loader.stop();
        }
        return Err(RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` currently supports only persistent container producer services; `{producer_task_name}` resolves to `container`",
                activation_mode.as_str()
            ),
        });
    }
    if activation_mode == TaskTargetActivationMode::RestartReady && producer_initially_observed {
        restart_target_producer(
            task_name,
            target_name,
            producer_task_name,
            &producer_backend,
            producer_runtime_spec,
            Some(producer_task_command.as_str()),
            producer_working_dir.as_path(),
            &readiness_target,
        )?;
    }
    let remove_backend_on_interrupt =
        activation_started_producer_requires_backend_cleanup_on_interrupt(
            producer_task_name,
            &producer_backend,
            producer_working_dir.as_path(),
        )?;

    let producer_contract = producer_contract.clone();
    let producer_contract_path = producer_contract_path.clone();
    let producer_backend_clone = producer_backend.clone();
    let producer_policy_env = policy_env.cloned();
    let producer_task_name_owned = producer_task_name.to_string();
    let producer_current_os = current_os.to_string();
    let producer_working_dir_for_thread = producer_working_dir.clone();
    let (result_tx, result_rx) = mpsc::channel();

    thread::spawn(move || {
        let mut producer_state = TaskRunState::default();
        let result = execute_task_with_hooks(
            &producer_contract,
            producer_contract_path.as_path(),
            producer_task_name_owned.as_str(),
            &[],
            ExecutionOverrides::default(),
            producer_policy_env.as_ref(),
            &producer_backend_clone,
            producer_activation_mode,
            producer_working_dir_for_thread.as_path(),
            producer_current_os.as_str(),
            TaskExecutionRelation::Requested,
            generation.saturating_add(1),
            &mut producer_state,
        );
        let _ = result_tx.send((result, producer_state));
    });
    state.activation_started_producers.insert(
        (
            service_member.clone(),
            service_repo.clone(),
            producer_task_name.to_string(),
        ),
        ActivationStartedProducerCleanup {
            task_name: producer_task_name.to_string(),
            backend: producer_backend.clone(),
            runtime: Some(producer_runtime_spec.clone()),
            command: matches!(
                producer_backend,
                ResolvedExecutionBackend::BackendProvider { .. }
            )
            .then_some(producer_task_command.clone()),
            working_dir: producer_working_dir.clone(),
            remove_backend_on_interrupt,
        },
    );
    let backend_provider_handoff = matches!(
        producer_backend,
        ResolvedExecutionBackend::BackendProvider { .. }
    );

    if activation_mode == TaskTargetActivationMode::EnsureStarted {
        if let Ok((result, producer_state)) = result_rx.try_recv() {
            if backend_provider_handoff && matches!(result, Ok(0)) {
                if let Some(loader) = loader.take() {
                    loader.stop();
                }
                state
                    .ensured_target_producers
                    .insert(producer_key, TaskTargetActivationStatus::StartedStarted);
                return Ok(TaskTargetActivationStatus::StartedStarted);
            }
            if let Some(loader) = loader.take() {
                loader.stop();
            }
            state.activation_started_producers.remove(&(
                service_member.clone(),
                service_repo.clone(),
                producer_task_name.to_string(),
            ));
            let producer_label = service_target_producer_label(
                service_member.as_deref(),
                service_repo.as_deref(),
                producer_task_name,
            );
            return Err(target_activation_producer_failure(
                task_name,
                target_name,
                activation_mode,
                producer_label.as_str(),
                result,
                producer_state,
            ));
        }
        if let Some(loader) = loader.take() {
            loader.stop();
        }
        state
            .ensured_target_producers
            .insert(producer_key, TaskTargetActivationStatus::StartedStarted);
        return Ok(TaskTargetActivationStatus::StartedStarted);
    }

    let mut result_rx = Some(result_rx);
    let mut next_probe_at = Instant::now() + readiness_timing.start_period;
    let mut failed_probes = 0u32;
    loop {
        if Instant::now() >= next_probe_at {
            if readiness_target_observed_with_timeout(&readiness_target, readiness_timing.timeout) {
                if let Some(loader) = loader.take() {
                    loader.stop();
                }
                let started_status = match activation_mode {
                    TaskTargetActivationMode::Manual => TaskTargetActivationStatus::Manual,
                    TaskTargetActivationMode::EnsureStarted => {
                        TaskTargetActivationStatus::StartedStarted
                    }
                    TaskTargetActivationMode::RestartReady => {
                        TaskTargetActivationStatus::RestartedReady
                    }
                    TaskTargetActivationMode::EnsureReady => {
                        TaskTargetActivationStatus::StartedReady
                    }
                    TaskTargetActivationMode::EnsureRunning => {
                        TaskTargetActivationStatus::StartedRunning
                    }
                };
                state
                    .ensured_target_producers
                    .insert(producer_key, started_status);
                return Ok(started_status);
            }
            failed_probes = failed_probes.saturating_add(1);
            if let Some(retries) = readiness_timing.retries
                && failed_probes >= retries
            {
                if let Some(loader) = loader.take() {
                    loader.stop();
                }
                let cleanup_note = cleanup_activation_started_producer_and_note(
                    producer_task_name,
                    &producer_backend,
                    Some(producer_runtime_spec),
                    Some(producer_task_command.as_str()),
                    producer_working_dir.as_path(),
                    remove_backend_on_interrupt,
                );
                state.activation_started_producers.remove(&(
                    service_member.clone(),
                    service_repo.clone(),
                    producer_task_name.to_string(),
                ));
                return Err(RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` for producer task `{producer_task_name}` did not satisfy readiness after {} failed probe attempt{}{}",
                        activation_mode.as_str(),
                        retries,
                        if retries == 1 { "" } else { "s" },
                        cleanup_note
                            .as_deref()
                            .map(|note| format!("; {note}"))
                            .unwrap_or_default()
                    ),
                });
            }
            next_probe_at = Instant::now() + readiness_timing.interval;
        }

        if let Some(receiver) = result_rx.as_ref()
            && let Ok((result, producer_state)) = receiver.try_recv()
        {
            if backend_provider_handoff && matches!(result, Ok(0)) {
                result_rx = None;
            } else {
                if let Some(loader) = loader.take() {
                    loader.stop();
                }
                state.activation_started_producers.remove(&(
                    service_member.clone(),
                    service_repo.clone(),
                    producer_task_name.to_string(),
                ));
                let producer_label = service_target_producer_label(
                    service_member.as_deref(),
                    service_repo.as_deref(),
                    producer_task_name,
                );
                return Err(target_activation_producer_failure(
                    task_name,
                    target_name,
                    activation_mode,
                    producer_label.as_str(),
                    result,
                    producer_state,
                ));
            }
        }

        if RUN_INTERRUPT_REQUESTED.load(Ordering::Relaxed) {
            if let Some(loader) = loader.take() {
                loader.stop();
            }
            state.interrupted = true;
            let cleanup_note = match result_rx.take() {
                Some(receiver) => match receiver.recv_timeout(Duration::from_secs(5)) {
                    Ok((_result, producer_state)) => {
                        state.activation_started_producers.remove(&(
                            service_member.clone(),
                            service_repo.clone(),
                            producer_task_name.to_string(),
                        ));
                        merge_execution_note(
                            producer_state.execution_note,
                            cleanup_activation_started_producer_and_note(
                                producer_task_name,
                                &producer_backend,
                                Some(producer_runtime_spec),
                                Some(producer_task_command.as_str()),
                                producer_working_dir.as_path(),
                                remove_backend_on_interrupt,
                            ),
                        )
                    }
                    Err(mpsc::RecvTimeoutError::Timeout) => {
                        let note = cleanup_activation_started_producer_and_note(
                            producer_task_name,
                            &producer_backend,
                            Some(producer_runtime_spec),
                            Some(producer_task_command.as_str()),
                            producer_working_dir.as_path(),
                            remove_backend_on_interrupt,
                        );
                        state.activation_started_producers.remove(&(
                            service_member.clone(),
                            service_repo.clone(),
                            producer_task_name.to_string(),
                        ));
                        note
                    }
                    Err(mpsc::RecvTimeoutError::Disconnected) => {
                        state.activation_started_producers.remove(&(
                            service_member.clone(),
                            service_repo.clone(),
                            producer_task_name.to_string(),
                        ));
                        None
                    }
                },
                None => {
                    let note = cleanup_activation_started_producer_and_note(
                        producer_task_name,
                        &producer_backend,
                        Some(producer_runtime_spec),
                        Some(producer_task_command.as_str()),
                        producer_working_dir.as_path(),
                        remove_backend_on_interrupt,
                    );
                    state.activation_started_producers.remove(&(
                        service_member.clone(),
                        service_repo.clone(),
                        producer_task_name.to_string(),
                    ));
                    note
                }
            };
            return Err(RunError::TaskTargetResolutionFailed {
                task: task_name.to_string(),
                target: target_name.to_string(),
                details: format!(
                    "target activation `{}` for producer task `{producer_task_name}` was interrupted before becoming {}{}",
                    activation_mode.as_str(),
                    activation_expected_state(activation_mode),
                    cleanup_note
                        .as_deref()
                        .map(|note| format!("; {note}"))
                        .unwrap_or_default()
                ),
            });
        }
        let sleep_for = next_probe_at
            .checked_duration_since(Instant::now())
            .map(|remaining| remaining.min(Duration::from_millis(30)))
            .unwrap_or(Duration::from_millis(30));
        thread::sleep(sleep_for);
    }
}

fn cleanup_interrupted_activation_started_producers_and_note(
    _contract: &Contract,
    _contract_path: &Path,
    _working_dir: &Path,
    state: &mut TaskRunState,
) -> Option<String> {
    let producer_names = std::mem::take(&mut state.activation_started_producers);
    let mut notes = Vec::new();
    for ((member, repo, producer_task_name), cleanup) in producer_names {
        let producer_label =
            service_target_producer_label(member.as_deref(), repo.as_deref(), &producer_task_name);
        if let Some(note) = cleanup_activation_started_producer_and_note(
            cleanup.task_name.as_str(),
            &cleanup.backend,
            cleanup.runtime.as_ref(),
            cleanup.command.as_deref(),
            cleanup.working_dir.as_path(),
            cleanup.remove_backend_on_interrupt,
        ) {
            notes.push(note.replace(
                &format!("activation-started producer `{}`", cleanup.task_name),
                &format!("activation-started producer `{producer_label}`"),
            ));
        }
    }
    if notes.is_empty() {
        None
    } else {
        Some(notes.join("; "))
    }
}

fn cleanup_interrupted_requested_task_service_workload_and_note(
    state: &mut TaskRunState,
) -> Option<String> {
    let cleanup = state.requested_task_interrupt_cleanup.take()?;
    let note = match resolved_execution_backend_kind(&cleanup.backend) {
        Backend::Native => cleanup_interrupted_native_service_workload_and_note(
            cleanup.task_name.as_str(),
            cleanup.runtime.as_ref(),
        ),
        // Container service interrupt cleanup is already handled in container execution paths.
        Backend::Container => None,
        Backend::Remote => {
            if matches!(
                cleanup.backend,
                ResolvedExecutionBackend::BackendProvider { .. }
            ) {
                cleanup_interrupted_backend_provider_service_workload_and_note(
                    cleanup.task_name.as_str(),
                    &cleanup.backend,
                    cleanup.command.as_deref(),
                    cleanup.working_dir.as_path(),
                )
            } else {
                cleanup_interrupted_remote_service_workload_and_note(
                    cleanup.task_name.as_str(),
                    &cleanup.backend,
                    cleanup.runtime.as_ref(),
                )
            }
        }
    }
    .map(normalize_requested_service_cleanup_note)?;
    Some(format!(
        "requested service task `{}`: {note}",
        cleanup.task_name
    ))
}

pub(crate) fn cleanup_selected_workflow_native_service_workloads(
    contract: &Contract,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
) -> Result<(), String> {
    let mut failures = Vec::new();
    for task_name in contract.selected_workflow_task_closure_names(workflow_name) {
        let effective = effective_task_execution(contract, task_name.as_str(), overrides);
        if effective.backend != Backend::Native {
            continue;
        }
        let Some(task) = contract.tasks.get(task_name.as_str()) else {
            continue;
        };
        let Some(runtime) = task.service_runtime_for_backend(Backend::Native) else {
            continue;
        };
        if !task_owns_native_host_service_workload(task) {
            continue;
        }
        let Some(note) =
            cleanup_interrupted_native_service_workload_and_note(task_name.as_str(), Some(runtime))
        else {
            continue;
        };
        if !note.contains("cleaned up after interrupt") {
            failures.push(format!(
                "workflow task `{}`: {}",
                task_name,
                normalize_requested_service_cleanup_note(note)
            ));
        }
    }

    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

fn task_owns_native_host_service_workload(task: &TaskSpec) -> bool {
    let adapter_owned_compose = |exe: &str, args: &[String]| {
        matches!(exe, "docker" | "podman") && args.first().is_some_and(|arg| arg == "compose")
    };

    if let Some(command) = task.command.as_ref()
        && adapter_owned_compose(command.exe.as_str(), &command.args)
    {
        return false;
    }

    if let Some(crate::schema::TaskLaunchSpec::Command(command)) = task.launch.as_ref()
        && adapter_owned_compose(command.exe.as_str(), &command.args)
    {
        return false;
    }

    true
}

fn cleanup_interrupted_started_services_and_note(
    contract: &Contract,
    working_dir: &Path,
    state: &mut TaskRunState,
) -> Option<String> {
    let mut stopped = Vec::new();
    let mut failures = Vec::new();
    let mut started_services = service_start_order(contract)
        .into_iter()
        .filter(|name| state.started_services.contains(name))
        .collect::<Vec<_>>();
    started_services.reverse();

    for service_name in started_services {
        let Some(service) = contract.services.get(service_name.as_str()) else {
            continue;
        };
        if service.stop_command(service_name.as_str()).is_none() {
            continue;
        }

        match run_service_stop_command(
            service_name.as_str(),
            service,
            working_dir,
            TaskExecutionMode::CaptureActivation,
        ) {
            Ok(output) if output.exit_code == 0 => {
                state.host_service_cleanup.push(HostServiceCleanupEvidence {
                    service: service_name.clone(),
                    action: String::from("stop"),
                    status: String::from("succeeded"),
                    trigger: String::from("interrupt_cleanup"),
                    detail: cleanup_command_output_detail_text(&output),
                });
                stopped.push(service_name);
            }
            Ok(output) => {
                let detail = format!(
                    "stop command exited with code {}{}",
                    output.exit_code,
                    render_cleanup_command_output_detail(&output)
                );
                state.host_service_cleanup.push(HostServiceCleanupEvidence {
                    service: service_name.clone(),
                    action: String::from("stop"),
                    status: String::from("failed"),
                    trigger: String::from("interrupt_cleanup"),
                    detail: Some(detail.clone()),
                });
                failures.push(format!("required service `{service_name}` {detail}"));
            }
            Err(error) => {
                state.host_service_cleanup.push(HostServiceCleanupEvidence {
                    service: service_name.clone(),
                    action: String::from("stop"),
                    status: String::from("failed"),
                    trigger: String::from("interrupt_cleanup"),
                    detail: Some(error.clone()),
                });
                failures.push(format!(
                    "required service `{service_name}` stop command failed: {error}"
                ));
            }
        }
    }

    let success_note = (!stopped.is_empty()).then(|| {
        format!(
            "required services {} stopped after interrupt",
            join_quoted_names(&stopped)
        )
    });
    merge_execution_note(
        success_note,
        (!failures.is_empty()).then(|| failures.join("; ")),
    )
}

fn normalize_requested_service_cleanup_note(note: String) -> String {
    note.strip_prefix("activation-started ")
        .map(str::to_string)
        .unwrap_or(note)
}

fn join_quoted_names(names: &[String]) -> String {
    names
        .iter()
        .map(|name| format!("`{name}`"))
        .collect::<Vec<_>>()
        .join(", ")
}

fn render_cleanup_command_output_detail(output: &TaskCommandOutput) -> String {
    [output.stderr.trim(), output.stdout.trim()]
        .into_iter()
        .find(|value| !value.is_empty())
        .map(|value| format!(" ({})", value.lines().next().unwrap_or(value)))
        .unwrap_or_default()
}

fn cleanup_command_output_detail_text(output: &TaskCommandOutput) -> Option<String> {
    let detail = render_cleanup_command_output_detail(output);
    (!detail.is_empty()).then_some(detail)
}

fn wait_for_readiness_target_to_clear(target: &RuntimeReadinessTarget) -> bool {
    for _ in 0..30 {
        if !readiness_target_observed(target) {
            return true;
        }
        thread::sleep(Duration::from_millis(100));
    }
    !readiness_target_observed(target)
}

fn restart_target_producer(
    task_name: &str,
    target_name: &str,
    producer_task_name: &str,
    backend: &ResolvedExecutionBackend,
    runtime: &TaskRuntimeSpec,
    task_command: Option<&str>,
    working_dir: &Path,
    readiness_target: &RuntimeReadinessTarget,
) -> Result<(), RunError> {
    let cleanup_note = if resolved_execution_backend_kind(backend) == Backend::Native {
        cleanup_interrupted_native_service_workload_and_note(producer_task_name, Some(runtime))
    } else if resolved_execution_backend_kind(backend) == Backend::Remote {
        if matches!(backend, ResolvedExecutionBackend::BackendProvider { .. }) {
            cleanup_interrupted_backend_provider_service_workload_and_note(
                producer_task_name,
                backend,
                task_command,
                working_dir,
            )
        } else {
            cleanup_interrupted_remote_service_workload_and_note(
                producer_task_name,
                backend,
                Some(runtime),
            )
        }
    } else {
        let Some((engine, container_name)) =
            persistent_container_target_for_backend(backend, working_dir)
        else {
            return Err(RunError::TaskTargetResolutionFailed {
                task: task_name.to_string(),
                target: target_name.to_string(),
                details: format!(
                    "target activation `restart_ready` could not restart producer task `{producer_task_name}` because ota could not resolve its persistent backend target"
                ),
            });
        };
        cleanup_interrupted_persistent_service_workload_and_note(
            producer_task_name,
            engine.as_str(),
            &container_name,
            Some(runtime),
        )
    };

    if !wait_for_readiness_target_to_clear(readiness_target) {
        return Err(RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `restart_ready` could not stop producer task `{producer_task_name}` before restart{}",
                cleanup_note
                    .as_deref()
                    .map(|note| format!("; {note}"))
                    .unwrap_or_default()
            ),
        });
    }

    Ok(())
}

fn declared_target_probe_target(
    contract: &Contract,
    task_name: &str,
    target_name: &str,
    target_spec: &TaskTargetSpec,
    caller_backend: Backend,
    working_dir: &Path,
    producer_backend: &ResolvedExecutionBackend,
    caller_task: &TaskSpec,
    producer_task: &TaskSpec,
    producer_task_name: &str,
    producer_listener_name: &str,
    producer_runtime_spec: &TaskRuntimeSpec,
) -> Result<RuntimeReadinessTarget, RunError> {
    let service = target_spec.service.as_ref().ok_or_else(|| {
        RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` requires a `service` target; `url` targets only support `manual`",
                target_spec.activation.mode.as_str()
            ),
        }
    })?;
    let activation_mode = target_spec.activation.mode;
    let shared_container_binding =
        task_specs_share_container_local_backend(contract, caller_task, producer_task);
    let shared_native_binding =
        task_specs_share_backend_binding(contract, caller_task, producer_task, Backend::Native);
    let shared_remote_binding =
        task_specs_share_backend_binding(contract, caller_task, producer_task, Backend::Remote);
    let readiness = producer_runtime_spec.readiness.as_ref();
    let use_runtime_readiness = matches!(
        activation_mode,
        TaskTargetActivationMode::EnsureReady | TaskTargetActivationMode::RestartReady
    );
    let probe_listener_name = if use_runtime_readiness {
        readiness
            .and_then(|probe| probe.listener.as_deref())
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .unwrap_or(producer_listener_name)
    } else {
        producer_listener_name
    };
    let listener = match service.address_view {
        TaskTargetAddressView::Host => select_target_listener_for_host_view(
            producer_task,
            probe_listener_name,
        )
        .map_err(|details| RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details,
        })?,
        TaskTargetAddressView::Topology => {
            if (caller_backend == Backend::Container && shared_container_binding)
                || (caller_backend == Backend::Native && shared_native_binding)
                || (caller_backend == Backend::Remote && shared_remote_binding)
            {
                select_target_listener_for_backend(producer_task, probe_listener_name, caller_backend)
            } else {
                select_target_listener_for_host_view(producer_task, probe_listener_name)
                    .map_err(|details| RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details,
                    })?
            }
        }
        TaskTargetAddressView::Internal => {
            if caller_backend == Backend::Container && shared_container_binding
                || caller_backend == Backend::Native && shared_native_binding
                || caller_backend == Backend::Remote && shared_remote_binding
            {
                select_target_listener_for_backend(producer_task, probe_listener_name, caller_backend)
            } else {
                None
            }
        }
    }
    .ok_or_else(|| RunError::TaskTargetResolutionFailed {
        task: task_name.to_string(),
        target: target_name.to_string(),
        details: format!(
            "target activation `{}` references unknown listener `{probe_listener_name}` on service task `{producer_task_name}`",
            activation_mode.as_str()
        ),
    })?;
    let (address, port) = match service.address_view {
        TaskTargetAddressView::Host => {
            if resolved_execution_backend_kind(producer_backend) == Backend::Remote
                && !(caller_backend == Backend::Remote && shared_remote_binding)
            {
                return Err(RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` currently supports remote producer auto-start only when `{task_name}` and `{producer_task_name}` share one declared remote backend binding; `{producer_task_name}` target view is `host`",
                        activation_mode.as_str()
                    ),
                });
            }
            let host_projection = listener.project.host.as_ref().ok_or_else(|| {
                RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` requires producer listener `{producer_task_name}.{probe_listener_name}` to declare `project.host`",
                        activation_mode.as_str()
                    ),
                }
            })?;
            let host_port = host_projection.port.value.ok_or_else(|| {
                RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` requires producer listener `{producer_task_name}.{probe_listener_name}` to declare a fixed `project.host.port.value`",
                        activation_mode.as_str()
                    ),
                }
            })?;
            (host_projection.address.clone(), host_port)
        }
        TaskTargetAddressView::Topology => {
            if (caller_backend == Backend::Container && shared_container_binding)
                || (caller_backend == Backend::Native && shared_native_binding)
            {
                let bind_port = listener.bind.port.value.ok_or_else(|| {
                    RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details: format!(
                            "target activation `{}` requires producer listener `{producer_task_name}.{probe_listener_name}` to declare a fixed `bind.port.value` for shared-backend `address_view: topology`",
                            activation_mode.as_str()
                        ),
                    }
                })?;
                (
                    colocated_topology_listener_address(listener.bind.address.as_str()),
                    bind_port,
                )
            } else if caller_backend == Backend::Remote && shared_remote_binding {
                let bind_port = listener.bind.port.value.ok_or_else(|| {
                    RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details: format!(
                            "target activation `{}` requires producer listener `{producer_task_name}.{probe_listener_name}` to declare a fixed `bind.port.value` for shared-backend `address_view: topology`",
                            activation_mode.as_str()
                        ),
                    }
                })?;
                let Some(probe) = remote_readiness_probe_target(producer_backend, working_dir)
                else {
                    return Err(RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details: format!(
                            "target activation `{}` currently supports built-in remote providers only; `{producer_task_name}` does not resolve to one",
                            activation_mode.as_str()
                        ),
                    });
                };
                return Ok(
                    match readiness
                        .filter(|_| use_runtime_readiness)
                        .and_then(|probe| probe.kind)
                    {
                        Some(TaskRuntimeReadinessKind::Http) => {
                            RuntimeReadinessTarget::RemoteHttp {
                                probe,
                                address: colocated_topology_listener_address(
                                    listener.bind.address.as_str(),
                                ),
                                port: bind_port,
                                request: readiness_http_request(readiness),
                            }
                        }
                        Some(TaskRuntimeReadinessKind::Tcp) | None => {
                            RuntimeReadinessTarget::RemoteTcp {
                                probe,
                                port: bind_port,
                            }
                        }
                    },
                );
            } else {
                let host_projection = listener.project.host.as_ref().ok_or_else(|| {
                    RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details: format!(
                            "target activation `{}` requires producer listener `{producer_task_name}.{probe_listener_name}` to declare `project.host`",
                            activation_mode.as_str()
                        ),
                    }
                })?;
                let host_port = host_projection.port.value.ok_or_else(|| {
                    RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details: format!(
                            "target activation `{}` requires producer listener `{producer_task_name}.{probe_listener_name}` to declare a fixed `project.host.port.value`",
                            activation_mode.as_str()
                        ),
                    }
                })?;
                (host_projection.address.clone(), host_port)
            }
        }
        TaskTargetAddressView::Internal => {
            if !((caller_backend == Backend::Container && shared_container_binding)
                || (caller_backend == Backend::Native && shared_native_binding))
                && !(caller_backend == Backend::Remote && shared_remote_binding)
            {
                return Err(RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` cannot probe `address_view: internal` for `{task_name}` -> `{producer_task_name}` without a shared backend binding on the active execution plane",
                        activation_mode.as_str()
                    ),
                });
            }
            let bind_port = listener.bind.port.value.ok_or_else(|| {
                RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "target activation `{}` requires producer listener `{producer_task_name}.{probe_listener_name}` to declare a fixed `bind.port.value` for `address_view: internal`",
                        activation_mode.as_str()
                    ),
                }
            })?;
            if caller_backend == Backend::Remote {
                let Some(probe) = remote_readiness_probe_target(producer_backend, working_dir)
                else {
                    return Err(RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details: format!(
                            "target activation `{}` currently supports built-in remote providers only; `{producer_task_name}` does not resolve to one",
                            activation_mode.as_str()
                        ),
                    });
                };
                return Ok(
                    match readiness
                        .filter(|_| use_runtime_readiness)
                        .and_then(|probe| probe.kind)
                    {
                        Some(TaskRuntimeReadinessKind::Http) => {
                            RuntimeReadinessTarget::RemoteHttp {
                                probe,
                                address: colocated_topology_listener_address(
                                    listener.bind.address.as_str(),
                                ),
                                port: bind_port,
                                request: readiness_http_request(readiness),
                            }
                        }
                        Some(TaskRuntimeReadinessKind::Tcp) | None => {
                            RuntimeReadinessTarget::RemoteTcp {
                                probe,
                                port: bind_port,
                            }
                        }
                    },
                );
            }
            (
                colocated_topology_listener_address(listener.bind.address.as_str()),
                bind_port,
            )
        }
    };
    if use_runtime_readiness
        && let Some(probe_name) = readiness
            .and_then(|readiness| readiness.probe.as_deref())
            .map(str::trim)
            .filter(|name| !name.is_empty())
    {
        let resolved =
            resolve_named_readiness_probe_contract(contract, probe_name).map_err(|details| {
                RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details,
                }
            })?;
        return Ok(match resolved {
            ResolvedNamedReadinessProbeContract::Http { request, .. } => {
                if caller_backend == Backend::Remote && shared_remote_binding {
                    RuntimeReadinessTarget::RemoteHttp {
                        probe: remote_readiness_probe_target(producer_backend, working_dir)
                            .ok_or_else(|| RunError::TaskTargetResolutionFailed {
                                task: task_name.to_string(),
                                target: target_name.to_string(),
                                details: format!(
                                    "target activation `{}` currently supports built-in remote providers only; `{producer_task_name}` does not resolve to one",
                                    activation_mode.as_str()
                                ),
                            })?,
                        address,
                        port,
                        request,
                    }
                } else {
                    RuntimeReadinessTarget::Http {
                        address,
                        port,
                        request,
                    }
                }
            }
            ResolvedNamedReadinessProbeContract::Tcp { .. } => {
                if caller_backend == Backend::Remote && shared_remote_binding {
                    RuntimeReadinessTarget::RemoteTcp {
                        probe: remote_readiness_probe_target(producer_backend, working_dir)
                            .ok_or_else(|| RunError::TaskTargetResolutionFailed {
                                task: task_name.to_string(),
                                target: target_name.to_string(),
                                details: format!(
                                    "target activation `{}` currently supports built-in remote providers only; `{producer_task_name}` does not resolve to one",
                                    activation_mode.as_str()
                                ),
                            })?,
                        port,
                    }
                } else {
                    RuntimeReadinessTarget::Tcp { address, port }
                }
            }
        });
    }
    match readiness
        .filter(|_| use_runtime_readiness)
        .and_then(|probe| probe.kind)
    {
        Some(TaskRuntimeReadinessKind::Http) => Ok(RuntimeReadinessTarget::Http {
            address,
            port,
            request: readiness_http_request(readiness),
        }),
        Some(TaskRuntimeReadinessKind::Tcp) | None => {
            Ok(RuntimeReadinessTarget::Tcp { address, port })
        }
    }
}

