#[cfg(test)]
fn target_probe_endpoint_reachable(address: &str, port: u16) -> bool {
    target_probe_endpoint_reachable_with_timeout(address, port, None)
}

pub(crate) fn target_probe_endpoint_reachable_with_timeout(
    address: &str,
    port: u16,
    timeout: Option<Duration>,
) -> bool {
    target_probe_endpoint_result_with_timeout(address, port, timeout).is_ok()
}

fn target_probe_endpoint_result_with_timeout(
    address: &str,
    port: u16,
    timeout: Option<Duration>,
) -> Result<(), String> {
    let connect_timeout = timeout.unwrap_or(Duration::from_millis(200));
    let mut saw_non_timeout_error = false;
    let mut last_non_timeout_error = None;
    let mut last_error = None;
    for (index, socket) in probe_socket_candidates(address, port)
        .into_iter()
        .enumerate()
    {
        let effective_timeout = probe_connect_timeout_for_candidate(connect_timeout, index);
        match TcpStream::connect_timeout(&socket, effective_timeout) {
            Ok(_) => return Ok(()),
            Err(error) => {
                let detail = normalize_probe_io_error(&error);
                if !detail.contains("timed out") {
                    saw_non_timeout_error = true;
                    last_non_timeout_error = Some(format!("{detail} ({socket})"));
                }
                last_error = Some(format!("{detail} ({socket})"));
            }
        }
    }
    if saw_non_timeout_error {
        return Err(last_non_timeout_error
            .or_else(|| last_error)
            .unwrap_or_else(|| String::from("connection failed")));
    }
    Err(last_error.unwrap_or_else(|| String::from("timed out")))
}

pub(crate) fn probe_socket_candidates(address: &str, port: u16) -> Vec<std::net::SocketAddr> {
    let normalized = address.trim();
    let mut candidates = Vec::new();
    candidates.push(normalized.to_string());
    if is_loopback_only_host_address(normalized) {
        candidates.push(String::from("127.0.0.1"));
        candidates.push(String::from("::1"));
        candidates.push(String::from("localhost"));
    }
    let mut seen = BTreeSet::new();
    let mut sockets = Vec::new();
    for candidate in candidates {
        if let Ok(resolved) = (candidate.as_str(), port).to_socket_addrs() {
            for socket in resolved {
                if seen.insert(socket) {
                    sockets.push(socket);
                }
            }
        }
    }
    sockets
}

fn target_activation_producer_failure(
    task_name: &str,
    target_name: &str,
    activation_mode: TaskTargetActivationMode,
    producer_task_name: &str,
    result: Result<i32, RunError>,
    producer_state: TaskRunState,
) -> RunError {
    let stdout_hint = producer_state
        .stdout
        .lines()
        .rev()
        .find(|line| !line.trim().is_empty())
        .map(str::trim)
        .map(str::to_string);
    let stderr_hint = producer_state
        .stderr
        .lines()
        .rev()
        .find(|line| !line.trim().is_empty())
        .map(str::trim)
        .map(str::to_string);
    let output_hint = stderr_hint
        .or(stdout_hint)
        .map(|line| format!(" Last output: {line}"))
        .unwrap_or_default();

    match result {
        Ok(exit_code) => RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` started producer task `{producer_task_name}`, but it exited with code {exit_code} before becoming {}.{output_hint}",
                activation_mode.as_str(),
                activation_expected_state(activation_mode)
            ),
        },
        Err(error) => RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target activation `{}` failed to start producer task `{producer_task_name}`: {error}.{output_hint}",
                activation_mode.as_str()
            ),
        },
    }
}

fn activation_expected_state(mode: TaskTargetActivationMode) -> &'static str {
    match mode {
        TaskTargetActivationMode::Manual => "available",
        TaskTargetActivationMode::EnsureStarted => "started",
        TaskTargetActivationMode::RestartReady => "ready after restart",
        TaskTargetActivationMode::EnsureReady => "ready",
        TaskTargetActivationMode::EnsureRunning => "running",
    }
}

fn single_task_input_name(task: &TaskSpec) -> Option<&str> {
    (task.inputs.len() == 1)
        .then(|| task.inputs.keys().next().map(String::as_str))
        .flatten()
}

fn single_task_input_shorthand_value(input_args: &[String]) -> Option<String> {
    let bare_values = input_args
        .iter()
        .filter(|token| token.as_str() != "--")
        .collect::<Vec<_>>();
    match bare_values.as_slice() {
        [value] if !value.starts_with("--") && !value.is_empty() => Some((**value).clone()),
        _ => None,
    }
}

fn insert_task_input_value(
    task_name: &str,
    task: &TaskSpec,
    provided: &mut BTreeMap<String, String>,
    input_name: String,
    value: String,
) -> Result<(), RunError> {
    let spec = task
        .inputs
        .get(&input_name)
        .expect("validated input insertion should only reference declared task inputs");

    if !spec.allowed.is_empty() && !spec.allowed.iter().any(|allowed| allowed == &value) {
        return Err(RunError::InvalidTaskInputValue {
            task: task_name.to_string(),
            input: input_name,
            value,
            allowed: spec.allowed.join(", "),
        });
    }

    if provided.insert(input_name.clone(), value).is_some() {
        return Err(RunError::DuplicateTaskInput {
            task: task_name.to_string(),
            input: input_name,
        });
    }

    Ok(())
}

fn resolve_task_target_bindings(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    task: &TaskSpec,
    explicit_inputs: &BTreeSet<String>,
    provided_inputs: &mut BTreeMap<String, String>,
    caller_backend: Backend,
    execution_overrides: ExecutionOverrides,
) -> Result<Vec<TaskTargetResolutionEvidence>, RunError> {
    let mut resolutions = Vec::new();

    for (target_name, target_spec) in &task.targets {
        let override_input = target_spec
            .override_input
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string);
        let service_ref = if let Some(service) = target_spec.service.as_ref() {
            let service_member = service
                .member
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty());
            let service_repo = service
                .repo
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty());
            let (service_contract, _) = load_target_service_contract_with_path(
                contract,
                contract_path,
                task_name,
                target_name,
                service_member,
                service_repo,
            )?;
            let listener = resolve_service_target_listener_name(
                &service_contract,
                task_name,
                target_name,
                service_member,
                service_repo,
                service.task.as_str(),
                service.listener.as_deref(),
            )?;
            Some(TaskTargetResolutionServiceRef {
                member: service.member.clone(),
                repo: service.repo.clone(),
                task: service.task.clone(),
                listener,
                address_view: service.address_view,
            })
        } else {
            None
        };
        let url_ref = target_spec
            .url
            .as_ref()
            .map(|url| TaskTargetResolutionUrlRef { url: url.clone() });

        if let Some(override_input_name) = override_input.as_deref()
            && explicit_inputs.contains(override_input_name)
            && let Some(explicit_value) = provided_inputs.get(override_input_name).cloned()
        {
            resolutions.push(TaskTargetResolutionEvidence {
                target: target_name.clone(),
                override_input: override_input.clone(),
                source: TaskTargetResolutionSource::ExplicitOverride,
                activation: None,
                service_ref,
                url_ref,
                effective_url: explicit_value,
            });
            continue;
        }

        match resolve_task_target_binding_url_with_contract_path(
            contract,
            contract_path,
            task_name,
            target_name,
            target_spec,
            caller_backend,
            execution_overrides,
        ) {
            Ok(effective_url) => {
                if let Some(override_input_name) = override_input.as_deref()
                    && !provided_inputs.contains_key(override_input_name)
                {
                    insert_task_input_value(
                        task_name,
                        task,
                        provided_inputs,
                        override_input_name.to_string(),
                        effective_url.clone(),
                    )?;
                }
                resolutions.push(TaskTargetResolutionEvidence {
                    target: target_name.clone(),
                    override_input: override_input.clone(),
                    source: TaskTargetResolutionSource::TargetBinding,
                    activation: None,
                    service_ref,
                    url_ref,
                    effective_url,
                });
            }
            Err(error) => {
                if let Some(override_input_name) = override_input.as_deref()
                    && let Some(default) = task
                        .inputs
                        .get(override_input_name)
                        .and_then(|input| input.default.clone())
                {
                    resolutions.push(TaskTargetResolutionEvidence {
                        target: target_name.clone(),
                        override_input: override_input.clone(),
                        source: TaskTargetResolutionSource::CompatibilityLiteralDefault,
                        activation: None,
                        service_ref,
                        url_ref,
                        effective_url: default,
                    });
                    continue;
                }

                return Err(error);
            }
        }
    }

    Ok(resolutions)
}

fn load_target_service_contract_with_path(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    target_name: &str,
    service_member: Option<&str>,
    service_repo: Option<&str>,
) -> Result<(Contract, PathBuf), RunError> {
    match (service_member, service_repo) {
        (Some(member), None) => load_contract_for_member(
            monorepo_contract_origin_for_path(contract_path)
                .map_err(|error| RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "could not resolve monorepo origin for `service.member: {member}`: {error}"
                    ),
                })?
                .ok_or_else(|| RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "`service.member: {member}` requires running from a monorepo root or member contract"
                    ),
                })?
                .root_path
                .as_path(),
            member,
        )
        .map_err(|error| RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!("could not load `service.member: {member}`: {error}"),
        }),
        (None, Some(repo)) => load_contract_for_workspace_repo(contract_path, repo).map_err(
            |details| RunError::TaskTargetResolutionFailed {
                task: task_name.to_string(),
                target: target_name.to_string(),
                details: format!("could not load `service.repo: {repo}`: {details}"),
            },
        ),
        _ => Ok((contract.clone(), contract_path.to_path_buf())),
    }
}

fn service_target_reference_label(
    service_member: Option<&str>,
    service_repo: Option<&str>,
    service_task_name: &str,
) -> String {
    match (service_member, service_repo) {
        (Some(member), None) => format!("member `{member}` task `{service_task_name}`"),
        (None, Some(repo)) => format!("workspace repo `{repo}` task `{service_task_name}`"),
        _ => format!("service task `{service_task_name}`"),
    }
}

fn service_target_producer_label(
    service_member: Option<&str>,
    service_repo: Option<&str>,
    producer_task_name: &str,
) -> String {
    match (service_member, service_repo) {
        (Some(member), None) => format!("{member}:{producer_task_name}"),
        (None, Some(repo)) => format!("{repo}:{producer_task_name}"),
        _ => producer_task_name.to_string(),
    }
}

#[cfg(test)]
fn resolve_task_target_binding_url(
    contract: &Contract,
    task_name: &str,
    target_name: &str,
    target_spec: &TaskTargetSpec,
    caller_backend: Backend,
    execution_overrides: ExecutionOverrides,
) -> Result<String, RunError> {
    resolve_task_target_binding_url_with_contract_path(
        contract,
        Path::new("ota.yaml"),
        task_name,
        target_name,
        target_spec,
        caller_backend,
        execution_overrides,
    )
}

pub(crate) fn resolve_task_target_binding_url_with_contract_path(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    target_name: &str,
    target_spec: &TaskTargetSpec,
    caller_backend: Backend,
    execution_overrides: ExecutionOverrides,
) -> Result<String, RunError> {
    if let Some(url) = target_spec.url.as_deref() {
        return Ok(url.trim().to_string());
    }

    let service =
        target_spec
            .service
            .as_ref()
            .ok_or_else(|| RunError::TaskTargetResolutionFailed {
                task: task_name.to_string(),
                target: target_name.to_string(),
                details: String::from("target must declare one of `service` or `url`"),
            })?;
    let service_task_name = service.task.trim();
    let caller_task =
        contract
            .tasks
            .get(task_name)
            .ok_or_else(|| RunError::TaskTargetResolutionFailed {
                task: task_name.to_string(),
                target: target_name.to_string(),
                details: format!("consumer task `{task_name}` is not defined in ota.yaml"),
            })?;
    let service_member = service
        .member
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let service_repo = service
        .repo
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if service_repo.is_some() && service.address_view != TaskTargetAddressView::Host {
        return Err(RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: String::from("`service.repo` currently supports only `address_view: host`"),
        });
    }
    let (service_contract, _) = load_target_service_contract_with_path(
        contract,
        contract_path,
        task_name,
        target_name,
        service_member,
        service_repo,
    )?;
    let service_task = service_contract.tasks.get(service_task_name).ok_or_else(|| {
        RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: match (service_member, service_repo) {
                (Some(member), None) => format!(
                    "target references unknown `service.task: {service_task_name}` in member `{member}`"
                ),
                (None, Some(repo)) => format!(
                    "target references unknown `service.task: {service_task_name}` in workspace repo `{repo}`"
                ),
                _ => format!("target references unknown `service.task: {service_task_name}`"),
            },
        }
    })?;
    let shared_container_binding =
        task_specs_share_container_local_backend(contract, caller_task, service_task);
    let shared_native_binding =
        task_specs_share_backend_binding(contract, caller_task, service_task, Backend::Native);
    let shared_remote_binding =
        task_specs_share_backend_binding(contract, caller_task, service_task, Backend::Remote);

    let listener_name = resolve_service_target_listener_name(
        &service_contract,
        task_name,
        target_name,
        service_member,
        service_repo,
        service_task_name,
        service.listener.as_deref(),
    )?;
    let listener = match service.address_view {
        TaskTargetAddressView::Host => {
            select_target_listener_for_host_view(service_task, listener_name.as_str()).map_err(
                |details| RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details,
                },
            )?
        }
        TaskTargetAddressView::Topology | TaskTargetAddressView::Internal => {
            select_target_listener_for_backend(service_task, listener_name.as_str(), caller_backend)
        }
    }
    .ok_or_else(|| RunError::TaskTargetResolutionFailed {
        task: task_name.to_string(),
        target: target_name.to_string(),
        details: format!(
            "target references unknown listener `{listener_name}` on {}",
            service_target_reference_label(service_member, service_repo, service_task_name)
        ),
    })?;

    match service.address_view {
        TaskTargetAddressView::Host => {
            let host_projection = listener.project.host.as_ref().ok_or_else(|| {
                RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "listener `{service_task_name}.{listener_name}` on {} has no `project.host` endpoint to resolve",
                        service_target_reference_label(
                            service_member,
                            service_repo,
                            service_task_name,
                        )
                    ),
                }
            })?;
            let host_port = host_projection.port.value.ok_or_else(|| {
                RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "listener `{service_task_name}.{listener_name}` on {} does not declare a fixed `project.host.port.value`",
                        service_target_reference_label(
                            service_member,
                            service_repo,
                            service_task_name,
                        )
                    ),
                }
            })?;
            let host_address = resolve_host_view_address_for_caller(
                contract,
                task_name,
                target_name,
                caller_backend,
                host_projection.address.as_str(),
                execution_overrides,
            )?;
            Ok(format_task_target_host_endpoint(
                listener.protocol,
                host_address.as_str(),
                host_port,
                host_projection.path.as_deref(),
            ))
        }
        TaskTargetAddressView::Topology => {
            if caller_backend == Backend::Native {
                if shared_native_binding
                    || (service_member.is_none()
                        && service_repo.is_none()
                        && tasks_share_backend_binding(
                            contract,
                            task_name,
                            service_task_name,
                            Backend::Native,
                        ))
                {
                    return resolve_colocated_shared_backend_listener_endpoint(
                        task_name,
                        target_name,
                        service_task_name,
                        listener_name.as_str(),
                        listener,
                        TaskTargetAddressView::Topology,
                    );
                }
                let host_projection = listener.project.host.as_ref().ok_or_else(|| {
                    RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details: format!(
                            "listener `{service_task_name}.{listener_name}` has no `project.host` endpoint to resolve"
                        ),
                    }
                })?;
                let host_port = host_projection.port.value.ok_or_else(|| {
                    RunError::TaskTargetResolutionFailed {
                        task: task_name.to_string(),
                        target: target_name.to_string(),
                        details: format!(
                            "listener `{service_task_name}.{listener_name}` does not declare a fixed `project.host.port.value`"
                        ),
                    }
                })?;
                return Ok(format_task_target_host_endpoint(
                    listener.protocol,
                    host_projection.address.as_str(),
                    host_port,
                    host_projection.path.as_deref(),
                ));
            }

            if caller_backend == Backend::Container
                && (shared_container_binding
                    || (service_member.is_none()
                        && service_repo.is_none()
                        && tasks_share_container_local_backend(
                            contract,
                            task_name,
                            service_task_name,
                        )))
            {
                return resolve_colocated_shared_backend_listener_endpoint(
                    task_name,
                    target_name,
                    service_task_name,
                    listener_name.as_str(),
                    listener,
                    TaskTargetAddressView::Topology,
                );
            }

            if caller_backend == Backend::Remote
                && (shared_remote_binding
                    || (service_member.is_none()
                        && service_repo.is_none()
                        && tasks_share_backend_binding(
                            contract,
                            task_name,
                            service_task_name,
                            Backend::Remote,
                        )))
            {
                return resolve_colocated_shared_backend_listener_endpoint(
                    task_name,
                    target_name,
                    service_task_name,
                    listener_name.as_str(),
                    listener,
                    TaskTargetAddressView::Topology,
                );
            }

            if caller_backend != Backend::Native {
                return Err(RunError::TaskTargetResolutionFailed {
                    task: task_name.to_string(),
                    target: target_name.to_string(),
                    details: format!(
                        "`address_view: topology` requires either native caller execution or a shared backend binding between `{task_name}` and `{service_task_name}`; current caller backend is `{}`",
                        match caller_backend {
                            Backend::Native => "native",
                            Backend::Container => "container",
                            Backend::Remote => "remote",
                        }
                    ),
                });
            }
            unreachable!()
        }
        TaskTargetAddressView::Internal => {
            if (caller_backend == Backend::Container
                && (shared_container_binding
                    || (service_member.is_none()
                        && service_repo.is_none()
                        && tasks_share_container_local_backend(
                            contract,
                            task_name,
                            service_task_name,
                        ))))
                || (caller_backend == Backend::Native
                    && (shared_native_binding
                        || (service_member.is_none()
                            && service_repo.is_none()
                            && tasks_share_backend_binding(
                                contract,
                                task_name,
                                service_task_name,
                                Backend::Native,
                            ))))
                || (caller_backend == Backend::Remote
                    && (shared_remote_binding
                        || (service_member.is_none()
                            && service_repo.is_none()
                            && tasks_share_backend_binding(
                                contract,
                                task_name,
                                service_task_name,
                                Backend::Remote,
                            ))))
            {
                return resolve_colocated_shared_backend_listener_endpoint(
                    task_name,
                    target_name,
                    service_task_name,
                    listener_name.as_str(),
                    listener,
                    TaskTargetAddressView::Internal,
                );
            }

            Err(RunError::TaskTargetResolutionFailed {
                task: task_name.to_string(),
                target: target_name.to_string(),
                details: format!(
                    "`address_view: internal` requires a shared backend binding between `{task_name}` and `{service_task_name}`; current caller backend is `{}`",
                    match caller_backend {
                        Backend::Native => "native",
                        Backend::Container => "container",
                        Backend::Remote => "remote",
                    }
                ),
            })
        }
    }
}

fn resolve_colocated_shared_backend_listener_endpoint(
    task_name: &str,
    target_name: &str,
    service_task_name: &str,
    listener_name: &str,
    listener: &crate::schema::TaskRuntimeListenerSpec,
    address_view: TaskTargetAddressView,
) -> Result<String, RunError> {
    let bind_port = listener.bind.port.value.ok_or_else(|| {
        RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "listener `{service_task_name}.{listener_name}` requires `bind.port.mode: fixed` to resolve `address_view: {}` for shared backends",
                match address_view {
                    TaskTargetAddressView::Topology => "topology",
                    TaskTargetAddressView::Host => "host",
                    TaskTargetAddressView::Internal => "internal",
                }
            ),
        }
    })?;
    Ok(format_task_target_host_endpoint(
        listener.protocol,
        colocated_topology_listener_address(listener.bind.address.as_str()).as_str(),
        bind_port,
        None,
    ))
}

fn resolve_host_view_address_for_caller(
    contract: &Contract,
    task_name: &str,
    target_name: &str,
    caller_backend: Backend,
    declared_address: &str,
    execution_overrides: ExecutionOverrides,
) -> Result<String, RunError> {
    let normalized = declared_address.trim();
    if caller_backend != Backend::Container || !is_loopback_only_host_address(normalized) {
        return Ok(normalized.to_string());
    }

    let engine = effective_task_container_backend_for_target_resolution(
        contract,
        task_name,
        execution_overrides,
    )
    .and_then(|container| {
        container_engine_candidates_from_backend(Some(container))
            .into_iter()
            .next()
    })
    .ok_or_else(|| RunError::TaskTargetResolutionFailed {
        task: task_name.to_string(),
        target: target_name.to_string(),
        details: String::from(
            "container caller host-view resolution requires a declared container backend so ota can choose a caller-reachable host projection",
        ),
    })?;

    match engine.as_str() {
        "docker" => Ok(String::from("host.docker.internal")),
        "podman" => Ok(String::from("host.containers.internal")),
        _ => Err(RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "container caller host-view resolution does not yet support container engine `{engine}`"
            ),
        }),
    }
}

fn effective_task_container_backend_for_target_resolution<'a>(
    contract: &'a Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> Option<&'a ContainerBackend> {
    let effective = effective_task_execution(contract, task_name, overrides);
    let local_backend_context_name =
        resolve_task_shared_local_backend(contract, task_name, Backend::Container)
            .ok()
            .flatten()
            .and_then(|shared| shared.context_name);
    local_backend_context_name
        .as_deref()
        .and_then(|name| {
            contract
                .execution
                .as_ref()
                .and_then(|execution| execution.contexts.get(name))
        })
        .filter(|context| context.backend == Backend::Container)
        .and_then(|context| context.container.as_ref())
        .or(effective.container)
}

fn select_target_listener_for_backend<'a>(
    service_task: &'a TaskSpec,
    listener_name: &str,
    caller_backend: Backend,
) -> Option<&'a crate::schema::TaskRuntimeListenerSpec> {
    service_task
        .service_runtime_for_backend(caller_backend)
        .and_then(|runtime| runtime.listeners.get(listener_name))
}

fn declared_service_listener_names(task: &TaskSpec) -> BTreeSet<String> {
    let mut listeners = BTreeSet::new();
    if let Some(runtime) = task
        .runtime
        .as_ref()
        .filter(|runtime| runtime.kind == TaskRuntimeKind::Service)
    {
        listeners.extend(runtime.listeners.keys().cloned());
    }
    if let Some(execution) = task.execution.as_ref() {
        for (_, branch) in execution.modes.iter() {
            if let Some(runtime) = branch
                .runtime
                .as_ref()
                .filter(|runtime| runtime.kind == TaskRuntimeKind::Service)
            {
                listeners.extend(runtime.listeners.keys().cloned());
            }
        }
    }
    listeners
}

fn resolve_service_target_listener_name(
    contract: &Contract,
    task_name: &str,
    target_name: &str,
    service_member: Option<&str>,
    service_repo: Option<&str>,
    service_task_name: &str,
    listener: Option<&str>,
) -> Result<String, RunError> {
    if let Some(listener_name) = listener.map(str::trim) {
        if !listener_name.is_empty() {
            return Ok(listener_name.to_string());
        }
    }

    let service_task = contract.tasks.get(service_task_name).ok_or_else(|| {
        RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: match service_member {
                Some(member) => format!(
                    "target references unknown `service.task: {service_task_name}` in member `{member}`"
                ),
                None => format!("target references unknown `service.task: {service_task_name}`"),
            },
        }
    })?;
    let listeners = declared_service_listener_names(service_task);
    match listeners.len() {
        1 => listeners
            .iter()
            .next()
            .cloned()
            .ok_or_else(|| RunError::TaskTargetResolutionFailed {
                task: task_name.to_string(),
                target: target_name.to_string(),
                details: format!(
                    "target `{target_name}` could not resolve the sole listener for {}",
                    service_target_reference_label(service_member, service_repo, service_task_name,)
                ),
            }),
        0 => Err(RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target `{target_name}` references {}, but task `{service_task_name}` does not declare any service listeners",
                service_target_reference_label(service_member, service_repo, service_task_name)
            ),
        }),
        _ => Err(RunError::TaskTargetResolutionFailed {
            task: task_name.to_string(),
            target: target_name.to_string(),
            details: format!(
                "target `{target_name}` references {}, which exposes multiple listeners; declare `service.listener` explicitly",
                service_target_reference_label(service_member, service_repo, service_task_name)
            ),
        }),
    }
}

fn select_target_listener_for_host_view<'a>(
    service_task: &'a TaskSpec,
    listener_name: &str,
) -> Result<Option<&'a crate::schema::TaskRuntimeListenerSpec>, String> {
    let mut matches = Vec::<(&'static str, &'a crate::schema::TaskRuntimeListenerSpec)>::new();
    if let Some(listener) = service_task
        .service_runtime()
        .and_then(|runtime| runtime.listeners.get(listener_name))
    {
        matches.push(("runtime.listeners", listener));
    }
    if let Some(execution) = service_task.execution.as_ref() {
        for (backend, branch) in execution.modes.iter() {
            let Some(listener) = branch
                .runtime
                .as_ref()
                .filter(|runtime| runtime.kind == TaskRuntimeKind::Service)
                .and_then(|runtime| runtime.listeners.get(listener_name))
            else {
                continue;
            };
            let origin = match backend {
                Backend::Native => "execution.modes.native.runtime.listeners",
                Backend::Container => "execution.modes.container.runtime.listeners",
                Backend::Remote => "execution.modes.remote.runtime.listeners",
            };
            matches.push((origin, listener));
        }
    }

    let Some((_, selected)) = matches.first().copied() else {
        return Ok(None);
    };
    let selected_signature = host_view_listener_signature(selected);
    if matches
        .iter()
        .all(|(_, listener)| host_view_listener_signature(listener) == selected_signature)
    {
        return Ok(Some(selected));
    }

    let origins = matches
        .iter()
        .map(|(origin, _)| format!("`{origin}.{listener_name}`"))
        .collect::<Vec<_>>()
        .join(", ");
    Err(format!(
        "listener `{listener_name}` has conflicting host-view declarations across {origins}; declare one canonical host projection for this listener"
    ))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct HostViewListenerSignature {
    protocol: TaskRuntimeProtocol,
    host: Option<crate::schema::TaskRuntimeHostProjectionSpec>,
}

fn host_view_listener_signature(
    listener: &crate::schema::TaskRuntimeListenerSpec,
) -> HostViewListenerSignature {
    HostViewListenerSignature {
        protocol: listener.protocol,
        host: listener.project.host.clone(),
    }
}

fn is_loopback_only_host_address(value: &str) -> bool {
    let normalized = value.trim().to_ascii_lowercase();
    normalized == "localhost"
        || normalized == "::1"
        || normalized == "127.0.0.1"
        || normalized.starts_with("127.")
}

fn tasks_share_container_local_backend(
    contract: &Contract,
    caller_task_name: &str,
    service_task_name: &str,
) -> bool {
    tasks_share_backend_binding(
        contract,
        caller_task_name,
        service_task_name,
        Backend::Container,
    )
}

fn task_specs_share_container_local_backend(
    contract: &Contract,
    caller_task: &TaskSpec,
    service_task: &TaskSpec,
) -> bool {
    let Some(execution) = contract.execution.as_ref() else {
        return false;
    };
    let Some(binding) = caller_task.backend_binding_for_backend(Backend::Container) else {
        return false;
    };
    if Some(binding) != service_task.backend_binding_for_backend(Backend::Container) {
        return false;
    }
    execution
        .shared_backends
        .get(binding)
        .is_some_and(|shared| {
            shared.backend == Backend::Container
                && shared.scope == crate::schema::ExecutionSharedBackendScope::Local
        })
}

fn tasks_share_backend_binding(
    contract: &Contract,
    caller_task_name: &str,
    service_task_name: &str,
    backend: Backend,
) -> bool {
    let Some(caller_task) = contract.tasks.get(caller_task_name) else {
        return false;
    };
    let Some(service_task) = contract.tasks.get(service_task_name) else {
        return false;
    };
    task_specs_share_backend_binding(contract, caller_task, service_task, backend)
}

fn task_specs_share_backend_binding(
    contract: &Contract,
    caller_task: &TaskSpec,
    service_task: &TaskSpec,
    backend: Backend,
) -> bool {
    let Some(execution) = contract.execution.as_ref() else {
        return false;
    };
    let Some(binding) = caller_task.backend_binding_for_backend(backend) else {
        return false;
    };
    if Some(binding) != service_task.backend_binding_for_backend(backend) {
        return false;
    }
    execution
        .shared_backends
        .get(binding)
        .is_some_and(|shared| shared.backend == backend)
}

fn colocated_topology_listener_address(bind_address: &str) -> String {
    match bind_address.trim() {
        "0.0.0.0" | "::" | "[::]" => String::from("127.0.0.1"),
        other => other.to_string(),
    }
}

fn format_task_target_host_endpoint(
    protocol: TaskRuntimeProtocol,
    address: &str,
    port: u16,
    path: Option<&str>,
) -> String {
    if let Some(scheme) = protocol.url_scheme() {
        let normalized_path = normalized_runtime_path(path);
        let path_suffix = if normalized_path == "/" {
            ""
        } else {
            normalized_path.as_str()
        };
        format!("{}://{}:{}{}", scheme, address.trim(), port, path_suffix)
    } else {
        format!("{}:{}", address.trim(), port)
    }
}

fn render_target_resolution_note(resolution: &TaskTargetResolutionEvidence) -> String {
    let declared = if let Some(service_ref) = resolution.service_ref.as_ref() {
        match (service_ref.member.as_deref(), service_ref.repo.as_deref()) {
            (Some(member), None) => {
                format!(
                    "service({member}:{}.{})",
                    service_ref.task, service_ref.listener
                )
            }
            (None, Some(repo)) => {
                format!(
                    "service({repo}:{}.{})",
                    service_ref.task, service_ref.listener
                )
            }
            _ => format!("service({}.{})", service_ref.task, service_ref.listener),
        }
    } else if let Some(url_ref) = resolution.url_ref.as_ref() {
        format!("url({})", url_ref.url)
    } else {
        String::from("target")
    };
    match resolution.override_input.as_deref() {
        Some(input) => format!(
            "target `{}` declared `{declared}` via `{input}` -> `{}` ({})",
            resolution.target,
            resolution.effective_url,
            render_target_resolution_source_and_activation_label(resolution)
        ),
        None => format!(
            "target `{}` declared `{declared}` -> `{}` ({})",
            resolution.target,
            resolution.effective_url,
            render_target_resolution_source_and_activation_label(resolution)
        ),
    }
}

pub(crate) fn render_target_resolution_source_and_activation_label(
    resolution: &TaskTargetResolutionEvidence,
) -> String {
    let source = match resolution.source {
        TaskTargetResolutionSource::ExplicitOverride => "user override",
        TaskTargetResolutionSource::TargetBinding => "target binding",
        TaskTargetResolutionSource::CompatibilityLiteralDefault => "compatibility literal default",
    };
    let Some(activation) = resolution.activation.as_ref() else {
        return source.to_string();
    };
    let activation_label = match (activation.mode, activation.status) {
        (TaskTargetActivationMode::Manual, TaskTargetActivationStatus::Manual) => {
            "activation manual"
        }
        (
            TaskTargetActivationMode::EnsureStarted,
            TaskTargetActivationStatus::SkippedExplicitOverride,
        ) => "activation ensure_started skipped_override",
        (
            TaskTargetActivationMode::RestartReady,
            TaskTargetActivationStatus::SkippedExplicitOverride,
        ) => "activation restart_ready skipped_override",
        (TaskTargetActivationMode::EnsureStarted, TaskTargetActivationStatus::Manual) => {
            "activation ensure_started manual"
        }
        (TaskTargetActivationMode::RestartReady, TaskTargetActivationStatus::Manual) => {
            "activation restart_ready manual"
        }
        (TaskTargetActivationMode::EnsureStarted, TaskTargetActivationStatus::ReusedStarted) => {
            "activation ensure_started reused_started"
        }
        (TaskTargetActivationMode::EnsureStarted, TaskTargetActivationStatus::StartedStarted) => {
            "activation ensure_started started_started"
        }
        (TaskTargetActivationMode::RestartReady, TaskTargetActivationStatus::RestartedReady) => {
            "activation restart_ready restarted_ready"
        }
        (
            TaskTargetActivationMode::EnsureReady,
            TaskTargetActivationStatus::SkippedExplicitOverride,
        ) => "activation ensure_ready skipped_override",
        (TaskTargetActivationMode::EnsureReady, TaskTargetActivationStatus::Manual) => {
            "activation ensure_ready manual"
        }
        (TaskTargetActivationMode::EnsureReady, TaskTargetActivationStatus::ReusedReady) => {
            "activation ensure_ready reused_ready"
        }
        (TaskTargetActivationMode::EnsureReady, TaskTargetActivationStatus::StartedReady) => {
            "activation ensure_ready started_ready"
        }
        (
            TaskTargetActivationMode::EnsureRunning,
            TaskTargetActivationStatus::SkippedExplicitOverride,
        ) => "activation ensure_running skipped_override",
        (TaskTargetActivationMode::EnsureRunning, TaskTargetActivationStatus::Manual) => {
            "activation ensure_running manual"
        }
        (TaskTargetActivationMode::EnsureRunning, TaskTargetActivationStatus::ReusedRunning) => {
            "activation ensure_running reused_running"
        }
        (TaskTargetActivationMode::EnsureRunning, TaskTargetActivationStatus::StartedRunning) => {
            "activation ensure_running started_running"
        }
        (TaskTargetActivationMode::Manual, other) => match other {
            TaskTargetActivationStatus::SkippedExplicitOverride => {
                "activation manual skipped_override"
            }
            TaskTargetActivationStatus::ReusedStarted => "activation manual reused_started",
            TaskTargetActivationStatus::StartedStarted => "activation manual started_started",
            TaskTargetActivationStatus::RestartedReady => "activation manual restarted_ready",
            TaskTargetActivationStatus::ReusedReady => "activation manual reused_ready",
            TaskTargetActivationStatus::StartedReady => "activation manual started_ready",
            TaskTargetActivationStatus::ReusedRunning => "activation manual reused_running",
            TaskTargetActivationStatus::StartedRunning => "activation manual started_running",
            TaskTargetActivationStatus::Manual => "activation manual",
        },
        (TaskTargetActivationMode::EnsureStarted, TaskTargetActivationStatus::ReusedReady) => {
            "activation ensure_started reused_ready"
        }
        (TaskTargetActivationMode::EnsureStarted, TaskTargetActivationStatus::StartedReady) => {
            "activation ensure_started started_ready"
        }
        (TaskTargetActivationMode::EnsureStarted, TaskTargetActivationStatus::ReusedRunning) => {
            "activation ensure_started reused_running"
        }
        (TaskTargetActivationMode::EnsureStarted, TaskTargetActivationStatus::StartedRunning) => {
            "activation ensure_started started_running"
        }
        (TaskTargetActivationMode::RestartReady, TaskTargetActivationStatus::ReusedRunning) => {
            "activation restart_ready reused_running"
        }
        (TaskTargetActivationMode::RestartReady, TaskTargetActivationStatus::StartedRunning) => {
            "activation restart_ready started_running"
        }
        (TaskTargetActivationMode::RestartReady, TaskTargetActivationStatus::ReusedStarted) => {
            "activation restart_ready reused_started"
        }
        (TaskTargetActivationMode::RestartReady, TaskTargetActivationStatus::StartedStarted) => {
            "activation restart_ready started_started"
        }
        (TaskTargetActivationMode::RestartReady, TaskTargetActivationStatus::ReusedReady) => {
            "activation restart_ready reused_ready"
        }
        (TaskTargetActivationMode::RestartReady, TaskTargetActivationStatus::StartedReady) => {
            "activation restart_ready started_ready"
        }
        (TaskTargetActivationMode::EnsureReady, TaskTargetActivationStatus::ReusedRunning) => {
            "activation ensure_ready reused_running"
        }
        (TaskTargetActivationMode::EnsureReady, TaskTargetActivationStatus::StartedRunning) => {
            "activation ensure_ready started_running"
        }
        (TaskTargetActivationMode::EnsureReady, TaskTargetActivationStatus::ReusedStarted) => {
            "activation ensure_ready reused_started"
        }
        (TaskTargetActivationMode::EnsureReady, TaskTargetActivationStatus::StartedStarted) => {
            "activation ensure_ready started_started"
        }
        (TaskTargetActivationMode::EnsureRunning, TaskTargetActivationStatus::ReusedReady) => {
            "activation ensure_running reused_ready"
        }
        (TaskTargetActivationMode::EnsureRunning, TaskTargetActivationStatus::StartedReady) => {
            "activation ensure_running started_ready"
        }
        (TaskTargetActivationMode::EnsureRunning, TaskTargetActivationStatus::ReusedStarted) => {
            "activation ensure_running reused_started"
        }
        (TaskTargetActivationMode::EnsureRunning, TaskTargetActivationStatus::StartedStarted) => {
            "activation ensure_running started_started"
        }
        (TaskTargetActivationMode::EnsureStarted, TaskTargetActivationStatus::RestartedReady) => {
            "activation ensure_started restarted_ready"
        }
        (TaskTargetActivationMode::EnsureReady, TaskTargetActivationStatus::RestartedReady) => {
            "activation ensure_ready restarted_ready"
        }
        (TaskTargetActivationMode::EnsureRunning, TaskTargetActivationStatus::RestartedReady) => {
            "activation ensure_running restarted_ready"
        }
    };
    format!("{source}; {activation_label}")
}

fn shared_local_backend_evidence_from_step(
    backend: &ResolvedExecutionBackend,
    command_output: &TaskCommandOutput,
) -> Option<SharedLocalBackendEvidence> {
    let shared_local_backend = match backend {
        ResolvedExecutionBackend::Native {
            shared_local_backend: Some(shared_local_backend),
        }
        | ResolvedExecutionBackend::Container {
            shared_local_backend: Some(shared_local_backend),
            ..
        } => shared_local_backend,
        _ => return None,
    };

    let effective_identity = match backend {
        ResolvedExecutionBackend::Native { .. } => format!(
            "shared-backend:{}:{}:native",
            shared_local_backend.name,
            shared_local_backend
                .context_name
                .as_deref()
                .unwrap_or(LEGACY_EXECUTION_CONTEXT_NAME)
        ),
        ResolvedExecutionBackend::Container { .. } => {
            command_output.target.clone().unwrap_or_else(|| {
                format!(
                    "local-backend:{}:{}",
                    shared_local_backend.name,
                    shared_local_backend
                        .context_name
                        .as_deref()
                        .unwrap_or(LEGACY_EXECUTION_CONTEXT_NAME)
                )
            })
        }
        _ => unreachable!(),
    };

    Some(SharedLocalBackendEvidence {
        name: shared_local_backend.name.clone(),
        backend: match shared_local_backend.backend {
            Backend::Native => String::from("native"),
            Backend::Container => String::from("container"),
            Backend::Remote => String::from("remote"),
        },
        lifecycle: format_lifecycle(shared_local_backend.lifecycle).to_string(),
        context: shared_local_backend.context_name.clone(),
        environment: shared_local_backend.environment.clone(),
        effective_identity,
        reuse: match backend {
            ResolvedExecutionBackend::Container { .. } => command_output
                .execution_note
                .as_deref()
                .and_then(shared_local_backend_reuse_from_note),
            _ => None,
        },
    })
}

fn shared_local_backend_reuse_from_note(note: &str) -> Option<SharedLocalBackendReuse> {
    if note.contains("persistent container recreated") {
        Some(SharedLocalBackendReuse::Recreated)
    } else if note.contains("persistent container reused") {
        Some(SharedLocalBackendReuse::Reused)
    } else if note.contains("persistent container created") {
        Some(SharedLocalBackendReuse::Created)
    } else {
        None
    }
}

fn task_input_env_name(name: &str) -> String {
    let mut env = String::from("OTA_INPUT_");
    for ch in name.chars() {
        if ch.is_ascii_alphanumeric() {
            env.push(ch.to_ascii_uppercase());
        } else {
            env.push('_');
        }
    }
    env
}

pub fn effective_execution(
    contract: &Contract,
    overrides: ExecutionOverrides,
) -> (Backend, Option<Lifecycle>) {
    let execution = contract.execution.as_ref();
    let default_context = execution.and_then(|execution| execution.default_context());
    let backend = overrides
        .backend
        .or_else(|| default_context.map(|(_, context)| context.backend))
        .or_else(|| execution.and_then(|execution| execution.preferred))
        .unwrap_or(Backend::Native);
    let lifecycle = overrides
        .lifecycle
        .or_else(|| {
            default_context
                .filter(|(_, context)| context.backend == backend)
                .and_then(|(_, context)| context.lifecycle)
        })
        .or_else(|| execution.and_then(|execution| execution.lifecycle))
        .or_else(|| {
            execution.and_then(|execution| {
                execution
                    .contexts
                    .values()
                    .find(|context| context.backend == backend)
                    .and_then(|context| context.lifecycle)
            })
        });

    (backend, lifecycle)
}

#[derive(Clone, Copy)]
pub(crate) struct EffectiveTaskExecution<'a> {
    pub context_name: Option<&'a str>,
    pub backend: Backend,
    pub lifecycle: Option<Lifecycle>,
    pub container: Option<&'a ContainerBackend>,
    pub remote: Option<&'a RemoteBackend>,
}

fn selected_task_mode_branch<'a>(
    contract: &'a Contract,
    task_name: &str,
    backend: Backend,
) -> Option<&'a TaskModeBranchSpec> {
    contract
        .tasks
        .get(task_name)
        .and_then(|task| task.mode_execution_branch(backend))
}

fn selected_task_declared_context<'a>(
    contract: &'a Contract,
    task_name: &str,
) -> Option<(&'a str, &'a ExecutionContext)> {
    let execution = contract.execution.as_ref()?;
    let task_context = contract
        .tasks
        .get(task_name)
        .and_then(|task| task.context.as_deref());
    let context_name = task_context.or(execution.default_context.as_deref())?;
    execution
        .contexts
        .get_key_value(context_name)
        .map(|(name, context)| (name.as_str(), context))
}

pub(crate) fn selected_task_context_for_backend<'a>(
    contract: &'a Contract,
    task_name: &str,
    backend: Backend,
) -> Option<(&'a str, &'a ExecutionContext)> {
    let execution = contract.execution.as_ref()?;
    let Some(task) = contract.tasks.get(task_name) else {
        if let Some((name, context)) = execution.default_context()
            && context.backend == backend
        {
            return Some((name, context));
        }

        return execution
            .contexts
            .iter()
            .find(|(_, context)| context.backend == backend)
            .map(|(name, context)| (name.as_str(), context));
    };
    let branch_context = task
        .mode_execution_branch(backend)
        .and_then(|branch| branch.context.as_deref())
        .filter(|context_name| {
            execution
                .contexts
                .get(*context_name)
                .is_some_and(|context| context.backend == backend)
        });
    let context_name = if let Some(context_name) = branch_context {
        context_name
    } else if let Some(context_name) = task.context.as_deref() {
        if execution
            .contexts
            .get(context_name)
            .is_some_and(|context| context.backend == backend)
        {
            context_name
        } else if execution
            .default_context()
            .is_some_and(|(_, context)| context.backend == backend)
        {
            execution.default_context().map(|(name, _)| name)?
        } else {
            execution
                .contexts
                .iter()
                .find(|(_, context)| context.backend == backend)
                .map(|(name, _)| name.as_str())?
        }
    } else if let Some((name, context)) = execution.default_context() {
        if context.backend == backend {
            name
        } else {
            execution
                .contexts
                .iter()
                .find(|(_, context)| context.backend == backend)
                .map(|(name, _)| name.as_str())?
        }
    } else {
        execution
            .contexts
            .iter()
            .find(|(_, context)| context.backend == backend)
            .map(|(name, _)| name.as_str())?
    };
    execution
        .contexts
        .get_key_value(context_name)
        .map(|(name, context)| (name.as_str(), context))
}

pub(crate) fn reported_task_context_for_backend<'a>(
    contract: &'a Contract,
    task_name: &str,
    backend: Backend,
) -> Option<&'a str> {
    let execution = contract.execution.as_ref()?;
    let task = contract.tasks.get(task_name)?;

    if let Some(branch) = task.mode_execution_branch(backend) {
        if let Some(context_name) = branch.context.as_deref()
            && let Some((name, context)) = execution.contexts.get_key_value(context_name)
            && context.backend == backend
        {
            return Some(name.as_str());
        }
    }

    if let Some(context_name) = task.context.as_deref() {
        if let Some((name, context)) = execution.contexts.get_key_value(context_name)
            && context.backend == backend
        {
            return Some(name.as_str());
        }
    }

    if let Some((name, context)) = execution.default_context()
        && context.backend == backend
    {
        return Some(name);
    }

    execution
        .contexts
        .iter()
        .find(|(_, context)| context.backend == backend)
        .map(|(name, _)| name.as_str())
}

pub(crate) fn named_execution_context<'a>(
    contract: &'a Contract,
    context_name: &str,
) -> Option<(&'a str, &'a ExecutionContext)> {
    contract
        .execution
        .as_ref()?
        .contexts
        .get_key_value(context_name)
        .map(|(name, context)| (name.as_str(), context))
}

fn compose_networks_for_context(context: &ExecutionContext) -> Vec<String> {
    context
        .attachments
        .compose
        .iter()
        .map(|project| project.trim())
        .filter(|project| !project.is_empty())
        .map(|project| format!("{project}_default"))
        .collect()
}

fn task_container_context_name<'a>(contract: &'a Contract, task_name: &str) -> Option<&'a str> {
    let effective = effective_task_execution(contract, task_name, ExecutionOverrides::default());
    (effective.backend == Backend::Container)
        .then_some(effective.context_name)
        .flatten()
}

fn task_container_publications(
    contract: &Contract,
    task_name: &str,
) -> Vec<ContainerPortPublication> {
    let effective = effective_task_execution(contract, task_name, ExecutionOverrides::default());
    task_container_publication_details(contract, task_name, effective.backend)
        .into_iter()
        .map(|(_, publication)| publication)
        .collect()
}

fn task_container_publication_details(
    contract: &Contract,
    task_name: &str,
    backend: Backend,
) -> Vec<(String, ContainerPortPublication)> {
    let Some(task) = contract.tasks.get(task_name) else {
        return Vec::new();
    };
    let Some(runtime) = task.service_runtime_for_backend(backend) else {
        return Vec::new();
    };

    runtime
        .listeners
        .iter()
        .filter_map(|(listener_name, listener)| {
            let host = listener.project.host.as_ref()?;
            Some((
                listener_name.clone(),
                ContainerPortPublication {
                    bind_port: listener
                        .bind
                        .port
                        .value
                        .expect("validated container runtime listener should declare a bind port"),
                    host_address: host.address.trim().to_string(),
                    host_port_mode: host.port.mode,
                    host_port: host.port.value,
                    protocol: listener.protocol,
                },
            ))
        })
        .collect()
}

fn task_runtime_listener_publications(
    runtime: Option<&TaskRuntimeSpec>,
) -> Vec<(String, ContainerPortPublication)> {
    let Some(runtime) = runtime else {
        return Vec::new();
    };

    runtime
        .listeners
        .iter()
        .filter_map(|(listener_name, listener)| {
            let host = listener.project.host.as_ref()?;
            Some((
                listener_name.clone(),
                ContainerPortPublication {
                    bind_port: listener
                        .bind
                        .port
                        .value
                        .expect("validated container runtime listener should declare a bind port"),
                    host_address: host.address.trim().to_string(),
                    host_port_mode: host.port.mode,
                    host_port: host.port.value,
                    protocol: listener.protocol,
                },
            ))
        })
        .collect()
}

fn selected_host_port_override_listener(
    task_name: &str,
    runtime: &TaskRuntimeSpec,
) -> Result<String, RunError> {
    let projected = runtime
        .listeners
        .iter()
        .filter_map(|(listener_name, listener)| {
            listener
                .project
                .host
                .as_ref()
                .map(|_| listener_name.clone())
        })
        .collect::<Vec<_>>();
    if projected.is_empty() {
        return Err(RunError::HostPortOverrideNoProjectedListener {
            task: task_name.to_string(),
        });
    }

    let primaries = runtime
        .listeners
        .iter()
        .filter_map(|(listener_name, listener)| {
            listener
                .project
                .host
                .as_ref()
                .is_some_and(|host| host.primary)
                .then_some(listener_name.clone())
        })
        .collect::<Vec<_>>();
    if primaries.len() == 1 {
        return Ok(primaries[0].clone());
    }
    if projected.len() == 1 {
        return Ok(projected[0].clone());
    }

    Err(RunError::HostPortOverrideAmbiguousProjectedListener {
        task: task_name.to_string(),
        listeners: projected.join(", "),
    })
}

fn preflight_host_port_override(
    task_name: &str,
    runtime: Option<&TaskRuntimeSpec>,
    backend: &ResolvedExecutionBackend,
    host_port_override: Option<u16>,
) -> Result<(), RunError> {
    if host_port_override.is_none() {
        return Ok(());
    }

    if !matches!(backend, ResolvedExecutionBackend::Container { .. }) {
        let backend = match backend {
            ResolvedExecutionBackend::Native { .. } => "native",
            ResolvedExecutionBackend::Container { .. } => "container",
            ResolvedExecutionBackend::Remote { .. } => "remote",
            ResolvedExecutionBackend::BackendProvider { .. } => "backend-provider",
        };
        return Err(RunError::HostPortOverrideUnsupportedBackend {
            task: task_name.to_string(),
            backend,
        });
    }

    let mut listener_publications = task_runtime_listener_publications(runtime);
    apply_host_port_override_to_listener_publications(
        task_name,
        runtime,
        &mut listener_publications,
        host_port_override,
    )?;
    Ok(())
}

fn container_memory_override_or_default(
    task_name: &str,
    container: &ContainerBackend,
    field_prefix: &str,
    override_bytes: Option<u64>,
) -> Result<Option<u64>, RunError> {
    let Some(memory) = container
        .resources
        .as_ref()
        .and_then(|resources| resources.memory.as_ref())
    else {
        return Ok(override_bytes);
    };

    let minimum_field = format!("{field_prefix}.resources.memory.minimum");
    let default_field = format!("{field_prefix}.resources.memory.default");
    let minimum_bytes = memory
        .minimum
        .as_deref()
        .map(|value| {
            parse_memory_size_bytes(value).map_err(|error| RunError::InvalidContainerMemoryValue {
                task: task_name.to_string(),
                field: minimum_field.clone(),
                value: value.to_string(),
                details: error.to_string(),
            })
        })
        .transpose()?;
    let default_bytes = memory
        .default
        .as_deref()
        .map(|value| {
            parse_memory_size_bytes(value).map_err(|error| RunError::InvalidContainerMemoryValue {
                task: task_name.to_string(),
                field: default_field.clone(),
                value: value.to_string(),
                details: error.to_string(),
            })
        })
        .transpose()?;
    if let (Some(default_bytes), Some(minimum_bytes)) = (default_bytes, minimum_bytes)
        && default_bytes < minimum_bytes
    {
        return Err(RunError::InvalidContainerMemoryRange {
            task: task_name.to_string(),
            default_field,
            default_value: format_memory_size_bytes(default_bytes),
            minimum_field,
            minimum_value: format_memory_size_bytes(minimum_bytes),
        });
    }

    // `minimum` is an honest support floor; if no explicit default is declared,
    // request the minimum so ordinary runs cannot silently execute below it.
    let requested = override_bytes.or(default_bytes).or(minimum_bytes);
    if let (Some(requested_bytes), Some(minimum_bytes)) = (requested, minimum_bytes)
        && requested_bytes < minimum_bytes
    {
        return Err(RunError::MemoryOverrideBelowMinimum {
            task: task_name.to_string(),
            requested: format_memory_size_bytes(requested_bytes),
            minimum: format_memory_size_bytes(minimum_bytes),
            field: minimum_field,
        });
    }

    Ok(requested)
}

fn apply_host_port_override_to_listener_publications(
    task_name: &str,
    runtime: Option<&TaskRuntimeSpec>,
    listener_publications: &mut [(String, ContainerPortPublication)],
    host_port_override: Option<u16>,
) -> Result<(), RunError> {
    let Some(host_port) = host_port_override else {
        return Ok(());
    };
    let runtime = runtime.ok_or_else(|| RunError::HostPortOverrideNoProjectedListener {
        task: task_name.to_string(),
    })?;

    let listener_name = selected_host_port_override_listener(task_name, runtime)?;
    let listener = runtime
        .listeners
        .get(listener_name.as_str())
        .expect("selected host-port override listener should exist");
    let host_projection = listener.project.host.as_ref().ok_or_else(|| {
        RunError::HostPortOverrideNoProjectedListener {
            task: task_name.to_string(),
        }
    })?;
    if host_projection.port.mode != TaskRuntimeHostPortMode::Fixed {
        return Err(RunError::HostPortOverrideRequiresFixedProjectedPort {
            task: task_name.to_string(),
            listener: listener_name,
        });
    }

    let publication = listener_publications
        .iter_mut()
        .find(|(name, _)| name == listener_name.as_str())
        .map(|(_, publication)| publication)
        .ok_or_else(|| RunError::HostPortOverrideNoProjectedListener {
            task: task_name.to_string(),
        })?;
    publication.host_port_mode = TaskRuntimeHostPortMode::Fixed;
    publication.host_port = Some(host_port);

    Ok(())
}

fn prepare_container_runtime_projection(
    task_name: &str,
    runtime: Option<&TaskRuntimeSpec>,
    publications: &[ContainerPortPublication],
    listener_publications: &[(String, ContainerPortPublication)],
    resolve_auto_host_ports: bool,
    host_port_override: Option<u16>,
) -> Result<PreparedContainerRuntimeProjection, RunError> {
    if runtime.is_none() || listener_publications.is_empty() {
        if host_port_override.is_some() {
            return Err(RunError::HostPortOverrideNoProjectedListener {
                task: task_name.to_string(),
            });
        }
        return Ok(PreparedContainerRuntimeProjection {
            publications: publications.to_vec(),
            listener_publications: listener_publications.to_vec(),
            env: BTreeMap::new(),
            expected_host_ports: BTreeMap::new(),
        });
    }

    let mut prepared_listeners = listener_publications.to_vec();
    apply_host_port_override_to_listener_publications(
        task_name,
        runtime,
        &mut prepared_listeners,
        host_port_override,
    )?;
    for (listener_name, publication) in &mut prepared_listeners {
        if resolve_auto_host_ports && publication.host_port_mode == TaskRuntimeHostPortMode::Auto {
            let listener =
                TcpListener::bind((publication.host_address.as_str(), 0)).map_err(|source| {
                    runtime_listener_host_publication_bind_failed(
                        task_name,
                        listener_name.as_str(),
                        &publication.host_address,
                        format!(
                            "could not reserve an ephemeral host port on `{}`: {source}",
                            publication.host_address
                        ),
                    )
                })?;
            let port = listener
                .local_addr()
                .map_err(|source| RunError::SpawnFailed {
                    task: String::from("runtime-projection"),
                    source,
                })?
                .port();
            drop(listener);
            publication.host_port_mode = TaskRuntimeHostPortMode::Fixed;
            publication.host_port = Some(port);
        }
    }

    let prepared_publications = merge_container_publication_sets(
        publications,
        &prepared_listeners
            .iter()
            .map(|(_, publication)| publication.clone())
            .collect::<Vec<_>>(),
    );

    let mut expected_host_ports = BTreeMap::new();
    for (listener_name, publication) in &prepared_listeners {
        if publication.host_port_mode != TaskRuntimeHostPortMode::Fixed {
            continue;
        }
        let Some(port) = publication.host_port else {
            continue;
        };
        expected_host_ports.insert(listener_name.clone(), port);
    }

    let env = runtime_public_env(runtime, &prepared_listeners, &expected_host_ports);

    Ok(PreparedContainerRuntimeProjection {
        publications: prepared_publications,
        listener_publications: prepared_listeners,
        env,
        expected_host_ports,
    })
}

fn merge_container_publication_sets(
    base: &[ContainerPortPublication],
    overlay: &[ContainerPortPublication],
) -> Vec<ContainerPortPublication> {
    let mut merged = base.to_vec();
    for overlay_publication in overlay {
        if let Some(existing) = merged.iter_mut().find(|existing| {
            existing.bind_port == overlay_publication.bind_port
                && existing.host_address == overlay_publication.host_address
                && existing.protocol == overlay_publication.protocol
        }) {
            *existing = overlay_publication.clone();
        } else {
            merged.push(overlay_publication.clone());
        }
    }
    merged
}

fn resolve_container_task_runtime_from_publications(
    runtime: Option<&TaskRuntimeSpec>,
    listener_publications: &[(String, ContainerPortPublication)],
) -> Option<ResolvedTaskRuntime> {
    let runtime = runtime?;
    let publication_index = listener_publications
        .iter()
        .map(|(listener_name, publication)| (listener_name.as_str(), publication))
        .collect::<BTreeMap<_, _>>();

    let listeners = runtime
        .listeners
        .iter()
        .map(|(listener_name, listener)| {
            let bind_port = listener
                .bind
                .port
                .value
                .expect("validated container listener should have a fixed bind port");
            let resolved = listener.project.host.as_ref().and_then(|host| {
                let publication = publication_index.get(listener_name.as_str())?;
                let host_port = publication.host_port?;
                Some(ResolvedTaskRuntimeResolution {
                    host: Some(ResolvedTaskRuntimeHost {
                        address: host.address.trim().to_string(),
                        port: host_port,
                        url: listener.protocol.url_scheme().map(|scheme| {
                            format!(
                                "{scheme}://{}:{host_port}{}",
                                host.address.trim(),
                                normalized_runtime_path(host.path.as_deref())
                            )
                        }),
                    }),
                })
            });

            (
                listener_name.clone(),
                ResolvedTaskRuntimeListener {
                    protocol: listener.protocol,
                    bind: ResolvedTaskRuntimeBind {
                        address: listener.bind.address.trim().to_string(),
                        port: bind_port,
                    },
                    resolved,
                },
            )
        })
        .collect::<BTreeMap<_, _>>();

    Some(build_resolved_runtime(runtime, listeners))
}

fn runtime_public_env_from_resolved_runtime(
    runtime: &ResolvedTaskRuntime,
) -> BTreeMap<String, String> {
    let mut env = BTreeMap::new();

    for endpoint in &runtime.exposed_endpoints {
        env.insert(
            format!(
                "OTA_PUBLIC_URL_{}",
                runtime_listener_env_suffix(endpoint.listener.as_str())
            ),
            resolved_runtime_host_endpoint_text(&endpoint.host),
        );
    }

    if let Some(endpoint) = runtime
        .primary_endpoint
        .as_ref()
        .or_else(|| runtime.exposed_endpoints.first())
    {
        env.insert(
            String::from("OTA_PUBLIC_HOST"),
            endpoint.host.address.clone(),
        );
        env.insert(
            String::from("OTA_PUBLIC_PORT"),
            endpoint.host.port.to_string(),
        );
        env.insert(
            String::from("OTA_PUBLIC_URL"),
            resolved_runtime_host_endpoint_text(&endpoint.host),
        );
    }

    env
}

fn runtime_bind_env(runtime: Option<&TaskRuntimeSpec>) -> BTreeMap<String, String> {
    let Some(runtime) = runtime else {
        return BTreeMap::new();
    };

    let mut env = BTreeMap::new();
    let primary_listener = runtime_primary_bind_listener_name(runtime);
    for (listener_name, listener) in &runtime.listeners {
        let bind_address = listener.bind.address.trim();
        if bind_address.is_empty() {
            continue;
        }
        let suffix = runtime_listener_env_suffix(listener_name.as_str());
        env.insert(
            format!("OTA_BIND_ADDRESS_{suffix}"),
            bind_address.to_string(),
        );
        if let Some(bind_port) = listener.bind.port.value {
            env.insert(format!("OTA_BIND_PORT_{suffix}"), bind_port.to_string());
            if primary_listener == Some(listener_name.as_str()) {
                env.insert(String::from("OTA_BIND_ADDRESS"), bind_address.to_string());
                env.insert(String::from("OTA_BIND_PORT"), bind_port.to_string());
                env.insert(String::from("HOST"), bind_address.to_string());
                env.insert(String::from("HOSTNAME"), bind_address.to_string());
                env.insert(String::from("PORT"), bind_port.to_string());
                env.insert(String::from("BIND_ADDRESS"), bind_address.to_string());
                env.insert(String::from("BIND_PORT"), bind_port.to_string());
                env.insert(String::from("SERVER_ADDRESS"), bind_address.to_string());
                env.insert(String::from("SERVER_PORT"), bind_port.to_string());
            }
        }
    }

    env
}

fn runtime_bind_env_for_native(runtime: Option<&TaskRuntimeSpec>) -> BTreeMap<String, String> {
    let mut env = runtime_bind_env(runtime);
    let Some(runtime) = runtime else {
        return env;
    };

    let Some(primary_listener_name) = runtime_primary_bind_listener_name(runtime) else {
        return env;
    };
    let Some(listener) = runtime.listeners.get(primary_listener_name) else {
        return env;
    };
    let Some(host) = listener.project.host.as_ref() else {
        return env;
    };
    let host_address = host.address.trim();
    if host_address.is_empty() {
        return env;
    }

    env.insert(String::from("HOST"), host_address.to_string());
    env.insert(String::from("HOSTNAME"), host_address.to_string());
    env.insert(String::from("BIND_ADDRESS"), host_address.to_string());
    env.insert(String::from("SERVER_ADDRESS"), host_address.to_string());
    env
}

fn runtime_bind_env_from_resolved_runtime(
    runtime: &ResolvedTaskRuntime,
) -> BTreeMap<String, String> {
    let mut env = BTreeMap::new();
    let primary_listener = runtime
        .primary_listener
        .as_deref()
        .or_else(|| runtime.listeners.keys().next().map(String::as_str));
    for (listener_name, listener) in &runtime.listeners {
        let bind_address = listener.bind.address.trim();
        if bind_address.is_empty() {
            continue;
        }
        let suffix = runtime_listener_env_suffix(listener_name.as_str());
        env.insert(
            format!("OTA_BIND_ADDRESS_{suffix}"),
            bind_address.to_string(),
        );
        env.insert(
            format!("OTA_BIND_PORT_{suffix}"),
            listener.bind.port.to_string(),
        );
        if primary_listener == Some(listener_name.as_str()) {
            env.insert(String::from("OTA_BIND_ADDRESS"), bind_address.to_string());
            env.insert(
                String::from("OTA_BIND_PORT"),
                listener.bind.port.to_string(),
            );
            env.insert(String::from("HOST"), bind_address.to_string());
            env.insert(String::from("HOSTNAME"), bind_address.to_string());
            env.insert(String::from("PORT"), listener.bind.port.to_string());
            env.insert(String::from("BIND_ADDRESS"), bind_address.to_string());
            env.insert(String::from("BIND_PORT"), listener.bind.port.to_string());
            env.insert(String::from("SERVER_ADDRESS"), bind_address.to_string());
            env.insert(String::from("SERVER_PORT"), listener.bind.port.to_string());
        }
    }

    env
}

fn runtime_primary_bind_listener_name(runtime: &TaskRuntimeSpec) -> Option<&str> {
    if let Some((listener_name, _)) = runtime.listeners.iter().find(|(_, listener)| {
        listener
            .project
            .host
            .as_ref()
            .is_some_and(|host| host.primary)
    }) {
        return Some(listener_name.as_str());
    }

    if runtime.listeners.len() == 1 {
        return runtime.listeners.keys().next().map(String::as_str);
    }

    runtime.listeners.keys().next().map(String::as_str)
}

fn extend_missing_env(target: &mut BTreeMap<String, String>, fallback: BTreeMap<String, String>) {
    for (key, value) in fallback {
        target.entry(key).or_insert(value);
    }
}

fn ready_runtime_public_endpoint_line(runtime: &ResolvedTaskRuntime) -> Option<String> {
    runtime
        .primary_endpoint
        .as_ref()
        .or_else(|| runtime.exposed_endpoints.first())
        .map(|endpoint| {
            let external = resolved_runtime_host_endpoint_text(&endpoint.host);
            let internal = resolved_runtime_internal_endpoint_text(endpoint);
            if external == internal {
                format!(
                    "\n\n{} {}  {}\n\n",
                    endpoint_banner_symbol(true),
                    endpoint_banner_label("External:", true),
                    endpoint_banner_url(external.as_str())
                )
            } else {
                format!(
                    "\n\n{} {}  {}\n{} {}  {}\n\n",
                    endpoint_banner_symbol(true),
                    endpoint_banner_label("External:", true),
                    endpoint_banner_url(external.as_str()),
                    endpoint_banner_symbol(false),
                    endpoint_banner_label("Internal:", false),
                    endpoint_banner_url(internal.as_str())
                )
            }
        })
}

fn endpoint_banner_symbol(external: bool) -> String {
    if supports_dynamic_stderr_ui(io::stderr().is_terminal()) {
        endpoint_banner_paint(
            if external { "⚈" } else { "⦾" },
            if external {
                "1;38;2;0;255;120"
            } else {
                "1;38;2;94;168;214"
            },
        )
    } else if external {
        String::from("⚈")
    } else {
        String::from("⦾")
    }
}

fn endpoint_banner_label(label: &str, external: bool) -> String {
    if supports_dynamic_stderr_ui(io::stderr().is_terminal()) {
        endpoint_banner_paint(
            label,
            if external {
                "1;38;2;0;255;120"
            } else {
                "1;38;2;94;168;214"
            },
        )
    } else {
        label.to_string()
    }
}

fn endpoint_banner_url(url: &str) -> String {
    if supports_dynamic_stderr_ui(io::stderr().is_terminal()) {
        endpoint_banner_paint(url, "1;37")
    } else {
        url.to_string()
    }
}

fn endpoint_banner_paint(value: &str, code: &str) -> String {
    format!("\u{1b}[{code}m{value}\u{1b}[0m")
}

fn resolved_runtime_host_endpoint_text(host: &ResolvedTaskRuntimeHost) -> String {
    host.url
        .clone()
        .unwrap_or_else(|| format!("{}:{}", host.address, host.port))
}

pub(crate) fn resolved_runtime_internal_endpoint_text(
    endpoint: &ResolvedTaskRuntimeEndpoint,
) -> String {
    endpoint
        .protocol
        .url_scheme()
        .map(|scheme| {
            format!(
                "{scheme}://{}:{}/",
                endpoint.bind.address, endpoint.bind.port
            )
        })
        .unwrap_or_else(|| format!("{}:{}", endpoint.bind.address, endpoint.bind.port))
}

fn resolved_primary_listener_name(
    runtime: &TaskRuntimeSpec,
    available: &BTreeSet<String>,
) -> Option<String> {
    let projected = runtime
        .listeners
        .iter()
        .filter_map(|(listener_name, listener)| {
            listener.project.host.as_ref().and_then(|_| {
                available
                    .contains(listener_name)
                    .then_some(listener_name.clone())
            })
        })
        .collect::<Vec<_>>();
    if projected.is_empty() {
        return None;
    }

    if let Some((listener_name, _)) = runtime.listeners.iter().find(|(listener_name, listener)| {
        listener
            .project
            .host
            .as_ref()
            .is_some_and(|host| host.primary && available.contains(*listener_name))
    }) {
        return Some(listener_name.clone());
    }

    if projected.len() == 1 {
        return projected.into_iter().next();
    }

    projected.into_iter().next()
}

fn runtime_public_env(
    runtime: Option<&TaskRuntimeSpec>,
    _listener_publications: &[(String, ContainerPortPublication)],
    expected_host_ports: &BTreeMap<String, u16>,
) -> BTreeMap<String, String> {
    let Some(runtime) = runtime else {
        return BTreeMap::new();
    };

    let mut env = BTreeMap::new();
    let available = expected_host_ports
        .keys()
        .cloned()
        .collect::<BTreeSet<String>>();
    let primary_listener = resolved_primary_listener_name(runtime, &available);
    let mut selected_primary: Option<(String, u16, String)> = None;
    for (listener_name, listener) in &runtime.listeners {
        let Some(host_projection) = listener.project.host.as_ref() else {
            continue;
        };
        let Some(host_port) = expected_host_ports.get(listener_name) else {
            continue;
        };
        let host_address = host_projection.address.trim().to_string();
        let endpoint = listener
            .protocol
            .url_scheme()
            .map(|scheme| {
                format!(
                    "{scheme}://{}:{host_port}{}",
                    host_address,
                    normalized_runtime_path(host_projection.path.as_deref())
                )
            })
            .unwrap_or_else(|| format!("{}:{host_port}", host_address));

        env.insert(
            format!(
                "OTA_PUBLIC_URL_{}",
                runtime_listener_env_suffix(listener_name.as_str())
            ),
            endpoint.clone(),
        );

        if primary_listener.as_deref() == Some(listener_name.as_str()) {
            selected_primary = Some((host_address.clone(), *host_port, endpoint.clone()));
        } else if selected_primary.is_none() {
            selected_primary = Some((host_address.clone(), *host_port, endpoint.clone()));
        }
    }

    if let Some((host, port, endpoint)) = selected_primary {
        env.insert(String::from("OTA_PUBLIC_HOST"), host);
        env.insert(String::from("OTA_PUBLIC_PORT"), port.to_string());
        env.insert(String::from("OTA_PUBLIC_URL"), endpoint);
    }

    env
}

fn runtime_listener_env_suffix(listener_name: &str) -> String {
    let mut suffix = String::new();
    for ch in listener_name.chars() {
        if ch.is_ascii_alphanumeric() {
            suffix.push(ch.to_ascii_uppercase());
        } else {
            suffix.push('_');
        }
    }
    suffix
}

fn is_container_host_publication_conflict(stdout: &str, stderr: &str) -> bool {
    let output = format!("{stdout}\n{stderr}").to_ascii_lowercase();
    output.contains("port is already allocated")
        || output.contains("address already in use")
        || output.contains("bind for")
}

fn preflight_container_host_publications(
    task_name: &str,
    listener_publications: &[(String, ContainerPortPublication)],
) -> Result<(), RunError> {
    for (listener_name, publication) in listener_publications {
        if publication.host_port_mode != TaskRuntimeHostPortMode::Fixed {
            continue;
        }
        let Some(port) = publication.host_port else {
            continue;
        };

        match TcpListener::bind((publication.host_address.as_str(), port)) {
            Ok(listener) => drop(listener),
            Err(error) if error.kind() == io::ErrorKind::AddrInUse => {
                return Err(RunError::HostPublicationConflict {
                    task: task_name.to_string(),
                    listener: listener_name.clone(),
                    address: publication.host_address.clone(),
                    port,
                });
            }
            Err(error) => {
                return Err(runtime_listener_host_publication_bind_failed(
                    task_name,
                    listener_name,
                    &publication.host_address,
                    format!(
                        "could not bind host port `{port}` on `{}`: {error}",
                        publication.host_address
                    ),
                ));
            }
        }
    }

    Ok(())
}

pub(crate) fn preflight_native_runtime_listener_binds(
    task_name: &str,
    runtime: Option<&TaskRuntimeSpec>,
) -> Result<(), RunError> {
    let Some(runtime) = runtime else {
        return Ok(());
    };

    for (listener_name, listener) in &runtime.listeners {
        if listener.bind.port.mode != crate::schema::TaskRuntimePortMode::Fixed {
            continue;
        }
        let Some(port) = listener.bind.port.value else {
            continue;
        };

        match TcpListener::bind((listener.bind.address.as_str(), port)) {
            Ok(bound) => drop(bound),
            Err(error) if error.kind() == io::ErrorKind::AddrInUse => {
                return Err(RunError::NativeListenerBindConflict {
                    task: task_name.to_string(),
                    listener: listener_name.clone(),
                    address: listener.bind.address.clone(),
                    port,
                });
            }
            Err(_) => {}
        }
    }

    Ok(())
}

fn reclaimed_conflicting_persistent_backends_note(count: usize) -> Option<String> {
    match count {
        0 => None,
        1 => Some(String::from(
            "reclaimed 1 conflicting persistent backend before starting task",
        )),
        _ => Some(format!(
            "reclaimed {count} conflicting persistent backends before starting task"
        )),
    }
}

fn preflight_reused_persistent_container_listener_binds(
    task_name: &str,
    runtime: Option<&TaskRuntimeSpec>,
    engine: &str,
    container_name: &str,
) -> Result<(), RunError> {
    let Some(runtime) = runtime else {
        return Ok(());
    };

    let fixed_binds = runtime
        .listeners
        .iter()
        .filter_map(|(listener_name, listener)| {
            listener
                .bind
                .port
                .value
                .map(|port| (listener_name.clone(), listener.bind.address.clone(), port))
        })
        .collect::<Vec<_>>();
    if fixed_binds.is_empty() {
        return Ok(());
    }

    let probe = container_command_output(
        engine,
        &[
            "exec",
            "-i",
            container_name,
            "sh",
            "-c",
            "cat /proc/net/tcp /proc/net/tcp6 2>/dev/null || true",
        ],
        None,
        task_name,
    )?;
    if probe.exit_code != 0 {
        return Ok(());
    }

    let listening_ports = proc_net_listening_tcp_ports(&probe.stdout);
    for (listener_name, address, port) in fixed_binds {
        if listening_ports.contains(&port) {
            return Err(RunError::PersistentContainerListenerBindConflict {
                task: task_name.to_string(),
                listener: listener_name,
                address,
                port,
                container: container_name.to_string(),
            });
        }
    }

    Ok(())
}

fn proc_net_listening_tcp_ports(contents: &str) -> BTreeSet<u16> {
    contents
        .lines()
        .filter_map(parse_proc_net_listening_tcp_port)
        .collect()
}

fn parse_proc_net_listening_tcp_port(line: &str) -> Option<u16> {
    let columns = line.split_whitespace().collect::<Vec<_>>();
    if columns.len() < 4 || columns[0] == "sl" || columns[3] != "0A" {
        return None;
    }

    let (_, port_hex) = columns[1].rsplit_once(':')?;
    u16::from_str_radix(port_hex, 16).ok()
}

fn build_resolved_runtime(
    runtime: &TaskRuntimeSpec,
    listeners: BTreeMap<String, ResolvedTaskRuntimeListener>,
) -> ResolvedTaskRuntime {
    let available = listeners
        .iter()
        .filter_map(|(listener_name, listener)| {
            listener
                .resolved
                .as_ref()
                .and_then(|resolved| resolved.host.as_ref())
                .map(|_| listener_name.clone())
        })
        .collect::<BTreeSet<String>>();
    let selected_primary = resolved_primary_listener_name(runtime, &available);

    let mut exposed_endpoints = Vec::new();
    for (listener_name, listener) in &listeners {
        let Some(host) = listener
            .resolved
            .as_ref()
            .and_then(|resolved| resolved.host.as_ref())
        else {
            continue;
        };
        exposed_endpoints.push(ResolvedTaskRuntimeEndpoint {
            listener: listener_name.clone(),
            protocol: listener.protocol,
            bind: listener.bind.clone(),
            host: host.clone(),
            primary: selected_primary.as_deref() == Some(listener_name.as_str()),
        });
    }

    let primary_endpoint = selected_primary
        .as_ref()
        .and_then(|listener_name| {
            exposed_endpoints
                .iter()
                .find(|endpoint| endpoint.listener == *listener_name)
                .cloned()
        })
        .or_else(|| exposed_endpoints.first().cloned());
    let primary_listener = primary_endpoint
        .as_ref()
        .map(|endpoint| endpoint.listener.clone());

    ResolvedTaskRuntime {
        kind: runtime.kind,
        listeners,
        primary_listener,
        primary_endpoint,
        exposed_endpoints,
    }
}

fn task_container_publication_sets_for_context(
    contract: &Contract,
    context_name: Option<&str>,
) -> Vec<Vec<ContainerPortPublication>> {
    let normalized_context = context_name.unwrap_or(LEGACY_EXECUTION_CONTEXT_NAME);
    let mut publication_sets = vec![Vec::new()];

    for task_name in contract.tasks.keys() {
        if task_container_context_name(contract, task_name.as_str())
            .unwrap_or(LEGACY_EXECUTION_CONTEXT_NAME)
            != normalized_context
        {
            continue;
        }
        let publications = task_container_publications(contract, task_name.as_str());
        if publication_sets
            .iter()
            .any(|existing| *existing == publications)
        {
            continue;
        }
        publication_sets.push(publications);
    }

    publication_sets
}

fn container_identity_seed(
    context_name: Option<&str>,
    shared_local_backend_name: Option<&str>,
    publications: &[ContainerPortPublication],
    isolated_paths: &[String],
    memory_bytes: Option<u64>,
) -> Option<String> {
    let mut seed = match (shared_local_backend_name, context_name) {
        (Some(shared), Some(context)) => format!("shared:{shared}|context:{context}"),
        (Some(shared), None) => format!("shared:{shared}"),
        (None, Some(context)) => context.to_string(),
        (None, None) => return None,
    };
    if !publications.is_empty() {
        seed.push('|');
        seed.push_str(
            &publications
                .iter()
                .map(|publication| {
                    let host_port = publication
                        .host_port
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| String::from("auto"));
                    format!(
                        "{}:{}:{}:{host_port}:{}",
                        publication.bind_port,
                        publication.host_address,
                        publication.host_port_mode as u8,
                        publication.protocol as u8,
                    )
                })
                .collect::<Vec<_>>()
                .join(","),
        );
    }
    if !isolated_paths.is_empty() {
        seed.push('|');
        seed.push_str(
            &isolated_paths
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>()
                .join(","),
        );
    }
    if let Some(memory_bytes) = memory_bytes {
        seed.push('|');
        seed.push_str(format!("memory:{memory_bytes}").as_str());
    }
    Some(seed)
}

fn persistent_container_family_token(
    task_name: &str,
    context_name: Option<&str>,
    shared_local_backend_name: Option<&str>,
) -> String {
    let mut hasher = DefaultHasher::new();
    if let Some(shared_local_backend_name) = shared_local_backend_name {
        shared_local_backend_name.hash(&mut hasher);
    } else {
        task_name.hash(&mut hasher);
    }
    context_name
        .unwrap_or(LEGACY_EXECUTION_CONTEXT_NAME)
        .hash(&mut hasher);
    format!("{:x}", hasher.finish())
}

fn persistent_container_shape_token(
    context_name: Option<&str>,
    shared_local_backend_name: Option<&str>,
    image: &str,
    engine: &str,
    compose_networks: &[String],
    publications: &[ContainerPortPublication],
    isolated_paths: &[String],
    memory_bytes: Option<u64>,
) -> String {
    let mut hasher = DefaultHasher::new();
    shared_local_backend_name.hash(&mut hasher);
    context_name
        .unwrap_or(LEGACY_EXECUTION_CONTEXT_NAME)
        .hash(&mut hasher);
    image.hash(&mut hasher);
    engine.hash(&mut hasher);
    for compose_network in compose_networks {
        compose_network.hash(&mut hasher);
    }
    for publication in publications {
        publication.bind_port.hash(&mut hasher);
        publication.host_address.hash(&mut hasher);
        (publication.host_port_mode as u8).hash(&mut hasher);
        publication.host_port.hash(&mut hasher);
        (publication.protocol as u8).hash(&mut hasher);
    }
    for isolated_path in isolated_paths {
        isolated_path.hash(&mut hasher);
    }
    memory_bytes.hash(&mut hasher);
    format!("{:x}", hasher.finish())
}

pub(crate) fn effective_task_execution<'a>(
    contract: &'a Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> EffectiveTaskExecution<'a> {
    let execution = contract.execution.as_ref();
    let declared_context = selected_task_declared_context(contract, task_name);
    let task = contract.tasks.get(task_name);
    let declared_backend = declared_context.map(|(_, context)| context.backend);
    let backend = overrides
        .backend
        .or_else(|| task.and_then(TaskSpec::mode_default_backend))
        .or(declared_backend)
        .or_else(|| execution.and_then(|execution| execution.preferred))
        .unwrap_or(Backend::Native);
    let selected_context = selected_task_context_for_backend(contract, task_name, backend);
    let context = selected_context.map(|(_, context)| context);
    let mode_branch = selected_task_mode_branch(contract, task_name, backend);
    let lifecycle = overrides
        .lifecycle
        .or_else(|| mode_branch.and_then(|branch| branch.lifecycle))
        .or_else(|| {
            context
                .filter(|context| context.backend == backend)
                .and_then(|context| context.lifecycle)
        })
        .or_else(|| execution.and_then(|execution| execution.lifecycle));
    let container = (backend == Backend::Container)
        .then(|| {
            context
                .filter(|context| context.backend == Backend::Container)
                .and_then(|context| context.container.as_ref())
                .or_else(|| {
                    execution
                        .and_then(|execution| execution.backends.as_ref())
                        .and_then(|backends| backends.container.as_ref())
                })
        })
        .flatten();
    let remote = (backend == Backend::Remote)
        .then(|| {
            context
                .filter(|context| context.backend == Backend::Remote)
                .and_then(|context| context.remote.as_ref())
                .or_else(|| {
                    execution
                        .and_then(|execution| execution.backends.as_ref())
                        .and_then(|backends| backends.remote.as_ref())
                })
        })
        .flatten();
    let context_name = selected_context
        .map(|(name, _)| name)
        .or_else(|| matching_execution_context_name(execution, backend, lifecycle));

    EffectiveTaskExecution {
        context_name,
        backend,
        lifecycle,
        container,
        remote,
    }
}

fn resolve_task_shared_local_backend(
    contract: &Contract,
    task_name: &str,
    backend: Backend,
) -> Result<Option<ResolvedSharedLocalBackend>, RunError> {
    let Some(task) = contract.tasks.get(task_name) else {
        return Ok(None);
    };
    let Some(binding_name) = task.backend_binding_for_backend(backend) else {
        return Ok(None);
    };
    let Some(execution) = contract.execution.as_ref() else {
        return Err(RunError::SharedLocalBackendResolutionFailed {
            task: task_name.to_string(),
            binding: binding_name.to_string(),
            details: String::from("execution block is missing"),
        });
    };
    let Some(shared_backend) = execution.shared_backends.get(binding_name) else {
        return Err(RunError::SharedLocalBackendResolutionFailed {
            task: task_name.to_string(),
            binding: binding_name.to_string(),
            details: String::from("binding is not declared under `execution.shared_backends`"),
        });
    };
    if shared_backend.backend != backend {
        return Err(RunError::SharedLocalBackendResolutionFailed {
            task: task_name.to_string(),
            binding: binding_name.to_string(),
            details: format!(
                "binding backend `{}` does not match resolved task backend `{}`",
                match shared_backend.backend {
                    Backend::Native => "native",
                    Backend::Container => "container",
                    Backend::Remote => "remote",
                },
                match backend {
                    Backend::Native => "native",
                    Backend::Container => "container",
                    Backend::Remote => "remote",
                },
            ),
        });
    }
    let context_name = shared_backend
        .context
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| {
            selected_task_context_for_backend(contract, task_name, backend)
                .map(|(name, _)| name.to_string())
        });

    Ok(Some(ResolvedSharedLocalBackend {
        name: binding_name.to_string(),
        backend: shared_backend.backend,
        lifecycle: shared_backend.lifecycle,
        context_name,
        publications: if backend == Backend::Container {
            shared_local_backend_publications(contract, binding_name)
        } else {
            Vec::new()
        },
        fulfillment: shared_backend.fulfillment,
        environment: None,
    }))
}

fn shared_backend_publications_or_current<'a>(
    shared_local_backend: Option<&'a ResolvedSharedLocalBackend>,
    publications: &'a [ContainerPortPublication],
) -> &'a [ContainerPortPublication] {
    shared_local_backend
        .map(|shared_local_backend| shared_local_backend.publications.as_slice())
        .unwrap_or(publications)
}

fn effective_execution_publications<'a>(
    lifecycle: Lifecycle,
    shared_local_backend: Option<&'a ResolvedSharedLocalBackend>,
    publications: &'a [ContainerPortPublication],
) -> &'a [ContainerPortPublication] {
    if lifecycle == Lifecycle::Persistent {
        shared_backend_publications_or_current(shared_local_backend, publications)
    } else {
        publications
    }
}

fn shared_local_backend_publications(
    contract: &Contract,
    binding_name: &str,
) -> Vec<ContainerPortPublication> {
    let mut publications = Vec::new();
    for (task_name, task) in &contract.tasks {
        if task.backend_binding_for_backend(Backend::Container) != Some(binding_name) {
            continue;
        }
        for (_, publication) in
            task_container_publication_details(contract, task_name.as_str(), Backend::Container)
        {
            if !publications.contains(&publication) {
                publications.push(publication);
            }
        }
    }
    publications
}

pub(crate) fn resolve_shared_local_backend_environment(
    contract_path: Option<&Path>,
    task_name: &str,
    binding_name: &str,
    environment: Option<&ExecutionSharedBackendEnvironment>,
    fallback_image: &str,
) -> Result<(String, Option<BackendEnvironmentEvidence>), RunError> {
    let Some(environment) = environment else {
        return Ok((fallback_image.to_string(), None));
    };

    let declared_profile = environment
        .profile
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let declared_image_alias = environment
        .image_alias
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let declared_image = environment
        .image
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let declared_source = environment
        .source
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);

    let loaded_policy = if let Some(path) = contract_path {
        load_org_policy_pack_auto_details(path).map_err(|error| RunError::InvalidPolicyPack {
            details: error.to_string(),
        })?
    } else {
        None
    };
    let policy_label = loaded_policy
        .as_ref()
        .map(|loaded| format!("{} ({})", loaded.path.display(), loaded.source.as_str()));
    let policy_rules = loaded_policy
        .as_ref()
        .map(|loaded| &loaded.pack.policies.backend_environment);

    let mut effective_profile = None;
    let mut effective_alias = None;
    let (effective_image, effective_source) = if let Some(profile_name) =
        declared_profile.as_deref()
    {
        let Some(rules) = policy_rules else {
            return Err(RunError::SharedLocalBackendResolutionFailed {
                task: task_name.to_string(),
                binding: binding_name.to_string(),
                details: format!(
                    "declared environment profile `{profile_name}` requires an active org policy pack with `policies.backend_environment.profiles`"
                ),
            });
        };
        let Some(profile) = rules.profiles.get(profile_name) else {
            return Err(RunError::SharedLocalBackendResolutionFailed {
                task: task_name.to_string(),
                binding: binding_name.to_string(),
                details: format!(
                    "declared environment profile `{profile_name}` is not approved by policy"
                ),
            });
        };
        effective_profile = Some(profile_name.to_string());
        (
            profile.image.trim().to_string(),
            profile.source.as_deref().map(str::to_string),
        )
    } else if let Some(alias_name) = declared_image_alias.as_deref() {
        let Some(rules) = policy_rules else {
            return Err(RunError::SharedLocalBackendResolutionFailed {
                task: task_name.to_string(),
                binding: binding_name.to_string(),
                details: format!(
                    "declared image alias `{alias_name}` requires an active org policy pack with `policies.backend_environment.image_aliases`"
                ),
            });
        };
        let Some(alias) = rules.image_aliases.get(alias_name) else {
            return Err(RunError::SharedLocalBackendResolutionFailed {
                task: task_name.to_string(),
                binding: binding_name.to_string(),
                details: format!("declared image alias `{alias_name}` is not approved by policy"),
            });
        };
        effective_alias = Some(alias_name.to_string());
        (
            alias.image.trim().to_string(),
            alias.source.as_deref().map(str::to_string),
        )
    } else if let Some(image) = declared_image.as_deref() {
        (
            image.to_string(),
            declared_source
                .clone()
                .or_else(|| Some(String::from("repo_literal"))),
        )
    } else if let Some(rules) = policy_rules
        && let Some(default_profile) = rules
            .default_profile
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        && let Some(profile) = rules.profiles.get(default_profile)
    {
        effective_profile = Some(default_profile.to_string());
        (
            profile.image.trim().to_string(),
            profile.source.as_deref().map(str::to_string),
        )
    } else {
        (fallback_image.to_string(), None)
    };

    let effective_registry = container_image_registry(effective_image.as_str());
    if let Some(rules) = policy_rules {
        if (!rules.allowed_sources.is_empty() || !rules.denied_sources.is_empty())
            && effective_source.is_none()
        {
            return Err(RunError::SharedLocalBackendResolutionFailed {
                task: task_name.to_string(),
                binding: binding_name.to_string(),
                details: String::from(
                    "effective backend environment source is required by policy, but the resolved environment does not declare one",
                ),
            });
        }

        if let Some(source) = effective_source.as_deref() {
            if !rules.allowed_sources.is_empty()
                && !rules
                    .allowed_sources
                    .iter()
                    .any(|allowed| allowed.trim() == source)
            {
                return Err(RunError::SharedLocalBackendResolutionFailed {
                    task: task_name.to_string(),
                    binding: binding_name.to_string(),
                    details: format!(
                        "effective backend environment source `{source}` is not allowed by policy; expected one of: {}",
                        rules.allowed_sources.join(", ")
                    ),
                });
            }
            if rules
                .denied_sources
                .iter()
                .any(|denied| denied.trim() == source)
            {
                return Err(RunError::SharedLocalBackendResolutionFailed {
                    task: task_name.to_string(),
                    binding: binding_name.to_string(),
                    details: format!(
                        "effective backend environment source `{source}` is denied by policy"
                    ),
                });
            }
        }

        if let Some(registry) = effective_registry.as_deref() {
            if !rules.allowed_registries.is_empty()
                && !rules
                    .allowed_registries
                    .iter()
                    .any(|allowed| allowed.trim() == registry)
            {
                return Err(RunError::SharedLocalBackendResolutionFailed {
                    task: task_name.to_string(),
                    binding: binding_name.to_string(),
                    details: format!(
                        "effective backend environment registry `{registry}` is not allowed by policy; expected one of: {}",
                        rules.allowed_registries.join(", ")
                    ),
                });
            }
            if rules
                .denied_registries
                .iter()
                .any(|denied| denied.trim() == registry)
            {
                return Err(RunError::SharedLocalBackendResolutionFailed {
                    task: task_name.to_string(),
                    binding: binding_name.to_string(),
                    details: format!(
                        "effective backend environment registry `{registry}` is denied by policy"
                    ),
                });
            }
        }
    }

    let evidence = BackendEnvironmentEvidence {
        declared_profile,
        declared_image_alias,
        declared_image,
        declared_source,
        effective_profile,
        effective_image_alias: effective_alias,
        effective_image: effective_image.clone(),
        effective_source,
        effective_registry,
        policy: policy_label,
    };

    Ok((effective_image, Some(evidence)))
}

pub(crate) fn resolve_effective_task_container_backend(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
    contract_path: Option<&Path>,
) -> Result<(ContainerBackend, String, Option<ResolvedSharedLocalBackend>), RunError> {
    let effective = effective_task_execution(contract, task_name, overrides);
    let mut shared_local_backend =
        resolve_task_shared_local_backend(contract, task_name, Backend::Container)?;
    let local_backend_context_name = shared_local_backend
        .as_ref()
        .and_then(|shared| shared.context_name.clone());
    let resolved_context = local_backend_context_name
        .as_deref()
        .and_then(|name| {
            contract
                .execution
                .as_ref()
                .and_then(|execution| execution.contexts.get(name))
        })
        .filter(|context| context.backend == Backend::Container);
    let container = resolved_context
        .and_then(|context| context.container.as_ref())
        .or(effective.container)
        .cloned()
        .ok_or_else(|| RunError::MissingContainerImage {
            task: task_name.to_string(),
        })?;
    let (image, shared_environment) = if let Some(shared) = shared_local_backend.as_ref() {
        let shared_backend_environment = contract
            .execution
            .as_ref()
            .and_then(|execution| execution.shared_backends.get(shared.name.as_str()))
            .and_then(|shared_backend| shared_backend.environment.as_ref());
        resolve_shared_local_backend_environment(
            contract_path,
            task_name,
            shared.name.as_str(),
            shared_backend_environment,
            container.image.as_str(),
        )?
    } else {
        (container.image.clone(), None)
    };
    if let Some(shared) = shared_local_backend.as_mut() {
        shared.environment = shared_environment;
    }

    Ok((container, image, shared_local_backend))
}

fn container_image_registry(image: &str) -> Option<String> {
    let trimmed = image.trim();
    if trimmed.is_empty() {
        return None;
    }

    let prefix = trimmed.split('/').next().unwrap_or(trimmed);
    if prefix.contains('.') || prefix.contains(':') || prefix.eq_ignore_ascii_case("localhost") {
        Some(prefix.to_string())
    } else {
        Some(String::from("docker.io"))
    }
}

pub(crate) fn resolve_execution_backend(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> Result<ResolvedExecutionBackend, RunError> {
    resolve_execution_backend_with_contract_path(contract, task_name, overrides, None)
}

pub(crate) fn resolve_execution_backend_with_contract_path(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
    contract_path: Option<&Path>,
) -> Result<ResolvedExecutionBackend, RunError> {
    let effective = effective_task_execution(contract, task_name, overrides);
    if let Some(context_name) = effective.context_name
        && let Some((_, context)) = named_execution_context(contract, context_name)
        && !context.active_for_host(current_os(), current_arch())
    {
        return Err(RunError::UnsupportedHostPlatform {
            task: task_name.to_string(),
            context: context_name.to_string(),
            os: current_os().to_string(),
            arch: current_arch().to_string(),
            supported: context
                .only_on
                .as_ref()
                .map(|platforms| platforms.join(", "))
                .unwrap_or_else(|| String::from("all hosts")),
            supported_arch: context
                .only_arch
                .as_ref()
                .map(|architectures| architectures.join(", "))
                .unwrap_or_else(|| String::from("all architectures")),
        });
    }
    let preferred = effective.backend;
    let lifecycle = effective.lifecycle;

    if let Some(override_backend) = overrides.backend
        && let Some(task) = contract.tasks.get(task_name)
        && task
            .execution
            .as_ref()
            .is_some_and(|execution| execution.modes.any())
        && task.mode_default_backend() != Some(override_backend)
        && task.mode_execution_branch(override_backend).is_none()
    {
        let supported_modes = task
            .execution
            .as_ref()
            .map(|execution| execution.modes.iter())
            .into_iter()
            .flatten()
            .map(|(backend, _)| match backend {
                Backend::Native => "native",
                Backend::Container => "container",
                Backend::Remote => "remote",
            })
            .collect::<Vec<_>>();
        let rendered_modes = if supported_modes.is_empty() {
            String::from("none")
        } else {
            supported_modes.join(", ")
        };
        return Err(RunError::UnsupportedTaskModeOverride {
            task: task_name.to_string(),
            requested_mode: match override_backend {
                Backend::Native => String::from("native"),
                Backend::Container => String::from("container"),
                Backend::Remote => String::from("remote"),
            },
            supported_modes: rendered_modes,
        });
    }

    match preferred {
        Backend::Native => {
            if overrides.memory.is_some() {
                return Err(RunError::MemoryOverrideUnsupportedBackend {
                    task: task_name.to_string(),
                    backend: "native",
                });
            }
            let shared_local_backend =
                resolve_task_shared_local_backend(contract, task_name, Backend::Native)?;
            if let Some(shared_local_backend) = shared_local_backend.as_ref() {
                if let Some(requested) = overrides.lifecycle
                    && requested != shared_local_backend.lifecycle
                {
                    return Err(RunError::SharedLocalBackendResolutionFailed {
                        task: task_name.to_string(),
                        binding: shared_local_backend.name.clone(),
                        details: format!(
                            "requested lifecycle `{}` conflicts with declared shared backend lifecycle `{}`",
                            format_lifecycle(requested),
                            format_lifecycle(shared_local_backend.lifecycle),
                        ),
                    });
                }
            }
            Ok(ResolvedExecutionBackend::Native {
                shared_local_backend,
            })
        }
        Backend::Container => {
            let (container, image, shared_local_backend) =
                resolve_effective_task_container_backend(
                    contract,
                    task_name,
                    overrides,
                    contract_path,
                )?;
            let local_backend_context_name = shared_local_backend
                .as_ref()
                .and_then(|shared| shared.context_name.clone());

            let engine =
                selected_container_engine_from_backend(Some(&container)).ok_or_else(|| {
                    RunError::MissingContainerBackendCli {
                        task: task_name.to_string(),
                        engines: container_engine_candidates_from_backend(Some(&container))
                            .join(", "),
                    }
                })?;

            let lifecycle = if let Some(shared) = shared_local_backend.as_ref() {
                if let Some(requested) = overrides.lifecycle
                    && requested != shared.lifecycle
                {
                    return Err(RunError::SharedLocalBackendResolutionFailed {
                        task: task_name.to_string(),
                        binding: shared.name.clone(),
                        details: format!(
                            "requested lifecycle `{}` conflicts with declared shared backend lifecycle `{}`",
                            format_lifecycle(requested),
                            format_lifecycle(shared.lifecycle),
                        ),
                    });
                }
                shared.lifecycle
            } else {
                lifecycle.ok_or_else(|| RunError::MissingContainerLifecycle {
                    task: task_name.to_string(),
                })?
            };

            let context_name =
                local_backend_context_name.or_else(|| effective.context_name.map(str::to_string));
            let memory_field_prefix = if let Some(context_name) = context_name.as_deref() {
                contract
                    .execution
                    .as_ref()
                    .and_then(|execution| execution.contexts.get(context_name))
                    .and_then(|context| {
                        context
                            .container
                            .as_ref()
                            .map(|_| format!("execution.contexts.{context_name}.container"))
                    })
                    .unwrap_or_else(|| String::from("execution.backends.container"))
            } else {
                String::from("execution.backends.container")
            };
            let memory_bytes = container_memory_override_or_default(
                task_name,
                &container,
                memory_field_prefix.as_str(),
                overrides.memory,
            )?;
            let publications = task_container_publication_details(contract, task_name, preferred)
                .into_iter()
                .map(|(_, publication)| publication)
                .collect::<Vec<_>>();
            let dependency_isolation_paths = context_name
                .as_deref()
                .and_then(|name| {
                    contract
                        .execution
                        .as_ref()
                        .and_then(|execution| execution.contexts.get(name))
                })
                .map(context_dependency_isolation_paths)
                .unwrap_or_default();
            let compose_networks = context_name
                .as_deref()
                .and_then(|name| {
                    contract
                        .execution
                        .as_ref()
                        .and_then(|execution| execution.contexts.get(name))
                })
                .map(compose_networks_for_context)
                .unwrap_or_default();

            Ok(ResolvedExecutionBackend::Container {
                context_name,
                shared_local_backend,
                image,
                engine,
                lifecycle,
                memory_bytes,
                compose_networks,
                publications,
                dependency_isolation_paths,
            })
        }
        Backend::Remote => {
            if overrides.memory.is_some() {
                return Err(RunError::MemoryOverrideUnsupportedBackend {
                    task: task_name.to_string(),
                    backend: "remote",
                });
            }
            let shared_local_backend =
                resolve_task_shared_local_backend(contract, task_name, Backend::Remote)?;
            if let Some(shared_local_backend) = shared_local_backend.as_ref() {
                if let Some(requested) = overrides.lifecycle
                    && requested != shared_local_backend.lifecycle
                {
                    return Err(RunError::SharedLocalBackendResolutionFailed {
                        task: task_name.to_string(),
                        binding: shared_local_backend.name.clone(),
                        details: format!(
                            "requested lifecycle `{}` conflicts with declared shared backend lifecycle `{}`",
                            format_lifecycle(requested),
                            format_lifecycle(shared_local_backend.lifecycle),
                        ),
                    });
                }
            }
            effective
                .remote
                .ok_or_else(|| RunError::MissingRemoteProvider {
                    task: task_name.to_string(),
                })
                .and_then(|remote| {
                    if remote.provider.trim().is_empty() {
                        return Err(RunError::MissingRemoteProvider {
                            task: task_name.to_string(),
                        });
                    }
                    let target = remote
                        .target
                        .clone()
                        .filter(|target| !target.trim().is_empty())
                        .ok_or_else(|| RunError::MissingRemoteTarget {
                            task: task_name.to_string(),
                            provider: remote.provider.clone(),
                            example_target: remote_target_example(&remote.provider).to_string(),
                        })?;

                    if is_builtin_remote_provider(&remote.provider) {
                        Ok(ResolvedExecutionBackend::Remote {
                            shared_local_backend,
                            provider: remote.provider.clone(),
                            target,
                            cwd: remote.cwd.clone(),
                            ssh: remote.ssh.clone(),
                        })
                    } else {
                        let Some(extension) =
                            backend_provider_extension(contract, &remote.provider)
                        else {
                            return Err(RunError::MissingBackendProvider {
                                task: task_name.to_string(),
                                provider: remote.provider.clone(),
                            });
                        };

                        if extension.api_version != 1 {
                            return Err(RunError::UnsupportedBackendProviderVersion {
                                task: task_name.to_string(),
                                provider: remote.provider.clone(),
                                api_version: extension.api_version,
                            });
                        }

                        Ok(ResolvedExecutionBackend::BackendProvider {
                            shared_local_backend,
                            provider: remote.provider.clone(),
                            command: extension.command.clone(),
                            target,
                            cwd: remote.cwd.clone(),
                        })
                    }
                })
        }
    }
}

pub(crate) fn resolve_context_execution_backend(
    contract: &Contract,
    context_name: &str,
) -> Result<ResolvedExecutionBackend, RunError> {
    let Some((_, context)) = named_execution_context(contract, context_name) else {
        return Err(RunError::UnknownTask {
            task: format!("context:{context_name}"),
        });
    };

    match context.backend {
        Backend::Native => Ok(ResolvedExecutionBackend::Native {
            shared_local_backend: None,
        }),
        Backend::Container => {
            let Some(container) = context.container.as_ref() else {
                return Err(RunError::MissingContainerImage {
                    task: format!("context:{context_name}"),
                });
            };

            let engine =
                selected_container_engine_from_backend(Some(container)).ok_or_else(|| {
                    RunError::MissingContainerBackendCli {
                        task: format!("context:{context_name}"),
                        engines: container_engine_candidates_from_backend(Some(container))
                            .join(", "),
                    }
                })?;

            let lifecycle =
                context
                    .lifecycle
                    .ok_or_else(|| RunError::MissingContainerLifecycle {
                        task: format!("context:{context_name}"),
                    })?;
            let context_task_name = format!("context:{context_name}");
            let memory_field_prefix = format!("execution.contexts.{context_name}.container");
            let memory_bytes = container_memory_override_or_default(
                context_task_name.as_str(),
                container,
                memory_field_prefix.as_str(),
                None,
            )?;

            Ok(ResolvedExecutionBackend::Container {
                context_name: Some(context_name.to_string()),
                shared_local_backend: None,
                image: container.image.clone(),
                engine,
                lifecycle,
                memory_bytes,
                compose_networks: compose_networks_for_context(context),
                publications: Vec::new(),
                dependency_isolation_paths: context_dependency_isolation_paths(context),
            })
        }
        Backend::Remote => {
            let Some(remote) = context.remote.as_ref() else {
                return Err(RunError::MissingRemoteProvider {
                    task: format!("context:{context_name}"),
                });
            };

            if remote.provider.trim().is_empty() {
                return Err(RunError::MissingRemoteProvider {
                    task: format!("context:{context_name}"),
                });
            }
            let target = remote
                .target
                .clone()
                .filter(|target| !target.trim().is_empty())
                .ok_or_else(|| RunError::MissingRemoteTarget {
                    task: format!("context:{context_name}"),
                    provider: remote.provider.clone(),
                    example_target: remote_target_example(&remote.provider).to_string(),
                })?;

            if is_builtin_remote_provider(&remote.provider) {
                Ok(ResolvedExecutionBackend::Remote {
                    shared_local_backend: None,
                    provider: remote.provider.clone(),
                    target,
                    cwd: remote.cwd.clone(),
                    ssh: remote.ssh.clone(),
                })
            } else {
                let Some(extension) = backend_provider_extension(contract, &remote.provider) else {
                    return Err(RunError::MissingBackendProvider {
                        task: format!("context:{context_name}"),
                        provider: remote.provider.clone(),
                    });
                };

                if extension.api_version != 1 {
                    return Err(RunError::UnsupportedBackendProviderVersion {
                        task: format!("context:{context_name}"),
                        provider: remote.provider.clone(),
                        api_version: extension.api_version,
                    });
                }

                Ok(ResolvedExecutionBackend::BackendProvider {
                    shared_local_backend: None,
                    provider: remote.provider.clone(),
                    command: extension.command.clone(),
                    target,
                    cwd: remote.cwd.clone(),
                })
            }
        }
    }
}

fn backend_provider_extension<'a>(
    contract: &'a Contract,
    provider: &str,
) -> Option<&'a crate::schema::ExtensionSpec> {
    contract.extensions.get(provider).filter(|extension| {
        extension.kind == ExtensionKind::BackendProvider && !extension.command.trim().is_empty()
    })
}

fn is_builtin_remote_provider(provider: &str) -> bool {
    matches!(provider, "daytona" | "ssh" | "tsh" | "kubectl")
}

fn remote_target_example(provider: &str) -> &'static str {
    match provider {
        "daytona" => "sandbox-dev",
        "ssh" | "tsh" => "user@host",
        "kubectl" => "pod/ota-dev",
        _ => "remote-target",
    }
}

fn remote_readiness_probe_target(
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
) -> Option<RemoteReadinessProbeTarget> {
    match backend {
        ResolvedExecutionBackend::Remote {
            provider,
            target,
            cwd,
            ssh,
            ..
        } => Some(RemoteReadinessProbeTarget {
            provider: provider.clone(),
            target: target.clone(),
            cwd: cwd
                .clone()
                .or_else(|| Some(working_dir.display().to_string())),
            ssh: ssh.clone(),
            provider_command: None,
            working_dir: working_dir.display().to_string(),
        }),
        ResolvedExecutionBackend::BackendProvider {
            provider,
            command,
            target,
            cwd,
            ..
        } => Some(RemoteReadinessProbeTarget {
            provider: provider.clone(),
            target: target.clone(),
            cwd: cwd.clone(),
            ssh: None,
            provider_command: Some(command.clone()),
            working_dir: working_dir.display().to_string(),
        }),
        _ => None,
    }
}

fn execute_remote_task_command(
    task_name: &str,
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    command: &str,
    env_overrides: &BTreeMap<String, String>,
    provider: &str,
    target: &str,
    cwd: Option<&str>,
    ssh: Option<&crate::schema::RemoteSshOptions>,
    mode: TaskExecutionMode,
) -> Result<TaskCommandOutput, RunError> {
    let command = if matches!(mode, TaskExecutionMode::CaptureActivation)
        && runtime.is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service)
    {
        if let Some(runtime) = runtime
            && let Some(ready_port) = remote_activation_readiness_port(runtime)
        {
            remote_activation_service_command_with_path_export(task_name, command, None, ready_port)
        } else {
            persistent_service_command_with_path_export(task_name, command, None)
        }
    } else {
        command.to_string()
    };
    let mut remote_command = match provider {
        "daytona" => daytona_remote_command(target, cwd, command.as_str(), env_overrides),
        "ssh" => ssh_remote_command(target, cwd, ssh, command.as_str(), env_overrides),
        "tsh" => tsh_remote_command(target, cwd, command.as_str(), env_overrides),
        "kubectl" => kubectl_remote_command(target, cwd, command.as_str(), env_overrides),
        other => {
            return Err(RunError::UnsupportedRemoteProvider {
                task: task_name.to_string(),
                provider: other.to_string(),
            });
        }
    };

    match mode {
        TaskExecutionMode::Stream {
            emit_progress,
            capture_output,
            live_log,
        } => {
            if emit_progress {
                if capture_output {
                    let interrupt_epoch = current_run_interrupt_epoch();
                    let output = run_streaming_command_with_capture_with_loader_options(
                        &mut remote_command,
                        &running_loader_label_for_backend(task_name, Backend::Remote),
                        true,
                        true,
                        live_log.as_ref(),
                    )
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                    let interrupted = interruption_observed_since(interrupt_epoch);
                    Ok(TaskCommandOutput {
                        exit_code: output.exit_code,
                        stdout: output.stdout,
                        stderr: output.stderr,
                        target: Some(target.to_string()),
                        runtime: None,
                        service_termination: None,
                        execution_note: interruption_execution_note(interrupted, output.exit_code),
                        interrupted,
                    })
                } else {
                    let interrupt_epoch = current_run_interrupt_epoch();
                    let exit_code = run_streaming_command_with_loader(
                        &mut remote_command,
                        &running_loader_label_for_backend(task_name, Backend::Remote),
                    )
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                    let interrupted = interruption_observed_since(interrupt_epoch);
                    Ok(TaskCommandOutput {
                        exit_code,
                        stdout: String::new(),
                        stderr: String::new(),
                        target: Some(target.to_string()),
                        runtime: None,
                        service_termination: None,
                        execution_note: interruption_execution_note(interrupted, exit_code),
                        interrupted,
                    })
                }
            } else if capture_output {
                let interrupt_epoch = current_run_interrupt_epoch();
                let mut child = remote_command
                    .stdin(Stdio::inherit())
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .spawn()
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                let stdout_log = live_log.as_ref().map(|tee| tee.stdout.clone());
                let stdout_handle = child.stdout.take().map(|stdout| {
                    thread::spawn(move || {
                        stream_reader_to_sink(stdout, io::stdout(), None, true, stdout_log)
                    })
                });
                let stderr_log = live_log.as_ref().map(|tee| tee.stderr.clone());
                let stderr_handle = child.stderr.take().map(|stderr| {
                    thread::spawn(move || {
                        stream_reader_to_sink(stderr, io::stderr(), None, true, stderr_log)
                    })
                });
                let status = child.wait().map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
                let exit_code = status.code().unwrap_or(1);
                let interrupted = interruption_observed_since(interrupt_epoch);
                let stdout =
                    join_stream_reader(stdout_handle).map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                let stderr =
                    join_stream_reader(stderr_handle).map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                Ok(TaskCommandOutput {
                    exit_code,
                    stdout,
                    stderr,
                    target: Some(target.to_string()),
                    runtime: None,
                    service_termination: None,
                    execution_note: interruption_execution_note(interrupted, exit_code),
                    interrupted,
                })
            } else {
                let interrupt_epoch = current_run_interrupt_epoch();
                let exit_code = remote_command
                    .stdin(Stdio::inherit())
                    .stdout(Stdio::inherit())
                    .stderr(Stdio::inherit())
                    .status()
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?
                    .code()
                    .unwrap_or(1);
                let interrupted = interruption_observed_since(interrupt_epoch);

                Ok(TaskCommandOutput {
                    exit_code,
                    stdout: String::new(),
                    stderr: String::new(),
                    target: Some(target.to_string()),
                    runtime: None,
                    service_termination: None,
                    execution_note: interruption_execution_note(interrupted, exit_code),
                    interrupted,
                })
            }
        }
        TaskExecutionMode::Capture | TaskExecutionMode::CaptureActivation => {
            let interrupt_epoch = current_run_interrupt_epoch();
            let output = remote_command
                .stdin(Stdio::inherit())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .and_then(|child| child.wait_with_output())
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let exit_code = output.status.code().unwrap_or(1);
            let interrupted = interruption_observed_since(interrupt_epoch);
            Ok(TaskCommandOutput {
                exit_code,
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
                target: Some(target.to_string()),
                runtime: None,
                service_termination: None,
                execution_note: interruption_execution_note(interrupted, exit_code),
                interrupted,
            })
        }
    }
}

fn execute_backend_provider_task_command(
    task_name: &str,
    task_command: &str,
    working_dir: &Path,
    env_overrides: &BTreeMap<String, String>,
    provider: &str,
    provider_command: &str,
    target: &str,
    cwd: Option<&str>,
    command_context: BackendProviderCommandContext,
    mode: TaskExecutionMode,
) -> Result<TaskCommandOutput, RunError> {
    let mut provider_env = env_overrides.clone();
    provider_env.insert(
        String::from("OTA_BACKEND_PROVIDER_NAME"),
        provider.to_string(),
    );
    provider_env.insert(
        String::from("OTA_BACKEND_PROVIDER_KIND"),
        String::from("backend_provider"),
    );
    provider_env.insert(
        String::from("OTA_BACKEND_PROVIDER_API_VERSION"),
        String::from("1"),
    );
    provider_env.insert(
        String::from("OTA_BACKEND_PROVIDER_TARGET"),
        target.to_string(),
    );
    provider_env.insert(
        String::from("OTA_BACKEND_PROVIDER_COMMAND"),
        task_command.to_string(),
    );
    provider_env.insert(
        String::from("OTA_BACKEND_PROVIDER_COMMAND_CONTEXT"),
        command_context.as_str().to_string(),
    );
    provider_env.insert(
        String::from("OTA_BACKEND_PROVIDER_WORKDIR"),
        working_dir.display().to_string(),
    );
    if let Some(cwd) = cwd {
        provider_env.insert(String::from("OTA_BACKEND_PROVIDER_CWD"), cwd.to_string());
    }

    let request = backend_provider_request(
        provider,
        task_name,
        task_command,
        working_dir,
        target,
        cwd,
        command_context,
        mode.clone(),
        &provider_env,
    );
    let request_json = serde_json::to_string(&request).map_err(|source| {
        RunError::BackendProviderRequestSerialization {
            task: task_name.to_string(),
            provider: provider.to_string(),
            source,
        }
    })?;
    provider_env.insert(
        String::from("OTA_BACKEND_PROVIDER_REQUEST_JSON"),
        request_json.clone(),
    );

    let mut provider_command = shell_command(provider_command);

    match mode {
        TaskExecutionMode::Stream {
            emit_progress,
            live_log,
            ..
        } => {
            if emit_progress {
                eprintln!("RUN {task_name}");
            }
            provider_env.insert(
                String::from("OTA_BACKEND_PROVIDER_MODE"),
                String::from("stream"),
            );

            let mut child = provider_command
                .current_dir(working_dir)
                .envs(provider_env.iter())
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;

            if let Some(mut stdin) = child.stdin.take() {
                stdin
                    .write_all(request_json.as_bytes())
                    .and_then(|_| stdin.flush())
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
            }

            let loader = emit_progress
                .then(|| {
                    StreamPhaseLoader::start_with_policy(
                        &running_loader_label_for_backend(task_name, Backend::Remote),
                        StreamPhaseLoaderPolicy::Delayed,
                    )
                })
                .flatten();
            let notifier = loader.as_ref().map(|loader| loader.notifier());
            let stdout_notifier = notifier.clone();
            let stdout_log = live_log.as_ref().map(|tee| tee.stdout.clone());
            let stdout_handle = child.stdout.take().map(|stdout| {
                thread::spawn(move || {
                    stream_reader_to_sink(stdout, io::sink(), stdout_notifier, true, stdout_log)
                })
            });
            let stderr_notifier = notifier;
            let stderr_log = live_log.as_ref().map(|tee| tee.stderr.clone());
            let stderr_handle = child.stderr.take().map(|stderr| {
                thread::spawn(move || {
                    stream_reader_to_sink(stderr, io::stderr(), stderr_notifier, false, stderr_log)
                })
            });

            let status = child.wait().map_err(|source| RunError::SpawnFailed {
                task: task_name.to_string(),
                source,
            })?;

            let stdout =
                join_stream_reader(stdout_handle).map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let _ = join_stream_reader(stderr_handle).map_err(|source| RunError::SpawnFailed {
                task: task_name.to_string(),
                source,
            })?;
            if let Some(loader) = loader {
                loader.stop();
            }
            if !status.success() {
                return Err(RunError::BackendProviderExitedNonZero {
                    task: task_name.to_string(),
                    provider: provider.to_string(),
                    exit_code: status.code().unwrap_or(1),
                });
            }

            let response = parse_backend_provider_response(task_name, provider, &stdout)?;
            backend_provider_output(task_name, provider, target, response)
        }
        TaskExecutionMode::Capture | TaskExecutionMode::CaptureActivation => {
            provider_env.insert(
                String::from("OTA_BACKEND_PROVIDER_MODE"),
                String::from("capture"),
            );
            let mut child = provider_command
                .current_dir(working_dir)
                .envs(provider_env.iter())
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;

            if let Some(mut stdin) = child.stdin.take() {
                stdin
                    .write_all(request_json.as_bytes())
                    .and_then(|_| stdin.flush())
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
            }

            let output = child
                .wait_with_output()
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;

            if !output.status.success() {
                return Err(RunError::BackendProviderExitedNonZero {
                    task: task_name.to_string(),
                    provider: provider.to_string(),
                    exit_code: output.status.code().unwrap_or(1),
                });
            }

            let response = parse_backend_provider_response(
                task_name,
                provider,
                &String::from_utf8_lossy(&output.stdout),
            )?;
            backend_provider_output(task_name, provider, target, response)
        }
    }
}

#[derive(Debug, Serialize)]
struct BackendProviderRequest<'a> {
    extension_id: &'a str,
    extension_kind: &'static str,
    api_version: u32,
    command_context: &'static str,
    repo_context_path: String,
    working_dir: String,
    task: BackendProviderTaskRequest<'a>,
}

#[derive(Debug, Serialize)]
struct BackendProviderTaskRequest<'a> {
    name: &'a str,
    command: &'a str,
    mode: &'static str,
    target: &'a str,
    cwd: Option<&'a str>,
    environment: &'a BTreeMap<String, String>,
}

#[derive(Debug, Deserialize)]
struct BackendProviderResponse {
    ok: bool,
    #[serde(default)]
    result: Option<BackendProviderResult>,
    #[serde(default)]
    errors: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct BackendProviderResult {
    #[serde(default)]
    exit_code: i32,
    #[serde(default)]
    stdout: String,
    #[serde(default)]
    stderr: String,
    #[serde(default)]
    target: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BackendProviderCommandContext {
    Run,
    Activation,
    ActivationProbe,
    ActivationCleanup,
}

impl BackendProviderCommandContext {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Run => "run",
            Self::Activation => "activation",
            Self::ActivationProbe => "activation_probe",
            Self::ActivationCleanup => "activation_cleanup",
        }
    }
}

fn backend_provider_request<'a>(
    provider: &'a str,
    task_name: &'a str,
    task_command: &'a str,
    working_dir: &Path,
    target: &'a str,
    cwd: Option<&'a str>,
    command_context: BackendProviderCommandContext,
    mode: TaskExecutionMode,
    environment: &'a BTreeMap<String, String>,
) -> BackendProviderRequest<'a> {
    BackendProviderRequest {
        extension_id: provider,
        extension_kind: "backend_provider",
        api_version: 1,
        command_context: command_context.as_str(),
        repo_context_path: working_dir.display().to_string(),
        working_dir: working_dir.display().to_string(),
        task: BackendProviderTaskRequest {
            name: task_name,
            command: task_command,
            mode: match mode {
                TaskExecutionMode::Stream { .. } => "stream",
                TaskExecutionMode::Capture | TaskExecutionMode::CaptureActivation => "capture",
            },
            target,
            cwd,
            environment,
        },
    }
}

fn parse_backend_provider_response(
    task_name: &str,
    provider: &str,
    stdout: &str,
) -> Result<BackendProviderResponse, RunError> {
    serde_json::from_str(stdout).map_err(|source| RunError::BackendProviderResponseParse {
        task: task_name.to_string(),
        provider: provider.to_string(),
        source,
    })
}

fn backend_provider_output(
    task_name: &str,
    provider: &str,
    fallback_target: &str,
    response: BackendProviderResponse,
) -> Result<TaskCommandOutput, RunError> {
    if !response.ok {
        return Err(RunError::BackendProviderFailed {
            task: task_name.to_string(),
            provider: provider.to_string(),
            errors: if response.errors.is_empty() {
                String::from("backend provider returned `ok: false`")
            } else {
                response.errors.join(" | ")
            },
        });
    }

    let result = response
        .result
        .ok_or_else(|| RunError::BackendProviderMissingResult {
            task: task_name.to_string(),
            provider: provider.to_string(),
        })?;

    Ok(TaskCommandOutput {
        exit_code: result.exit_code,
        stdout: result.stdout,
        stderr: result.stderr,
        target: Some(result.target.unwrap_or_else(|| fallback_target.to_string())),
        runtime: None,
        service_termination: None,
        execution_note: None,
        interrupted: false,
    })
}

fn daytona_remote_command(
    target: &str,
    cwd: Option<&str>,
    command: &str,
    env_overrides: &BTreeMap<String, String>,
) -> Command {
    let mut remote = Command::new("daytona");
    remote.arg("exec").arg(target);
    if let Some(cwd) = cwd {
        remote.arg("--cwd").arg(cwd);
    }
    remote
        .arg("--")
        .arg("sh")
        .arg("-lc")
        .arg(shell_script_with_env(command, env_overrides));
    remote
}

fn ssh_remote_command(
    target: &str,
    cwd: Option<&str>,
    ssh: Option<&crate::schema::RemoteSshOptions>,
    command: &str,
    env_overrides: &BTreeMap<String, String>,
) -> Command {
    let script = shell_script_with_env_and_cwd(command, env_overrides, cwd);
    let mut remote = Command::new("ssh");
    if let Some(ssh) = ssh {
        if let Some(config_file) = ssh
            .config_file
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            remote.arg("-F").arg(config_file);
        }
        if let Some(identity_file) = ssh
            .identity_file
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            remote.arg("-i").arg(identity_file);
        }
    }
    remote
        .arg(target)
        .arg(format!("sh -lc {}", shell_quote(script.as_str())));
    remote
}

fn tsh_remote_command(
    target: &str,
    cwd: Option<&str>,
    command: &str,
    env_overrides: &BTreeMap<String, String>,
) -> Command {
    let mut remote = Command::new("tsh");
    remote
        .arg("ssh")
        .arg(target)
        .arg("--")
        .arg("sh")
        .arg("-lc")
        .arg(shell_script_with_env_and_cwd(command, env_overrides, cwd));
    remote
}

fn kubectl_remote_command(
    target: &str,
    cwd: Option<&str>,
    command: &str,
    env_overrides: &BTreeMap<String, String>,
) -> Command {
    let mut remote = Command::new("kubectl");
    remote
        .arg("exec")
        .arg(target)
        .arg("--")
        .arg("sh")
        .arg("-lc")
        .arg(shell_script_with_env_and_cwd(command, env_overrides, cwd));
    remote
}

fn shell_script_with_env(command: &str, env_overrides: &BTreeMap<String, String>) -> String {
    if env_overrides.is_empty() {
        return command.to_string();
    }

    let mut script = String::new();
    for (name, value) in env_overrides {
        script.push_str("export ");
        script.push_str(name);
        script.push('=');
        script.push_str(&shell_quote(value));
        script.push_str("; ");
    }
    script.push_str(command);
    script
}

fn shell_script_with_env_and_cwd(
    command: &str,
    env_overrides: &BTreeMap<String, String>,
    cwd: Option<&str>,
) -> String {
    let command = shell_script_with_env(command, env_overrides);
    match cwd {
        Some(cwd) => format!("cd {} && {}", shell_quote(cwd), command),
        None => command,
    }
}

fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\"'\"'"))
}

fn execute_native_task_command(
    contract: Option<&Contract>,
    task: Option<&crate::schema::TaskSpec>,
    task_name: &str,
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    command: &str,
    working_dir: &Path,
    env_overrides: &BTreeMap<String, String>,
    mode: TaskExecutionMode,
    backend: &ResolvedExecutionBackend,
) -> Result<TaskCommandOutput, RunError> {
    let runtime_spec = runtime;
    let mut process = shell_command(command);
    process.current_dir(working_dir).envs(env_overrides.iter());
    let activation_service_pidfile = matches!(mode, TaskExecutionMode::CaptureActivation)
        .then(|| persistent_service_workload_pidfile_path(task_name))
        .filter(|_| runtime.is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service));

    match mode {
        TaskExecutionMode::Stream {
            emit_progress,
            capture_output,
            live_log,
        } => {
            if emit_progress {
                let interrupt_epoch = current_run_interrupt_epoch();
                let loader = StreamPhaseLoader::start_with_policy(
                    &running_loader_label(task_name, backend),
                    StreamPhaseLoaderPolicy::Delayed,
                );
                let notifier = loader.as_ref().map(|loader| loader.notifier());
                let mut child = process
                    .stdin(Stdio::inherit())
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .spawn()
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;

                let stdout_notifier = notifier.clone();
                let stdout_log = live_log.as_ref().map(|tee| tee.stdout.clone());
                let stdout_handle = child.stdout.take().map(|stdout| {
                    thread::spawn(move || {
                        stream_reader_to_sink(
                            stdout,
                            io::stdout(),
                            stdout_notifier,
                            capture_output,
                            stdout_log,
                        )
                    })
                });
                let stderr_notifier = notifier;
                let stderr_log = live_log.as_ref().map(|tee| tee.stderr.clone());
                let stderr_handle = child.stderr.take().map(|stderr| {
                    thread::spawn(move || {
                        stream_reader_to_sink(
                            stderr,
                            io::stderr(),
                            stderr_notifier,
                            capture_output,
                            stderr_log,
                        )
                    })
                });

                let resolved_runtime =
                    resolve_native_task_runtime(runtime_spec, task_name, &mut child, None)?;
                let readiness_probe = start_runtime_readiness_probe(
                    None,
                    runtime_spec,
                    resolved_runtime.as_ref(),
                    false,
                    None,
                    interrupt_epoch,
                );
                let status = wait_for_child_with_runtime_readiness_budget(
                    &mut child,
                    readiness_probe.as_ref(),
                    |child| {
                        let _ = child.kill();
                        let _ = cleanup_interrupted_native_service_workload_and_note(
                            task_name,
                            runtime_spec,
                        );
                    },
                )
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
                let stdout =
                    join_stream_reader(stdout_handle).map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                let stderr =
                    join_stream_reader(stderr_handle).map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                if let Some(loader) = loader {
                    loader.stop();
                }

                let command_exit_code = status.code().unwrap_or(1);
                let interrupted = interruption_observed_since(interrupt_epoch);
                let readiness_outcome = collect_runtime_readiness_after_command_exit(
                    contract,
                    task,
                    Backend::Native,
                    readiness_probe,
                    runtime_spec,
                    resolved_runtime.as_ref(),
                    command_exit_code,
                    interrupted,
                );
                let (exit_code, execution_note) = normalize_native_service_startup_exit_code(
                    task,
                    runtime_spec,
                    resolved_runtime.as_ref(),
                    command_exit_code,
                    interrupted,
                    readiness_outcome,
                );
                Ok(TaskCommandOutput {
                    exit_code,
                    stdout,
                    stderr,
                    target: None,
                    runtime: resolved_runtime,
                    service_termination: None,
                    execution_note,
                    interrupted,
                })
            } else {
                let interrupt_epoch = current_run_interrupt_epoch();
                let mut child = if capture_output {
                    process
                        .stdin(Stdio::inherit())
                        .stdout(Stdio::piped())
                        .stderr(Stdio::piped())
                        .spawn()
                } else {
                    process
                        .stdin(Stdio::inherit())
                        .stdout(Stdio::inherit())
                        .stderr(Stdio::inherit())
                        .spawn()
                }
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
                let stdout_handle = if capture_output {
                    let stdout_log = live_log.as_ref().map(|tee| tee.stdout.clone());
                    child.stdout.take().map(|stdout| {
                        thread::spawn(move || {
                            stream_reader_to_sink(stdout, io::stdout(), None, true, stdout_log)
                        })
                    })
                } else {
                    None
                };
                let stderr_handle = if capture_output {
                    let stderr_log = live_log.as_ref().map(|tee| tee.stderr.clone());
                    child.stderr.take().map(|stderr| {
                        thread::spawn(move || {
                            stream_reader_to_sink(stderr, io::stderr(), None, true, stderr_log)
                        })
                    })
                } else {
                    None
                };
                let resolved_runtime =
                    resolve_native_task_runtime(runtime_spec, task_name, &mut child, None)?;
                let readiness_probe = start_runtime_readiness_probe(
                    None,
                    runtime_spec,
                    resolved_runtime.as_ref(),
                    false,
                    None,
                    interrupt_epoch,
                );
                let status = wait_for_child_with_runtime_readiness_budget(
                    &mut child,
                    readiness_probe.as_ref(),
                    |child| {
                        let _ = child.kill();
                        let _ = cleanup_interrupted_native_service_workload_and_note(
                            task_name,
                            runtime_spec,
                        );
                    },
                )
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
                let stdout =
                    join_stream_reader(stdout_handle).map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                let stderr =
                    join_stream_reader(stderr_handle).map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;

                let command_exit_code = status.code().unwrap_or(1);
                let interrupted = interruption_observed_since(interrupt_epoch);
                let readiness_outcome = collect_runtime_readiness_after_command_exit(
                    contract,
                    task,
                    Backend::Native,
                    readiness_probe,
                    runtime_spec,
                    resolved_runtime.as_ref(),
                    command_exit_code,
                    interrupted,
                );
                let (exit_code, execution_note) = normalize_native_service_startup_exit_code(
                    task,
                    runtime_spec,
                    resolved_runtime.as_ref(),
                    command_exit_code,
                    interrupted,
                    readiness_outcome,
                );
                Ok(TaskCommandOutput {
                    exit_code,
                    stdout,
                    stderr,
                    target: None,
                    runtime: resolved_runtime,
                    service_termination: None,
                    execution_note,
                    interrupted,
                })
            }
        }
        TaskExecutionMode::Capture | TaskExecutionMode::CaptureActivation => {
            let interrupt_epoch = current_run_interrupt_epoch();
            if matches!(mode, TaskExecutionMode::CaptureActivation)
                && runtime.is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service)
            {
                #[cfg(not(unix))]
                {
                    return Err(RunError::InvalidTaskExecution {
                        task: task_name.to_string(),
                    });
                }
                #[cfg(unix)]
                {
                    process = shell_command(&persistent_service_command_with_path_export(
                        task_name, command, None,
                    ));
                    process.current_dir(working_dir).envs(env_overrides.iter());
                }
            }
            let mut child = process
                .stdin(Stdio::inherit())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;

            let stdout_handle = child.stdout.take().map(|stdout| {
                thread::spawn(move || stream_reader_to_sink(stdout, io::sink(), None, true, None))
            });
            let stderr_handle = child.stderr.take().map(|stderr| {
                thread::spawn(move || stream_reader_to_sink(stderr, io::sink(), None, true, None))
            });

            let runtime = resolve_native_task_runtime(
                runtime,
                task_name,
                &mut child,
                activation_service_pidfile.as_deref(),
            )?;
            let status = child.wait().map_err(|source| RunError::SpawnFailed {
                task: task_name.to_string(),
                source,
            })?;
            let stdout =
                join_stream_reader(stdout_handle).map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let stderr =
                join_stream_reader(stderr_handle).map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;

            let exit_code = status.code().unwrap_or(1);
            let interrupted = interruption_observed_since(interrupt_epoch);
            Ok(TaskCommandOutput {
                exit_code,
                stdout,
                stderr,
                target: None,
                runtime,
                service_termination: None,
                execution_note: interruption_execution_note(interrupted, exit_code),
                interrupted,
            })
        }
    }
}

fn resolve_native_task_runtime(
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    task_name: &str,
    child: &mut Child,
    activation_service_pidfile: Option<&str>,
) -> Result<Option<ResolvedTaskRuntime>, RunError> {
    let Some(runtime) = runtime else {
        return Ok(None);
    };

    let pid = child.id();
    let mut listeners = BTreeMap::new();

    for (listener_name, listener) in &runtime.listeners {
        let bind_port = match listener.bind.port.mode {
            crate::schema::TaskRuntimePortMode::Fixed => listener
                .bind
                .port
                .value
                .expect("validated fixed native listener should include a bind port"),
            crate::schema::TaskRuntimePortMode::Discover => {
                let discovery_pid = if let Some(pidfile) = activation_service_pidfile {
                    wait_for_activation_service_workload_pid(
                        child,
                        pidfile,
                        task_name,
                        listener_name,
                    )?
                } else {
                    pid
                };
                discover_native_listener_port(child, discovery_pid, task_name, listener_name)?
            }
            crate::schema::TaskRuntimePortMode::Auto => {
                return Err(RunError::InvalidTaskExecution {
                    task: task_name.to_string(),
                });
            }
        };

        let resolved = listener
            .project
            .host
            .as_ref()
            .map(|host| ResolvedTaskRuntimeResolution {
                host: Some(ResolvedTaskRuntimeHost {
                    address: host.address.trim().to_string(),
                    port: bind_port,
                    url: listener.protocol.url_scheme().map(|scheme| {
                        format!(
                            "{scheme}://{}:{bind_port}{}",
                            host.address.trim(),
                            normalized_runtime_path(host.path.as_deref())
                        )
                    }),
                }),
            });

        listeners.insert(
            listener_name.clone(),
            ResolvedTaskRuntimeListener {
                protocol: listener.protocol,
                bind: ResolvedTaskRuntimeBind {
                    address: listener.bind.address.trim().to_string(),
                    port: bind_port,
                },
                resolved,
            },
        );
    }

    Ok(Some(build_resolved_runtime(runtime, listeners)))
}

fn wait_for_activation_service_workload_pid(
    child: &mut Child,
    pidfile: &str,
    task_name: &str,
    listener_name: &str,
) -> Result<u32, RunError> {
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                return Err(runtime_listener_bind_discovery_failed(
                    task_name,
                    listener_name,
                    RuntimeListenerBindDiscoveryFailure::ProcessExited {
                        exit_code: status.code().unwrap_or(1),
                    },
                ));
            }
            Ok(None) => {}
            Err(source) => {
                return Err(runtime_listener_bind_discovery_failed(
                    task_name,
                    listener_name,
                    RuntimeListenerBindDiscoveryFailure::ProcessInspectionFailed {
                        details: source.to_string(),
                    },
                ));
            }
        }

        if let Ok(contents) = fs::read_to_string(pidfile)
            && let Some(pid) = contents
                .split_whitespace()
                .next()
                .and_then(|value| value.parse::<u32>().ok())
                .filter(|pid| *pid > 0)
        {
            return Ok(pid);
        }

        if Instant::now() >= deadline {
            return Err(runtime_listener_bind_discovery_failed(
                task_name,
                listener_name,
                RuntimeListenerBindDiscoveryFailure::ProcessInspectionFailed {
                    details: format!(
                        "activation-owned native service did not record a workload pid in `{pidfile}` before readiness discovery timed out"
                    ),
                },
            ));
        }

        thread::sleep(Duration::from_millis(50));
    }
}

fn discover_native_listener_port(
    child: &mut Child,
    pid: u32,
    task_name: &str,
    listener_name: &str,
) -> Result<u16, RunError> {
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                return Err(runtime_listener_bind_discovery_failed(
                    task_name,
                    listener_name,
                    RuntimeListenerBindDiscoveryFailure::ProcessExited {
                        exit_code: status.code().unwrap_or(1),
                    },
                ));
            }
            Ok(None) => {}
            Err(source) => {
                return Err(runtime_listener_bind_discovery_failed(
                    task_name,
                    listener_name,
                    RuntimeListenerBindDiscoveryFailure::ProcessInspectionFailed {
                        details: source.to_string(),
                    },
                ));
            }
        }

        match native_listening_ports_for_pid(pid) {
            Ok(ports) if ports.len() == 1 => {
                return Ok(*ports
                    .iter()
                    .next()
                    .expect("single discovered port should exist"));
            }
            Ok(ports) if ports.len() > 1 => {
                return Err(runtime_listener_bind_discovery_failed(
                    task_name,
                    listener_name,
                    RuntimeListenerBindDiscoveryFailure::MultiplePorts {
                        pid,
                        ports: ports
                            .into_iter()
                            .map(|port| port.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    },
                ));
            }
            Ok(_) => {}
            Err(details) => {
                return Err(runtime_listener_bind_discovery_failed(
                    task_name,
                    listener_name,
                    RuntimeListenerBindDiscoveryFailure::ProcessInspectionFailed { details },
                ));
            }
        }

        if Instant::now() >= deadline {
            return Err(runtime_listener_bind_discovery_failed(
                task_name,
                listener_name,
                RuntimeListenerBindDiscoveryFailure::TimedOut,
            ));
        }

        thread::sleep(Duration::from_millis(100));
    }
}

fn native_listening_ports_for_pid(pid: u32) -> Result<BTreeSet<u16>, String> {
    #[cfg(unix)]
    {
        return native_listening_ports_for_pid_unix(pid);
    }

    #[cfg(windows)]
    {
        return native_listening_ports_for_pid_windows(pid);
    }

    #[allow(unreachable_code)]
    Err(String::from(
        "runtime port discovery is not supported on this operating system yet",
    ))
}

#[cfg(unix)]
fn native_listening_ports_for_pid_unix(pid: u32) -> Result<BTreeSet<u16>, String> {
    let mut ports = lsof_listening_ports_for_args(["-Pan", "-p", &pid.to_string()])?;

    if ports.is_empty()
        && let Some(process_group) = unix_process_group_id(pid)?
    {
        ports.extend(lsof_listening_ports_for_args([
            "-Pan",
            "-g",
            &process_group.to_string(),
        ])?);
    }

    Ok(ports)
}

#[cfg(unix)]
fn unix_process_group_id(pid: u32) -> Result<Option<u32>, String> {
    let output = Command::new("ps")
        .args(["-o", "pgid=", "-p", &pid.to_string()])
        .output()
        .map_err(|error| format!("failed to run `ps` for pid {pid}: {error}"))?;
    if !output.status.success() {
        return Ok(None);
    }

    Ok(String::from_utf8_lossy(&output.stdout)
        .trim()
        .parse::<u32>()
        .ok())
}

#[cfg(unix)]
fn lsof_listening_ports_for_args<const N: usize>(
    base_args: [&str; N],
) -> Result<BTreeSet<u16>, String> {
    let mut args = base_args.iter().copied().collect::<Vec<_>>();
    args.push("-iTCP");
    args.push("-sTCP:LISTEN");
    let output = Command::new("lsof")
        .args(&args)
        .output()
        .map_err(|error| format!("failed to run `lsof`: {error}"))?;
    if !output.status.success() {
        return Ok(BTreeSet::new());
    }

    Ok(String::from_utf8_lossy(&output.stdout)
        .lines()
        .skip(1)
        .filter_map(parse_lsof_listening_port)
        .collect())
}

#[cfg(windows)]
fn native_listening_ports_for_pid_windows(pid: u32) -> Result<BTreeSet<u16>, String> {
    let output = Command::new("netstat")
        .args(["-ano", "-p", "tcp"])
        .output()
        .map_err(|error| format!("failed to run `netstat` for pid {pid}: {error}"))?;
    if !output.status.success() {
        return Ok(BTreeSet::new());
    }

    Ok(String::from_utf8_lossy(&output.stdout)
        .lines()
        .filter_map(|line| parse_netstat_listening_port(line, pid))
        .collect())
}

#[cfg(unix)]
fn parse_lsof_listening_port(line: &str) -> Option<u16> {
    let mut tokens = line.split_whitespace().rev();
    if tokens.next()? != "(LISTEN)" {
        return None;
    }
    parse_socket_port(tokens.next()?)
}

#[cfg(windows)]
fn parse_netstat_listening_port(line: &str, pid: u32) -> Option<u16> {
    let columns = line.split_whitespace().collect::<Vec<_>>();
    if columns.len() < 5 || columns[0] != "TCP" || columns[3] != "LISTENING" {
        return None;
    }
    if columns[4].parse::<u32>().ok()? != pid {
        return None;
    }
    parse_socket_port(columns[1])
}

fn parse_socket_port(value: &str) -> Option<u16> {
    let (_, port) = value.rsplit_once(':')?;
    port.trim().parse::<u16>().ok()
}

fn execute_container_task_command(
    contract: Option<&Contract>,
    task_name: &str,
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    context_name: Option<&str>,
    shared_local_backend_name: Option<&str>,
    command: &str,
    working_dir: &Path,
    env_overrides: &BTreeMap<String, String>,
    path_export: Option<&str>,
    secret_env_names: &BTreeSet<String>,
    image: &str,
    engine: &str,
    lifecycle: Lifecycle,
    memory_bytes: Option<u64>,
    compose_networks: &[String],
    publications: &[ContainerPortPublication],
    dependency_isolation_paths: &[String],
    deferred_backend_fulfillment: Option<&DeferredContainerBackendFulfillment>,
    host_port_override: Option<u16>,
    mode: TaskExecutionMode,
) -> Result<TaskCommandOutput, RunError> {
    let repo_ownership_token = repo_ownership_token_for_working_dir(task_name, working_dir)?;
    let command = wrap_container_command_for_corepack_activation(contract, task_name, command);
    if let Some(issue) = probe_container_backend(engine, task_name)? {
        return Ok(TaskCommandOutput {
            exit_code: 1,
            stdout: String::new(),
            stderr: issue,
            target: None,
            runtime: None,
            service_termination: None,
            execution_note: None,
            interrupted: false,
        });
    }

    let runtime_listener_publications = task_runtime_listener_publications(runtime);
    match lifecycle {
        Lifecycle::Ephemeral => {
            let mut reclaimed_orphaned_ephemeral_count =
                reap_repo_owned_ephemeral_containers(task_name, engine, &repo_ownership_token)?
                    .len();
            let mut reclaimed_conflict_retry_attempts = 0usize;
            let has_auto_projection =
                runtime_listener_publications
                    .iter()
                    .any(|(_, publication)| {
                        publication.host_port_mode == TaskRuntimeHostPortMode::Auto
                    });
            let max_attempts = if has_auto_projection {
                CONTAINER_AUTO_PUBLICATION_MAX_ATTEMPTS
            } else {
                1
            };

            let mut attempt = 0usize;
            loop {
                let projection = prepare_container_runtime_projection(
                    task_name,
                    runtime,
                    publications,
                    &runtime_listener_publications,
                    true,
                    host_port_override,
                )?;
                let mut resolved_env = env_overrides.clone();
                resolved_env.extend(projection.env.clone());
                extend_missing_env(&mut resolved_env, runtime_bind_env(runtime));
                if let Some(deferred_backend_fulfillment) = deferred_backend_fulfillment {
                    return execute_fulfilled_ephemeral_container_task_command(
                        task_name,
                        runtime,
                        context_name,
                        shared_local_backend_name,
                        &repo_ownership_token,
                        &command,
                        working_dir,
                        &resolved_env,
                        path_export,
                        secret_env_names,
                        image,
                        engine,
                        memory_bytes,
                        compose_networks,
                        &projection.publications,
                        &projection.listener_publications,
                        dependency_isolation_paths,
                        deferred_backend_fulfillment,
                        mode,
                    );
                }
                if let Err(preflight_error) = preflight_container_host_publications(
                    task_name,
                    &projection.listener_publications,
                ) {
                    if let RunError::HostPublicationConflict { port, .. } = preflight_error
                        && let Some((listener_name, publication)) = projection
                            .listener_publications
                            .iter()
                            .find(|(_, publication)| publication.host_port == Some(port))
                    {
                        let mut reclaimed_from_conflict = reap_repo_owned_ephemeral_containers(
                            task_name,
                            engine,
                            &repo_ownership_token,
                        )?;
                        let mut reclaimed_legacy_conflicts =
                            reap_legacy_repo_owned_conflicting_ephemeral_containers(
                                task_name,
                                engine,
                                &repo_ownership_token,
                                publication,
                                port,
                            )?;
                        reclaimed_from_conflict.append(&mut reclaimed_legacy_conflicts);
                        if !reclaimed_from_conflict.is_empty()
                            && reclaimed_conflict_retry_attempts
                                < EPHEMERAL_CONFLICT_RECLAIM_MAX_ATTEMPTS
                        {
                            reclaimed_orphaned_ephemeral_count += reclaimed_from_conflict.len();
                            reclaimed_conflict_retry_attempts += 1;
                            attempt += 1;
                            continue;
                        }
                        return Err(RunError::HostPublicationConflict {
                            task: task_name.to_string(),
                            listener: listener_name.clone(),
                            address: publication.host_address.clone(),
                            port,
                        });
                    }
                    return Err(preflight_error);
                }

                let mut output = execute_ephemeral_container_task_command(
                    contract,
                    task_name,
                    runtime,
                    context_name,
                    shared_local_backend_name,
                    &repo_ownership_token,
                    &command,
                    working_dir,
                    &resolved_env,
                    path_export,
                    secret_env_names,
                    image,
                    engine,
                    memory_bytes,
                    compose_networks,
                    &projection.publications,
                    &projection.listener_publications,
                    dependency_isolation_paths,
                    mode.clone(),
                )?;

                if output.exit_code == 0 {
                    output.execution_note = merge_execution_note(
                        output.execution_note,
                        reclaimed_orphaned_ephemeral_containers_note(
                            reclaimed_orphaned_ephemeral_count,
                        ),
                    );
                    return Ok(output);
                }

                if let Some(port) = parse_container_host_port_conflict(&output.stderr)
                    && let Some((listener_name, publication)) = projection
                        .listener_publications
                        .iter()
                        .find(|(_, publication)| publication.host_port == Some(port))
                {
                    let mut reclaimed_from_conflict = reap_repo_owned_ephemeral_containers(
                        task_name,
                        engine,
                        &repo_ownership_token,
                    )?;
                    let mut reclaimed_legacy_conflicts =
                        reap_legacy_repo_owned_conflicting_ephemeral_containers(
                            task_name,
                            engine,
                            &repo_ownership_token,
                            publication,
                            port,
                        )?;
                    reclaimed_from_conflict.append(&mut reclaimed_legacy_conflicts);
                    if !reclaimed_from_conflict.is_empty()
                        && reclaimed_conflict_retry_attempts
                            < EPHEMERAL_CONFLICT_RECLAIM_MAX_ATTEMPTS
                    {
                        reclaimed_orphaned_ephemeral_count += reclaimed_from_conflict.len();
                        reclaimed_conflict_retry_attempts += 1;
                        attempt += 1;
                        continue;
                    }
                    return Err(RunError::HostPublicationConflict {
                        task: task_name.to_string(),
                        listener: listener_name.clone(),
                        address: publication.host_address.clone(),
                        port,
                    });
                }

                if !has_auto_projection || attempt + 1 >= max_attempts {
                    if has_auto_projection
                        && is_container_host_publication_conflict(&output.stdout, &output.stderr)
                        && let Some((listener_name, _)) = projection
                            .listener_publications
                            .iter()
                            .find(|(_, publication)| {
                                publication.host_port_mode == TaskRuntimeHostPortMode::Auto
                            })
                        && let Some((_, publication)) = projection
                            .listener_publications
                            .iter()
                            .find(|(name, _)| name == listener_name)
                        && let Some(port) = publication.host_port
                    {
                        return Err(RunError::HostPublicationConflict {
                            task: task_name.to_string(),
                            listener: listener_name.clone(),
                            address: publication.host_address.clone(),
                            port,
                        });
                    }
                    output.execution_note = merge_execution_note(
                        output.execution_note,
                        reclaimed_orphaned_ephemeral_containers_note(
                            reclaimed_orphaned_ephemeral_count,
                        ),
                    );
                    return Ok(output);
                }

                if !is_container_host_publication_conflict(&output.stdout, &output.stderr) {
                    output.execution_note = merge_execution_note(
                        output.execution_note,
                        reclaimed_orphaned_ephemeral_containers_note(
                            reclaimed_orphaned_ephemeral_count,
                        ),
                    );
                    return Ok(output);
                }

                if let Some(target) = output.target.as_deref() {
                    let _ = remove_persistent_container(engine, target, task_name);
                }
                attempt += 1;
            }
        }
        Lifecycle::Persistent => {
            let projection = prepare_container_runtime_projection(
                task_name,
                runtime,
                publications,
                &runtime_listener_publications,
                false,
                host_port_override,
            )?;
            execute_persistent_container_task_command(
                contract,
                task_name,
                runtime,
                context_name,
                shared_local_backend_name,
                &repo_ownership_token,
                &command,
                working_dir,
                env_overrides,
                path_export,
                secret_env_names,
                image,
                engine,
                memory_bytes,
                compose_networks,
                &projection.publications,
                &projection.listener_publications,
                dependency_isolation_paths,
                mode,
            )
        }
    }
}

fn probe_container_backend(engine: &str, _task_name: &str) -> Result<Option<String>, RunError> {
    let Some(failure) = container_backend_probe_failure(engine) else {
        return Ok(None);
    };
    let details = if !failure.details.trim().is_empty() {
        failure.details
    } else {
        format!("`{engine} info` exited with status {:?}", failure.exit_code)
    };

    Ok(Some(format!(
        "container backend `{engine}` is unavailable: {details}"
    )))
}

fn resolved_runtime_has_public_endpoint(runtime: &ResolvedTaskRuntime) -> bool {
    runtime.primary_endpoint.is_some() || !runtime.exposed_endpoints.is_empty()
}

fn resolved_runtime_probe_endpoint(
    runtime: &ResolvedTaskRuntime,
) -> Option<ResolvedTaskRuntimeEndpoint> {
    runtime
        .primary_endpoint
        .as_ref()
        .or_else(|| runtime.exposed_endpoints.first())
        .cloned()
}

fn resolved_runtime_listener_probe_endpoint(
    runtime: &ResolvedTaskRuntime,
    listener_name: &str,
) -> Option<ResolvedTaskRuntimeEndpoint> {
    runtime.listeners.get(listener_name).and_then(|listener| {
        listener
            .resolved
            .as_ref()?
            .host
            .as_ref()
            .map(|host| ResolvedTaskRuntimeEndpoint {
                listener: listener_name.to_string(),
                protocol: listener.protocol,
                bind: listener.bind.clone(),
                host: host.clone(),
                primary: runtime.primary_listener.as_deref() == Some(listener_name),
            })
    })
}

fn runtime_readiness_target(
    contract: Option<&Contract>,
    runtime_spec: &TaskRuntimeSpec,
    runtime: &ResolvedTaskRuntime,
) -> Option<RuntimeReadinessTarget> {
    let readiness = runtime_spec.readiness.as_ref();
    let endpoint = match readiness.and_then(|readiness| readiness.listener.as_deref()) {
        Some(listener_name) => {
            resolved_runtime_listener_probe_endpoint(runtime, listener_name.trim())?
        }
        None => resolved_runtime_probe_endpoint(runtime)?,
    };
    if let Some(probe_name) = readiness
        .and_then(|readiness| readiness.probe.as_deref())
        .map(str::trim)
        .filter(|name| !name.is_empty())
    {
        let resolved = resolve_named_readiness_probe_contract(contract?, probe_name).ok()?;
        return Some(match resolved {
            ResolvedNamedReadinessProbeContract::Http { request, .. } => {
                RuntimeReadinessTarget::Http {
                    address: endpoint.host.address,
                    port: endpoint.host.port,
                    request,
                }
            }
            ResolvedNamedReadinessProbeContract::Tcp { .. } => RuntimeReadinessTarget::Tcp {
                address: endpoint.host.address,
                port: endpoint.host.port,
            },
        });
    }

    match readiness.and_then(|readiness| readiness.kind) {
        Some(TaskRuntimeReadinessKind::Http) => Some(RuntimeReadinessTarget::Http {
            address: endpoint.host.address,
            port: endpoint.host.port,
            request: readiness_http_request(readiness),
        }),
        Some(TaskRuntimeReadinessKind::Tcp) | None => Some(RuntimeReadinessTarget::Tcp {
            address: endpoint.host.address,
            port: endpoint.host.port,
        }),
    }
}

fn runtime_readiness_targets(
    contract: Option<&Contract>,
    runtime_spec: &TaskRuntimeSpec,
    runtime: &ResolvedTaskRuntime,
) -> Option<Vec<RuntimeReadinessTarget>> {
    let mut targets = Vec::new();
    targets.push(runtime_readiness_target(contract, runtime_spec, runtime)?);
    let Some(readiness) = runtime_spec.readiness.as_ref() else {
        return Some(targets);
    };
    let contract = contract?;
    for signal_probe in &readiness.signal_probes {
        let probe_name = signal_probe.trim();
        if probe_name.is_empty() {
            continue;
        }
        let probe = contract.probe(probe_name)?;
        let target = if let Some(target) = probe.target.as_ref() {
            if target.kind == crate::schema::ReadinessProbeTargetKind::Task
                && target.address_view == TaskTargetAddressView::Internal
            {
                let listener_name = target.listener.as_deref().map(str::trim)?;
                let listener = runtime.listeners.get(listener_name)?;
                let port = listener.bind.port;
                match probe.kind {
                    crate::schema::ReadinessProbeKind::Http => RuntimeReadinessTarget::Http {
                        address: listener.bind.address.clone(),
                        port,
                        request: named_probe_http_request_contract(contract, probe_name, probe)
                            .ok()?,
                    },
                    crate::schema::ReadinessProbeKind::Tcp => RuntimeReadinessTarget::Tcp {
                        address: listener.bind.address.clone(),
                        port,
                    },
                }
            } else {
                let resolved = resolve_named_readiness_probe(contract, probe_name).ok()?;
                match resolved {
                    ResolvedNamedReadinessProbe::Http {
                        address,
                        port,
                        request,
                        ..
                    } => RuntimeReadinessTarget::Http {
                        address,
                        port,
                        request,
                    },
                    ResolvedNamedReadinessProbe::Tcp { address, port, .. } => {
                        RuntimeReadinessTarget::Tcp { address, port }
                    }
                }
            }
        } else {
            let resolved = resolve_named_readiness_probe(contract, probe_name).ok()?;
            match resolved {
                ResolvedNamedReadinessProbe::Http {
                    address,
                    port,
                    request,
                    ..
                } => RuntimeReadinessTarget::Http {
                    address,
                    port,
                    request,
                },
                ResolvedNamedReadinessProbe::Tcp { address, port, .. } => {
                    RuntimeReadinessTarget::Tcp { address, port }
                }
            }
        };
        if !targets.contains(&target) {
            targets.push(target);
        }
    }
    Some(targets)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct HostRuntimeReadinessProbe {
    pub listener: String,
    pub protocol: TaskRuntimeProtocol,
    pub address: String,
    pub port: u16,
    pub request: Option<HttpReadinessRequest>,
    pub default_timeout: Option<Duration>,
    pub budget_hint: Option<Duration>,
}

pub(crate) fn task_runtime_host_readiness_probe_for_backend(
    contract: &Contract,
    task: &TaskSpec,
    backend: Backend,
    listener_name: &str,
) -> Result<HostRuntimeReadinessProbe, String> {
    let runtime = task.service_runtime_for_backend(backend).ok_or_else(|| {
        format!(
            "task does not resolve to a service runtime for backend `{}`",
            match backend {
                Backend::Native => "native",
                Backend::Container => "container",
                Backend::Remote => "remote",
            }
        )
    })?;
    if let Some(probe_name) = runtime
        .readiness
        .as_ref()
        .and_then(|readiness| readiness.probe.as_deref())
        .map(str::trim)
        .filter(|name| !name.is_empty())
    {
        let resolved = resolve_named_readiness_probe_contract(contract, probe_name)?;
        let probe_listener_name = runtime
            .readiness
            .as_ref()
            .and_then(|readiness| readiness.listener.as_deref())
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .unwrap_or(listener_name);
        let listener = runtime.listeners.get(probe_listener_name).ok_or_else(|| {
            format!("service runtime does not declare listener `{probe_listener_name}`")
        })?;
        let host = listener.project.host.as_ref().ok_or_else(|| {
            format!("listener `{probe_listener_name}` does not declare `project.host`")
        })?;
        let port = host.port.value.ok_or_else(|| {
            format!("listener `{probe_listener_name}` does not declare a fixed `project.host.port.value`")
        })?;
        let (request, default_timeout) = match resolved {
            ResolvedNamedReadinessProbeContract::Http {
                request, timeout, ..
            } => (Some(request), timeout),
            ResolvedNamedReadinessProbeContract::Tcp { timeout, .. } => (None, timeout),
        };
        return Ok(HostRuntimeReadinessProbe {
            listener: probe_listener_name.to_string(),
            protocol: listener.protocol,
            address: host.address.clone(),
            port,
            request,
            default_timeout,
            budget_hint: readiness_timing_budget_hint(Some(contract), runtime.readiness.as_ref()),
        });
    }
    let probe_listener_name = runtime
        .readiness
        .as_ref()
        .and_then(|readiness| readiness.listener.as_deref())
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .unwrap_or(listener_name);
    let listener = runtime.listeners.get(probe_listener_name).ok_or_else(|| {
        format!("service runtime does not declare listener `{probe_listener_name}`")
    })?;
    let host = listener.project.host.as_ref().ok_or_else(|| {
        format!("listener `{probe_listener_name}` does not declare `project.host`")
    })?;
    let port = host.port.value.ok_or_else(|| {
        format!(
            "listener `{probe_listener_name}` does not declare a fixed `project.host.port.value`"
        )
    })?;
    Ok(HostRuntimeReadinessProbe {
        listener: probe_listener_name.to_string(),
        protocol: listener.protocol,
        address: host.address.clone(),
        port,
        request: runtime
            .readiness
            .as_ref()
            .and_then(|readiness| readiness.kind)
            .is_some_and(|kind| kind == TaskRuntimeReadinessKind::Http)
            .then(|| readiness_http_request(runtime.readiness.as_ref())),
        default_timeout: runtime
            .readiness
            .as_ref()
            .and_then(|readiness| readiness.timeout.as_deref())
            .and_then(parse_readiness_duration_spec),
        budget_hint: readiness_timing_budget_hint(Some(contract), runtime.readiness.as_ref()),
    })
}

pub(crate) fn task_surface_host_readiness_probe_for_backend(
    contract: &Contract,
    task: &TaskSpec,
    backend: Backend,
    surface_name: &str,
) -> Result<HostRuntimeReadinessProbe, String> {
    let runtime = task.service_runtime_for_backend(backend).ok_or_else(|| {
        format!(
            "task does not resolve to a service runtime for backend `{}`",
            match backend {
                Backend::Native => "native",
                Backend::Container => "container",
                Backend::Remote => "remote",
            }
        )
    })?;
    if !runtime.surfaces.contains_name(surface_name) {
        return Err(format!(
            "service runtime does not attach surface `{surface_name}`"
        ));
    }
    let listener = runtime
        .listeners
        .get(surface_name)
        .ok_or_else(|| format!("service runtime does not declare listener `{surface_name}`"))?;
    let host = listener
        .project
        .host
        .as_ref()
        .ok_or_else(|| format!("listener `{surface_name}` does not declare `project.host`"))?;
    let port = host.port.value.ok_or_else(|| {
        format!("listener `{surface_name}` does not declare a fixed `project.host.port.value`")
    })?;
    let surface = contract
        .surface(surface_name)
        .ok_or_else(|| format!("surface `{surface_name}` is not declared"))?;
    let (request, default_timeout) = match surface.readiness.as_ref() {
        Some(readiness) => match readiness.kind {
            TaskRuntimeReadinessKind::Http => (
                Some(HttpReadinessRequest {
                    method: readiness
                        .method
                        .unwrap_or(TaskRuntimeReadinessHttpMethod::Get),
                    path: readiness
                        .path
                        .clone()
                        .or_else(|| surface.effective_path())
                        .unwrap_or_else(|| String::from("/")),
                    headers: readiness.headers.clone(),
                    success_statuses: readiness
                        .success
                        .as_ref()
                        .map(|success| success.status.clone())
                        .unwrap_or_else(|| vec![200]),
                    body_contains: readiness.body.as_ref().map(|body| body.contains.clone()),
                }),
                readiness
                    .timeout
                    .as_deref()
                    .and_then(parse_readiness_duration_spec),
            ),
            TaskRuntimeReadinessKind::Tcp => (
                None,
                readiness
                    .timeout
                    .as_deref()
                    .and_then(parse_readiness_duration_spec),
            ),
        },
        None => (None, None),
    };

    Ok(HostRuntimeReadinessProbe {
        listener: surface_name.to_string(),
        protocol: listener.protocol,
        address: host.address.clone(),
        port,
        request,
        default_timeout,
        budget_hint: surface_readiness_timing_budget_hint(surface.readiness.as_ref()),
    })
}

pub(crate) fn host_runtime_readiness_observed(
    probe: &HostRuntimeReadinessProbe,
    timeout: Option<Duration>,
) -> bool {
    match probe.request.as_ref() {
        Some(request) => http_readiness_endpoint_reachable(
            probe.address.as_str(),
            probe.port,
            request,
            timeout.or(probe.default_timeout),
        ),
        None => target_probe_endpoint_reachable_with_timeout(
            probe.address.as_str(),
            probe.port,
            timeout,
        ),
    }
}

fn readiness_target_observed(target: &RuntimeReadinessTarget) -> bool {
    readiness_target_observed_with_timeout(target, None)
}

fn readiness_target_observed_with_timeout(
    target: &RuntimeReadinessTarget,
    timeout: Option<Duration>,
) -> bool {
    readiness_target_observation_with_timeout(target, timeout).is_ok()
}

fn readiness_target_observation_with_timeout(
    target: &RuntimeReadinessTarget,
    timeout: Option<Duration>,
) -> Result<(), String> {
    match target {
        RuntimeReadinessTarget::Tcp { address, port } => {
            target_probe_endpoint_result_with_timeout(address.as_str(), *port, timeout)
        }
        RuntimeReadinessTarget::Http {
            address,
            port,
            request,
        } => http_readiness_endpoint_result(address.as_str(), *port, request, timeout),
        RuntimeReadinessTarget::RemoteTcp { probe, port } => {
            remote_target_probe_port_reachable(probe, *port)
                .then_some(())
                .ok_or_else(|| String::from("remote TCP readiness probe failed"))
        }
        RuntimeReadinessTarget::RemoteHttp {
            probe,
            address,
            port,
            request,
        } => remote_target_probe_http_reachable(probe, address.as_str(), *port, request, timeout)
            .then_some(())
            .ok_or_else(|| String::from("remote HTTP readiness probe failed")),
    }
}

fn readiness_targets_observed_with_timeout(
    targets: &[RuntimeReadinessTarget],
    timeout: Option<Duration>,
) -> bool {
    readiness_targets_observation_with_timeout(targets, timeout).is_ok()
}

fn readiness_targets_observation_with_timeout(
    targets: &[RuntimeReadinessTarget],
    timeout: Option<Duration>,
) -> Result<(), ReadinessAttemptFailure> {
    for target in targets {
        if let Err(detail) = readiness_target_observation_with_timeout(target, timeout) {
            return Err(ReadinessAttemptFailure {
                target: format_readiness_target(target),
                detail,
            });
        }
    }
    Ok(())
}

fn readiness_http_request(readiness: Option<&TaskRuntimeReadinessSpec>) -> HttpReadinessRequest {
    HttpReadinessRequest {
        method: readiness
            .and_then(|probe| probe.method)
            .unwrap_or(TaskRuntimeReadinessHttpMethod::Get),
        path: normalized_runtime_path(readiness.and_then(|probe| probe.path.as_deref())),
        headers: readiness
            .map(|probe| probe.headers.clone())
            .unwrap_or_default(),
        success_statuses: readiness
            .and_then(|probe| probe.success.as_ref())
            .map(|success| success.status.clone())
            .unwrap_or_else(|| (200u16..400u16).collect()),
        body_contains: readiness
            .and_then(|probe| probe.body.as_ref().map(|body| body.contains.clone())),
    }
}

pub(crate) fn resolve_named_readiness_probe_contract(
    contract: &Contract,
    probe_name: &str,
) -> Result<ResolvedNamedReadinessProbeContract, String> {
    let probe = contract
        .probe(probe_name)
        .ok_or_else(|| format!("unknown readiness probe `{probe_name}`"))?;
    let timeout = probe.timeout.map(Duration::from_millis);
    let source = resolve_named_probe_contract_source(contract, probe_name, probe)?;
    match probe.kind {
        crate::schema::ReadinessProbeKind::Http => Ok(ResolvedNamedReadinessProbeContract::Http {
            request: named_probe_http_request_contract(contract, probe_name, probe)?,
            timeout,
            source,
        }),
        crate::schema::ReadinessProbeKind::Tcp => {
            Ok(ResolvedNamedReadinessProbeContract::Tcp { timeout, source })
        }
    }
}

pub(crate) fn resolve_named_readiness_probe(
    contract: &Contract,
    probe_name: &str,
) -> Result<ResolvedNamedReadinessProbe, String> {
    let probe = contract
        .probe(probe_name)
        .ok_or_else(|| format!("unknown readiness probe `{probe_name}`"))?;
    match probe.kind {
        crate::schema::ReadinessProbeKind::Http => {
            resolve_named_http_readiness_probe(contract, probe_name, probe)
        }
        crate::schema::ReadinessProbeKind::Tcp => {
            let (address, port, _, source) =
                resolve_named_probe_target_endpoint(contract, probe_name, probe)?;
            Ok(ResolvedNamedReadinessProbe::Tcp {
                address,
                port,
                timeout: probe.timeout.map(Duration::from_millis),
                source,
            })
        }
    }
}

fn resolve_named_http_readiness_probe(
    contract: &Contract,
    probe_name: &str,
    probe: &crate::schema::ReadinessProbeSpec,
) -> Result<ResolvedNamedReadinessProbe, String> {
    let timeout = probe.timeout.map(Duration::from_millis);
    let (address, port, path, source) = if let Some(url) = probe.url.as_deref() {
        let (address, port, path) = parse_http_probe_url(url).ok_or_else(|| {
            format!(
                "readiness probe `{probe_name}` does not declare a valid absolute `http://` URL"
            )
        })?;
        (
            address,
            port,
            path,
            ReadinessProbeSource::LiteralUrl {
                url: url.to_string(),
            },
        )
    } else {
        let (address, port, base_path, source) =
            resolve_named_probe_target_endpoint(contract, probe_name, probe)?;
        let path = combine_readiness_probe_paths(base_path.as_deref(), probe.path.as_deref());
        (address, port, path, source)
    };
    Ok(ResolvedNamedReadinessProbe::Http {
        address,
        port,
        request: HttpReadinessRequest {
            path,
            ..named_probe_http_request_contract(contract, probe_name, probe)?
        },
        timeout,
        source,
    })
}

fn named_probe_http_request_contract(
    contract: &Contract,
    probe_name: &str,
    probe: &crate::schema::ReadinessProbeSpec,
) -> Result<HttpReadinessRequest, String> {
    Ok(HttpReadinessRequest {
        method: probe.method.unwrap_or(TaskRuntimeReadinessHttpMethod::Get),
        path: named_probe_http_request_path(contract, probe_name, probe)?,
        headers: probe.headers.clone(),
        success_statuses: probe
            .success
            .as_ref()
            .map(|success| success.status.clone())
            .or_else(|| probe.expect_status.map(|status| vec![status]))
            .unwrap_or_else(|| vec![200]),
        body_contains: probe.body.as_ref().map(|body| body.contains.clone()),
    })
}

fn named_probe_http_request_path(
    contract: &Contract,
    probe_name: &str,
    probe: &crate::schema::ReadinessProbeSpec,
) -> Result<String, String> {
    if let Some(url) = probe.url.as_deref() {
        let (_, _, path) = parse_http_probe_url(url).ok_or_else(|| {
            format!(
                "readiness probe `{probe_name}` does not declare a valid absolute `http://` URL"
            )
        })?;
        return Ok(path);
    }
    let target = probe
        .target
        .as_ref()
        .ok_or_else(|| format!("readiness probe `{probe_name}` does not declare a target"))?;
    let base_path = match target.kind {
        ReadinessProbeTargetKind::Task if target.address_view == TaskTargetAddressView::Host => {
            let listener_name = target
                .listener
                .as_deref()
                .map(str::trim)
                .filter(|name| !name.is_empty())
                .ok_or_else(|| {
                    format!(
                        "readiness probe `{probe_name}` task target must declare `target.listener`"
                    )
                })?;
            let task = contract.tasks.get(target.name.as_str()).ok_or_else(|| {
                format!(
                    "readiness probe `{probe_name}` references unknown task `{}`",
                    target.name
                )
            })?;
            let listener = select_target_listener_for_host_view(task, listener_name)?
                .ok_or_else(|| {
                    format!(
                        "readiness probe `{probe_name}` references unknown task listener `{}.{listener_name}`",
                        target.name
                    )
                })?;
            listener
                .project
                .host
                .as_ref()
                .and_then(|host| host.path.clone())
        }
        _ => None,
    };
    Ok(combine_readiness_probe_paths(
        base_path.as_deref(),
        probe.path.as_deref(),
    ))
}

fn resolve_named_probe_contract_source(
    contract: &Contract,
    probe_name: &str,
    probe: &crate::schema::ReadinessProbeSpec,
) -> Result<ReadinessProbeSource, String> {
    if let Some(url) = probe.url.as_deref() {
        return Ok(ReadinessProbeSource::LiteralUrl {
            url: url.to_string(),
        });
    }
    let target = probe
        .target
        .as_ref()
        .ok_or_else(|| format!("readiness probe `{probe_name}` does not declare a target"))?;
    match target.kind {
        ReadinessProbeTargetKind::Task => {
            let listener = target
                .listener
                .as_deref()
                .map(str::trim)
                .filter(|name| !name.is_empty())
                .ok_or_else(|| {
                    format!(
                        "readiness probe `{probe_name}` task target must declare `target.listener`"
                    )
                })?;
            let task = contract.tasks.get(target.name.as_str()).ok_or_else(|| {
                format!(
                    "readiness probe `{probe_name}` references unknown task `{}`",
                    target.name
                )
            })?;
            if !declared_service_listener_names(task).contains(listener) {
                return Err(format!(
                    "readiness probe `{probe_name}` references unknown task listener `{}.{listener}`",
                    target.name
                ));
            }
            if let Some(observer_task) = target
                .observer
                .as_ref()
                .and_then(|observer| observer.task.as_deref())
                .map(str::trim)
                .filter(|name| !name.is_empty())
                && !contract.tasks.contains_key(observer_task)
            {
                return Err(format!(
                    "readiness probe `{probe_name}` references unknown observer task `{observer_task}`"
                ));
            }
            Ok(ReadinessProbeSource::TaskListener {
                task: target.name.clone(),
                listener: listener.to_string(),
                address_view: target.address_view,
                observer: target
                    .observer
                    .as_ref()
                    .and_then(|observer| observer.task.as_deref())
                    .map(str::to_string),
            })
        }
        ReadinessProbeTargetKind::Service => {
            let service = contract.services.get(target.name.as_str()).ok_or_else(|| {
                format!(
                    "readiness probe `{probe_name}` references unknown service `{}`",
                    target.name
                )
            })?;
            let endpoint = if let Some(endpoint) = target
                .endpoint
                .as_deref()
                .map(str::trim)
                .filter(|name| !name.is_empty())
            {
                endpoint.to_string()
            } else if service.endpoints.len() == 1 {
                service
                    .endpoints
                    .keys()
                    .next()
                    .cloned()
                    .ok_or_else(|| {
                        format!(
                            "readiness probe `{probe_name}` could not resolve the sole endpoint for service `{}`",
                            target.name
                        )
                    })?
            } else if service.endpoints.is_empty() {
                return Err(format!(
                    "readiness probe `{probe_name}` references service `{}` but it does not declare any endpoints",
                    target.name
                ));
            } else {
                return Err(format!(
                    "readiness probe `{probe_name}` references service `{}` with multiple endpoints; declare `target.endpoint` explicitly",
                    target.name
                ));
            };
            if service.endpoint_named(endpoint.as_str()).is_none() {
                return Err(format!(
                    "readiness probe `{probe_name}` references unknown service endpoint `{}.{endpoint}`",
                    target.name
                ));
            }
            Ok(ReadinessProbeSource::ServiceEndpoint {
                service: target.name.clone(),
                endpoint,
            })
        }
    }
}

fn resolve_named_probe_target_endpoint(
    contract: &Contract,
    probe_name: &str,
    probe: &crate::schema::ReadinessProbeSpec,
) -> Result<(String, u16, Option<String>, ReadinessProbeSource), String> {
    let target = probe
        .target
        .as_ref()
        .ok_or_else(|| format!("readiness probe `{probe_name}` does not declare a target"))?;
    match target.kind {
        ReadinessProbeTargetKind::Task => {
            if target.address_view != TaskTargetAddressView::Host {
                return Err(format!(
                    "readiness probe `{probe_name}` currently supports only `target.address_view: host` for task targets"
                ));
            }
            let listener_name = target
                .listener
                .as_deref()
                .map(str::trim)
                .filter(|name| !name.is_empty())
                .ok_or_else(|| {
                    format!(
                        "readiness probe `{probe_name}` task target must declare `target.listener`"
                    )
                })?;
            let task = contract.tasks.get(target.name.as_str()).ok_or_else(|| {
                format!(
                    "readiness probe `{probe_name}` references unknown task `{}`",
                    target.name
                )
            })?;
            let listener = select_target_listener_for_host_view(task, listener_name)?
                .ok_or_else(|| {
                    format!(
                        "readiness probe `{probe_name}` references unknown task listener `{}.{listener_name}`",
                        target.name
                    )
                })?;
            let host = listener.project.host.as_ref().ok_or_else(|| {
                format!(
                    "readiness probe `{probe_name}` requires task listener `{}.{listener_name}` to declare `project.host`",
                    target.name
                )
            })?;
            let port = host.port.value.ok_or_else(|| {
                format!(
                    "readiness probe `{probe_name}` requires task listener `{}.{listener_name}` to declare a fixed `project.host.port.value`",
                    target.name
                )
            })?;
            Ok((
                host.address.clone(),
                port,
                host.path.clone(),
                ReadinessProbeSource::TaskListener {
                    task: target.name.clone(),
                    listener: listener_name.to_string(),
                    address_view: target.address_view,
                    observer: target
                        .observer
                        .as_ref()
                        .and_then(|observer| observer.task.as_deref())
                        .map(str::to_string),
                },
            ))
        }
        ReadinessProbeTargetKind::Service => {
            let service = contract.services.get(target.name.as_str()).ok_or_else(|| {
                format!(
                    "readiness probe `{probe_name}` references unknown service `{}`",
                    target.name
                )
            })?;
            let endpoint_name = if let Some(endpoint_name) = target
                .endpoint
                .as_deref()
                .map(str::trim)
                .filter(|name| !name.is_empty())
            {
                endpoint_name.to_string()
            } else if service.endpoints.len() == 1 {
                service
                    .endpoints
                    .keys()
                    .next()
                    .cloned()
                    .ok_or_else(|| {
                        format!(
                            "readiness probe `{probe_name}` could not resolve the sole endpoint for service `{}`",
                            target.name
                        )
                    })?
            } else if service.endpoints.is_empty() {
                return Err(format!(
                    "readiness probe `{probe_name}` references service `{}` but it does not declare any endpoints",
                    target.name
                ));
            } else {
                return Err(format!(
                    "readiness probe `{probe_name}` references service `{}` with multiple endpoints; declare `target.endpoint` explicitly",
                    target.name
                ));
            };
            let endpoint = service
                .endpoint_named(endpoint_name.as_str())
                .ok_or_else(|| {
                    format!(
                        "readiness probe `{probe_name}` references unknown service endpoint `{}.{endpoint_name}`",
                        target.name
                    )
                })?;
            Ok((
                endpoint.address.clone(),
                endpoint.port,
                None,
                ReadinessProbeSource::ServiceEndpoint {
                    service: target.name.clone(),
                    endpoint: endpoint_name,
                },
            ))
        }
    }
}

pub(crate) fn combine_readiness_probe_paths(
    base_path: Option<&str>,
    probe_path: Option<&str>,
) -> String {
    let Some(probe_path) = probe_path else {
        return String::from("/");
    };
    let probe_path = normalized_runtime_path(Some(probe_path));
    let Some(base_path) = base_path
        .map(str::trim)
        .filter(|path| !path.is_empty() && *path != "/")
    else {
        return probe_path;
    };
    format!(
        "{}/{}",
        base_path.trim_end_matches('/'),
        probe_path.trim_start_matches('/')
    )
}

pub(crate) fn parse_http_probe_url(url: &str) -> Option<(String, u16, String)> {
    let remainder = url.strip_prefix("http://")?;
    let (host_port, path) = match remainder.split_once('/') {
        Some((host_port, path)) => (host_port, format!("/{path}")),
        None => (remainder, String::from("/")),
    };
    let (address, port) = match host_port.split_once(':') {
        Some((address, port_text)) => {
            let port = port_text.parse::<u16>().ok()?;
            (address.to_string(), port)
        }
        None => (host_port.to_string(), 80),
    };
    if address.trim().is_empty() {
        return None;
    }
    Some((address, port, path))
}

fn readiness_timing_policy(
    contract: Option<&Contract>,
    readiness: Option<&TaskRuntimeReadinessSpec>,
) -> ReadinessTimingPolicy {
    ReadinessTimingPolicy {
        start_period: readiness
            .and_then(|probe| probe.start_period.as_deref())
            .and_then(parse_readiness_duration_spec)
            .unwrap_or(Duration::ZERO),
        interval: readiness
            .and_then(|probe| probe.interval.as_deref())
            .and_then(parse_readiness_duration_spec)
            .unwrap_or(Duration::from_millis(200)),
        timeout: readiness.and_then(|probe| {
            probe
                .probe
                .as_deref()
                .map(str::trim)
                .filter(|name| !name.is_empty())
                .and_then(|name| {
                    contract.and_then(|contract| {
                        resolve_named_readiness_probe_contract(contract, name).ok()
                    })
                })
                .and_then(|resolved| match resolved {
                    ResolvedNamedReadinessProbeContract::Http { timeout, .. }
                    | ResolvedNamedReadinessProbeContract::Tcp { timeout, .. } => timeout,
                })
                .or_else(|| {
                    probe
                        .timeout
                        .as_deref()
                        .and_then(parse_readiness_duration_spec)
                })
        }),
        retries: readiness.and_then(|probe| probe.retries),
    }
}

fn readiness_timing_budget_hint(
    contract: Option<&Contract>,
    readiness: Option<&TaskRuntimeReadinessSpec>,
) -> Option<Duration> {
    let timing = readiness_timing_policy(contract, readiness);
    let retries = u64::from(timing.retries?);
    let timeout = timing.timeout.unwrap_or(Duration::from_millis(200));
    Some(
        timing.start_period.saturating_add(
            timeout
                .saturating_add(timing.interval)
                .saturating_mul(retries as u32),
        ),
    )
}

fn surface_readiness_timing_budget_hint(
    readiness: Option<&crate::schema::SurfaceReadinessSpec>,
) -> Option<Duration> {
    let readiness = readiness?;
    let retries = u64::from(readiness.retries?);
    let timeout = readiness
        .timeout
        .as_deref()
        .and_then(parse_readiness_duration_spec)
        .unwrap_or(Duration::from_millis(200));
    let interval = readiness
        .interval
        .as_deref()
        .and_then(parse_readiness_duration_spec)
        .unwrap_or(Duration::from_millis(200));
    let start_period = readiness
        .start_period
        .as_deref()
        .and_then(parse_readiness_duration_spec)
        .unwrap_or(Duration::ZERO);
    Some(
        start_period.saturating_add(
            timeout
                .saturating_add(interval)
                .saturating_mul(retries as u32),
        ),
    )
}

pub(crate) fn http_readiness_endpoint_reachable(
    address: &str,
    port: u16,
    request: &HttpReadinessRequest,
    timeout: Option<Duration>,
) -> bool {
    http_readiness_endpoint_result(address, port, request, timeout).is_ok()
}

pub(crate) fn http_readiness_endpoint_status(
    address: &str,
    port: u16,
    request: &HttpReadinessRequest,
    timeout: Option<Duration>,
) -> HttpReadinessStatus {
    match http_readiness_endpoint_result(address, port, request, timeout) {
        Ok(()) => HttpReadinessStatus::Passed,
        Err(detail) if detail.contains("timed out") => HttpReadinessStatus::TimedOut,
        Err(_) => HttpReadinessStatus::Failed,
    }
}

fn http_readiness_endpoint_result(
    address: &str,
    port: u16,
    request: &HttpReadinessRequest,
    timeout: Option<Duration>,
) -> Result<(), String> {
    let connect_timeout = timeout.unwrap_or(Duration::from_millis(200));
    let io_timeout = timeout.unwrap_or(Duration::from_millis(500));
    let addrs = probe_socket_candidates(address, port);
    if addrs.is_empty() {
        return Err(String::from("no socket candidates resolved"));
    }
    let mut last_error = None;
    let mut saw_non_timeout_error = false;
    let mut last_non_timeout_error = None;
    for (index, socket) in addrs.into_iter().enumerate() {
        let effective_timeout = probe_connect_timeout_for_candidate(connect_timeout, index);
        match http_readiness_socket_result(address, socket, request, effective_timeout, io_timeout)
        {
            Ok(()) => return Ok(()),
            Err(error) => {
                if !error.contains("timed out") {
                    saw_non_timeout_error = true;
                    last_non_timeout_error = Some(error.clone());
                }
                last_error = Some(error);
            }
        }
    }
    if saw_non_timeout_error {
        return Err(last_non_timeout_error
            .or_else(|| last_error)
            .unwrap_or_else(|| String::from("HTTP readiness probe failed")));
    }
    Err(last_error.unwrap_or_else(|| String::from("timed out")))
}

fn http_readiness_socket_result(
    address: &str,
    socket: std::net::SocketAddr,
    request: &HttpReadinessRequest,
    connect_timeout: Duration,
    io_timeout: Duration,
) -> Result<(), String> {
    let mut stream = TcpStream::connect_timeout(&socket, connect_timeout)
        .map_err(|error| format!("{} ({socket})", normalize_probe_io_error(&error)))?;
    let _ = stream.set_read_timeout(Some(io_timeout));
    let _ = stream.set_write_timeout(Some(io_timeout));
    let host_header = if address.contains(':') && !address.starts_with('[') {
        format!("[{}]", address.trim())
    } else {
        address.trim().to_string()
    };
    let mut request_text = format!(
        "{} {} HTTP/1.1\r\nHost: {host_header}\r\nConnection: close\r\n",
        request.method.as_str(),
        request.path,
    );
    for (name, value) in &request.headers {
        request_text.push_str(name);
        request_text.push_str(": ");
        request_text.push_str(value);
        request_text.push_str("\r\n");
    }
    request_text.push_str("\r\n");
    if let Err(error) = stream.write_all(request_text.as_bytes()) {
        return Err(normalize_probe_io_error(&error));
    }
    let mut response_bytes = Vec::with_capacity(1024);
    let mut chunk = [0u8; 1024];
    loop {
        match stream.read(&mut chunk) {
            Ok(0) => break,
            Ok(bytes_read) => {
                let remaining = 32768usize.saturating_sub(response_bytes.len());
                if remaining == 0 {
                    break;
                }
                response_bytes.extend_from_slice(&chunk[..bytes_read.min(remaining)]);
                if response_bytes.len() >= 32768 {
                    break;
                }
            }
            Err(error) => return Err(normalize_probe_io_error(&error)),
        }
    }
    response_matches_http_readiness(&response_bytes, request)
}

fn http_probe_io_timed_out(error: &std::io::Error) -> bool {
    matches!(
        error.kind(),
        std::io::ErrorKind::TimedOut | std::io::ErrorKind::WouldBlock
    )
}

fn normalize_probe_io_error(error: &std::io::Error) -> String {
    if http_probe_io_timed_out(error) {
        String::from("timed out")
    } else {
        error.to_string()
    }
}

fn probe_connect_timeout_for_candidate(base: Duration, candidate_index: usize) -> Duration {
    if candidate_index == 0 {
        base
    } else {
        base.min(Duration::from_millis(300))
    }
}

fn response_matches_http_readiness(
    response_bytes: &[u8],
    request: &HttpReadinessRequest,
) -> Result<(), String> {
    if response_bytes.is_empty() {
        return Err(String::from("empty HTTP response"));
    }
    let response = String::from_utf8_lossy(response_bytes);
    let Some(status_line) = response.lines().next() else {
        return Err(String::from("missing HTTP status line"));
    };
    let mut parts = status_line.split_whitespace();
    let _ = parts.next();
    let Some(status_code) = parts.next().and_then(|value| value.parse::<u16>().ok()) else {
        return Err(String::from("invalid HTTP status line"));
    };
    if !request.success_statuses.contains(&status_code) {
        return Err(format!(
            "HTTP status `{status_code}` did not satisfy readiness"
        ));
    }
    if let Some(contains) = request.body_contains.as_deref() {
        let body = response
            .split_once("\r\n\r\n")
            .map(|(_, body)| body)
            .unwrap_or("");
        if !body.contains(contains) {
            return Err(format!("response body did not contain `{contains}`"));
        }
    }
    Ok(())
}

fn remote_target_probe_port_reachable(probe: &RemoteReadinessProbeTarget, port: u16) -> bool {
    let command = format!(
        "port={port}; \
if command -v ss >/dev/null 2>&1; then \
  ss -Htnl \"sport = :$port\" 2>/dev/null | awk 'NF {{ found=1; exit }} END {{ exit(found ? 0 : 1) }}' && exit 0; \
fi; \
if command -v netstat >/dev/null 2>&1; then \
  netstat -an 2>/dev/null | awk -v port=\"$port\" '$0 ~ /LISTEN/ && ($0 ~ (\":\" port \"[[:space:]]\") || $0 ~ (\"\\.\" port \"[[:space:]]\")) {{ found=1; exit }} END {{ exit(found ? 0 : 1) }}' && exit 0; \
fi; \
hex=$(printf '%04X' \"$port\"); \
awk -v target=\"$hex\" 'BEGIN {{ found = 0 }} FNR > 1 {{ split($2, a, \":\"); if (($4 == \"0A\" || $4 == \"0a\") && toupper(a[2]) == toupper(target)) {{ found = 1; exit }} }} END {{ exit(found ? 0 : 1) }}' /proc/net/tcp /proc/net/tcp6 2>/dev/null",
    );
    let output = if let Some(provider_command) = probe.provider_command.as_deref() {
        execute_backend_provider_task_command(
            "__ota_remote_probe__",
            command.as_str(),
            Path::new(probe.working_dir.as_str()),
            &BTreeMap::new(),
            probe.provider.as_str(),
            provider_command,
            probe.target.as_str(),
            probe.cwd.as_deref(),
            BackendProviderCommandContext::ActivationProbe,
            TaskExecutionMode::Stream {
                emit_progress: false,
                capture_output: true,
                live_log: None,
            },
        )
    } else {
        execute_remote_task_command(
            "__ota_remote_probe__",
            None,
            command.as_str(),
            &BTreeMap::new(),
            probe.provider.as_str(),
            probe.target.as_str(),
            probe.cwd.as_deref(),
            probe.ssh.as_ref(),
            TaskExecutionMode::Stream {
                emit_progress: false,
                capture_output: true,
                live_log: None,
            },
        )
    };
    matches!(output, Ok(TaskCommandOutput { exit_code: 0, .. }))
}

fn remote_target_probe_http_reachable(
    probe: &RemoteReadinessProbeTarget,
    address: &str,
    port: u16,
    request: &HttpReadinessRequest,
    timeout: Option<Duration>,
) -> bool {
    let url = format!("http://{}:{}{}", address.trim(), port, request.path);
    let command = remote_http_readiness_probe_command(url.as_str(), request, timeout);
    let output = if let Some(provider_command) = probe.provider_command.as_deref() {
        execute_backend_provider_task_command(
            "__ota_remote_probe__",
            command.as_str(),
            Path::new(probe.working_dir.as_str()),
            &BTreeMap::new(),
            probe.provider.as_str(),
            provider_command,
            probe.target.as_str(),
            probe.cwd.as_deref(),
            BackendProviderCommandContext::ActivationProbe,
            TaskExecutionMode::Stream {
                emit_progress: false,
                capture_output: true,
                live_log: None,
            },
        )
    } else {
        execute_remote_task_command(
            "__ota_remote_probe__",
            None,
            command.as_str(),
            &BTreeMap::new(),
            probe.provider.as_str(),
            probe.target.as_str(),
            probe.cwd.as_deref(),
            probe.ssh.as_ref(),
            TaskExecutionMode::Stream {
                emit_progress: false,
                capture_output: true,
                live_log: None,
            },
        )
    };
    matches!(output, Ok(TaskCommandOutput { exit_code: 0, .. }))
}

fn remote_http_readiness_probe_command(
    url: &str,
    request: &HttpReadinessRequest,
    timeout: Option<Duration>,
) -> String {
    let status_csv = request
        .success_statuses
        .iter()
        .map(|status| status.to_string())
        .collect::<Vec<_>>()
        .join(",");
    let headers_shell = request
        .headers
        .iter()
        .map(|(name, value)| format!("-H {}", shell_quote(&format!("{name}: {value}"))))
        .collect::<Vec<_>>()
        .join(" ");
    let headers_json =
        serde_json::to_string(&request.headers).unwrap_or_else(|_| String::from("{}"));
    let body_contains = request.body_contains.clone().unwrap_or_default();
    let timeout_seconds = timeout
        .map(|duration| duration.as_secs_f64().max(0.001))
        .unwrap_or(2.0);
    format!(
        "url={url}; method={method}; statuses={statuses}; contains={contains}; headers_json={headers_json}; timeout={timeout}; \
if command -v curl >/dev/null 2>&1; then \
  body_file=$(mktemp 2>/dev/null || printf '/tmp/ota-readiness-body-$$'); \
  code=$(curl -sS --connect-timeout \"$timeout\" --max-time \"$timeout\" -X \"$method\" {headers} -o \"$body_file\" -w '%{{http_code}}' \"$url\") || {{ rm -f \"$body_file\"; exit 1; }}; \
  matched=1; OLDIFS=\"$IFS\"; IFS=,; for expected in $statuses; do if [ \"$code\" = \"$expected\" ]; then matched=0; break; fi; done; IFS=\"$OLDIFS\"; \
  [ $matched -eq 0 ] || {{ rm -f \"$body_file\"; exit 1; }}; \
  if [ -n \"$contains\" ]; then grep -Fq -- \"$contains\" \"$body_file\" || {{ rm -f \"$body_file\"; exit 1; }}; fi; \
  rm -f \"$body_file\"; exit 0; \
fi; \
if command -v python3 >/dev/null 2>&1; then \
  python3 - \"$url\" \"$method\" \"$statuses\" \"$contains\" \"$headers_json\" \"$timeout\" <<'PY' && exit 0 || exit 1\n\
import json, sys, urllib.error, urllib.request\n\
class NoRedirect(urllib.request.HTTPRedirectHandler):\n\
    def redirect_request(self, req, fp, code, msg, headers, newurl):\n\
        return None\n\
url, method, statuses_raw, contains, headers_raw, timeout_raw = sys.argv[1:7]\n\
statuses = {{int(value) for value in statuses_raw.split(',') if value}}\n\
headers = json.loads(headers_raw)\n\
timeout = float(timeout_raw)\n\
request = urllib.request.Request(url, method=method, headers=headers)\n\
opener = urllib.request.build_opener(NoRedirect)\n\
try:\n\
    with opener.open(request, timeout=timeout) as response:\n\
        status = response.status\n\
        body = response.read().decode(errors='ignore')\n\
except urllib.error.HTTPError as error:\n\
    status = error.code\n\
    body = error.read().decode(errors='ignore')\n\
except Exception:\n\
    raise SystemExit(1)\n\
if status not in statuses:\n\
    raise SystemExit(1)\n\
if contains and contains not in body:\n\
    raise SystemExit(1)\n\
raise SystemExit(0)\n\
PY\n\
fi; \
exit 1",
        url = shell_quote(url),
        method = shell_quote(request.method.as_str()),
        statuses = shell_quote(&status_csv),
        contains = shell_quote(&body_contains),
        headers_json = shell_quote(&headers_json),
        timeout = shell_quote(&timeout_seconds.to_string()),
        headers = headers_shell,
    )
}

fn start_runtime_readiness_probe(
    contract: Option<&Contract>,
    runtime_spec: Option<&TaskRuntimeSpec>,
    runtime: Option<&ResolvedTaskRuntime>,
    announce_ready_endpoint: bool,
    notifier: Option<StreamPhaseNotifier>,
    interrupt_epoch: u64,
) -> Option<RuntimeReadinessProbe> {
    let runtime_spec = runtime_spec?;
    let runtime = runtime?;
    if !resolved_runtime_has_public_endpoint(runtime) {
        return None;
    }
    let readiness_targets = runtime_readiness_targets(contract, runtime_spec, runtime)?;
    let timing = readiness_timing_policy(contract, runtime_spec.readiness.as_ref());
    let ready_line = announce_ready_endpoint
        .then(|| ready_runtime_public_endpoint_line(runtime))
        .flatten();
    let state = Arc::new(RuntimeReadinessProbeState {
        observed: AtomicBool::new(false),
        budget_exhausted: AtomicBool::new(false),
        report: Mutex::new(readiness_probe_report_template(
            runtime_spec,
            runtime,
            readiness_targets.as_slice(),
            &timing,
        )),
    });
    let stop = Arc::new(AtomicBool::new(false));
    let thread_state = Arc::clone(&state);
    let thread_stop = Arc::clone(&stop);
    let probe_notifier = notifier;
    let thread_targets = readiness_targets.clone();
    let handle = thread::spawn(move || {
        let mut interrupt_grace_applied = false;
        let mut next_probe_at = Instant::now() + timing.start_period;
        let mut failed_probes = 0u32;
        while !thread_stop.load(Ordering::Relaxed) {
            if Instant::now() >= next_probe_at {
                match readiness_targets_observation_with_timeout(
                    thread_targets.as_slice(),
                    timing.timeout,
                ) {
                    Ok(()) => {
                        thread_state.observed.store(true, Ordering::Relaxed);
                        if let Some(line) = ready_line.as_deref() {
                            if let Some(notifier) = probe_notifier.as_ref() {
                                notifier.wait_for_quiet_output(
                                    Duration::from_millis(300),
                                    thread_stop.as_ref(),
                                );
                                let _guard = notifier.begin_output();
                                eprintln!("{line}");
                            } else {
                                clear_stream_phase_line();
                                eprintln!("{line}");
                            }
                        }
                        break;
                    }
                    Err(failure) => {
                        failed_probes = failed_probes.saturating_add(1);
                        if let Some(report) =
                            record_readiness_probe_failure(&thread_state, failed_probes, &failure)
                        {
                            emit_readiness_probe_progress(
                                probe_notifier.as_ref(),
                                thread_stop.as_ref(),
                                &report,
                            );
                        }
                        if let Some(retries) = timing.retries
                            && failed_probes >= retries
                        {
                            thread_state.budget_exhausted.store(true, Ordering::Relaxed);
                            break;
                        }
                        next_probe_at = Instant::now() + timing.interval;
                    }
                }
            }
            if !interrupt_grace_applied && interruption_observed_since(interrupt_epoch) {
                let grace_deadline = std::time::Instant::now() + Duration::from_millis(300);
                while std::time::Instant::now() < grace_deadline
                    && !thread_stop.load(Ordering::Relaxed)
                {
                    if readiness_targets_observed_with_timeout(
                        thread_targets.as_slice(),
                        timing.timeout,
                    ) {
                        thread_state.observed.store(true, Ordering::Relaxed);
                        if let Some(line) = ready_line.as_deref() {
                            if let Some(notifier) = probe_notifier.as_ref() {
                                notifier.wait_for_quiet_output(
                                    Duration::from_millis(300),
                                    thread_stop.as_ref(),
                                );
                                let _guard = notifier.begin_output();
                                eprintln!("{line}");
                            } else {
                                clear_stream_phase_line();
                                eprintln!("{line}");
                            }
                        }
                        return;
                    }
                    thread::sleep(Duration::from_millis(30));
                }
                interrupt_grace_applied = true;
                continue;
            }
            let sleep_for = next_probe_at
                .checked_duration_since(Instant::now())
                .map(|remaining| remaining.min(Duration::from_millis(30)))
                .unwrap_or(Duration::from_millis(30));
            if !thread_stop.load(Ordering::Relaxed)
                && !(!interrupt_grace_applied && interruption_observed_since(interrupt_epoch))
            {
                thread::sleep(sleep_for);
            }
        }
    });
    Some(RuntimeReadinessProbe {
        state,
        stop,
        handle: Some(handle),
    })
}

fn classify_container_service_termination(
    runtime: Option<&TaskRuntimeSpec>,
    resolved_runtime: Option<&ResolvedTaskRuntime>,
    readiness_observed: bool,
    readiness_budget_exhausted: bool,
    readiness_report: Option<ReadinessProbeReport>,
    termination_state: Option<&ContainerTerminationState>,
    exit_code: i32,
    interrupted: bool,
    container_name: &str,
) -> Option<ServiceTermination> {
    let runtime = runtime?;
    if runtime.kind != TaskRuntimeKind::Service {
        return None;
    }
    if termination_state.and_then(|state| state.running) == Some(true) {
        return None;
    }

    let inspected_exit_code = termination_state.and_then(|state| state.exit_code);
    let effective_exit_code = inspected_exit_code.unwrap_or(exit_code);

    if !readiness_observed {
        if readiness_budget_exhausted {
            return Some(ServiceTermination {
                kind: ServiceTerminationKind::ServiceStopped,
                cause: ServiceTerminationCause::ReadinessTimedOut,
                after_readiness: false,
                target: if termination_state.is_some() {
                    String::from("container")
                } else {
                    String::from("service workload in persistent container")
                },
                container: container_name.to_string(),
                exit_code: termination_state
                    .and_then(|state| state.exit_code)
                    .or(Some(exit_code)),
                readiness: readiness_report,
            });
        }
        // For pre-readiness exits, only classify as interruption when interruption evidence
        // is explicit. Real non-zero startup failures should remain generic task failures.
        let interrupted_before_readiness = if !interrupted {
            false
        } else if let Some(inspected_exit_code) = inspected_exit_code {
            is_interrupt_exit_code(inspected_exit_code) || inspected_exit_code == 0
        } else {
            is_interrupt_exit_code(effective_exit_code) || effective_exit_code == 0
        };
        let cause = if termination_state.and_then(|state| state.oom_killed) == Some(true) {
            ServiceTerminationCause::OomKilled
        } else if interrupted_before_readiness {
            ServiceTerminationCause::Interrupted
        } else if effective_exit_code > 0 {
            ServiceTerminationCause::ExitedNonZero
        } else if effective_exit_code == 0 {
            ServiceTerminationCause::Exited
        } else {
            ServiceTerminationCause::Unknown
        };

        return Some(ServiceTermination {
            kind: ServiceTerminationKind::ServiceStopped,
            cause,
            after_readiness: false,
            target: if termination_state.is_some() {
                String::from("container")
            } else {
                String::from("service workload in persistent container")
            },
            container: container_name.to_string(),
            exit_code: termination_state
                .and_then(|state| state.exit_code)
                .or(Some(exit_code)),
            readiness: readiness_report,
        });
    }

    if !resolved_runtime.is_some_and(resolved_runtime_has_public_endpoint) {
        return None;
    }

    let after_readiness = true;
    let cause = if termination_state.and_then(|state| state.oom_killed) == Some(true) {
        ServiceTerminationCause::OomKilled
    } else if let Some(inspected_exit_code) = inspected_exit_code {
        // Inspected container exit evidence is authoritative for post-readiness service
        // classification, but an observed user interrupt still owns cooperative clean exits.
        if is_interrupt_exit_code(inspected_exit_code) || (interrupted && inspected_exit_code == 0)
        {
            ServiceTerminationCause::Interrupted
        } else if inspected_exit_code > 0 {
            ServiceTerminationCause::ExitedNonZero
        } else if inspected_exit_code == 0 {
            ServiceTerminationCause::Exited
        } else {
            ServiceTerminationCause::Unknown
        }
    } else if is_interrupt_exit_code(effective_exit_code) {
        ServiceTerminationCause::Interrupted
    } else if effective_exit_code > 0 {
        ServiceTerminationCause::ExitedNonZero
    } else if interrupted {
        ServiceTerminationCause::Interrupted
    } else if effective_exit_code == 0 {
        ServiceTerminationCause::Exited
    } else {
        ServiceTerminationCause::Unknown
    };

    Some(ServiceTermination {
        kind: ServiceTerminationKind::ServiceStopped,
        cause,
        after_readiness,
        target: if termination_state.is_some() {
            String::from("container")
        } else {
            String::from("service workload in persistent container")
        },
        container: container_name.to_string(),
        exit_code: termination_state
            .and_then(|state| state.exit_code)
            .or(Some(exit_code)),
        readiness: None,
    })
}

fn service_termination_execution_note(service_termination: &ServiceTermination) -> String {
    let cause = match service_termination.cause {
        ServiceTerminationCause::OomKilled => {
            format!("{} was OOM-killed", service_termination.target)
        }
        ServiceTerminationCause::Interrupted => {
            format!("{} was interrupted", service_termination.target)
        }
        ServiceTerminationCause::ReadinessTimedOut => String::from(
            "readiness budget exhausted before the declared runtime endpoint became reachable",
        ),
        ServiceTerminationCause::ExitedNonZero => {
            format!("{} exited non-zero", service_termination.target)
        }
        ServiceTerminationCause::Exited => format!("{} exited", service_termination.target),
        ServiceTerminationCause::Unknown => {
            format!("{} stop cause is unknown", service_termination.target)
        }
    };
    if service_termination.after_readiness {
        format!("service stopped after readiness; {cause}")
    } else {
        format!("service failed to start; {cause}")
    }
}

fn should_cleanup_interrupted_persistent_service_workload(
    service_termination: Option<&ServiceTermination>,
) -> bool {
    service_termination
        .is_some_and(|termination| termination.cause == ServiceTerminationCause::Interrupted)
}

fn inspect_container_termination_state(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Option<ContainerTerminationState> {
    let inspect = container_command_output(
        engine,
        &["inspect", "-f", "{{json .State}}", container_name],
        None,
        task_name,
    )
    .ok()?;
    if inspect.exit_code != 0 {
        return None;
    }
    let value = serde_json::from_str::<serde_json::Value>(inspect.stdout.trim()).ok()?;
    let state = value.as_object()?;
    Some(ContainerTerminationState {
        running: state_bool_value(state, &["Running", "running"]),
        exit_code: state_i32_value(state, &["ExitCode", "exitCode", "exit_code"]),
        oom_killed: state_bool_value(state, &["OOMKilled", "oomKilled", "oom_killed"]),
    })
}

fn state_bool_value(
    state: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<bool> {
    for key in keys {
        if let Some(value) = state.get(*key) {
            if let Some(boolean) = value.as_bool() {
                return Some(boolean);
            }
            if let Some(text) = value.as_str() {
                match text.trim().to_ascii_lowercase().as_str() {
                    "true" => return Some(true),
                    "false" => return Some(false),
                    _ => {}
                }
            }
        }
    }
    None
}

fn state_i32_value(
    state: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<i32> {
    for key in keys {
        if let Some(value) = state.get(*key) {
            if let Some(number) = value.as_i64() {
                if let Ok(parsed) = i32::try_from(number) {
                    return Some(parsed);
                }
            }
            if let Some(text) = value.as_str()
                && let Ok(parsed) = text.trim().parse::<i32>()
            {
                return Some(parsed);
            }
        }
    }
    None
}

fn execute_ephemeral_container_task_command(
    contract: Option<&Contract>,
    task_name: &str,
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    context_name: Option<&str>,
    shared_local_backend_name: Option<&str>,
    repo_ownership_token: &str,
    command: &str,
    working_dir: &Path,
    env_overrides: &BTreeMap<String, String>,
    path_export: Option<&str>,
    secret_env_names: &BTreeSet<String>,
    image: &str,
    engine: &str,
    memory_bytes: Option<u64>,
    compose_networks: &[String],
    publications: &[ContainerPortPublication],
    listener_publications: &[(String, ContainerPortPublication)],
    dependency_isolation_paths: &[String],
    mode: TaskExecutionMode,
) -> Result<TaskCommandOutput, RunError> {
    let identity_seed = container_identity_seed(
        context_name,
        shared_local_backend_name,
        publications,
        dependency_isolation_paths,
        memory_bytes,
    );
    let container_name =
        ephemeral_container_name_for_seed(working_dir, image, engine, identity_seed.as_deref());
    let prepared_runtime =
        resolve_container_task_runtime_from_publications(runtime, listener_publications);
    let workspace_mount_source = container_workspace_mount_source(working_dir);
    let mut create = container_engine_command(engine);
    create
        .arg("create")
        .arg("-i")
        .arg("--name")
        .arg(&container_name)
        .arg("--label")
        .arg(OTA_MANAGED_CONTAINER_LABEL)
        .arg("--label")
        .arg(OTA_EPHEMERAL_CONTAINER_LABEL)
        .arg("--label")
        .arg(format!(
            "{OTA_REPO_CONTAINER_LABEL_KEY}={repo_ownership_token}"
        ))
        .arg("--label")
        .arg(format!(
            "{OTA_OWNER_PID_CONTAINER_LABEL_KEY}={}",
            std::process::id()
        ))
        .arg("--entrypoint")
        .arg("sh")
        .arg("-v")
        .arg(container_workspace_mount_arg(&workspace_mount_source))
        .arg("-w")
        .arg("/workspace");
    append_container_host_user_arg(&mut create);
    append_container_host_user_home_arg(&mut create, env_overrides);
    if let Some(network) = compose_networks.first() {
        create.arg("--network").arg(network);
    }
    for (volume_name, container_path) in container_dependency_isolation_mounts(
        task_name,
        working_dir,
        context_name,
        image,
        engine,
        repo_ownership_token,
        dependency_isolation_paths,
    )? {
        create
            .arg("-v")
            .arg(format!("{volume_name}:{container_path}"));
    }
    append_container_publication_args(&mut create, publications);
    append_container_memory_arg(&mut create, memory_bytes);
    append_container_git_safe_directory_args(&mut create, env_overrides);
    for (name, value) in env_overrides {
        if secret_env_names.contains(name) {
            create.env(name, value);
            create.arg("--env").arg(name);
        } else {
            create.arg("--env").arg(format!("{name}={value}"));
        }
    }
    create
        .arg(image)
        .arg("-c")
        .arg(command_with_path_export(command, path_export));

    let create_status = create.output().map_err(|source| RunError::SpawnFailed {
        task: task_name.to_string(),
        source,
    })?;
    if !create_status.status.success() {
        let stdout = String::from_utf8_lossy(&create_status.stdout).into_owned();
        let stderr = String::from_utf8_lossy(&create_status.stderr).into_owned();
        return Ok(TaskCommandOutput {
            exit_code: create_status.status.code().unwrap_or(1),
            stdout,
            stderr,
            target: Some(container_name.clone()),
            runtime: None,
            service_termination: None,
            execution_note: None,
            interrupted: false,
        });
    }

    if let Some(failure) =
        ensure_container_networks(engine, &container_name, compose_networks, task_name)?
    {
        let _ = remove_persistent_container(engine, &container_name, task_name);
        return Ok(container_command_failure(failure, container_name.clone()));
    }

    match mode {
        TaskExecutionMode::Stream {
            capture_output,
            live_log,
            ..
        } => {
            let interrupt_epoch = current_run_interrupt_epoch();
            let mut container = ephemeral_container_stream_command(engine, &container_name);
            let output_result =
                run_streaming_command_with_capture_with_loader_hook_and_timeout_options(
                    &mut container,
                    &running_loader_label_for_backend(task_name, Backend::Container),
                    true,
                    capture_output,
                    live_log.as_ref(),
                    |notifier| {
                        start_runtime_readiness_probe(
                            contract,
                            runtime,
                            prepared_runtime.as_ref(),
                            true,
                            notifier,
                            interrupt_epoch,
                        )
                    },
                    Some(|child: &mut Child| {
                        let _ = remove_persistent_container(engine, &container_name, task_name);
                        let _ = child.kill();
                    }),
                );
            let (output, readiness_probe) = match output_result {
                Ok(output) => output,
                Err(source) => {
                    let _ = remove_persistent_container(engine, &container_name, task_name);
                    return Err(RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    });
                }
            };
            let interrupted_by_user = interruption_observed_since(interrupt_epoch);
            let readiness_outcome = readiness_probe
                .map(RuntimeReadinessProbe::stop_and_collect)
                .unwrap_or(RuntimeReadinessProbeOutcome {
                    observed: false,
                    budget_exhausted: false,
                    report: None,
                });
            let termination_state =
                inspect_container_termination_state(task_name, engine, &container_name);
            let service_termination = classify_container_service_termination(
                runtime,
                prepared_runtime.as_ref(),
                readiness_outcome.observed,
                readiness_outcome.budget_exhausted,
                readiness_outcome.report.clone(),
                termination_state.as_ref(),
                output.exit_code,
                interrupted_by_user,
                &container_name,
            );
            let service_termination = if readiness_outcome.observed
                || readiness_outcome.budget_exhausted
                || output.exit_code == 0
                || interrupted_by_user
            {
                service_termination
            } else {
                None
            };
            let mut exit_code = output.exit_code;
            if service_termination.is_some() && exit_code == 0 {
                exit_code = 1;
            }
            let mut execution_note = interruption_execution_note(interrupted_by_user, exit_code);
            if let Some(note) = service_termination
                .as_ref()
                .map(service_termination_execution_note)
            {
                execution_note = Some(match execution_note {
                    Some(existing) => format!("{existing}; {note}"),
                    None => note,
                });
            }
            if let Some(cleanup_note) =
                remove_ephemeral_container_and_note(task_name, engine, &container_name)
            {
                execution_note = Some(match execution_note {
                    Some(note) => format!("{note}; {cleanup_note}"),
                    None => cleanup_note,
                });
            }

            Ok(TaskCommandOutput {
                exit_code,
                stdout: output.stdout,
                stderr: output.stderr,
                target: Some(container_name.clone()),
                runtime: prepared_runtime.clone(),
                service_termination,
                execution_note,
                interrupted: interrupted_by_user,
            })
        }
        TaskExecutionMode::Capture | TaskExecutionMode::CaptureActivation => {
            let interrupt_epoch = current_run_interrupt_epoch();
            let mut container = container_engine_command(engine);
            container.arg("start").arg("-ai").arg(&container_name);
            let mut child = container
                .stdin(Stdio::inherit())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let stdout_handle = child.stdout.take().map(|stdout| {
                thread::spawn(move || stream_reader_to_sink(stdout, io::sink(), None, true, None))
            });
            let stderr_handle = child.stderr.take().map(|stderr| {
                thread::spawn(move || stream_reader_to_sink(stderr, io::sink(), None, true, None))
            });
            let readiness_probe = start_runtime_readiness_probe(
                contract,
                runtime,
                prepared_runtime.as_ref(),
                false,
                None,
                interrupt_epoch,
            );
            let status = wait_for_child_with_runtime_readiness_budget(
                &mut child,
                readiness_probe.as_ref(),
                |child| {
                    let _ = remove_persistent_container(engine, &container_name, task_name);
                    let _ = child.kill();
                },
            )
            .map_err(|source| {
                let _ = remove_persistent_container(engine, &container_name, task_name);
                RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                }
            })?;
            let stdout =
                join_stream_reader(stdout_handle).map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let stderr =
                join_stream_reader(stderr_handle).map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let output_exit_code = status.code().unwrap_or(1);
            let interrupted_by_user = interruption_observed_since(interrupt_epoch);
            let readiness_outcome = readiness_probe
                .map(RuntimeReadinessProbe::stop_and_collect)
                .unwrap_or(RuntimeReadinessProbeOutcome {
                    observed: false,
                    budget_exhausted: false,
                    report: None,
                });
            let termination_state =
                inspect_container_termination_state(task_name, engine, &container_name);
            let service_termination = classify_container_service_termination(
                runtime,
                prepared_runtime.as_ref(),
                readiness_outcome.observed,
                readiness_outcome.budget_exhausted,
                readiness_outcome.report.clone(),
                termination_state.as_ref(),
                output_exit_code,
                interrupted_by_user,
                &container_name,
            );
            let service_termination = if readiness_outcome.observed
                || readiness_outcome.budget_exhausted
                || output_exit_code == 0
                || interrupted_by_user
            {
                service_termination
            } else {
                None
            };
            let mut exit_code = output_exit_code;
            if service_termination.is_some() && exit_code == 0 {
                exit_code = 1;
            }
            let mut execution_note = interruption_execution_note(interrupted_by_user, exit_code);
            if let Some(note) = service_termination
                .as_ref()
                .map(service_termination_execution_note)
            {
                execution_note = Some(match execution_note {
                    Some(existing) => format!("{existing}; {note}"),
                    None => note,
                });
            }
            if let Some(cleanup_note) =
                remove_ephemeral_container_and_note(task_name, engine, &container_name)
            {
                execution_note = Some(match execution_note {
                    Some(note) => format!("{note}; {cleanup_note}"),
                    None => cleanup_note,
                });
            }

            Ok(TaskCommandOutput {
                exit_code,
                stdout,
                stderr,
                target: Some(container_name),
                runtime: prepared_runtime,
                service_termination,
                execution_note,
                interrupted: interrupted_by_user,
            })
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn execute_fulfilled_ephemeral_container_task_command(
    task_name: &str,
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    context_name: Option<&str>,
    shared_local_backend_name: Option<&str>,
    repo_ownership_token: &str,
    command: &str,
    working_dir: &Path,
    env_overrides: &BTreeMap<String, String>,
    path_export: Option<&str>,
    secret_env_names: &BTreeSet<String>,
    image: &str,
    engine: &str,
    memory_bytes: Option<u64>,
    compose_networks: &[String],
    publications: &[ContainerPortPublication],
    _listener_publications: &[(String, ContainerPortPublication)],
    dependency_isolation_paths: &[String],
    deferred_backend_fulfillment: &DeferredContainerBackendFulfillment,
    mode: TaskExecutionMode,
) -> Result<TaskCommandOutput, RunError> {
    if runtime.is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service) {
        let mut evidence = deferred_backend_fulfillment.evidence.clone();
        evidence.result = BackendFulfillmentResult::Failed;
        return Err(RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: evidence.backend_unit.clone(),
            details: String::from(
                "run-path fulfillment for direct ephemeral container contexts does not support service tasks yet",
            ),
            evidence,
        });
    }

    let identity_seed = container_identity_seed(
        context_name,
        shared_local_backend_name,
        publications,
        dependency_isolation_paths,
        memory_bytes,
    );
    let container_name =
        ephemeral_container_name_for_seed(working_dir, image, engine, identity_seed.as_deref());

    let create = create_idle_ephemeral_container(
        task_name,
        working_dir,
        context_name,
        repo_ownership_token,
        image,
        engine,
        &container_name,
        memory_bytes,
        compose_networks,
        publications,
        dependency_isolation_paths,
        env_overrides,
        secret_env_names,
    )?;
    if create.exit_code != 0 {
        return Ok(TaskCommandOutput {
            exit_code: create.exit_code,
            stdout: create.stdout,
            stderr: create.stderr,
            target: Some(container_name),
            runtime: None,
            service_termination: None,
            execution_note: None,
            interrupted: false,
        });
    }

    if let Some(failure) =
        ensure_container_networks(engine, &container_name, compose_networks, task_name)?
    {
        let _ = remove_persistent_container(engine, &container_name, task_name);
        return Ok(container_command_failure(failure, container_name));
    }
    let start = container_command_output(engine, &["start", &container_name], None, task_name)?;
    if start.exit_code != 0 {
        let _ = remove_persistent_container(engine, &container_name, task_name);
        return Ok(container_command_failure(start, container_name));
    }

    let provisioning_target = ProvisioningExecutionTarget::Container {
        image: image.to_string(),
        engine: engine.to_string(),
        lifecycle: Lifecycle::Persistent,
        container_name: Some(container_name.clone()),
    };
    let provisioning = apply_run_path_provisioning_request_with_bootstrap(
        &ProvisioningBackendRequest {
            actions: deferred_backend_fulfillment.actions.clone(),
        },
        &deferred_backend_fulfillment.adapter_bootstrap,
        working_dir,
        &provisioning_target,
        backend_fulfillment_output_mode(mode.clone()),
    );
    let provisioning_output = match provisioning {
        Ok(output) => output,
        Err(error) => {
            let _ = remove_persistent_container(engine, &container_name, task_name);
            let mut evidence = deferred_backend_fulfillment.evidence.clone();
            evidence.result = BackendFulfillmentResult::Failed;
            return Err(RunError::BackendFulfillmentFailed {
                task: task_name.to_string(),
                backend_unit: evidence.backend_unit.clone(),
                details: render_backend_fulfillment_failure(error),
                evidence,
            });
        }
    };
    if let Err(error) = install_source_managed_tool_wrappers(
        engine,
        &container_name,
        task_name,
        &deferred_backend_fulfillment.actions,
    ) {
        let _ = remove_persistent_container(engine, &container_name, task_name);
        return Err(error);
    }
    let remaining = detect_missing_named_container_requirements(
        &deferred_backend_fulfillment.evidence.declared_runtimes,
        &deferred_backend_fulfillment.evidence.declared_tools,
        engine,
        &container_name,
        task_name,
        deferred_backend_fulfillment.policy_pack.as_deref(),
        deferred_backend_fulfillment.target_os.as_str(),
    );
    let remaining = remaining
        .into_iter()
        .filter(|gap| {
            !source_managed_remaining_gap_covered(gap, &deferred_backend_fulfillment.actions)
        })
        .collect::<Vec<_>>();
    if !remaining.is_empty() {
        let _ = remove_persistent_container(engine, &container_name, task_name);
        let mut evidence = deferred_backend_fulfillment.evidence.clone();
        evidence.result = BackendFulfillmentResult::Failed;
        evidence.missing = remaining
            .iter()
            .map(BackendRequirementGap::description)
            .collect();
        return Err(RunError::BackendFulfillmentFailed {
            task: task_name.to_string(),
            backend_unit: evidence.backend_unit.clone(),
            details: format!(
                "provisioning finished but requirements are still missing: {}",
                evidence.missing.join("; ")
            ),
            evidence,
        });
    }

    let deferred_path_export = source_managed_tool_path_export_required(
        &deferred_backend_fulfillment.actions,
    )
    .then(|| source_managed_tool_path_export(&deferred_backend_fulfillment.actions, path_export));
    let wrapped_command =
        wrap_command_for_source_managed_actions(command, &deferred_backend_fulfillment.actions);
    let output_result = exec_persistent_container_task_command(
        task_name,
        runtime,
        &wrapped_command,
        env_overrides,
        deferred_path_export.as_deref().or(path_export),
        secret_env_names,
        engine,
        mode,
        &container_name,
        None,
    );
    let mut output = match output_result {
        Ok(output) => output,
        Err(error) => {
            let _ = remove_persistent_container(engine, &container_name, task_name);
            return Err(error);
        }
    };
    output.stdout = format!("{}{}", provisioning_output.stdout, output.stdout);
    output.stderr = format!("{}{}", provisioning_output.stderr, output.stderr);
    output.execution_note = merge_execution_note(
        output.execution_note,
        remove_ephemeral_container_and_note(task_name, engine, &container_name),
    );
    Ok(output)
}

#[allow(clippy::too_many_arguments)]
fn create_idle_ephemeral_container(
    task_name: &str,
    working_dir: &Path,
    context_name: Option<&str>,
    repo_ownership_token: &str,
    image: &str,
    engine: &str,
    container_name: &str,
    memory_bytes: Option<u64>,
    compose_networks: &[String],
    publications: &[ContainerPortPublication],
    dependency_isolation_paths: &[String],
    env_overrides: &BTreeMap<String, String>,
    secret_env_names: &BTreeSet<String>,
) -> Result<ContainerCommandOutput, RunError> {
    let workspace_mount_source = container_workspace_mount_source(working_dir);
    let mut create = container_engine_command(engine);
    create
        .arg("create")
        .arg("-i")
        .arg("--name")
        .arg(container_name)
        .arg("--label")
        .arg(OTA_MANAGED_CONTAINER_LABEL)
        .arg("--label")
        .arg(OTA_EPHEMERAL_CONTAINER_LABEL)
        .arg("--label")
        .arg(format!(
            "{OTA_REPO_CONTAINER_LABEL_KEY}={repo_ownership_token}"
        ))
        .arg("--label")
        .arg(format!(
            "{OTA_OWNER_PID_CONTAINER_LABEL_KEY}={}",
            std::process::id()
        ))
        .arg("--entrypoint")
        .arg("sh")
        .arg("-v")
        .arg(container_workspace_mount_arg(&workspace_mount_source))
        .arg("-w")
        .arg("/workspace");
    append_container_host_user_arg(&mut create);
    append_container_host_user_home_arg(&mut create, env_overrides);
    if let Some(network) = compose_networks.first() {
        create.arg("--network").arg(network);
    }
    for (volume_name, container_path) in container_dependency_isolation_mounts(
        task_name,
        working_dir,
        context_name,
        image,
        engine,
        repo_ownership_token,
        dependency_isolation_paths,
    )? {
        create
            .arg("-v")
            .arg(format!("{volume_name}:{container_path}"));
    }
    append_container_publication_args(&mut create, publications);
    append_container_memory_arg(&mut create, memory_bytes);
    append_container_git_safe_directory_args(&mut create, env_overrides);
    for (name, value) in env_overrides {
        if secret_env_names.contains(name) {
            create.env(name, value);
            create.arg("--env").arg(name);
        } else {
            create.arg("--env").arg(format!("{name}={value}"));
        }
    }
    create
        .arg(image)
        .arg("-c")
        .arg("while true; do sleep 3600; done");

    let output = create.output().map_err(|source| RunError::SpawnFailed {
        task: task_name.to_string(),
        source,
    })?;
    Ok(ContainerCommandOutput {
        exit_code: output.status.code().unwrap_or(1),
        stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
        stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
    })
}

fn execute_persistent_container_task_command(
    contract: Option<&Contract>,
    task_name: &str,
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    context_name: Option<&str>,
    shared_local_backend_name: Option<&str>,
    repo_ownership_token: &str,
    command: &str,
    working_dir: &Path,
    env_overrides: &BTreeMap<String, String>,
    path_export: Option<&str>,
    secret_env_names: &BTreeSet<String>,
    image: &str,
    engine: &str,
    memory_bytes: Option<u64>,
    compose_networks: &[String],
    publications: &[ContainerPortPublication],
    listener_publications: &[(String, ContainerPortPublication)],
    dependency_isolation_paths: &[String],
    mode: TaskExecutionMode,
) -> Result<TaskCommandOutput, RunError> {
    let identity_seed = container_identity_seed(
        context_name,
        shared_local_backend_name,
        publications,
        dependency_isolation_paths,
        memory_bytes,
    );
    let container_name =
        persistent_container_name_for_seed(working_dir, image, engine, identity_seed.as_deref());
    let family_token =
        persistent_container_family_token(task_name, context_name, shared_local_backend_name);
    let shape_token = persistent_container_shape_token(
        context_name,
        shared_local_backend_name,
        image,
        engine,
        compose_networks,
        publications,
        dependency_isolation_paths,
        memory_bytes,
    );

    let mut reconciliation = match ensure_persistent_container_ready(
        task_name,
        working_dir,
        context_name,
        repo_ownership_token,
        image,
        engine,
        &container_name,
        family_token.as_str(),
        shape_token.as_str(),
        compose_networks,
        memory_bytes,
        publications,
        listener_publications,
        dependency_isolation_paths,
    )? {
        PersistentContainerEnsureResult::Ready(reconciliation) => reconciliation,
        PersistentContainerEnsureResult::Failure(failure) => return Ok(failure),
    };

    if reconciliation.action == PersistentContainerReconciliationAction::Reused {
        preflight_reused_persistent_container_listener_binds(
            task_name,
            runtime,
            engine,
            &container_name,
        )?;
    }

    let fixed_expected_host_ports = fixed_listener_host_ports(listener_publications);
    let (resolved_runtime, resolved_env) = match persistent_container_runtime_projection(
        runtime,
        engine,
        &container_name,
        task_name,
        &fixed_expected_host_ports,
        env_overrides,
    ) {
        Ok(projection) => projection,
        Err(error) if persistent_runtime_projection_host_port_mismatch(&error) => {
            let remove = remove_persistent_container(engine, &container_name, task_name)?;
            if remove.exit_code != 0 {
                return Ok(container_command_failure(remove, container_name.clone()));
            }
            match ensure_persistent_container_ready(
                task_name,
                working_dir,
                context_name,
                repo_ownership_token,
                image,
                engine,
                &container_name,
                family_token.as_str(),
                shape_token.as_str(),
                compose_networks,
                memory_bytes,
                publications,
                listener_publications,
                dependency_isolation_paths,
            )? {
                PersistentContainerEnsureResult::Ready(_) => {
                    reconciliation =
                        PersistentContainerReconciliation::recreated("execution shape changed");
                }
                PersistentContainerEnsureResult::Failure(failure) => {
                    return Ok(failure);
                }
            }
            persistent_container_runtime_projection(
                runtime,
                engine,
                &container_name,
                task_name,
                &fixed_expected_host_ports,
                env_overrides,
            )?
        }
        Err(error) => return Err(error),
    };
    let readiness_probe = start_runtime_readiness_probe(
        contract,
        runtime,
        resolved_runtime.as_ref(),
        matches!(mode, TaskExecutionMode::Stream { .. }),
        None,
        current_run_interrupt_epoch(),
    );
    let mut output = exec_persistent_container_task_command(
        task_name,
        runtime,
        command,
        &resolved_env,
        path_export,
        secret_env_names,
        engine,
        mode.clone(),
        &container_name,
        readiness_probe.as_ref(),
    )?;
    let readiness_outcome = readiness_probe
        .map(RuntimeReadinessProbe::stop_and_collect)
        .unwrap_or(RuntimeReadinessProbeOutcome {
            observed: false,
            budget_exhausted: false,
            report: None,
        });
    let termination_state = (!runtime
        .is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service))
    .then(|| inspect_container_termination_state(task_name, engine, &container_name))
    .flatten();
    output.service_termination = classify_container_service_termination(
        runtime,
        resolved_runtime.as_ref(),
        readiness_outcome.observed,
        readiness_outcome.budget_exhausted,
        readiness_outcome.report.clone(),
        termination_state.as_ref(),
        output.exit_code,
        output.interrupted,
        &container_name,
    );
    if output.service_termination.is_some() && output.exit_code == 0 {
        output.exit_code = 1;
    }
    output.execution_note = merge_execution_note(
        output.execution_note,
        output
            .service_termination
            .as_ref()
            .map(service_termination_execution_note),
    );
    if should_cleanup_interrupted_persistent_service_workload(output.service_termination.as_ref()) {
        output.execution_note = merge_execution_note(
            output.execution_note,
            cleanup_interrupted_persistent_service_workload_and_note(
                task_name,
                engine,
                &container_name,
                runtime,
            ),
        );
    }
    if output.exit_code != 0 && persistent_container_exec_hit_stopped_container(&output.stderr) {
        let remove = remove_persistent_container(engine, &container_name, task_name)?;
        if remove.exit_code != 0 {
            return Ok(container_command_failure(remove, container_name.clone()));
        }
        match ensure_persistent_container_ready(
            task_name,
            working_dir,
            context_name,
            repo_ownership_token,
            image,
            engine,
            &container_name,
            family_token.as_str(),
            shape_token.as_str(),
            compose_networks,
            memory_bytes,
            publications,
            listener_publications,
            dependency_isolation_paths,
        )? {
            PersistentContainerEnsureResult::Ready(_) => {
                reconciliation = PersistentContainerReconciliation::recreated(
                    "container stopped and was recreated before exec",
                );
            }
            PersistentContainerEnsureResult::Failure(failure) => {
                return Ok(failure);
            }
        }
        let (resolved_runtime, resolved_env) = persistent_container_runtime_projection(
            runtime,
            engine,
            &container_name,
            task_name,
            &fixed_expected_host_ports,
            env_overrides,
        )?;
        let readiness_probe = start_runtime_readiness_probe(
            contract,
            runtime,
            resolved_runtime.as_ref(),
            matches!(mode, TaskExecutionMode::Stream { .. }),
            None,
            current_run_interrupt_epoch(),
        );
        let mut output = exec_persistent_container_task_command(
            task_name,
            runtime,
            command,
            &resolved_env,
            path_export,
            secret_env_names,
            engine,
            mode.clone(),
            &container_name,
            readiness_probe.as_ref(),
        )?;
        let readiness_outcome = readiness_probe
            .map(RuntimeReadinessProbe::stop_and_collect)
            .unwrap_or(RuntimeReadinessProbeOutcome {
                observed: false,
                budget_exhausted: false,
                report: None,
            });
        let termination_state = (!runtime
            .is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service))
        .then(|| inspect_container_termination_state(task_name, engine, &container_name))
        .flatten();
        output.service_termination = classify_container_service_termination(
            runtime,
            resolved_runtime.as_ref(),
            readiness_outcome.observed,
            readiness_outcome.budget_exhausted,
            readiness_outcome.report.clone(),
            termination_state.as_ref(),
            output.exit_code,
            output.interrupted,
            &container_name,
        );
        if output.service_termination.is_some() && output.exit_code == 0 {
            output.exit_code = 1;
        }
        output.execution_note = merge_execution_note(
            output.execution_note,
            output
                .service_termination
                .as_ref()
                .map(service_termination_execution_note),
        );
        if should_cleanup_interrupted_persistent_service_workload(
            output.service_termination.as_ref(),
        ) {
            output.execution_note = merge_execution_note(
                output.execution_note,
                cleanup_interrupted_persistent_service_workload_and_note(
                    task_name,
                    engine,
                    &container_name,
                    runtime,
                ),
            );
        }
        return Ok(TaskCommandOutput {
            runtime: resolved_runtime,
            execution_note: merge_execution_note(
                Some(reconciliation.note()),
                output.execution_note,
            ),
            ..output
        });
    }

    Ok(TaskCommandOutput {
        runtime: resolved_runtime,
        execution_note: merge_execution_note(Some(reconciliation.note()), output.execution_note),
        ..output
    })
}

enum PersistentContainerEnsureResult {
    Ready(PersistentContainerReconciliation),
    Failure(TaskCommandOutput),
}

fn fixed_listener_host_ports(
    listener_publications: &[(String, ContainerPortPublication)],
) -> BTreeMap<String, u16> {
    listener_publications
        .iter()
        .filter_map(|(listener_name, publication)| {
            (publication.host_port_mode == TaskRuntimeHostPortMode::Fixed).then_some(
                publication
                    .host_port
                    .map(|port| (listener_name.clone(), port)),
            )
        })
        .flatten()
        .collect()
}

fn persistent_container_runtime_projection(
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    engine: &str,
    container_name: &str,
    task_name: &str,
    expected_host_ports: &BTreeMap<String, u16>,
    env_overrides: &BTreeMap<String, String>,
) -> Result<(Option<ResolvedTaskRuntime>, BTreeMap<String, String>), RunError> {
    let resolved_runtime = resolve_container_task_runtime(
        runtime,
        engine,
        container_name,
        task_name,
        expected_host_ports,
    )?;
    let mut resolved_env = env_overrides.clone();
    if let Some(runtime) = resolved_runtime.as_ref() {
        resolved_env.extend(runtime_public_env_from_resolved_runtime(runtime));
        extend_missing_env(
            &mut resolved_env,
            runtime_bind_env_from_resolved_runtime(runtime),
        );
    }
    Ok((resolved_runtime, resolved_env))
}

fn persistent_runtime_projection_host_port_mismatch(error: &RunError) -> bool {
    matches!(
        error,
        RunError::RuntimeListenerResolutionFailed {
            kind: RuntimeListenerResolutionKind::HostPublication(
                RuntimeListenerHostPublicationFailure::MismatchedPublishedPort { .. }
            ),
            ..
        }
    )
}

fn ensure_persistent_container_ready(
    task_name: &str,
    working_dir: &Path,
    context_name: Option<&str>,
    repo_ownership_token: &str,
    image: &str,
    engine: &str,
    container_name: &str,
    family_token: &str,
    shape_token: &str,
    compose_networks: &[String],
    memory_bytes: Option<u64>,
    publications: &[ContainerPortPublication],
    listener_publications: &[(String, ContainerPortPublication)],
    dependency_isolation_paths: &[String],
) -> Result<PersistentContainerEnsureResult, RunError> {
    let removed_drifted_family = reconcile_persistent_container_family(
        task_name,
        working_dir,
        engine,
        repo_ownership_token,
        container_name,
        family_token,
        shape_token,
        listener_publications,
    )?;

    let inspect = container_command_output(engine, &["inspect", container_name], None, task_name)?;
    if inspect.exit_code != 0 {
        let status = create_persistent_container(
            task_name,
            working_dir,
            context_name,
            repo_ownership_token,
            image,
            engine,
            container_name,
            family_token,
            shape_token,
            compose_networks,
            memory_bytes,
            publications,
            listener_publications,
            dependency_isolation_paths,
        )?;
        if status.exit_code != 0 {
            return Ok(PersistentContainerEnsureResult::Failure(
                container_command_failure(status, container_name.to_string()),
            ));
        }
        if let Some(failure) =
            ensure_container_networks(engine, container_name, compose_networks, task_name)?
        {
            return Ok(PersistentContainerEnsureResult::Failure(
                container_command_failure(failure, container_name.to_string()),
            ));
        }
        return Ok(PersistentContainerEnsureResult::Ready(
            if removed_drifted_family {
                PersistentContainerReconciliation::recreated("execution shape changed")
            } else {
                PersistentContainerReconciliation::created()
            },
        ));
    }

    let existing_labels = persistent_container_labels_for_name(task_name, engine, container_name)?;
    let recreate_due_to_current_shape_drift = existing_labels
        .get(OTA_PERSISTENT_CONTAINER_FAMILY_LABEL_KEY)
        .is_some_and(|label| label == family_token)
        && existing_labels
            .get(OTA_PERSISTENT_CONTAINER_SHAPE_LABEL_KEY)
            .is_none_or(|label| label != shape_token);
    if recreate_due_to_current_shape_drift {
        let remove = remove_persistent_container(engine, container_name, task_name)?;
        if remove.exit_code != 0 {
            return Ok(PersistentContainerEnsureResult::Failure(
                container_command_failure(remove, container_name.to_string()),
            ));
        }
        let create = create_persistent_container(
            task_name,
            working_dir,
            context_name,
            repo_ownership_token,
            image,
            engine,
            container_name,
            family_token,
            shape_token,
            compose_networks,
            memory_bytes,
            publications,
            listener_publications,
            dependency_isolation_paths,
        )?;
        if create.exit_code != 0 {
            if let Some(port) = parse_container_host_port_conflict(&create.stderr)
                && let Some((listener_name, publication)) = listener_publications
                    .iter()
                    .find(|(_, publication)| publication.host_port == Some(port))
            {
                return Err(RunError::HostPublicationConflict {
                    task: task_name.to_string(),
                    listener: listener_name.clone(),
                    address: publication.host_address.clone(),
                    port,
                });
            }
            return Ok(PersistentContainerEnsureResult::Failure(
                container_command_failure(create, container_name.to_string()),
            ));
        }
        if let Some(failure) =
            ensure_container_networks(engine, container_name, compose_networks, task_name)?
        {
            return Ok(PersistentContainerEnsureResult::Failure(
                container_command_failure(failure, container_name.to_string()),
            ));
        }
        return Ok(PersistentContainerEnsureResult::Ready(
            PersistentContainerReconciliation::recreated("execution shape changed"),
        ));
    }

    match persistent_container_running(engine, container_name, task_name)? {
        Some(true) => {
            if let Some(failure) =
                ensure_container_networks(engine, container_name, compose_networks, task_name)?
            {
                return Ok(PersistentContainerEnsureResult::Failure(
                    container_command_failure(failure, container_name.to_string()),
                ));
            }
            return Ok(PersistentContainerEnsureResult::Ready(
                PersistentContainerReconciliation::reused(),
            ));
        }
        Some(false) => {
            let remove = remove_persistent_container(engine, container_name, task_name)?;
            if remove.exit_code != 0 {
                return Ok(PersistentContainerEnsureResult::Failure(
                    container_command_failure(remove, container_name.to_string()),
                ));
            }
            let create = create_persistent_container(
                task_name,
                working_dir,
                context_name,
                repo_ownership_token,
                image,
                engine,
                container_name,
                family_token,
                shape_token,
                compose_networks,
                memory_bytes,
                publications,
                listener_publications,
                dependency_isolation_paths,
            )?;
            if create.exit_code != 0 {
                if let Some(port) = parse_container_host_port_conflict(&create.stderr)
                    && let Some((listener_name, publication)) = listener_publications
                        .iter()
                        .find(|(_, publication)| publication.host_port == Some(port))
                {
                    return Err(RunError::HostPublicationConflict {
                        task: task_name.to_string(),
                        listener: listener_name.clone(),
                        address: publication.host_address.clone(),
                        port,
                    });
                }
                return Ok(PersistentContainerEnsureResult::Failure(
                    container_command_failure(create, container_name.to_string()),
                ));
            }
            if let Some(failure) =
                ensure_container_networks(engine, container_name, compose_networks, task_name)?
            {
                return Ok(PersistentContainerEnsureResult::Failure(
                    container_command_failure(failure, container_name.to_string()),
                ));
            }
            return Ok(PersistentContainerEnsureResult::Ready(
                PersistentContainerReconciliation::recreated(
                    "existing container was stopped before execution",
                ),
            ));
        }
        None => {}
    }

    let status = container_command_output(engine, &["start", container_name], None, task_name)?;
    if status.exit_code != 0 {
        return Ok(PersistentContainerEnsureResult::Failure(
            container_command_failure(status, container_name.to_string()),
        ));
    }

    if let Some(failure) =
        ensure_container_networks(engine, container_name, compose_networks, task_name)?
    {
        return Ok(PersistentContainerEnsureResult::Failure(
            container_command_failure(failure, container_name.to_string()),
        ));
    }

    Ok(PersistentContainerEnsureResult::Ready(
        PersistentContainerReconciliation::reused_with_reason("existing container was started"),
    ))
}

fn reconcile_persistent_container_family(
    task_name: &str,
    working_dir: &Path,
    engine: &str,
    repo_ownership_token: &str,
    desired_container_name: &str,
    family_token: &str,
    shape_token: &str,
    listener_publications: &[(String, ContainerPortPublication)],
) -> Result<bool, RunError> {
    let mut candidate_names = BTreeSet::new();
    candidate_names.extend(
        persistent_container_names_for_repo(task_name, engine, repo_ownership_token)?.into_iter(),
    );
    let legacy_candidates =
        repo_scoped_legacy_persistent_container_names(task_name, engine, working_dir)?;
    let legacy_candidate_names = legacy_candidates.into_iter().collect::<BTreeSet<_>>();
    candidate_names.extend(legacy_candidate_names.iter().cloned());

    let mut removed = false;
    for container_name in candidate_names {
        if container_name == desired_container_name {
            continue;
        }
        let labels = persistent_container_labels_for_name(task_name, engine, &container_name)?;
        let remove_due_to_family_drift = labels
            .get(OTA_PERSISTENT_CONTAINER_FAMILY_LABEL_KEY)
            .is_some_and(|label| label == family_token)
            && labels
                .get(OTA_PERSISTENT_CONTAINER_SHAPE_LABEL_KEY)
                .is_none_or(|label| label != shape_token);
        let remove_due_to_legacy_conflict = legacy_candidate_names.contains(&container_name)
            && legacy_container_conflicts_with_listener_publications(
                task_name,
                engine,
                &container_name,
                listener_publications,
            )?;
        if remove_due_to_family_drift || remove_due_to_legacy_conflict {
            let remove = remove_persistent_container(engine, &container_name, task_name)?;
            if remove.exit_code != 0 {
                let details = if !remove.stderr.trim().is_empty() {
                    remove.stderr.trim().to_string()
                } else if !remove.stdout.trim().is_empty() {
                    remove.stdout.trim().to_string()
                } else {
                    format!(
                        "`{engine} rm -f {container_name}` exited with {}",
                        remove.exit_code
                    )
                };
                return Err(RunError::PersistentContainerCleanupFailure {
                    task: task_name.to_string(),
                    action: String::from("remove"),
                    container: container_name,
                    engine: engine.to_string(),
                    details,
                });
            }
            removed = true;
        }
    }

    Ok(removed)
}

fn legacy_container_conflicts_with_listener_publications(
    task_name: &str,
    engine: &str,
    container_name: &str,
    listener_publications: &[(String, ContainerPortPublication)],
) -> Result<bool, RunError> {
    for (_, publication) in listener_publications {
        if publication.host_port_mode != TaskRuntimeHostPortMode::Fixed {
            continue;
        }
        let Some(expected_host_port) = publication.host_port else {
            continue;
        };
        let actual_host_port = container_published_port(
            engine,
            container_name,
            publication.bind_port,
            publication.protocol,
            task_name,
        )?;
        if actual_host_port == Some(expected_host_port) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn repo_scoped_legacy_persistent_container_names(
    task_name: &str,
    engine: &str,
    working_dir: &Path,
) -> Result<Vec<String>, RunError> {
    let names = container_ps_names(engine, &["ps", "-a", "--format", "{{.Names}}"])?;
    let mut legacy = Vec::new();
    for container_name in names {
        let labels = persistent_container_labels_for_name(task_name, engine, &container_name)?;
        if labels.contains_key(OTA_REPO_CONTAINER_LABEL_KEY) {
            continue;
        }
        let looks_like_legacy_ota_name =
            container_name.starts_with("ota-") && !container_name.starts_with("ota-ephemeral-");
        let is_managed_persistent_without_repo = labels
            .get("dev.ota.managed")
            .is_some_and(|value| value == "true")
            && labels
                .get("dev.ota.lifecycle")
                .is_some_and(|value| value == "persistent");
        if !looks_like_legacy_ota_name && !is_managed_persistent_without_repo {
            continue;
        }
        let Some(workspace_source) =
            persistent_container_workspace_source_for_name(task_name, engine, &container_name)?
        else {
            continue;
        };
        if workspace_source_matches_repo(&workspace_source, working_dir) {
            legacy.push(container_name);
        }
    }
    Ok(legacy)
}

fn persistent_container_labels_for_name(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Result<BTreeMap<String, String>, RunError> {
    let args = ["inspect", "-f", "{{json .Config.Labels}}", container_name];
    let output = container_command_output(engine, &args, None, task_name)?;
    if output.exit_code != 0 {
        return Err(RunError::PersistentContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &output),
        });
    }

    let stdout = output.stdout.trim();
    if stdout.is_empty() || stdout == "null" {
        return Ok(BTreeMap::new());
    }

    let labels_value: serde_json::Value = serde_json::from_str(stdout).map_err(|source| {
        RunError::PersistentContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details: format!("invalid `inspect` labels JSON response: {source}"),
        }
    })?;

    let Some(labels_object) = labels_value.as_object() else {
        return Ok(BTreeMap::new());
    };

    let mut labels = BTreeMap::new();
    for (key, value) in labels_object {
        if let Some(value) = value.as_str() {
            labels.insert(key.to_string(), value.to_string());
        }
    }
    Ok(labels)
}

fn persistent_container_workspace_source_for_name(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Result<Option<String>, RunError> {
    let args = ["inspect", "-f", "{{json .Mounts}}", container_name];
    let output = container_command_output(engine, &args, None, task_name)?;
    if output.exit_code != 0 {
        return Err(RunError::PersistentContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &output),
        });
    }

    let stdout = output.stdout.trim();
    if stdout.is_empty() || stdout == "null" {
        return Ok(None);
    }
    let mounts_value: serde_json::Value = serde_json::from_str(stdout).map_err(|source| {
        RunError::PersistentContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details: format!("invalid `inspect` mounts JSON response: {source}"),
        }
    })?;
    let Some(mounts_array) = mounts_value.as_array() else {
        return Ok(None);
    };
    for mount in mounts_array {
        let Some(mount_object) = mount.as_object() else {
            continue;
        };
        let Some(destination) = mount_object
            .get("Destination")
            .and_then(|value| value.as_str())
        else {
            continue;
        };
        if destination != "/workspace" {
            continue;
        }
        if let Some(source) = mount_object.get("Source").and_then(|value| value.as_str()) {
            return Ok(Some(source.to_string()));
        }
    }
    Ok(None)
}

fn container_attached_volume_names(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Result<BTreeSet<String>, RunError> {
    let args = ["inspect", "-f", "{{json .Mounts}}", container_name];
    let output = container_command_output(engine, &args, None, task_name)?;
    if output.exit_code != 0 {
        return Err(RunError::PersistentContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &output),
        });
    }

    let stdout = output.stdout.trim();
    if stdout.is_empty() || stdout == "null" {
        return Ok(BTreeSet::new());
    }
    let mounts_value: serde_json::Value = serde_json::from_str(stdout).map_err(|source| {
        RunError::PersistentContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details: format!("invalid `inspect` mounts JSON response: {source}"),
        }
    })?;
    let Some(mounts_array) = mounts_value.as_array() else {
        return Ok(BTreeSet::new());
    };

    let mut volume_names = BTreeSet::new();
    for mount in mounts_array {
        let Some(mount_object) = mount.as_object() else {
            continue;
        };
        if mount_object
            .get("Type")
            .and_then(|value| value.as_str())
            .is_some_and(|kind| kind != "volume")
        {
            continue;
        }
        if let Some(volume_name) = mount_object.get("Name").and_then(|value| value.as_str()) {
            volume_names.insert(volume_name.to_string());
        }
    }
    Ok(volume_names)
}

fn containers_attached_to_dependency_isolation_volumes(
    task_name: &str,
    engine: &str,
    volume_names: &BTreeSet<String>,
) -> Result<Vec<String>, RunError> {
    if volume_names.is_empty() {
        return Ok(Vec::new());
    }

    let container_names = container_ps_names(engine, &["ps", "-a", "--format", "{{.Names}}"])?;
    let mut attached = Vec::new();
    for container_name in container_names {
        let mounted_volume_names =
            container_attached_volume_names(task_name, engine, &container_name)?;
        if mounted_volume_names
            .iter()
            .any(|volume_name| volume_names.contains(volume_name))
        {
            attached.push(container_name);
        }
    }
    Ok(attached)
}

fn workspace_source_matches_repo(source: &str, working_dir: &Path) -> bool {
    let source_path = Path::new(source);
    if source_path == working_dir {
        return true;
    }
    match (fs::canonicalize(source_path), fs::canonicalize(working_dir)) {
        (Ok(source_canonical), Ok(working_canonical)) => source_canonical == working_canonical,
        _ => source_path == working_dir,
    }
}

fn create_persistent_container(
    task_name: &str,
    working_dir: &Path,
    context_name: Option<&str>,
    repo_ownership_token: &str,
    image: &str,
    engine: &str,
    container_name: &str,
    family_token: &str,
    shape_token: &str,
    compose_networks: &[String],
    memory_bytes: Option<u64>,
    publications: &[ContainerPortPublication],
    listener_publications: &[(String, ContainerPortPublication)],
    dependency_isolation_paths: &[String],
) -> Result<ContainerCommandOutput, RunError> {
    preflight_container_host_publications(task_name, listener_publications)?;
    record_repo_managed_engine(task_name, working_dir, engine)?;
    let workspace_mount_source = container_workspace_mount_source(working_dir);
    let mut args = vec![
        "run".to_string(),
        "-d".to_string(),
        "--name".to_string(),
        container_name.to_string(),
        "--label".to_string(),
        OTA_MANAGED_CONTAINER_LABEL.to_string(),
        "--label".to_string(),
        OTA_PERSISTENT_CONTAINER_LABEL.to_string(),
        "--label".to_string(),
        format!("{OTA_REPO_CONTAINER_LABEL_KEY}={repo_ownership_token}"),
        "--label".to_string(),
        format!("{OTA_PERSISTENT_CONTAINER_FAMILY_LABEL_KEY}={family_token}"),
        "--label".to_string(),
        format!("{OTA_PERSISTENT_CONTAINER_SHAPE_LABEL_KEY}={shape_token}"),
        "--entrypoint".to_string(),
        "sh".to_string(),
        "-v".to_string(),
        container_workspace_mount_arg(&workspace_mount_source),
        "-w".to_string(),
        "/workspace".to_string(),
    ];
    if let Some(network) = compose_networks.first() {
        args.push("--network".to_string());
        args.push(network.clone());
    }
    append_container_host_user_vec(&mut args);
    append_container_host_user_home_vec(&mut args);
    for (volume_name, container_path) in container_dependency_isolation_mounts(
        task_name,
        working_dir,
        context_name,
        image,
        engine,
        repo_ownership_token,
        dependency_isolation_paths,
    )? {
        args.push("-v".to_string());
        args.push(format!("{volume_name}:{container_path}"));
    }
    append_container_publication_vec(&mut args, publications);
    append_container_memory_vec(&mut args, memory_bytes);
    append_container_git_safe_directory_vec(&mut args);
    args.push(image.to_string());
    args.push("-lc".to_string());
    args.push("while true; do sleep 3600; done".to_string());
    let arg_refs = args.iter().map(String::as_str).collect::<Vec<_>>();
    container_command_output(engine, &arg_refs, None, task_name)
}

fn append_container_publication_args(
    command: &mut Command,
    publications: &[ContainerPortPublication],
) {
    for publication in publications {
        command
            .arg("-p")
            .arg(container_publication_arg(publication));
    }
}

fn append_container_publication_vec(
    args: &mut Vec<String>,
    publications: &[ContainerPortPublication],
) {
    for publication in publications {
        args.push("-p".to_string());
        args.push(container_publication_arg(publication));
    }
}

fn append_container_memory_arg(command: &mut Command, memory_bytes: Option<u64>) {
    if let Some(memory_bytes) = memory_bytes {
        command.arg("--memory").arg(memory_bytes.to_string());
    }
}

fn append_container_memory_vec(args: &mut Vec<String>, memory_bytes: Option<u64>) {
    if let Some(memory_bytes) = memory_bytes {
        args.push("--memory".to_string());
        args.push(memory_bytes.to_string());
    }
}

fn append_container_host_user_arg(command: &mut Command) {
    if let Some(user_spec) = container_host_user_spec() {
        command.arg("--user").arg(user_spec);
    }
}

fn append_container_host_user_home_arg(
    command: &mut Command,
    env_overrides: &BTreeMap<String, String>,
) {
    if container_host_user_spec().is_some() && !env_overrides.contains_key("HOME") {
        command.arg("--env").arg("HOME=/tmp");
    }
}

fn append_container_host_user_vec(args: &mut Vec<String>) {
    if let Some(user_spec) = container_host_user_spec() {
        args.push("--user".to_string());
        args.push(user_spec);
    }
}

fn append_container_host_user_home_vec(args: &mut Vec<String>) {
    if container_host_user_spec().is_some() {
        args.push("--env".to_string());
        args.push("HOME=/tmp".to_string());
    }
}

fn container_host_user_spec() -> Option<String> {
    CONTAINER_HOST_USER_SPEC_CACHE
        .get_or_init(resolve_container_host_user_spec)
        .clone()
}

#[cfg(not(unix))]
fn resolve_container_host_user_spec() -> Option<String> {
    None
}

#[cfg(unix)]
fn resolve_container_host_user_spec() -> Option<String> {
    let uid = shell_numeric_id("-u")?;
    let gid = shell_numeric_id("-g")?;
    if uid == "0" && gid == "0" {
        return None;
    }
    Some(format!("{uid}:{gid}"))
}

#[cfg(unix)]
fn shell_numeric_id(flag: &str) -> Option<String> {
    let output = Command::new("id")
        .arg(flag)
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let text = String::from_utf8(output.stdout).ok()?;
    let trimmed = text.trim();
    if trimmed.is_empty() || !trimmed.chars().all(|character| character.is_ascii_digit()) {
        return None;
    }
    Some(trimmed.to_string())
}

fn append_container_git_safe_directory_args(
    command: &mut Command,
    env_overrides: &BTreeMap<String, String>,
) {
    if !should_inject_container_git_safe_directory_env(env_overrides) {
        return;
    }
    command
        .arg("--env")
        .arg("GIT_CONFIG_COUNT=1")
        .arg("--env")
        .arg("GIT_CONFIG_KEY_0=safe.directory")
        .arg("--env")
        .arg("GIT_CONFIG_VALUE_0=/workspace");
}

fn append_container_git_safe_directory_vec(args: &mut Vec<String>) {
    args.push("--env".to_string());
    args.push("GIT_CONFIG_COUNT=1".to_string());
    args.push("--env".to_string());
    args.push("GIT_CONFIG_KEY_0=safe.directory".to_string());
    args.push("--env".to_string());
    args.push("GIT_CONFIG_VALUE_0=/workspace".to_string());
}

fn should_inject_container_git_safe_directory_env(
    env_overrides: &BTreeMap<String, String>,
) -> bool {
    !env_overrides.keys().any(|name| {
        name == "GIT_CONFIG_COUNT"
            || name.starts_with("GIT_CONFIG_KEY_")
            || name.starts_with("GIT_CONFIG_VALUE_")
    })
}

fn container_publication_arg(publication: &ContainerPortPublication) -> String {
    let transport = publication.protocol.network_protocol();
    match publication.host_port_mode {
        TaskRuntimeHostPortMode::Fixed => format!(
            "{}:{}:{}/{}",
            publication.host_address,
            publication
                .host_port
                .expect("validated fixed host publication should include a host port"),
            publication.bind_port,
            transport
        ),
        TaskRuntimeHostPortMode::Auto => format!(
            "{}::{}/{}",
            publication.host_address, publication.bind_port, transport
        ),
    }
}

fn resolve_container_task_runtime(
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    engine: &str,
    container_name: &str,
    task_name: &str,
    expected_host_ports: &BTreeMap<String, u16>,
) -> Result<Option<ResolvedTaskRuntime>, RunError> {
    let Some(runtime) = runtime else {
        return Ok(None);
    };

    let listeners = runtime
        .listeners
        .iter()
        .map(|(listener_name, listener)| {
            let bind_port = listener
                .bind
                .port
                .value
                .expect("validated container listener should have a fixed bind port");
            let resolved = match listener.project.host.as_ref() {
                Some(host) => {
                    let transport = listener.protocol.network_protocol();
                    let port = container_published_port(
                        engine,
                        container_name,
                        bind_port,
                        listener.protocol,
                        task_name,
                    )?
                    .ok_or_else(|| {
                        runtime_listener_host_publication_failed(
                            task_name,
                            listener_name,
                            container_name,
                            bind_port,
                            transport,
                        )
                    })?;
                    if let Some(expected_port) = expected_host_ports.get(listener_name)
                        && *expected_port != port
                    {
                        return Err(runtime_listener_host_publication_mismatch_failed(
                            task_name,
                            listener_name,
                            container_name,
                            bind_port,
                            transport,
                            *expected_port,
                            port,
                        ));
                    }
                    Some(ResolvedTaskRuntimeResolution {
                        host: Some(ResolvedTaskRuntimeHost {
                            address: host.address.trim().to_string(),
                            port,
                            url: listener.protocol.url_scheme().map(|scheme| {
                                format!(
                                    "{scheme}://{}:{port}{}",
                                    host.address.trim(),
                                    normalized_runtime_path(host.path.as_deref())
                                )
                            }),
                        }),
                    })
                }
                None => None,
            };

            Ok((
                listener_name.clone(),
                ResolvedTaskRuntimeListener {
                    protocol: listener.protocol,
                    bind: ResolvedTaskRuntimeBind {
                        address: listener.bind.address.trim().to_string(),
                        port: bind_port,
                    },
                    resolved,
                },
            ))
        })
        .collect::<Result<BTreeMap<_, _>, RunError>>()?;

    Ok(Some(build_resolved_runtime(runtime, listeners)))
}

fn container_published_port(
    engine: &str,
    container_name: &str,
    bind_port: u16,
    protocol: TaskRuntimeProtocol,
    task_name: &str,
) -> Result<Option<u16>, RunError> {
    let transport = protocol.network_protocol();
    let query = format!("{bind_port}/{transport}");
    let output =
        container_command_output(engine, &["port", container_name, &query], None, task_name)?;
    if output.exit_code != 0 {
        return Ok(None);
    }

    Ok(output
        .stdout
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .and_then(parse_published_port_line))
}

fn container_published_host_port_exists(
    task_name: &str,
    engine: &str,
    container_name: &str,
    host_port: u16,
) -> Result<bool, RunError> {
    let output = container_command_output(engine, &["port", container_name], None, task_name)?;
    if output.exit_code != 0 {
        return Ok(false);
    }

    Ok(output
        .stdout
        .lines()
        .filter_map(parse_container_port_output_host_port)
        .any(|published_host_port| published_host_port == host_port))
}

fn parse_container_port_output_host_port(value: &str) -> Option<u16> {
    let publication = value
        .split_once("->")
        .map(|(_, rhs)| rhs.trim())
        .unwrap_or_else(|| value.trim());
    parse_published_port_line(publication)
}

fn parse_published_port_line(value: &str) -> Option<u16> {
    let (_, port) = value.rsplit_once(':')?;
    port.trim().parse::<u16>().ok()
}

fn normalized_runtime_path(value: Option<&str>) -> String {
    match value.map(str::trim).filter(|value| !value.is_empty()) {
        Some(path) if path.starts_with('/') => path.to_string(),
        Some(path) => format!("/{path}"),
        None => String::from("/"),
    }
}

fn ensure_container_networks(
    engine: &str,
    container_name: &str,
    compose_networks: &[String],
    task_name: &str,
) -> Result<Option<ContainerCommandOutput>, RunError> {
    if compose_networks.is_empty() {
        return Ok(None);
    }

    let inspect = container_command_output(
        engine,
        &[
            "inspect",
            "-f",
            "{{json .NetworkSettings.Networks}}",
            container_name,
        ],
        None,
        task_name,
    )?;
    if inspect.exit_code != 0 {
        return Ok(Some(inspect));
    }

    let attached =
        serde_json::from_str::<serde_json::Map<String, serde_json::Value>>(inspect.stdout.trim())
            .map(|networks| networks.keys().cloned().collect::<BTreeSet<_>>())
            .unwrap_or_default();

    for network in compose_networks {
        if attached.contains(network) {
            continue;
        }

        let status = container_command_output(
            engine,
            &["network", "connect", network, container_name],
            None,
            task_name,
        )?;
        if status.exit_code != 0 && !container_network_already_connected(&status) {
            return Ok(Some(status));
        }
    }

    Ok(None)
}

fn container_network_already_connected(status: &ContainerCommandOutput) -> bool {
    let combined = format!("{}\n{}", status.stdout, status.stderr).to_ascii_lowercase();
    combined.contains("already exists")
        || combined.contains("already connected")
        || combined.contains("is already connected")
}

const EPHEMERAL_CONTAINER_REMOVE_MAX_ATTEMPTS: usize = 5;

fn ephemeral_container_remove_retry_delay(attempt: usize) -> Duration {
    let shift = attempt.min(4) as u32;
    let millis = 100u64.saturating_mul(1u64 << shift).min(1_000);
    Duration::from_millis(millis)
}

fn container_removal_already_in_progress(output: &ContainerCommandOutput) -> bool {
    let combined = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
    combined.contains("removal of container") && combined.contains("already in progress")
}

fn remove_persistent_container(
    engine: &str,
    container_name: &str,
    task_name: &str,
) -> Result<ContainerCommandOutput, RunError> {
    let args = ["rm", "-f", container_name];
    for attempt in 0..EPHEMERAL_CONTAINER_REMOVE_MAX_ATTEMPTS {
        let remove = container_command_output(engine, &args, None, task_name)?;
        if remove.exit_code == 0 {
            return Ok(remove);
        }
        if attempt + 1 < EPHEMERAL_CONTAINER_REMOVE_MAX_ATTEMPTS
            && container_removal_already_in_progress(&remove)
        {
            thread::sleep(ephemeral_container_remove_retry_delay(attempt));
            continue;
        }
        return Ok(remove);
    }

    container_command_output(engine, &args, None, task_name)
}

fn remove_ephemeral_container_and_note(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Option<String> {
    match remove_persistent_container(engine, container_name, task_name) {
        Ok(output) if output.exit_code == 0 => None,
        Ok(output) => Some(format!(
            "ephemeral container cleanup failed for `{container_name}`: {}",
            container_command_failure_details(engine, &["rm", "-f", container_name], &output)
        )),
        Err(error) => Some(format!(
            "ephemeral container cleanup failed for `{container_name}`: {error}"
        )),
    }
}

fn cleanup_interrupted_persistent_service_workload_and_note(
    task_name: &str,
    engine: &str,
    container_name: &str,
    runtime: Option<&TaskRuntimeSpec>,
) -> Option<String> {
    let pidfile = persistent_service_workload_pidfile_path(task_name);
    let fixed_bind_ports = runtime
        .into_iter()
        .flat_map(|runtime| runtime.listeners.values())
        .filter_map(|listener| {
            (listener.bind.port.mode == crate::schema::TaskRuntimePortMode::Fixed)
                .then_some(listener.bind.port.value)
                .flatten()
        })
        .collect::<Vec<_>>();
    let fixed_bind_ports_arg = fixed_bind_ports
        .iter()
        .map(u16::to_string)
        .collect::<Vec<_>>()
        .join(" ");
    let cleanup_script = r#"
pidfile=$1
ports=$2
cleaned=0

port_listening() {
  target="$1"
  awk -v port="$target" '
    BEGIN { found = 0 }
    NR > 1 {
      split($2, a, ":");
      if (($4 == "0A" || $4 == "0a") && (toupper(a[2]) == toupper(port) || a[2] == port)) {
        found = 1
        exit
      }
    }
    END { exit(found ? 0 : 1) }
  ' /proc/net/tcp /proc/net/tcp6 2>/dev/null
}

terminate_pid_tree() {
  pid="$1"
  [ -n "$pid" ] || return 0
  [ "$pid" = "$$" ] && return 0
  [ "$pid" = "1" ] && return 0
  [ -d "/proc/$pid" ] || kill -0 "$pid" 2>/dev/null || return 0
  children=$(cat "/proc/$pid/task/$pid/children" 2>/dev/null || pgrep -P "$pid" 2>/dev/null || true)
  for child in $children; do terminate_pid_tree "$child"; done
  kill -TERM "$pid" 2>/dev/null || true
  sleep 0.2
  i=0
  while kill -0 "$pid" 2>/dev/null && [ "$i" -lt 30 ]; do
    i=$((i + 1))
    sleep 0.1
  done
  if kill -0 "$pid" 2>/dev/null; then
    kill -KILL "$pid" 2>/dev/null || true
    sleep 0.5
  fi
  return 0
}

cleanup_pidfile_owner() {
  [ -s "$pidfile" ] || return 0
  read pid started < "$pidfile" || { rm -f "$pidfile"; return 0; }
  [ -n "$pid" ] || { rm -f "$pidfile"; return 0; }
  if [ -z "$started" ]; then
    cleanup_unverified_failed=0
    if kill -0 "$pid" 2>/dev/null; then
      pid_owns_listener=0
      if [ -n "$ports" ]; then
        for port in $ports; do
          hex=$(printf '%04X' "$port")
          owners=$(find_listener_owner_pids "$hex" "$port")
          for owner in $owners; do
            if [ "$owner" = "$pid" ]; then
              pid_owns_listener=1
              break
            fi
          done
          [ "$pid_owns_listener" = "1" ] && break
        done
      fi
      if [ "$pid_owns_listener" = "1" ]; then
        terminate_pid_tree "$pid"
        cleaned=1
      else
        cleanup_unverified_failed=1
      fi
    fi
    rm -f "$pidfile"
    [ "$cleanup_unverified_failed" = "1" ] && return 1
    return 0
  fi
  current=$(cut -d' ' -f22 "/proc/$pid/stat" 2>/dev/null || true)
  if [ -z "$current" ] || [ "$current" != "$started" ]; then
    rm -f "$pidfile"
    cleaned=1
    return 0
  fi
  terminate_pid_tree "$pid"
  cleaned=1
  rm -f "$pidfile"
}

find_listener_owner_pids() {
  target_hex="$1"
  target_port="$2"
  owners=""
  if command -v ss >/dev/null 2>&1; then
    ss_pids=$(ss -Htnlp "sport = :$target_port" 2>/dev/null | sed -n 's/.*pid=\([0-9][0-9]*\).*/\1/p' | sort -u || true)
    for pid in $ss_pids; do
      [ "$pid" = "$$" ] && continue
      [ "$pid" = "1" ] && continue
      case " $owners " in
        *" $pid "*) ;;
        *) owners="$owners $pid" ;;
      esac
    done
  fi
  if [ -z "$owners" ] && command -v lsof >/dev/null 2>&1; then
    lsof_pids=$(lsof -nP -iTCP:"$target_port" -sTCP:LISTEN -t 2>/dev/null || true)
    for pid in $lsof_pids; do
      [ "$pid" = "$$" ] && continue
      [ "$pid" = "1" ] && continue
      case " $owners " in
        *" $pid "*) ;;
        *) owners="$owners $pid" ;;
      esac
    done
  fi
  if [ -z "$owners" ]; then
    inodes=$(awk -v target="$target_hex" '
      BEGIN { found = 0 }
      NR > 1 {
        split($2, a, ":");
        if (($4 == "0A" || $4 == "0a") && (toupper(a[2]) == toupper(target) || a[2] == target)) {
          print $10
          found = 1
        }
      }
      END { if (!found) exit 1 }
    ' /proc/net/tcp /proc/net/tcp6 2>/dev/null | sort -u || true)
    if [ -n "$inodes" ]; then
      for inode in $inodes; do
        for fd in /proc/[0-9]*/fd/*; do
          [ -e "$fd" ] || continue
          link=$(readlink "$fd" 2>/dev/null || true)
          [ "$link" = "socket:[$inode]" ] || continue
          pid=${fd#/proc/}
          pid=${pid%%/*}
          [ "$pid" = "$$" ] && continue
          [ "$pid" = "1" ] && continue
          case " $owners " in
            *" $pid "*) ;;
            *) owners="$owners $pid" ;;
          esac
        done
      done
    fi
  fi
  if [ -z "$owners" ] && command -v fuser >/dev/null 2>&1; then
    fuser_pids=$(fuser -n tcp "$target_port" 2>/dev/null | awk '{for (i = 1; i <= NF; i++) if ($i ~ /^[0-9]+$/) print $i}')
    for pid in $fuser_pids; do
      [ "$pid" = "$$" ] && continue
      [ "$pid" = "1" ] && continue
      case " $owners " in
        *" $pid "*) ;;
        *) owners="$owners $pid" ;;
      esac
    done
  fi
  printf '%s\n' "$owners"
}

cleanup_listener_owners() {
  [ -n "$ports" ] || return 0
  attempt=0
  while [ "$attempt" -lt 20 ]; do
    for port in $ports; do
      hex=$(printf '%04X' "$port")
      owners=$(find_listener_owner_pids "$hex" "$port")
      for pid in $owners; do
        terminate_pid_tree "$pid"
        cleaned=1
      done
    done
    all_free=1
    for port in $ports; do
      hex=$(printf '%04X' "$port")
      if port_listening "$hex"; then
        all_free=0
        break
      fi
    done
    [ "$all_free" = "1" ] && return 0
    attempt=$((attempt + 1))
    sleep 0.1
  done

  if command -v fuser >/dev/null 2>&1; then
    for port in $ports; do
      fallback_pids=$(fuser -n tcp "$port" 2>/dev/null | awk '{for (i = 1; i <= NF; i++) if ($i ~ /^[0-9]+$/) print $i}')
      for pid in $fallback_pids; do
        terminate_pid_tree "$pid"
        cleaned=1
      done
    done
  fi

  for port in $ports; do
    hex=$(printf '%04X' "$port")
    if port_listening "$hex"; then
      final_owner_pids=$(find_listener_owner_pids "$hex" "$port")
      if [ -n "$final_owner_pids" ]; then
        lingering=1
        break
      fi
    fi
  done

  [ "$lingering" = "1" ] && return 1
  return 0
}

cleanup_pidfile_owner
cleanup_listener_owners
cleanup_listener_owners_status=$?
if [ "$cleaned" = "1" ] || [ "$cleanup_listener_owners_status" -eq 0 ]; then
  [ "$cleaned" = "1" ] && printf cleaned
  exit 0
fi
exit 1
"#;
    match container_command_output_with_stdin(
        engine,
        &[
            "exec",
            "-i",
            container_name,
            "sh",
            "-s",
            "--",
            &pidfile,
            &fixed_bind_ports_arg,
        ],
        cleanup_script,
        None,
        task_name,
    ) {
        Ok(output) if output.exit_code == 0 && output.stdout.contains("cleaned") => Some(
            String::from("interrupted service workload cleaned up inside persistent backend"),
        ),
        Ok(output) if output.exit_code == 0 => None,
        Ok(output) if output.stdout.contains("cleaned") => Some(String::from(
            "interrupted service workload cleaned up inside persistent backend",
        )),
        Ok(_) => {
            let ports_note = fixed_bind_ports
                .iter()
                .map(u16::to_string)
                .collect::<Vec<_>>()
                .join(", ");
            let port_note = if ports_note.is_empty() {
                String::new()
            } else {
                format!("; fixed listener port(s) {ports_note} remained in use")
            };
            Some(format!(
                "interrupted service workload cleanup failed in `{container_name}`{port_note}"
            ))
        }
        Err(error) => Some(format!(
            "interrupted service workload cleanup failed in `{container_name}`: {error}"
        )),
    }
}

fn cleanup_interrupted_native_service_workload_and_note(
    task_name: &str,
    runtime: Option<&TaskRuntimeSpec>,
) -> Option<String> {
    #[cfg(not(unix))]
    {
        let _ = (task_name, runtime);
        return None;
    }

    #[cfg(unix)]
    {
        let pidfile = persistent_service_workload_pidfile_path(task_name);
        let fixed_bind_ports = runtime
            .into_iter()
            .flat_map(|runtime| runtime.listeners.values())
            .filter_map(|listener| {
                (listener.bind.port.mode == crate::schema::TaskRuntimePortMode::Fixed)
                    .then_some(listener.bind.port.value)
                    .flatten()
            })
            .collect::<Vec<_>>();
        let fixed_bind_ports_arg = fixed_bind_ports
            .iter()
            .map(u16::to_string)
            .collect::<Vec<_>>()
            .join(" ");
        let cleanup_script = r#"
pidfile=$1
ports=$2
cleaned=0
port_listening() {
  target="$1"
  awk -v port="$target" '
    BEGIN { found = 0 }
    NR > 1 {
      split($2, a, ":");
      if (($4 == "0A" || $4 == "0a") && (toupper(a[2]) == toupper(port) || a[2] == port)) {
        found = 1
        exit
      }
    }
    END { exit(found ? 0 : 1) }
  ' /proc/net/tcp /proc/net/tcp6 2>/dev/null
}
terminate_pid_tree() {
  pid="$1"
  [ -n "$pid" ] || return 0
  [ "$pid" = "$$" ] && return 0
  [ "$pid" = "1" ] && return 0
  [ -d "/proc/$pid" ] || kill -0 "$pid" 2>/dev/null || return 0
  children=$(cat "/proc/$pid/task/$pid/children" 2>/dev/null || pgrep -P "$pid" 2>/dev/null || true)
  for child in $children; do terminate_pid_tree "$child"; done
  kill -TERM "$pid" 2>/dev/null || true
  sleep 0.2
  i=0
  while kill -0 "$pid" 2>/dev/null && [ "$i" -lt 30 ]; do i=$((i + 1)); sleep 0.1; done
  if kill -0 "$pid" 2>/dev/null; then
    kill -KILL "$pid" 2>/dev/null || true
    sleep 0.5
  fi
}
find_listener_owner_pids() {
  target_hex="$1"
  target_port="$2"
  owners=""
  if command -v ss >/dev/null 2>&1; then
    ss_pids=$(ss -Htnlp "sport = :$target_port" 2>/dev/null | sed -n 's/.*pid=\([0-9][0-9]*\).*/\1/p' | sort -u || true)
    for pid in $ss_pids; do
      [ "$pid" = "$$" ] && continue
      [ "$pid" = "1" ] && continue
      case " $owners " in *" $pid "*) ;; *) owners="$owners $pid" ;; esac
    done
  fi
  if [ -z "$owners" ] && command -v lsof >/dev/null 2>&1; then
    lsof_pids=$(lsof -nP -iTCP:"$target_port" -sTCP:LISTEN -t 2>/dev/null || true)
    for pid in $lsof_pids; do
      [ "$pid" = "$$" ] && continue
      [ "$pid" = "1" ] && continue
      case " $owners " in *" $pid "*) ;; *) owners="$owners $pid" ;; esac
    done
  fi
  if [ -z "$owners" ] && [ -r /proc/net/tcp ]; then
    inodes=$(awk -v port="$target_hex" '
      NR > 1 {
        split($2, a, ":")
        if (($4 == "0A" || $4 == "0a") && toupper(a[2]) == toupper(port)) {
          print $10
        }
      }
    ' /proc/net/tcp /proc/net/tcp6 2>/dev/null | sort -u)
    for inode in $inodes; do
      for fd in /proc/[0-9]*/fd/*; do
        link=$(readlink "$fd" 2>/dev/null || true)
        [ "$link" = "socket:[$inode]" ] || continue
        pid="${fd#/proc/}"
        pid="${pid%%/*}"
        [ "$pid" = "$$" ] && continue
        [ "$pid" = "1" ] && continue
        case " $owners " in *" $pid "*) ;; *) owners="$owners $pid" ;; esac
      done
    done
  fi
  printf '%s\n' "$owners"
}
cleanup_pidfile_owner() {
  [ -s "$pidfile" ] || return 0
  read pid started < "$pidfile" || { rm -f "$pidfile"; return 0; }
  [ -n "$pid" ] || { rm -f "$pidfile"; return 0; }
  if [ -n "$started" ]; then
    current=$(cut -d' ' -f22 "/proc/$pid/stat" 2>/dev/null || true)
    [ -n "$current" ] && [ "$current" = "$started" ] && terminate_pid_tree "$pid" && cleaned=1
  elif kill -0 "$pid" 2>/dev/null; then
    terminate_pid_tree "$pid"
    cleaned=1
  fi
  rm -f "$pidfile"
}
cleanup_listener_owners() {
  [ -n "$ports" ] || return 0
  for port in $ports; do
    hex=$(printf '%04X' "$port")
    owners=$(find_listener_owner_pids "$hex" "$port")
    for pid in $owners; do
      terminate_pid_tree "$pid"
      cleaned=1
    done
  done
  for port in $ports; do
    hex=$(printf '%04X' "$port")
    port_listening "$hex" && return 1
  done
  return 0
}
cleanup_pidfile_owner
cleanup_listener_owners
status=$?
if [ "$cleaned" = "1" ] || [ "$status" -eq 0 ]; then
  [ "$cleaned" = "1" ] && printf cleaned
  exit 0
fi
exit 1
"#;
        let mut child = match Command::new("sh")
            .arg("-s")
            .arg("--")
            .arg(&pidfile)
            .arg(&fixed_bind_ports_arg)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
        {
            Ok(child) => child,
            Err(error) => {
                return Some(format!(
                    "activation-started native service cleanup failed: {error}"
                ));
            }
        };
        if let Some(mut stdin) = child.stdin.take()
            && let Err(error) = stdin.write_all(cleanup_script.as_bytes())
        {
            return Some(format!(
                "activation-started native service cleanup failed: {error}"
            ));
        }
        match child.wait_with_output() {
            Ok(output)
                if output.status.success()
                    && String::from_utf8_lossy(&output.stdout).contains("cleaned") =>
            {
                Some(String::from(
                    "activation-started native service workload cleaned up after interrupt",
                ))
            }
            Ok(output) if output.status.success() => None,
            Ok(output) if String::from_utf8_lossy(&output.stdout).contains("cleaned") => {
                Some(String::from(
                    "activation-started native service workload cleaned up after interrupt",
                ))
            }
            Ok(_) => Some(String::from(
                "activation-started native service cleanup could not verify listener release after interrupt",
            )),
            Err(error) => Some(format!(
                "activation-started native service cleanup failed: {error}"
            )),
        }
    }
}

fn cleanup_interrupted_remote_service_workload_and_note(
    task_name: &str,
    backend: &ResolvedExecutionBackend,
    runtime: Option<&TaskRuntimeSpec>,
) -> Option<String> {
    let ResolvedExecutionBackend::Remote {
        provider,
        target,
        cwd,
        ..
    } = backend
    else {
        return None;
    };

    let pidfile = persistent_service_workload_pidfile_path(task_name);
    let fixed_bind_ports = runtime
        .into_iter()
        .flat_map(|runtime| runtime.listeners.values())
        .filter_map(|listener| {
            (listener.bind.port.mode == crate::schema::TaskRuntimePortMode::Fixed)
                .then_some(listener.bind.port.value)
                .flatten()
        })
        .collect::<Vec<_>>();
    let fixed_bind_ports_arg = fixed_bind_ports
        .iter()
        .map(u16::to_string)
        .collect::<Vec<_>>()
        .join(" ");
    let cleanup_command = format!(
        "pidfile={pidfile}; \
ports={ports}; \
cleaned=0; \
port_listening() {{ target=\"$1\"; awk -v port=\"$target\" 'BEGIN {{ found = 0 }} NR > 1 {{ split($2, a, \":\"); if (($4 == \"0A\" || $4 == \"0a\") && (toupper(a[2]) == toupper(port) || a[2] == port)) {{ found = 1; exit }} }} END {{ exit(found ? 0 : 1) }}' /proc/net/tcp /proc/net/tcp6 2>/dev/null; }}; \
terminate_pid_tree() {{ pid=\"$1\"; [ -n \"$pid\" ] || return 0; [ \"$pid\" = \"$$\" ] && return 0; [ \"$pid\" = \"1\" ] && return 0; kill -0 \"$pid\" 2>/dev/null || return 0; children=$(pgrep -P \"$pid\" 2>/dev/null || true); for child in $children; do terminate_pid_tree \"$child\"; done; kill -TERM \"$pid\" 2>/dev/null || true; sleep 0.2; i=0; while kill -0 \"$pid\" 2>/dev/null && [ \"$i\" -lt 30 ]; do i=$((i + 1)); sleep 0.1; done; if kill -0 \"$pid\" 2>/dev/null; then kill -KILL \"$pid\" 2>/dev/null || true; sleep 0.5; fi; }}; \
find_listener_owner_pids() {{ target_port=\"$1\"; owners=\"\"; target_hex=$(printf '%04X' \"$target_port\"); if command -v ss >/dev/null 2>&1; then ss_pids=$(ss -Htnlp \"sport = :$target_port\" 2>/dev/null | sed -n 's/.*pid=\\([0-9][0-9]*\\).*/\\1/p' | sort -u || true); for pid in $ss_pids; do [ \"$pid\" = \"$$\" ] && continue; [ \"$pid\" = \"1\" ] && continue; case \" $owners \" in *\" $pid \"*) ;; *) owners=\"$owners $pid\" ;; esac; done; fi; if [ -z \"$owners\" ] && command -v lsof >/dev/null 2>&1; then lsof_pids=$(lsof -nP -iTCP:\"$target_port\" -sTCP:LISTEN -t 2>/dev/null || true); for pid in $lsof_pids; do [ \"$pid\" = \"$$\" ] && continue; [ \"$pid\" = \"1\" ] && continue; case \" $owners \" in *\" $pid \"*) ;; *) owners=\"$owners $pid\" ;; esac; done; fi; if [ -z \"$owners\" ] && [ -r /proc/net/tcp ]; then inodes=$(awk -v port=\"$target_hex\" 'NR > 1 {{ split($2, a, \":\"); if (($4 == \"0A\" || $4 == \"0a\") && toupper(a[2]) == toupper(port)) print $10 }}' /proc/net/tcp /proc/net/tcp6 2>/dev/null | sort -u); for inode in $inodes; do for fd in /proc/[0-9]*/fd/*; do link=$(readlink \"$fd\" 2>/dev/null || true); [ \"$link\" = \"socket:[$inode]\" ] || continue; pid=\"${{fd#/proc/}}\"; pid=\"${{pid%%/*}}\"; [ \"$pid\" = \"$$\" ] && continue; [ \"$pid\" = \"1\" ] && continue; case \" $owners \" in *\" $pid \"*) ;; *) owners=\"$owners $pid\" ;; esac; done; done; fi; printf '%s\\n' \"$owners\"; }}; \
cleanup_pidfile_owner() {{ [ -s \"$pidfile\" ] || return 0; read pid started < \"$pidfile\" || {{ rm -f \"$pidfile\"; return 0; }}; [ -n \"$pid\" ] || {{ rm -f \"$pidfile\"; return 0; }}; if [ -n \"$started\" ]; then current=$(cut -d' ' -f22 \"/proc/$pid/stat\" 2>/dev/null || true); [ -n \"$current\" ] && [ \"$current\" = \"$started\" ] && terminate_pid_tree \"$pid\" && cleaned=1; elif kill -0 \"$pid\" 2>/dev/null; then terminate_pid_tree \"$pid\"; cleaned=1; fi; rm -f \"$pidfile\"; }}; \
cleanup_listener_owners() {{ [ -n \"$ports\" ] || return 0; attempt=0; while [ \"$attempt\" -lt 20 ]; do for port in $ports; do owners=$(find_listener_owner_pids \"$port\"); for pid in $owners; do terminate_pid_tree \"$pid\"; cleaned=1; done; done; all_free=1; for port in $ports; do hex=$(printf '%04X' \"$port\"); if port_listening \"$hex\"; then all_free=0; break; fi; done; [ \"$all_free\" = \"1\" ] && return 0; attempt=$((attempt + 1)); sleep 0.1; done; return 1; }}; \
cleanup_pidfile_owner; \
cleanup_listener_owners; \
status=$?; \
if [ \"$cleaned\" = \"1\" ] || [ \"$status\" -eq 0 ]; then [ \"$cleaned\" = \"1\" ] && printf cleaned; exit 0; fi; \
exit 1",
        pidfile = shell_quote(&pidfile),
        ports = shell_quote(&fixed_bind_ports_arg),
    );
    let probe = RemoteReadinessProbeTarget {
        provider: provider.clone(),
        target: target.clone(),
        cwd: cwd.clone(),
        ssh: match backend {
            ResolvedExecutionBackend::Remote { ssh, .. } => ssh.clone(),
            _ => None,
        },
        provider_command: match backend {
            ResolvedExecutionBackend::BackendProvider { command, .. } => Some(command.clone()),
            _ => None,
        },
        working_dir: cwd.clone().unwrap_or_default(),
    };
    let ports_cleared = || {
        fixed_bind_ports
            .iter()
            .all(|port| !remote_target_probe_port_reachable(&probe, *port))
    };
    match execute_remote_task_command(
        task_name,
        None,
        cleanup_command.as_str(),
        &BTreeMap::new(),
        provider.as_str(),
        target.as_str(),
        cwd.as_deref(),
        match backend {
            ResolvedExecutionBackend::Remote { ssh, .. } => ssh.as_ref(),
            _ => None,
        },
        TaskExecutionMode::Capture,
    ) {
        Ok(_) if ports_cleared() => Some(String::from(
            "activation-started remote service workload cleaned up after interrupt",
        )),
        Ok(output) if output.exit_code == 0 && output.stdout.contains("cleaned") => Some(
            String::from("activation-started remote service workload cleaned up after interrupt"),
        ),
        Ok(output) if output.exit_code == 0 => None,
        Ok(output) if output.stdout.contains("cleaned") => Some(String::from(
            "activation-started remote service workload cleaned up after interrupt",
        )),
        Ok(_) => Some(String::from(
            "activation-started remote service cleanup could not verify listener release after interrupt",
        )),
        Err(error) => Some(format!(
            "activation-started remote service cleanup failed: {error}"
        )),
    }
}

fn cleanup_interrupted_backend_provider_service_workload_and_note(
    task_name: &str,
    backend: &ResolvedExecutionBackend,
    task_command: Option<&str>,
    working_dir: &Path,
) -> Option<String> {
    let ResolvedExecutionBackend::BackendProvider {
        provider,
        command: provider_command,
        target,
        cwd,
        ..
    } = backend
    else {
        return None;
    };
    let task_command = task_command?;
    match execute_backend_provider_task_command(
        task_name,
        task_command,
        working_dir,
        &BTreeMap::new(),
        provider.as_str(),
        provider_command.as_str(),
        target.as_str(),
        cwd.as_deref(),
        BackendProviderCommandContext::ActivationCleanup,
        TaskExecutionMode::Capture,
    ) {
        Ok(output) if output.exit_code == 0 => Some(String::from(
            "activation-started backend-provider service workload cleaned up after interrupt",
        )),
        Ok(output) => Some(format!(
            "activation-started backend-provider service cleanup exited with status {}",
            output.exit_code
        )),
        Err(error) => Some(format!(
            "activation-started backend-provider service cleanup failed: {error}"
        )),
    }
}

fn cleanup_activation_started_producer_and_note(
    producer_task_name: &str,
    backend: &ResolvedExecutionBackend,
    runtime: Option<&TaskRuntimeSpec>,
    task_command: Option<&str>,
    working_dir: &Path,
    remove_backend_on_interrupt: bool,
) -> Option<String> {
    if resolved_execution_backend_kind(backend) == Backend::Native {
        return cleanup_interrupted_native_service_workload_and_note(producer_task_name, runtime)
            .map(|note| format!("activation-started producer `{producer_task_name}`: {note}"));
    }
    if resolved_execution_backend_kind(backend) == Backend::Remote {
        if matches!(backend, ResolvedExecutionBackend::BackendProvider { .. }) {
            return cleanup_interrupted_backend_provider_service_workload_and_note(
                producer_task_name,
                backend,
                task_command,
                working_dir,
            )
            .map(|note| format!("activation-started producer `{producer_task_name}`: {note}"));
        }
        return cleanup_interrupted_remote_service_workload_and_note(
            producer_task_name,
            backend,
            runtime,
        )
        .map(|note| format!("activation-started producer `{producer_task_name}`: {note}"));
    }
    let Some((engine, container_name)) =
        persistent_container_target_for_backend(backend, working_dir)
    else {
        return None;
    };
    let mut note = cleanup_interrupted_persistent_service_workload_and_note(
        producer_task_name,
        engine.as_str(),
        &container_name,
        runtime,
    );
    if remove_backend_on_interrupt {
        let removal_note = match remove_persistent_container(
            engine.as_str(),
            &container_name,
            producer_task_name,
        ) {
            Ok(output) if output.exit_code == 0 => Some(String::from(
                "activation-started producer persistent backend removed after interrupt",
            )),
            Ok(output) => Some(format!(
                "activation-started producer persistent backend cleanup failed for `{container_name}`: {}",
                container_command_failure_details(
                    engine.as_str(),
                    &["rm", "-f", &container_name],
                    &output,
                )
            )),
            Err(error) => Some(format!(
                "activation-started producer persistent backend cleanup failed for `{container_name}`: {error}"
            )),
        };
        note = merge_execution_note(note, removal_note);
    }
    note.map(|note| format!("activation-started producer `{producer_task_name}`: {note}"))
}

fn activation_started_producer_requires_backend_cleanup_on_interrupt(
    producer_task_name: &str,
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
) -> Result<bool, RunError> {
    let Some((engine, container_name)) =
        persistent_container_target_for_backend(backend, working_dir)
    else {
        return Ok(false);
    };
    Ok(!persistent_container_exists(
        engine.as_str(),
        container_name.as_str(),
        producer_task_name,
    )?)
}

fn persistent_container_target_for_backend(
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
) -> Option<(String, String)> {
    let ResolvedExecutionBackend::Container {
        context_name,
        shared_local_backend,
        image,
        engine,
        lifecycle,
        memory_bytes,
        publications,
        dependency_isolation_paths,
        ..
    } = backend
    else {
        return None;
    };
    if *lifecycle != Lifecycle::Persistent {
        return None;
    }
    let identity_seed = container_identity_seed(
        context_name.as_deref(),
        shared_local_backend
            .as_ref()
            .map(|shared| shared.name.as_str()),
        shared_backend_publications_or_current(shared_local_backend.as_ref(), publications),
        dependency_isolation_paths,
        *memory_bytes,
    );
    Some((
        engine.clone(),
        persistent_container_name_for_seed(
            working_dir,
            image.as_str(),
            engine.as_str(),
            identity_seed.as_deref(),
        ),
    ))
}

fn reclaim_repo_owned_conflicting_persistent_containers(
    task_name: &str,
    working_dir: &Path,
    repo_ownership_token: &str,
    listener_publications: &[(String, ContainerPortPublication)],
    preferred_engine: Option<&str>,
) -> Result<usize, RunError> {
    let conflict_ports = listener_publications
        .iter()
        .filter(|(_, publication)| publication.host_port_mode == TaskRuntimeHostPortMode::Fixed)
        .filter_map(|(_, publication)| publication.host_port)
        .collect::<BTreeSet<_>>();
    if conflict_ports.is_empty() {
        return Ok(0);
    }

    let mut engines = repo_managed_engines(task_name, working_dir)?;
    if let Some(engine) = preferred_engine {
        engines.insert(engine.to_string());
    }

    let mut reclaimed = 0usize;
    let mut visited = BTreeSet::new();
    for engine in engines {
        for container_name in
            persistent_container_names_for_repo(task_name, engine.as_str(), repo_ownership_token)?
        {
            if !visited.insert((engine.clone(), container_name.clone())) {
                continue;
            }
            let mut conflicts = false;
            for conflict_port in &conflict_ports {
                if container_published_host_port_exists(
                    task_name,
                    engine.as_str(),
                    container_name.as_str(),
                    *conflict_port,
                )? {
                    conflicts = true;
                    break;
                }
            }
            if !conflicts {
                continue;
            }
            if remove_persistent_container_if_present(
                task_name,
                engine.as_str(),
                container_name.as_str(),
            )? {
                reclaimed += 1;
            }
        }
    }

    Ok(reclaimed)
}

fn reclaimed_orphaned_ephemeral_containers_note(count: usize) -> Option<String> {
    match count {
        0 => None,
        1 => Some(String::from(
            "reclaimed 1 orphaned ephemeral container before starting task",
        )),
        _ => Some(format!(
            "reclaimed {count} orphaned ephemeral containers before starting task"
        )),
    }
}

fn merge_execution_note(existing: Option<String>, appended: Option<String>) -> Option<String> {
    match (existing, appended) {
        (Some(existing), Some(appended)) => Some(format!("{existing}; {appended}")),
        (Some(existing), None) => Some(existing),
        (None, Some(appended)) => Some(appended),
        (None, None) => None,
    }
}

fn reap_repo_owned_ephemeral_containers(
    task_name: &str,
    engine: &str,
    repo_ownership_token: &str,
) -> Result<Vec<String>, RunError> {
    let candidates =
        repo_owned_ephemeral_container_candidates(task_name, engine, repo_ownership_token)?;

    let mut reclaimed = Vec::new();
    for container_name in candidates {
        if !ephemeral_container_is_orphaned(task_name, engine, container_name.as_str())? {
            continue;
        }
        reclaim_ephemeral_container_candidate(task_name, engine, container_name.as_str())?;
        reclaimed.push(container_name);
    }

    Ok(reclaimed)
}

fn reap_legacy_repo_owned_conflicting_ephemeral_containers(
    task_name: &str,
    engine: &str,
    repo_ownership_token: &str,
    publication: &ContainerPortPublication,
    conflict_port: u16,
) -> Result<Vec<String>, RunError> {
    let candidates = repo_owned_ephemeral_container_candidates_by_inspection(
        task_name,
        engine,
        repo_ownership_token,
    )?;
    let mut reclaimed = Vec::new();
    for container_name in candidates {
        if !legacy_running_ephemeral_conflicts_with_publication(
            task_name,
            engine,
            container_name.as_str(),
            publication,
            conflict_port,
        )? {
            continue;
        }
        reclaim_ephemeral_container_candidate(task_name, engine, container_name.as_str())?;
        reclaimed.push(container_name);
    }
    Ok(reclaimed)
}

fn repo_owned_ephemeral_container_candidates_by_inspection(
    task_name: &str,
    engine: &str,
    repo_ownership_token: &str,
) -> Result<Vec<String>, RunError> {
    let args = ["ps", "-a", "--format", "{{.Names}}"];
    let output = container_command_output(engine, &args, None, task_name)?;
    if output.exit_code != 0 {
        return Err(RunError::EphemeralContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("list"),
            container: String::from("ota-ephemeral-*"),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &output),
        });
    }

    let mut candidates = Vec::new();
    for container_name in output
        .stdout
        .lines()
        .map(str::trim)
        .filter(|name| !name.is_empty() && name.starts_with("ota-ephemeral-"))
    {
        let labels = ephemeral_container_labels_for_name(task_name, engine, container_name)?;
        if labels.get("dev.ota.managed").map(String::as_str) != Some("true") {
            continue;
        }
        if labels.get(OTA_REPO_CONTAINER_LABEL_KEY).map(String::as_str)
            != Some(repo_ownership_token)
        {
            continue;
        }
        candidates.push(container_name.to_string());
    }
    candidates.sort();
    candidates.dedup();
    Ok(candidates)
}

fn repo_owned_ephemeral_container_candidates(
    task_name: &str,
    engine: &str,
    repo_ownership_token: &str,
) -> Result<Vec<String>, RunError> {
    let repo_label = format!("{OTA_REPO_CONTAINER_LABEL_KEY}={repo_ownership_token}");
    let repo_owned = container_names_for_label(task_name, engine, &repo_label)?;
    let managed = container_names_for_label(task_name, engine, OTA_MANAGED_CONTAINER_LABEL)?;
    let ephemeral = container_names_for_label(task_name, engine, OTA_EPHEMERAL_CONTAINER_LABEL)?;

    let mut candidates = repo_owned
        .into_iter()
        .filter(|name| {
            managed.contains(name) && ephemeral.contains(name) && name.starts_with("ota-ephemeral-")
        })
        .collect::<Vec<_>>();
    candidates.sort();
    candidates.dedup();
    Ok(candidates)
}

fn reclaim_ephemeral_container_candidate(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Result<(), RunError> {
    let remove = remove_persistent_container(engine, container_name, task_name)?;
    if remove.exit_code != 0 {
        return Err(RunError::EphemeralContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("remove"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details: if !remove.stderr.trim().is_empty() {
                remove.stderr.trim().to_string()
            } else if !remove.stdout.trim().is_empty() {
                remove.stdout.trim().to_string()
            } else {
                format!(
                    "`{engine} rm -f {container_name}` exited with {}",
                    remove.exit_code
                )
            },
        });
    }
    Ok(())
}

fn ephemeral_container_is_orphaned(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Result<bool, RunError> {
    match persistent_container_running(engine, container_name, task_name)? {
        Some(false) => Ok(true),
        Some(true) => {
            let labels = ephemeral_container_labels_for_name(task_name, engine, container_name)?;
            let owner_pid = labels
                .get(OTA_OWNER_PID_CONTAINER_LABEL_KEY)
                .and_then(|value| value.trim().parse::<u32>().ok());
            Ok(owner_pid
                .and_then(owner_pid_running)
                .is_some_and(|running| !running))
        }
        None => Ok(false),
    }
}

fn legacy_running_ephemeral_conflicts_with_publication(
    task_name: &str,
    engine: &str,
    container_name: &str,
    publication: &ContainerPortPublication,
    conflict_port: u16,
) -> Result<bool, RunError> {
    if persistent_container_running(engine, container_name, task_name)? != Some(true) {
        return Ok(false);
    }

    let labels = ephemeral_container_labels_for_name(task_name, engine, container_name)?;
    if labels.contains_key(OTA_OWNER_PID_CONTAINER_LABEL_KEY) {
        return Ok(false);
    }

    let published = container_published_port(
        engine,
        container_name,
        publication.bind_port,
        publication.protocol,
        task_name,
    )?;
    if published == Some(conflict_port) {
        return Ok(true);
    }

    container_published_host_port_exists(task_name, engine, container_name, conflict_port)
}

fn ephemeral_container_labels_for_name(
    task_name: &str,
    engine: &str,
    container_name: &str,
) -> Result<BTreeMap<String, String>, RunError> {
    let args = ["inspect", "-f", "{{json .Config.Labels}}", container_name];
    let output = container_command_output(engine, &args, None, task_name)?;
    if output.exit_code != 0 {
        return Err(RunError::EphemeralContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &output),
        });
    }

    let stdout = output.stdout.trim();
    if stdout.is_empty() || stdout == "null" {
        return Ok(BTreeMap::new());
    }

    parse_container_labels_json(stdout).map_err(|details| {
        RunError::EphemeralContainerCleanupFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            container: container_name.to_string(),
            engine: engine.to_string(),
            details,
        }
    })
}

fn parse_container_labels_json(stdout: &str) -> Result<BTreeMap<String, String>, String> {
    let labels_value: serde_json::Value = serde_json::from_str(stdout)
        .map_err(|source| format!("invalid `inspect` labels JSON response: {source}"))?;

    let Some(labels_object) = labels_value.as_object() else {
        return Ok(BTreeMap::new());
    };

    let mut labels = BTreeMap::new();
    for (key, value) in labels_object {
        if let Some(value) = value.as_str() {
            labels.insert(key.to_string(), value.to_string());
        }
    }
    Ok(labels)
}

fn owner_pid_running(pid: u32) -> Option<bool> {
    #[cfg(unix)]
    {
        if pid == 0 {
            return Some(false);
        }
        let pid_string = pid.to_string();
        let output = Command::new("ps")
            .args(["-p", pid_string.as_str(), "-o", "pid="])
            .output()
            .ok()?;
        if !output.status.success() {
            return Some(false);
        }
        return Some(
            String::from_utf8_lossy(&output.stdout)
                .lines()
                .any(|line| line.trim() == pid_string),
        );
    }
    #[cfg(windows)]
    {
        let filter = format!("PID eq {pid}");
        let output = Command::new("tasklist")
            .args(["/FI", filter.as_str(), "/NH", "/FO", "CSV"])
            .output()
            .ok()?;
        if !output.status.success() {
            return None;
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        if stdout.to_ascii_lowercase().contains("no tasks are running") {
            return Some(false);
        }
        let pid_token = format!("\"{pid}\"");
        return Some(stdout.lines().any(|line| line.contains(&pid_token)));
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = pid;
        None
    }
}

fn persistent_container_running(
    engine: &str,
    container_name: &str,
    task_name: &str,
) -> Result<Option<bool>, RunError> {
    let inspect = container_command_output(
        engine,
        &["inspect", "-f", "{{.State.Running}}", container_name],
        None,
        task_name,
    )?;
    if inspect.exit_code != 0 {
        return Ok(None);
    }

    match inspect.stdout.trim() {
        "true" => Ok(Some(true)),
        "false" => Ok(Some(false)),
        _ => Ok(None),
    }
}

fn persistent_container_exists(
    engine: &str,
    container_name: &str,
    task_name: &str,
) -> Result<bool, RunError> {
    let inspect = container_command_output(engine, &["inspect", container_name], None, task_name)?;
    Ok(inspect.exit_code == 0)
}

fn persistent_container_exec_hit_stopped_container(stderr: &str) -> bool {
    stderr.contains("cannot exec in a stopped container")
}

fn container_command_failure(
    status: ContainerCommandOutput,
    container_name: String,
) -> TaskCommandOutput {
    TaskCommandOutput {
        exit_code: status.exit_code,
        stdout: status.stdout,
        stderr: status.stderr,
        target: Some(container_name),
        runtime: None,
        service_termination: None,
        execution_note: None,
        interrupted: false,
    }
}

fn exec_persistent_container_task_command(
    task_name: &str,
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    command: &str,
    env_overrides: &BTreeMap<String, String>,
    path_export: Option<&str>,
    secret_env_names: &BTreeSet<String>,
    engine: &str,
    mode: TaskExecutionMode,
    container_name: &str,
    readiness_probe: Option<&RuntimeReadinessProbe>,
) -> Result<TaskCommandOutput, RunError> {
    let path_export = container_task_path_export(engine, container_name, task_name, path_export)?;
    let mut container = container_engine_command(engine);
    container.arg("exec").arg("-i");
    append_container_git_safe_directory_args(&mut container, env_overrides);
    for (name, value) in env_overrides {
        if secret_env_names.contains(name) {
            container.env(name, value);
            container.arg("--env").arg(name);
        } else {
            container.arg("--env").arg(format!("{name}={value}"));
        }
    }
    container.arg(&container_name).arg("sh").arg("-c").arg(
        if runtime.is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service) {
            persistent_service_command_with_path_export(task_name, command, path_export.as_deref())
        } else {
            command_with_path_export(command, path_export.as_deref())
        },
    );

    match mode {
        TaskExecutionMode::Stream {
            capture_output,
            live_log,
            ..
        } => {
            if capture_output {
                let interrupt_epoch = current_run_interrupt_epoch();
                let loader = StreamPhaseLoader::start_with_policy(
                    &running_loader_label_for_backend(task_name, Backend::Container),
                    StreamPhaseLoaderPolicy::Delayed,
                );
                let notifier = loader.as_ref().map(|loader| loader.notifier());
                let mut child = container
                    .stdin(Stdio::inherit())
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .spawn()
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                let stdout_log = live_log.as_ref().map(|tee| tee.stdout.clone());
                let stdout_handle = child.stdout.take().map(|stdout| {
                    thread::spawn(move || {
                        stream_reader_to_sink(
                            stdout,
                            io::stdout(),
                            notifier.clone(),
                            true,
                            stdout_log,
                        )
                    })
                });
                let stderr_log = live_log.as_ref().map(|tee| tee.stderr.clone());
                let stderr_handle = child.stderr.take().map(|stderr| {
                    let stderr_notifier = loader.as_ref().map(|loader| loader.notifier());
                    thread::spawn(move || {
                        stream_reader_to_sink(
                            stderr,
                            io::stderr(),
                            stderr_notifier,
                            true,
                            stderr_log,
                        )
                    })
                });
                let status = wait_for_child_with_runtime_readiness_budget(
                    &mut child,
                    readiness_probe,
                    |child| {
                        let _ = cleanup_interrupted_persistent_service_workload_and_note(
                            task_name,
                            engine,
                            container_name,
                            runtime,
                        );
                        let _ = child.kill();
                    },
                )
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
                let stdout =
                    join_stream_reader(stdout_handle).map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                let stderr =
                    join_stream_reader(stderr_handle).map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                if let Some(loader) = loader {
                    loader.stop();
                }
                let interrupted = interruption_observed_since(interrupt_epoch);
                let exit_code = normalize_persistent_service_interrupt_exit_code(
                    runtime,
                    interrupted,
                    status.code().unwrap_or(1),
                );
                Ok(TaskCommandOutput {
                    exit_code,
                    stdout,
                    stderr,
                    target: Some(container_name.to_string()),
                    runtime: None,
                    service_termination: None,
                    execution_note: interruption_execution_note(interrupted, exit_code),
                    interrupted,
                })
            } else {
                let interrupt_epoch = current_run_interrupt_epoch();
                let loader = StreamPhaseLoader::start_with_policy(
                    &running_loader_label_for_backend(task_name, Backend::Container),
                    StreamPhaseLoaderPolicy::Delayed,
                );
                let mut child = container
                    .stdin(Stdio::inherit())
                    .stdout(Stdio::inherit())
                    .stderr(Stdio::inherit())
                    .spawn()
                    .map_err(|source| RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    })?;
                let status = wait_for_child_with_runtime_readiness_budget(
                    &mut child,
                    readiness_probe,
                    |child| {
                        let _ = cleanup_interrupted_persistent_service_workload_and_note(
                            task_name,
                            engine,
                            container_name,
                            runtime,
                        );
                        let _ = child.kill();
                    },
                )
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
                if let Some(loader) = loader {
                    loader.stop();
                }
                let interrupted = interruption_observed_since(interrupt_epoch);
                let exit_code = normalize_persistent_service_interrupt_exit_code(
                    runtime,
                    interrupted,
                    status.code().unwrap_or(1),
                );

                Ok(TaskCommandOutput {
                    exit_code,
                    stdout: String::new(),
                    stderr: String::new(),
                    target: Some(container_name.to_string()),
                    runtime: None,
                    service_termination: None,
                    execution_note: interruption_execution_note(interrupted, exit_code),
                    interrupted,
                })
            }
        }
        TaskExecutionMode::Capture | TaskExecutionMode::CaptureActivation => {
            let interrupt_epoch = current_run_interrupt_epoch();
            let mut child = container
                .stdin(Stdio::inherit())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let stdout_handle = child.stdout.take().map(|stdout| {
                thread::spawn(move || stream_reader_to_sink(stdout, io::sink(), None, true, None))
            });
            let stderr_handle = child.stderr.take().map(|stderr| {
                thread::spawn(move || stream_reader_to_sink(stderr, io::sink(), None, true, None))
            });
            let status = wait_for_child_with_runtime_readiness_budget(
                &mut child,
                readiness_probe,
                |child| {
                    let _ = cleanup_interrupted_persistent_service_workload_and_note(
                        task_name,
                        engine,
                        container_name,
                        runtime,
                    );
                    let _ = child.kill();
                },
            )
            .map_err(|source| RunError::SpawnFailed {
                task: task_name.to_string(),
                source,
            })?;
            let stdout =
                join_stream_reader(stdout_handle).map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let stderr =
                join_stream_reader(stderr_handle).map_err(|source| RunError::SpawnFailed {
                    task: task_name.to_string(),
                    source,
                })?;
            let interrupted = interruption_observed_since(interrupt_epoch);
            let exit_code = normalize_persistent_service_interrupt_exit_code(
                runtime,
                interrupted,
                status.code().unwrap_or(1),
            );
            Ok(TaskCommandOutput {
                exit_code,
                stdout,
                stderr,
                target: Some(container_name.to_string()),
                runtime: None,
                service_termination: None,
                execution_note: interruption_execution_note(interrupted, exit_code),
                interrupted,
            })
        }
    }
}

fn normalize_persistent_service_interrupt_exit_code(
    runtime: Option<&crate::schema::TaskRuntimeSpec>,
    interrupted: bool,
    exit_code: i32,
) -> i32 {
    if interrupted
        && runtime.is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service)
        && !is_interrupt_exit_code(exit_code)
    {
        130
    } else {
        exit_code
    }
}

fn container_command_output(
    engine: &str,
    args: &[&str],
    working_dir: Option<&Path>,
    task_name: &str,
) -> Result<ContainerCommandOutput, RunError> {
    let is_internal_clean_task =
        task_name == OTA_ENGINE_CLEAN_QUERY_TASK_NAME || task_name == OTA_CLEAN_INTERNAL_TASK_NAME;
    if is_internal_clean_task
        && let Some(details) = clean_engine_timeout_cache()
            .lock()
            .expect("clean timeout cache should be lockable")
            .get(engine)
            .cloned()
    {
        return Ok(ContainerCommandOutput {
            exit_code: 124,
            stdout: String::new(),
            stderr: details,
        });
    }

    let mut container = container_engine_command(engine);
    container.args(args);
    container.stdout(Stdio::piped()).stderr(Stdio::piped());
    if let Some(working_dir) = working_dir {
        container.current_dir(working_dir);
    }
    if is_internal_clean_task {
        const CLEAN_CONTAINER_COMMAND_TIMEOUT_SECS: u64 = 30;
        let mut child = container.spawn().map_err(|source| RunError::SpawnFailed {
            task: task_name.to_string(),
            source,
        })?;
        let deadline = Instant::now() + Duration::from_secs(CLEAN_CONTAINER_COMMAND_TIMEOUT_SECS);
        let mut timed_out = false;
        loop {
            match child.try_wait() {
                Ok(Some(_)) => break,
                Ok(None) if Instant::now() >= deadline => {
                    timed_out = true;
                    let _ = child.kill();
                    break;
                }
                Ok(None) => thread::sleep(Duration::from_millis(100)),
                Err(source) => {
                    return Err(RunError::SpawnFailed {
                        task: task_name.to_string(),
                        source,
                    });
                }
            }
        }

        let output = child
            .wait_with_output()
            .map_err(|source| RunError::SpawnFailed {
                task: task_name.to_string(),
                source,
            })?;
        let mut stdout = String::from_utf8_lossy(&output.stdout).into_owned();
        let mut stderr = String::from_utf8_lossy(&output.stderr).into_owned();
        let mut exit_code = output.status.code().unwrap_or(1);
        if timed_out {
            if !stderr.trim().is_empty() {
                stderr.push('\n');
            }
            let details = format!(
                "container command timed out after {} seconds while waiting for the engine",
                CLEAN_CONTAINER_COMMAND_TIMEOUT_SECS
            );
            stderr.push_str(details.as_str());
            if exit_code == 0 {
                exit_code = 124;
            }
            clean_engine_timeout_cache()
                .lock()
                .expect("clean timeout cache should be lockable")
                .insert(engine.to_string(), details);
        }
        return Ok(ContainerCommandOutput {
            exit_code,
            stdout: std::mem::take(&mut stdout),
            stderr,
        });
    }

    let output = container.output().map_err(|source| RunError::SpawnFailed {
        task: task_name.to_string(),
        source,
    })?;
    Ok(ContainerCommandOutput {
        exit_code: output.status.code().unwrap_or(1),
        stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
        stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
    })
}

fn container_command_output_with_stdin(
    engine: &str,
    args: &[&str],
    stdin: &str,
    working_dir: Option<&Path>,
    task_name: &str,
) -> Result<ContainerCommandOutput, RunError> {
    let mut container = container_engine_command(engine);
    container.args(args);
    container
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    if let Some(working_dir) = working_dir {
        container.current_dir(working_dir);
    }
    let mut child = container.spawn().map_err(|source| RunError::SpawnFailed {
        task: task_name.to_string(),
        source,
    })?;
    if let Some(mut child_stdin) = child.stdin.take() {
        child_stdin
            .write_all(stdin.as_bytes())
            .map_err(|source| RunError::SpawnFailed {
                task: task_name.to_string(),
                source,
            })?;
    }
    let output = child
        .wait_with_output()
        .map_err(|source| RunError::SpawnFailed {
            task: task_name.to_string(),
            source,
        })?;
    Ok(ContainerCommandOutput {
        exit_code: output.status.code().unwrap_or(1),
        stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
        stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
    })
}

#[derive(Debug)]
struct ContainerCommandOutput {
    exit_code: i32,
    stdout: String,
    stderr: String,
}

pub(crate) fn persistent_container_name(working_dir: &Path, image: &str, engine: &str) -> String {
    persistent_container_name_for_seed(
        working_dir,
        image,
        engine,
        Some(LEGACY_EXECUTION_CONTEXT_NAME),
    )
}

fn persistent_container_name_for_seed(
    working_dir: &Path,
    image: &str,
    engine: &str,
    identity_seed: Option<&str>,
) -> String {
    let mut hasher = DefaultHasher::new();
    working_dir.display().to_string().hash(&mut hasher);
    image.hash(&mut hasher);
    engine.hash(&mut hasher);
    identity_seed.hash(&mut hasher);
    format!("ota-{:x}", hasher.finish())
}

pub(crate) fn ephemeral_container_name(working_dir: &Path, image: &str, engine: &str) -> String {
    ephemeral_container_name_for_seed(working_dir, image, engine, None)
}

fn ephemeral_container_name_for_seed(
    working_dir: &Path,
    image: &str,
    engine: &str,
    identity_seed: Option<&str>,
) -> String {
    let mut hasher = DefaultHasher::new();
    std::process::id().hash(&mut hasher);
    working_dir.display().to_string().hash(&mut hasher);
    image.hash(&mut hasher);
    engine.hash(&mut hasher);
    identity_seed.hash(&mut hasher);
    format!("ota-ephemeral-{:x}", hasher.finish())
}

fn container_dependency_isolation_volume_name(
    working_dir: &Path,
    context_name: Option<&str>,
    image: &str,
    engine: &str,
    isolated_path: &str,
) -> Option<String> {
    let context_name = context_name?;
    let mut hasher = DefaultHasher::new();
    working_dir.display().to_string().hash(&mut hasher);
    context_name.hash(&mut hasher);
    image.hash(&mut hasher);
    engine.hash(&mut hasher);
    isolated_path.hash(&mut hasher);
    Some(format!("ota-isolated-{:x}", hasher.finish()))
}

fn container_dependency_isolation_mounts(
    task_name: &str,
    working_dir: &Path,
    context_name: Option<&str>,
    image: &str,
    engine: &str,
    repo_ownership_token: &str,
    isolated_paths: &[String],
) -> Result<Vec<(String, String)>, RunError> {
    let mut mounts = Vec::new();
    for path in isolated_paths {
        let normalized = crate::execution::normalize_dependency_isolated_path(path)
            .expect("validated dependency isolation path should be relative");
        if dependency_isolation_path_is_file(working_dir, &normalized) {
            let source = dependency_isolation_file_mount_source(
                task_name,
                working_dir,
                context_name,
                image,
                engine,
                &normalized,
            )?;
            record_repo_managed_engine(task_name, working_dir, engine)?;
            mounts.push((
                container_workspace_mount_source_display(source.as_path()),
                format!("/workspace/{normalized}"),
            ));
            continue;
        }
        let Some(volume_name) = container_dependency_isolation_volume_name(
            working_dir,
            context_name,
            image,
            engine,
            &normalized,
        ) else {
            continue;
        };
        let labels =
            dependency_isolation_volume_labels(repo_ownership_token, context_name, &normalized);
        ensure_dependency_isolation_volume(
            task_name,
            working_dir,
            engine,
            image,
            &volume_name,
            &labels,
            &format!("/workspace/{normalized}"),
        )?;
        record_repo_managed_engine(task_name, working_dir, engine)?;
        mounts.push((volume_name, format!("/workspace/{normalized}")));
    }

    Ok(mounts)
}

fn container_dependency_isolation_volume_names(
    working_dir: &Path,
    context_name: Option<&str>,
    image: &str,
    engine: &str,
    _repo_ownership_token: &str,
    isolated_paths: &[String],
) -> Vec<String> {
    isolated_paths
        .iter()
        .filter_map(|path| {
            crate::execution::normalize_dependency_isolated_path(path)
                .filter(|normalized| !dependency_isolation_path_is_file(working_dir, normalized))
                .and_then(|normalized| {
                    container_dependency_isolation_volume_name(
                        working_dir,
                        context_name,
                        image,
                        engine,
                        &normalized,
                    )
                })
                .map(|volume_name| volume_name.to_string())
        })
        .collect()
}

fn dependency_isolation_path_is_file(working_dir: &Path, normalized_path: &str) -> bool {
    let candidate = working_dir.join(normalized_path);
    if let Ok(metadata) = fs::metadata(&candidate) {
        return metadata.is_file();
    }

    let file_name = Path::new(normalized_path)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(normalized_path);
    if matches!(
        file_name,
        ".env"
            | ".env.local"
            | ".env.development"
            | ".env.production"
            | ".pnp.cjs"
            | ".pnp.loader.mjs"
            | ".npmrc"
            | ".yarnrc.yml"
            | ".yarnrc.yaml"
            | "install-state.gz"
            | "package-lock.json"
            | "pnpm-lock.yaml"
            | "yarn.lock"
    ) {
        return true;
    }

    false
}

fn dependency_isolation_file_mount_source(
    task_name: &str,
    working_dir: &Path,
    context_name: Option<&str>,
    image: &str,
    engine: &str,
    normalized_path: &str,
) -> Result<PathBuf, RunError> {
    let mut hasher = DefaultHasher::new();
    working_dir.display().to_string().hash(&mut hasher);
    context_name.hash(&mut hasher);
    image.hash(&mut hasher);
    engine.hash(&mut hasher);
    normalized_path.hash(&mut hasher);
    let file_path = repo_ota_state_dir(working_dir)
        .join(OTA_ISOLATED_FILE_MOUNTS_DIR)
        .join(format!("{:x}", hasher.finish()));
    if let Some(parent) = file_path.parent() {
        fs::create_dir_all(parent).map_err(|source| {
            RunError::DependencyIsolationOwnershipFailure {
                task: task_name.to_string(),
                action: String::from("create"),
                path: parent.display().to_string(),
                details: source.to_string(),
            }
        })?;
    }

    if !file_path.exists() {
        let source_file = working_dir.join(normalized_path);
        if source_file.is_file() {
            fs::copy(&source_file, &file_path).map_err(|source| {
                RunError::DependencyIsolationOwnershipFailure {
                    task: task_name.to_string(),
                    action: String::from("write"),
                    path: file_path.display().to_string(),
                    details: source.to_string(),
                }
            })?;
        } else {
            File::create(&file_path).map_err(|source| {
                RunError::DependencyIsolationOwnershipFailure {
                    task: task_name.to_string(),
                    action: String::from("write"),
                    path: file_path.display().to_string(),
                    details: source.to_string(),
                }
            })?;
        }
    }

    Ok(file_path)
}

fn ensure_dependency_isolation_volume(
    task_name: &str,
    working_dir: &Path,
    engine: &str,
    image: &str,
    volume_name: &str,
    labels: &[String],
    container_path: &str,
) -> Result<(), RunError> {
    let inspect =
        container_command_output(engine, &["volume", "inspect", volume_name], None, task_name)?;
    if inspect.exit_code == 0 {
        return ensure_dependency_isolation_volume_owner(
            task_name,
            working_dir,
            engine,
            image,
            volume_name,
            container_path,
        );
    }

    let mut args = vec!["volume".to_string(), "create".to_string()];
    for label in labels {
        args.push("--label".to_string());
        args.push(label.clone());
    }
    args.push(volume_name.to_string());
    let create_args = args.iter().map(String::as_str).collect::<Vec<_>>();
    let create = container_command_output(engine, &create_args, None, task_name)?;
    if create.exit_code == 0 {
        return ensure_dependency_isolation_volume_owner(
            task_name,
            working_dir,
            engine,
            image,
            volume_name,
            container_path,
        );
    }

    Err(RunError::DependencyIsolationVolumeFailure {
        task: task_name.to_string(),
        action: String::from("prepare"),
        volume: volume_name.to_string(),
        engine: engine.to_string(),
        details: container_command_failure_details(engine, &create_args, &create),
    })
}

fn ensure_dependency_isolation_volume_owner(
    task_name: &str,
    working_dir: &Path,
    engine: &str,
    image: &str,
    volume_name: &str,
    container_path: &str,
) -> Result<(), RunError> {
    let Some(user_spec) = container_host_user_spec() else {
        return Ok(());
    };
    let command = format!(
        "mkdir -p {path} && chown -R {user} {path}",
        path = shell_quote(container_path),
        user = shell_quote(&user_spec)
    );
    let mount_arg = format!("{volume_name}:{container_path}");
    let args = [
        "run",
        "--rm",
        "-v",
        mount_arg.as_str(),
        "--entrypoint",
        "sh",
        image,
        "-lc",
        command.as_str(),
    ];
    let output = container_command_output(engine, &args, Some(working_dir), task_name)?;
    if output.exit_code == 0 {
        return Ok(());
    }

    Err(RunError::DependencyIsolationVolumeFailure {
        task: task_name.to_string(),
        action: String::from("prepare writable ownership for"),
        volume: volume_name.to_string(),
        engine: engine.to_string(),
        details: container_command_failure_details(engine, &args, &output),
    })
}

fn remove_dependency_isolation_volume(
    task_name: &str,
    engine: &str,
    volume_name: &str,
) -> Result<bool, RunError> {
    let inspect =
        container_command_output(engine, &["volume", "inspect", volume_name], None, task_name)?;
    if inspect.exit_code != 0 {
        return Ok(false);
    }

    let args = ["volume", "rm", "-f", volume_name];
    for attempt in 0..DEPENDENCY_ISOLATION_VOLUME_REMOVE_MAX_ATTEMPTS {
        let remove = container_command_output(engine, &args, None, task_name)?;
        if remove.exit_code == 0 {
            return Ok(true);
        }
        if attempt + 1 < DEPENDENCY_ISOLATION_VOLUME_REMOVE_MAX_ATTEMPTS
            && dependency_isolation_volume_still_in_use(&remove)
        {
            thread::sleep(dependency_isolation_volume_remove_retry_delay(attempt));
            continue;
        }

        return Err(RunError::DependencyIsolationVolumeFailure {
            task: task_name.to_string(),
            action: String::from("remove"),
            volume: volume_name.to_string(),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &remove),
        });
    }

    Ok(false)
}

fn dependency_isolation_volume_remove_retry_delay(attempt: usize) -> Duration {
    let shift = attempt.min(4) as u32;
    let millis = 100u64.saturating_mul(1u64 << shift).min(1_000);
    Duration::from_millis(millis)
}

fn dependency_isolation_volume_still_in_use(output: &ContainerCommandOutput) -> bool {
    let combined = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
    combined.contains("volume is in use")
}

fn dependency_isolation_volume_labels(
    repo_ownership_token: &str,
    context_name: Option<&str>,
    isolated_path: &str,
) -> Vec<String> {
    let mut labels = vec![
        OTA_MANAGED_VOLUME_LABEL.to_string(),
        OTA_DEPENDENCY_ISOLATION_VOLUME_LABEL.to_string(),
        format!("dev.ota.repo={repo_ownership_token}"),
        format!("dev.ota.path={isolated_path}"),
    ];
    if let Some(context_name) = context_name {
        labels.push(format!("dev.ota.context={context_name}"));
    }
    labels
}

fn dependency_isolation_volume_names_for_repo(
    task_name: &str,
    engine: &str,
    repo_ownership_token: &str,
) -> Result<Vec<String>, RunError> {
    let args = ["volume", "ls", "-q"];
    let output = container_command_output(engine, &args, None, task_name)?;
    if output.exit_code != 0 {
        return Err(RunError::DependencyIsolationVolumeFailure {
            task: task_name.to_string(),
            action: String::from("list"),
            volume: repo_ownership_token.to_string(),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &output),
        });
    }

    let candidate_names = output
        .stdout
        .lines()
        .map(str::trim)
        .filter(|volume_name| !volume_name.is_empty())
        .map(ToString::to_string)
        .collect::<Vec<_>>();

    let mut matching = Vec::new();
    for volume_name in candidate_names {
        let labels = dependency_isolation_volume_labels_for_name(task_name, engine, &volume_name)?;
        if dependency_isolation_volume_is_owned_by_repo(&labels, repo_ownership_token) {
            matching.push(volume_name);
        }
    }

    Ok(matching)
}

fn dependency_isolation_volume_labels_for_name(
    task_name: &str,
    engine: &str,
    volume_name: &str,
) -> Result<BTreeMap<String, String>, RunError> {
    let args = ["volume", "inspect", volume_name];
    let output = container_command_output(engine, &args, None, task_name)?;
    if output.exit_code != 0 {
        return Err(RunError::DependencyIsolationVolumeFailure {
            task: task_name.to_string(),
            action: String::from("inspect"),
            volume: volume_name.to_string(),
            engine: engine.to_string(),
            details: container_command_failure_details(engine, &args, &output),
        });
    }

    let inspect_json: serde_json::Value =
        serde_json::from_str(output.stdout.trim()).map_err(|source| {
            RunError::DependencyIsolationVolumeFailure {
                task: task_name.to_string(),
                action: String::from("inspect"),
                volume: volume_name.to_string(),
                engine: engine.to_string(),
                details: format!("invalid `volume inspect` JSON response: {source}"),
            }
        })?;

    let mut labels = BTreeMap::new();
    match inspect_json {
        serde_json::Value::Array(entries) => {
            if let Some(labels_value) = entries
                .first()
                .and_then(|entry| entry.get("Labels"))
                .and_then(serde_json::Value::as_object)
            {
                for (key, value) in labels_value {
                    if let Some(value) = value.as_str() {
                        labels.insert(key.to_string(), value.to_string());
                    }
                }
            }
        }
        serde_json::Value::Object(entry) => {
            if let Some(labels_value) = entry.get("Labels").and_then(serde_json::Value::as_object) {
                for (key, value) in labels_value {
                    if let Some(value) = value.as_str() {
                        labels.insert(key.to_string(), value.to_string());
                    }
                }
            }
        }
        _ => {}
    }

    Ok(labels)
}

fn dependency_isolation_volume_is_owned_by_repo(
    labels: &BTreeMap<String, String>,
    repo_ownership_token: &str,
) -> bool {
    dependency_isolation_volume_has_label(labels, OTA_MANAGED_VOLUME_LABEL)
        && dependency_isolation_volume_has_label(labels, OTA_DEPENDENCY_ISOLATION_VOLUME_LABEL)
        && labels
            .get("dev.ota.repo")
            .map(String::as_str)
            .is_some_and(|value| value == repo_ownership_token)
}

fn dependency_isolation_volume_has_label(
    labels: &BTreeMap<String, String>,
    expected: &str,
) -> bool {
    let Some((key, value)) = expected.split_once('=') else {
        return false;
    };
    labels
        .get(key)
        .map(String::as_str)
        .is_some_and(|actual| actual == value)
}

fn container_command_failure_details(
    engine: &str,
    args: &[&str],
    output: &ContainerCommandOutput,
) -> String {
    if !output.stderr.trim().is_empty() {
        return output.stderr.trim().to_string();
    }
    if !output.stdout.trim().is_empty() {
        return output.stdout.trim().to_string();
    }
    format!(
        "`{engine} {}` exited with status {}",
        args.join(" "),
        output.exit_code
    )
}

fn contract_working_dir(contract_path: &Path) -> &Path {
    contract_path
        .parent()
        .filter(|path| !path.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."))
}

fn host_workspace_template_value(working_dir: &Path) -> String {
    container_workspace_mount_source(working_dir)
        .display()
        .to_string()
}

fn container_workspace_mount_source(working_dir: &Path) -> PathBuf {
    fs::canonicalize(working_dir).unwrap_or_else(|_| {
        if working_dir.is_absolute() {
            working_dir.to_path_buf()
        } else {
            std::env::current_dir()
                .map(|cwd| cwd.join(working_dir))
                .unwrap_or_else(|_| working_dir.to_path_buf())
        }
    })
}

pub(crate) fn container_workspace_mount_arg(workspace_mount_source: &Path) -> String {
    format!(
        "{}:/workspace",
        container_workspace_mount_source_display(workspace_mount_source)
    )
}

#[cfg(not(windows))]
pub(crate) fn container_workspace_mount_source_display(workspace_mount_source: &Path) -> String {
    workspace_mount_source.display().to_string()
}

#[cfg(windows)]
pub(crate) fn container_workspace_mount_source_display(workspace_mount_source: &Path) -> String {
    let display = workspace_mount_source.display().to_string();
    if let Some(stripped) = display.strip_prefix(r"\\?\UNC\") {
        return format!(r"\\{stripped}");
    }
    if let Some(stripped) = display.strip_prefix(r"\\?\") {
        return stripped.to_string();
    }
    display
}

fn repo_ota_dir(working_dir: &Path) -> PathBuf {
    working_dir.join(".ota")
}

fn repo_ota_state_dir(working_dir: &Path) -> PathBuf {
    repo_ota_dir(working_dir).join(OTA_STATE_DIR)
}

fn repo_ota_state_file_path(working_dir: &Path, file_name: &str) -> PathBuf {
    repo_ota_state_dir(working_dir).join(file_name)
}

fn repo_execution_lock_path(working_dir: &Path) -> PathBuf {
    repo_ota_state_file_path(working_dir, OTA_RUN_EXECUTION_LOCK_FILE)
}

fn repo_active_executions_path(working_dir: &Path) -> PathBuf {
    repo_ota_state_file_path(working_dir, OTA_ACTIVE_EXECUTIONS_FILE)
}

fn acquire_repo_execution_lock(
    task_name: &str,
    working_dir: &Path,
    action: &str,
) -> Result<RepoExecutionLockGuard, RunError> {
    let lock_path = repo_execution_lock_path(working_dir);
    fs::create_dir_all(repo_ota_state_dir(working_dir)).map_err(|source| {
        RunError::RepoExecutionLockFailed {
            task: task_name.to_string(),
            action: String::from("create"),
            path: lock_path.display().to_string(),
            details: source.to_string(),
        }
    })?;
    let lock_file = fs::OpenOptions::new()
        .create(true)
        .read(true)
        .write(true)
        .open(&lock_path)
        .map_err(|source| RunError::RepoExecutionLockFailed {
            task: task_name.to_string(),
            action: String::from("open"),
            path: lock_path.display().to_string(),
            details: source.to_string(),
        })?;
    lock_file
        .lock_exclusive()
        .map_err(|source| RunError::RepoExecutionLockFailed {
            task: task_name.to_string(),
            action: action.to_string(),
            path: lock_path.display().to_string(),
            details: source.to_string(),
        })?;
    Ok(RepoExecutionLockGuard { lock_file })
}

fn read_active_repo_execution_records(
    working_dir: &Path,
) -> io::Result<Vec<ActiveRepoExecutionRecord>> {
    let path = repo_active_executions_path(working_dir);
    if !path.exists() {
        return Ok(Vec::new());
    }
    let contents = fs::read_to_string(path)?;
    if contents.trim().is_empty() {
        return Ok(Vec::new());
    }
    serde_json::from_str(contents.trim())
        .map_err(|error| io::Error::new(io::ErrorKind::InvalidData, error.to_string()))
}

fn write_active_repo_execution_records(
    working_dir: &Path,
    records: &[ActiveRepoExecutionRecord],
) -> io::Result<()> {
    let path = repo_active_executions_path(working_dir);
    if records.is_empty() {
        if path.exists() {
            fs::remove_file(path)?;
        }
        return Ok(());
    }
    let contents = serde_json::to_string_pretty(records)
        .map_err(|error| io::Error::new(io::ErrorKind::InvalidData, error.to_string()))?;
    fs::write(path, format!("{contents}\n"))
}

fn active_repo_execution_record_alive(record: &ActiveRepoExecutionRecord) -> bool {
    owner_pid_running(record.owner.pid).unwrap_or(true)
}

fn execution_conflict_reasons_with_active_owner(
    candidate: &RepoExecutionLockOwner,
    active: &RepoExecutionLockOwner,
) -> Vec<RepoExecutionConflictReason> {
    let mut reasons = Vec::new();
    if candidate
        .host_services
        .iter()
        .any(|service| active.host_services.contains(service))
    {
        reasons.push(RepoExecutionConflictReason::HostService);
    }
    if candidate
        .compose_projects
        .iter()
        .any(|project| active.compose_projects.contains(project))
    {
        reasons.push(RepoExecutionConflictReason::ComposeProject);
    }
    if candidate
        .persistent_backend_families
        .iter()
        .any(|family| active.persistent_backend_families.contains(family))
    {
        reasons.push(RepoExecutionConflictReason::PersistentBackendFamily);
    }
    if candidate
        .env_materialization_paths
        .iter()
        .any(|path| active.env_materialization_paths.contains(path))
    {
        reasons.push(RepoExecutionConflictReason::EnvMaterializationPath);
    }
    if candidate.service_task && active.service_task && candidate.task == active.task {
        reasons.push(RepoExecutionConflictReason::ServiceTask);
    }
    reasons
}

fn execution_conflicts_with_active_owner(
    candidate: &RepoExecutionLockOwner,
    active: &RepoExecutionLockOwner,
) -> bool {
    !execution_conflict_reasons_with_active_owner(candidate, active).is_empty()
}

fn merge_execution_conflict_reason(
    reasons: &mut Vec<RepoExecutionConflictReason>,
    reason: RepoExecutionConflictReason,
) {
    if !reasons.contains(&reason) {
        reasons.push(reason);
    }
}

fn active_execution_conflict_reasons(
    candidate: &RepoExecutionLockOwner,
    owners: &[RepoExecutionLockOwner],
) -> Vec<RepoExecutionConflictReason> {
    let mut reasons = Vec::new();
    for owner in owners {
        for reason in execution_conflict_reasons_with_active_owner(candidate, owner) {
            merge_execution_conflict_reason(&mut reasons, reason);
        }
    }
    reasons
}

fn active_repo_execution_id(owner: &RepoExecutionLockOwner) -> String {
    format!(
        "{}-{}-{}",
        owner.pid,
        owner.task.replace(':', "_"),
        OffsetDateTime::now_utc().unix_timestamp_nanos()
    )
}

fn register_active_repo_execution(
    task_name: &str,
    working_dir: &Path,
    owner: &RepoExecutionLockOwner,
) -> Result<ActiveRepoExecutionGuard, RunError> {
    let _registry_lock = acquire_repo_execution_lock(task_name, working_dir, "lock")?;
    let mut records = read_active_repo_execution_records(working_dir).map_err(|source| {
        RunError::RepoExecutionLockFailed {
            task: task_name.to_string(),
            action: String::from("read"),
            path: repo_active_executions_path(working_dir)
                .display()
                .to_string(),
            details: source.to_string(),
        }
    })?;
    records.retain(active_repo_execution_record_alive);
    let owners = records
        .iter()
        .filter(|record| execution_conflicts_with_active_owner(owner, &record.owner))
        .map(|record| record.owner.clone())
        .collect::<Vec<_>>();
    if !owners.is_empty() {
        return Err(RunError::RepoExecutionConflict {
            task: task_name.to_string(),
            path: repo_active_executions_path(working_dir)
                .display()
                .to_string(),
            reasons: active_execution_conflict_reasons(owner, &owners),
            owners,
        });
    }
    let execution_id = active_repo_execution_id(owner);
    records.push(ActiveRepoExecutionRecord {
        id: execution_id.clone(),
        owner: owner.clone(),
    });
    write_active_repo_execution_records(working_dir, &records).map_err(|source| {
        RunError::RepoExecutionLockFailed {
            task: task_name.to_string(),
            action: String::from("write"),
            path: repo_active_executions_path(working_dir)
                .display()
                .to_string(),
            details: source.to_string(),
        }
    })?;
    Ok(ActiveRepoExecutionGuard {
        working_dir: working_dir.to_path_buf(),
        execution_id,
    })
}

fn unregister_active_repo_execution(working_dir: &Path, execution_id: &str) -> io::Result<()> {
    let _registry_lock =
        acquire_repo_execution_lock("__ota_unregister_execution__", working_dir, "lock")
            .map_err(|error| io::Error::other(error.to_string()))?;
    let mut records = read_active_repo_execution_records(working_dir)?;
    records
        .retain(|record| record.id != execution_id && active_repo_execution_record_alive(record));
    write_active_repo_execution_records(working_dir, &records)
}

fn ensure_no_active_repo_execution_conflicts(
    task_name: &str,
    working_dir: &Path,
    cleanup_scope: Option<&PersistentCleanupScope>,
) -> Result<(), RunError> {
    let _registry_lock = acquire_repo_execution_lock(task_name, working_dir, "lock")?;
    let mut records = read_active_repo_execution_records(working_dir).map_err(|source| {
        RunError::RepoExecutionLockFailed {
            task: task_name.to_string(),
            action: String::from("read"),
            path: repo_active_executions_path(working_dir)
                .display()
                .to_string(),
            details: source.to_string(),
        }
    })?;
    records.retain(active_repo_execution_record_alive);
    write_active_repo_execution_records(working_dir, &records).map_err(|source| {
        RunError::RepoExecutionLockFailed {
            task: task_name.to_string(),
            action: String::from("write"),
            path: repo_active_executions_path(working_dir)
                .display()
                .to_string(),
            details: source.to_string(),
        }
    })?;
    let owners = records
        .into_iter()
        .map(|record| record.owner)
        .filter(|owner| {
            !cleanup_scope
                .is_some_and(|scope| active_execution_owned_by_cleanup_scope(owner, scope))
        })
        .collect::<Vec<_>>();
    if owners.is_empty() {
        Ok(())
    } else {
        Err(RunError::RepoExecutionConflict {
            task: task_name.to_string(),
            path: repo_active_executions_path(working_dir)
                .display()
                .to_string(),
            reasons: vec![RepoExecutionConflictReason::ActiveExecutionPresent],
            owners,
        })
    }
}

fn active_execution_owned_by_cleanup_scope(
    owner: &RepoExecutionLockOwner,
    scope: &PersistentCleanupScope,
) -> bool {
    scope.task_names.contains(owner.task.as_str())
        && owner
            .host_services
            .iter()
            .all(|service| scope.service_names.contains(service.as_str()))
        && owner
            .compose_projects
            .iter()
            .all(|project| scope.compose_projects.contains(project.as_str()))
        && owner
            .persistent_backend_families
            .iter()
            .all(|family| scope.persistent_backend_families.contains(family.as_str()))
        && owner
            .env_materialization_paths
            .iter()
            .all(|path| scope.env_materialization_paths.contains(path.as_str()))
}

fn legacy_repo_ota_state_file_path(working_dir: &Path, file_name: &str) -> PathBuf {
    repo_ota_dir(working_dir).join(file_name)
}

fn repo_managed_engines_path(working_dir: &Path) -> PathBuf {
    repo_ota_state_file_path(working_dir, OTA_MANAGED_ENGINES_FILE)
}

fn repo_managed_engines(
    _task_name: &str,
    working_dir: &Path,
) -> Result<BTreeSet<String>, RunError> {
    let path = repo_managed_engines_path(working_dir);
    let legacy_path = legacy_repo_ota_state_file_path(working_dir, OTA_MANAGED_ENGINES_FILE);
    if path.exists() && legacy_path.exists() {
        let _ = fs::remove_file(&legacy_path);
    }
    let Ok(contents) = fs::read_to_string(&path).or_else(|_| fs::read_to_string(&legacy_path))
    else {
        return Ok(BTreeSet::new());
    };

    let engines: BTreeSet<String> = contents
        .lines()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(String::from)
        .collect();

    if !path.exists() && legacy_path.exists() {
        if let Some(parent) = path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        let mut serialized = String::new();
        for engine in &engines {
            serialized.push_str(engine.as_str());
            serialized.push('\n');
        }
        let _ = fs::write(&path, serialized);
        let _ = fs::remove_file(&legacy_path);
    }

    Ok(engines)
}

fn write_repo_managed_engines(
    task_name: &str,
    working_dir: &Path,
    engines: &BTreeSet<String>,
) -> Result<(), RunError> {
    let path = repo_managed_engines_path(working_dir);
    let legacy_path = legacy_repo_ota_state_file_path(working_dir, OTA_MANAGED_ENGINES_FILE);
    fs::create_dir_all(repo_ota_state_dir(working_dir)).map_err(|source| {
        RunError::DependencyIsolationOwnershipFailure {
            task: task_name.to_string(),
            action: String::from("create"),
            path: path.display().to_string(),
            details: source.to_string(),
        }
    })?;

    if engines.is_empty() {
        let _ = fs::remove_file(&path);
        let _ = fs::remove_file(&legacy_path);
        return Ok(());
    }

    let mut contents = String::new();
    for engine in engines {
        contents.push_str(engine);
        contents.push('\n');
    }

    fs::write(&path, contents).map_err(|source| RunError::DependencyIsolationOwnershipFailure {
        task: task_name.to_string(),
        action: String::from("write"),
        path: path.display().to_string(),
        details: source.to_string(),
    })?;
    let _ = fs::remove_file(&legacy_path);
    Ok(())
}

fn record_repo_managed_engine(
    task_name: &str,
    working_dir: &Path,
    engine: &str,
) -> Result<(), RunError> {
    let mut engines = repo_managed_engines(task_name, working_dir)?;
    if engines.insert(engine.to_string()) {
        write_repo_managed_engines(task_name, working_dir, &engines)?;
    }
    Ok(())
}

fn repo_ownership_token(task_name: &str, contract_path: &Path) -> Result<String, RunError> {
    let working_dir = contract_working_dir(contract_path);
    repo_ownership_token_for_working_dir(task_name, working_dir)
}

fn repo_ownership_token_for_working_dir(
    task_name: &str,
    working_dir: &Path,
) -> Result<String, RunError> {
    let token_path = repo_ota_state_file_path(working_dir, OTA_OWNERSHIP_ID_FILE);
    let legacy_token_path = legacy_repo_ota_state_file_path(working_dir, OTA_OWNERSHIP_ID_FILE);
    if token_path.exists() && legacy_token_path.exists() {
        let _ = fs::remove_file(&legacy_token_path);
    }

    if let Ok(token) =
        fs::read_to_string(&token_path).or_else(|_| fs::read_to_string(&legacy_token_path))
    {
        let trimmed = token.trim();
        if !trimmed.is_empty() {
            if !token_path.exists() && legacy_token_path.exists() {
                if let Some(parent) = token_path.parent() {
                    let _ = fs::create_dir_all(parent);
                }
                let _ = fs::write(&token_path, trimmed);
                let _ = fs::remove_file(&legacy_token_path);
            }
            return Ok(trimmed.to_string());
        }
    }

    fs::create_dir_all(repo_ota_state_dir(working_dir)).map_err(|source| {
        RunError::DependencyIsolationOwnershipFailure {
            task: task_name.to_string(),
            action: String::from("create"),
            path: token_path.display().to_string(),
            details: source.to_string(),
        }
    })?;

    let mut hasher = DefaultHasher::new();
    working_dir.display().to_string().hash(&mut hasher);
    std::process::id().hash(&mut hasher);
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos()
        .hash(&mut hasher);
    let token = format!("{:016x}", hasher.finish());

    fs::write(&token_path, &token).map_err(|source| {
        RunError::DependencyIsolationOwnershipFailure {
            task: task_name.to_string(),
            action: String::from("write"),
            path: token_path.display().to_string(),
            details: source.to_string(),
        }
    })?;
    let _ = fs::remove_file(&legacy_token_path);

    Ok(token)
}

#[derive(Debug, Clone)]
struct NativeTaskActivationRequest {
    prerequisite_name: String,
    activation: NativePrerequisiteActivationSpec,
}

fn task_native_activation_env(
    contract: &Contract,
    task_name: &str,
    task: &TaskSpec,
    backend: &ResolvedExecutionBackend,
    working_dir: &Path,
    current_os: &str,
    state: &mut TaskRunState,
) -> Result<Option<BTreeMap<String, String>>, RunError> {
    if !matches!(backend, ResolvedExecutionBackend::Native { .. }) {
        return Ok(None);
    }

    let backend_kind = resolved_execution_backend_kind(backend);
    let context_name = task.context_for_backend(contract.execution.as_ref(), backend_kind);
    let requests = collect_native_task_activation_requests(
        contract,
        task,
        backend_kind,
        context_name,
        current_os,
    );
    if requests.is_empty() {
        return Ok(None);
    }

    let cache_key = native_activation_cache_key(task_name, &requests)?;
    if let Some(cached) = state.native_activation_env_cache.get(cache_key.as_str()) {
        return Ok(Some(cached.clone()));
    }

    let request = requests
        .first()
        .expect("non-empty activation request list should have a first entry");
    let env = capture_native_activation_env(
        task_name,
        request.prerequisite_name.as_str(),
        &request.activation,
        working_dir,
    )?;
    state
        .native_activation_env_cache
        .insert(cache_key, env.clone());
    Ok(Some(env))
}

fn collect_native_task_activation_requests(
    contract: &Contract,
    task: &TaskSpec,
    backend: Backend,
    context_name: Option<&str>,
    current_os: &str,
) -> Vec<NativeTaskActivationRequest> {
    let mut requests = Vec::new();
    let mut seen = BTreeSet::<String>::new();
    for native_name in task.scoped_native_requirements_for_execution(backend, context_name) {
        if !seen.insert(native_name.clone()) {
            continue;
        }
        let Some(prerequisite) = contract.native_prerequisites.get(native_name.as_str()) else {
            continue;
        };
        let Some(platform) = prerequisite.platform_for_os(current_os) else {
            continue;
        };
        let Some(activation) = platform.activation.as_ref() else {
            continue;
        };
        requests.push(NativeTaskActivationRequest {
            prerequisite_name: native_name,
            activation: activation.clone(),
        });
    }
    requests
}

fn native_activation_cache_key(
    task_name: &str,
    requests: &[NativeTaskActivationRequest],
) -> Result<String, RunError> {
    let first = requests
        .first()
        .expect("non-empty activation request list should have a first entry");
    let first_key = single_native_activation_key(&first.activation);
    let incompatible = requests
        .iter()
        .filter(|request| single_native_activation_key(&request.activation) != first_key)
        .map(|request| {
            format!(
                "{} ({})",
                request.prerequisite_name,
                single_native_activation_key(&request.activation)
            )
        })
        .collect::<Vec<_>>();
    if !incompatible.is_empty() {
        let mut entries = vec![format!("{} ({})", first.prerequisite_name, first_key)];
        entries.extend(incompatible);
        return Err(RunError::ConflictingNativePrerequisiteActivations {
            task: task_name.to_string(),
            details: entries.join(", "),
        });
    }
    Ok(first_key)
}

fn single_native_activation_key(activation: &NativePrerequisiteActivationSpec) -> String {
    match activation.kind {
        NativePrerequisiteActivationKind::VisualStudioDevShell => format!(
            "visual_studio_dev_shell:{}",
            activation.arch.as_deref().unwrap_or("x64")
        ),
        NativePrerequisiteActivationKind::Command => format!(
            "command:{}:{}",
            activation
                .shell
                .map(native_activation_shell_label)
                .unwrap_or("unknown"),
            activation.run.as_deref().unwrap_or_default()
        ),
    }
}

fn native_activation_shell_label(shell: NativePrerequisiteActivationShell) -> &'static str {
    match shell {
        NativePrerequisiteActivationShell::Sh => "sh",
        NativePrerequisiteActivationShell::Bash => "bash",
        NativePrerequisiteActivationShell::Zsh => "zsh",
        NativePrerequisiteActivationShell::Pwsh => "pwsh",
        NativePrerequisiteActivationShell::Cmd => "cmd",
    }
}

fn capture_native_activation_env(
    task_name: &str,
    prerequisite_name: &str,
    activation: &NativePrerequisiteActivationSpec,
    working_dir: &Path,
) -> Result<BTreeMap<String, String>, RunError> {
    match activation.kind {
        NativePrerequisiteActivationKind::VisualStudioDevShell => {
            capture_visual_studio_dev_shell_env(
                task_name,
                prerequisite_name,
                working_dir,
                activation.arch.as_deref().unwrap_or("x64"),
            )
        }
        NativePrerequisiteActivationKind::Command => {
            capture_command_activation_env(task_name, prerequisite_name, activation, working_dir)
        }
    }
}

pub(crate) fn capture_declared_native_activation_env(
    prerequisite_name: &str,
    activation: &NativePrerequisiteActivationSpec,
    working_dir: &Path,
) -> Result<BTreeMap<String, String>, String> {
    capture_native_activation_env("doctor", prerequisite_name, activation, working_dir)
        .map_err(|error| error.to_string())
}

fn capture_visual_studio_dev_shell_env(
    task_name: &str,
    prerequisite_name: &str,
    working_dir: &Path,
    arch: &str,
) -> Result<BTreeMap<String, String>, RunError> {
    #[cfg(not(windows))]
    {
        let _ = (task_name, prerequisite_name, working_dir, arch);
        return Ok(BTreeMap::new());
    }

    #[cfg(windows)]
    {
        let Some(vswhere_path) = visual_studio_vswhere_path() else {
            return Err(RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details: String::from(
                    "Visual Studio Developer Shell activation requires `ProgramFiles(x86)` to be set",
                ),
            });
        };
        if !vswhere_path.is_file() {
            return Err(RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details: format!(
                    "Visual Studio installer locator was not found at `{}`",
                    vswhere_path.display()
                ),
            });
        }

        let vswhere_output = visual_studio_installation_path(&vswhere_path).map_err(|source| {
            RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details: format!(
                    "failed to execute Visual Studio installer locator `{}`: {source}",
                    vswhere_path.display()
                ),
            }
        })?;
        if !vswhere_output.status.success() {
            let stdout = String::from_utf8_lossy(&vswhere_output.stdout)
                .trim()
                .to_string();
            let stderr = String::from_utf8_lossy(&vswhere_output.stderr)
                .trim()
                .to_string();
            let details = match (stdout.is_empty(), stderr.is_empty()) {
                (false, false) => format!("{stdout}; {stderr}"),
                (false, true) => stdout,
                (true, false) => stderr,
                (true, true) => format!(
                    "Visual Studio installer locator exited with code {}",
                    vswhere_output.status.code().unwrap_or(1)
                ),
            };
            return Err(RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details: format!(
                    "Visual Studio installer locator `{}` failed: {details}",
                    vswhere_path.display()
                ),
            });
        }

        let installation_path = String::from_utf8_lossy(&vswhere_output.stdout)
            .lines()
            .map(str::trim)
            .find(|line| !line.is_empty())
            .map(PathBuf::from)
            .ok_or_else(|| RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details: format!(
                    "Visual Studio installer locator `{}` did not return an installation path with the MSVC tools component",
                    vswhere_path.display()
                ),
            })?;

        let vsdevcmd_path = installation_path
            .join("Common7")
            .join("Tools")
            .join("VsDevCmd.bat");
        if !vsdevcmd_path.is_file() {
            return Err(RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details: format!(
                    "Visual Studio Developer shell script was not found at `{}`",
                    vsdevcmd_path.display()
                ),
            });
        }

        let script_path = visual_studio_dev_shell_script_path();
        write_visual_studio_dev_shell_script(&script_path, &vsdevcmd_path, arch).map_err(
            |source| RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details: format!(
                    "failed to write Visual Studio Developer shell wrapper `{}`: {source}",
                    script_path.display()
                ),
            },
        )?;
        let output = Command::new("cmd")
            .args(["/d", "/s", "/c", script_path.to_string_lossy().as_ref()])
            .current_dir(working_dir)
            .output();
        let _ = fs::remove_file(&script_path);
        let output = output.map_err(|source| RunError::NativePrerequisiteActivationFailed {
            task: task_name.to_string(),
            prerequisite: prerequisite_name.to_string(),
            details: format!(
                "failed to execute Visual Studio Developer shell wrapper `{}`: {source}",
                script_path.display()
            ),
        })?;
        if !output.status.success() {
            let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
            let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
            let details = match (stdout.is_empty(), stderr.is_empty()) {
                (false, false) => format!("{stdout}; {stderr}"),
                (false, true) => stdout,
                (true, false) => stderr,
                (true, true) => format!(
                    "Visual Studio Developer shell `{}` exited with code {}",
                    vsdevcmd_path.display(),
                    output.status.code().unwrap_or(1)
                ),
            };
            return Err(RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details,
            });
        }

        let env = parse_windows_env_block(&String::from_utf8_lossy(&output.stdout));
        if env.is_empty() {
            return Err(RunError::NativePrerequisiteActivationFailed {
                task: task_name.to_string(),
                prerequisite: prerequisite_name.to_string(),
                details: format!(
                    "Visual Studio Developer shell `{}` did not produce any environment values",
                    vsdevcmd_path.display()
                ),
            });
        }
        Ok(env)
    }
}

fn capture_command_activation_env(
    task_name: &str,
    prerequisite_name: &str,
    activation: &NativePrerequisiteActivationSpec,
    working_dir: &Path,
) -> Result<BTreeMap<String, String>, RunError> {
    let shell = activation
        .shell
        .expect("validated command activation shell");
    let run = activation
        .run
        .as_deref()
        .expect("validated command activation run");
    let output = command_activation_env_output(shell, run, working_dir).map_err(|source| {
        RunError::NativePrerequisiteActivationFailed {
            task: task_name.to_string(),
            prerequisite: prerequisite_name.to_string(),
            details: format!(
                "failed to execute `{}` native activation command: {source}",
                native_activation_shell_label(shell)
            ),
        }
    })?;
    if !output.status.success() {
        let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
        let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
        let details = match (stdout.is_empty(), stderr.is_empty()) {
            (false, false) => format!("{stdout}; {stderr}"),
            (false, true) => stdout,
            (true, false) => stderr,
            (true, true) => format!(
                "native activation command via `{}` exited with code {}",
                native_activation_shell_label(shell),
                output.status.code().unwrap_or(1)
            ),
        };
        return Err(RunError::NativePrerequisiteActivationFailed {
            task: task_name.to_string(),
            prerequisite: prerequisite_name.to_string(),
            details,
        });
    }
    let env = parse_activation_env_output(shell, &output.stdout);
    if env.is_empty() {
        return Err(RunError::NativePrerequisiteActivationFailed {
            task: task_name.to_string(),
            prerequisite: prerequisite_name.to_string(),
            details: format!(
                "native activation command via `{}` did not produce any environment values",
                native_activation_shell_label(shell)
            ),
        });
    }
    Ok(env)
}

fn command_activation_env_output(
    shell: NativePrerequisiteActivationShell,
    run: &str,
    working_dir: &Path,
) -> io::Result<std::process::Output> {
    let mut command = match shell {
        NativePrerequisiteActivationShell::Sh => {
            let mut command = Command::new("sh");
            command.arg("-lc").arg(format!("{run}\nenv -0"));
            command
        }
        NativePrerequisiteActivationShell::Bash => {
            let mut command = Command::new("bash");
            command.arg("-lc").arg(format!("{run}\nenv -0"));
            command
        }
        NativePrerequisiteActivationShell::Zsh => {
            let mut command = Command::new("zsh");
            command.arg("-lc").arg(format!("{run}\nenv -0"));
            command
        }
        NativePrerequisiteActivationShell::Pwsh => {
            let mut command = Command::new("pwsh");
            command.args([
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                format!(
                    "& {{ {run}; Get-ChildItem Env: | ForEach-Object {{ \"{{0}}={{1}}\" -f $_.Name, $_.Value }} }}"
                )
                .as_str(),
            ]);
            command
        }
        NativePrerequisiteActivationShell::Cmd => {
            let mut command = Command::new("cmd");
            command.args(["/d", "/s", "/c", &format!("{run} && set")]);
            command
        }
    };
    command.current_dir(working_dir).output()
}

fn parse_activation_env_output(
    shell: NativePrerequisiteActivationShell,
    stdout: &[u8],
) -> BTreeMap<String, String> {
    match shell {
        NativePrerequisiteActivationShell::Sh
        | NativePrerequisiteActivationShell::Bash
        | NativePrerequisiteActivationShell::Zsh => parse_nul_env_block(stdout),
        NativePrerequisiteActivationShell::Pwsh | NativePrerequisiteActivationShell::Cmd => {
            parse_windows_env_block(&String::from_utf8_lossy(stdout))
        }
    }
}

#[cfg(windows)]
fn visual_studio_vswhere_path() -> Option<PathBuf> {
    let program_files = std::env::var_os("ProgramFiles(x86)")?;
    Some(
        PathBuf::from(program_files)
            .join("Microsoft Visual Studio")
            .join("Installer")
            .join("vswhere.exe"),
    )
}

#[cfg(windows)]
fn visual_studio_installation_path(vswhere_path: &Path) -> io::Result<std::process::Output> {
    Command::new(vswhere_path)
        .args([
            "-latest",
            "-products",
            "*",
            "-requires",
            "Microsoft.VisualStudio.Component.VC.Tools.x86.x64",
            "-property",
            "installationPath",
        ])
        .output()
}

#[cfg(windows)]
fn visual_studio_dev_shell_script_path() -> PathBuf {
    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    std::env::temp_dir().join(format!("ota-vsdevcmd-{}-{}.cmd", std::process::id(), nonce))
}

#[cfg(windows)]
fn write_visual_studio_dev_shell_script(
    script_path: &Path,
    vsdevcmd_path: &Path,
    arch: &str,
) -> io::Result<()> {
    fs::write(
        script_path,
        format!(
            "@echo off\r\ncall \"{}\" -no_logo -arch={} >nul\r\nif errorlevel 1 exit /b %errorlevel%\r\nset\r\n",
            vsdevcmd_path.display(),
            arch
        ),
    )
}

pub(crate) fn parse_windows_env_block(stdout: &str) -> BTreeMap<String, String> {
    stdout
        .lines()
        .filter_map(parse_windows_env_line)
        .filter(|(name, _)| name != "VSWHERE" && name != "VSINSTALL")
        .collect()
}

fn parse_nul_env_block(stdout: &[u8]) -> BTreeMap<String, String> {
    stdout
        .split(|byte| *byte == b'\0')
        .filter_map(|entry| {
            if entry.is_empty() {
                return None;
            }
            let text = String::from_utf8_lossy(entry);
            parse_unix_env_line(&text)
        })
        .collect()
}

fn parse_unix_env_line(line: &str) -> Option<(String, String)> {
    let (name, value) = line.split_once('=')?;
    if name.is_empty() {
        return None;
    }
    Some((name.to_string(), value.to_string()))
}

fn parse_windows_env_line(line: &str) -> Option<(String, String)> {
    let (name, value) = line.split_once('=')?;
    if name.is_empty() || name.starts_with('=') {
        return None;
    }
    Some((name.to_string(), value.to_string()))
}

fn current_os() -> &'static str {
    match std::env::consts::OS {
        "macos" => "macos",
        "windows" => "windows",
        other => other,
    }
}

fn current_arch() -> &'static str {
    match std::env::consts::ARCH {
        "x86_64" | "amd64" => "x64",
        "aarch64" | "arm64" => "arm64",
        other => other,
    }
}

fn visit_task_with_overrides(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
    explicit_backend_override: bool,
    parent_task: Option<&str>,
    parent_backend: Option<Backend>,
    visited: &mut BTreeSet<String>,
    ordered: &mut Vec<String>,
    steps: &mut Vec<RunPlanStep>,
) {
    if !visited.insert(task_name.to_string()) {
        return;
    }

    let task = contract
        .tasks
        .get(task_name)
        .expect("validated task plan should only reference known tasks");
    let backend = effective_task_execution(contract, task_name, overrides).backend;
    let context = task
        .context_for_backend(contract.execution.as_ref(), backend)
        .map(str::to_string);
    let backend_selection_source = task
        .backend_selection_source(
            contract.execution.as_ref(),
            backend,
            explicit_backend_override,
            parent_backend,
        )
        .to_string();

    for dependency in task.depends_on_for_backend(backend) {
        let dependency_spec = contract
            .tasks
            .get(dependency)
            .expect("validated task plan should only reference known tasks");
        let dependency_overrides = ExecutionOverrides {
            backend: dependency_spec
                .dependency_backend_override_for_parent(overrides.backend, backend),
            ..overrides
        };
        visit_task_with_overrides(
            contract,
            dependency,
            dependency_overrides,
            explicit_backend_override,
            Some(task_name),
            Some(backend),
            visited,
            ordered,
            steps,
        );
    }
    if let Some(aggregate) = task.aggregate.as_ref() {
        for child in &aggregate.tasks {
            visit_task_with_overrides(
                contract,
                child,
                overrides,
                explicit_backend_override,
                Some(task_name),
                Some(backend),
                visited,
                ordered,
                steps,
            );
        }
    }

    steps.push(RunPlanStep {
        task: task_name.to_string(),
        parent: parent_task.map(str::to_string),
        backend,
        context,
        backend_selection_source,
    });
    ordered.push(task_name.to_string());
}

#[cfg(unix)]
fn shell_command(command: &str) -> Command {
    let mut shell = Command::new("sh");
    shell
        .arg("-c")
        .arg(signal_forwarding_shell_script(command.to_string()));
    shell
}

#[cfg(windows)]
fn shell_command(command: &str) -> Command {
    if looks_like_powershell_script(command) {
        return powershell_shell_command(command);
    }
    if looks_like_posix_script(command)
        && let Some(bash) = bash_executable()
    {
        bash_posix_shell_command(bash, command)
    } else {
        let mut shell = Command::new("cmd");
        shell.arg("/C").arg(command);
        shell
    }
}

#[cfg(any(windows, test))]
fn bash_posix_shell_command(executable: PathBuf, command: &str) -> Command {
    let mut shell = Command::new(executable);
    shell.args(["--noprofile", "--norc", "-c"]).arg(command);
    shell
}

#[cfg(any(windows, test))]
fn looks_like_posix_script(command: &str) -> bool {
    let command = command.trim();
    if command.is_empty() || looks_like_powershell_script(command) {
        return false;
    }
    const POSIX_MARKERS: [&str; 8] = [
        "command -v ",
        "; then",
        " fi",
        "&& ",
        " || ",
        "<<'PY'",
        "sh -lc ",
        "bash -lc ",
    ];
    if command.starts_with("cmd ") || command.starts_with("cmd/") {
        return false;
    }
    if command
        .split_ascii_whitespace()
        .next()
        .is_some_and(|token| {
            matches!(
                token,
                "printf"
                    | "test"
                    | "env"
                    | "python3"
                    | "python"
                    | "rm"
                    | "touch"
                    | "cat"
                    | "mkdir"
                    | "cp"
                    | "mv"
                    | "grep"
                    | "ls"
                    | "sh"
                    | "bash"
            )
        })
    {
        return true;
    }
    command.starts_with("./")
        || command.starts_with("../")
        || command.contains("&&")
        || command.contains("||")
        || POSIX_MARKERS.iter().any(|marker| command.contains(marker))
        || command.contains('\n')
        || command.contains("export ")
        || command.contains("printf '")
        || command.contains("printf \"")
        || command.starts_with("printf")
        || contains_posix_env_reference(command)
}

#[cfg(windows)]
fn has_bash() -> bool {
    bash_executable().is_some()
}

#[cfg(windows)]
fn bash_executable() -> Option<PathBuf> {
    static BASH: OnceLock<Option<PathBuf>> = OnceLock::new();
    BASH.get_or_init(find_bash_executable).clone()
}

#[cfg(windows)]
fn find_bash_executable() -> Option<PathBuf> {
    let mut candidates = env::var_os("PATH")
        .map(|paths| {
            env::split_paths(&paths)
                .flat_map(|dir| [dir.join("bash.exe"), dir.join("bash")])
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    for key in ["ProgramW6432", "ProgramFiles", "ProgramFiles(x86)"] {
        if let Some(base) = env::var_os(key) {
            let base = PathBuf::from(base);
            candidates.push(base.join("Git").join("bin").join("bash.exe"));
            candidates.push(base.join("Git").join("usr").join("bin").join("bash.exe"));
        }
    }

    candidates.into_iter().find(|candidate| {
        candidate.is_file()
            && Command::new(candidate)
                .arg("--version")
                .status()
                .map(|status| status.success())
                .unwrap_or(false)
    })
}

#[cfg(any(windows, test))]
fn looks_like_powershell_script(command: &str) -> bool {
    let command = command.trim_start();
    command.starts_with("powershell ")
        || command.starts_with("pwsh ")
        || command.contains("$LASTEXITCODE")
        || command.contains("$env:")
        || command.contains("Join-Path ")
        || command.contains("Test-Path ")
        || command.contains("Add-Content ")
        || command.contains("Set-Content ")
        || command.contains("Get-ChildItem ")
        || command.contains("New-Item ")
        || command.contains("Write-Host ")
        || command.contains("Write-Error ")
        || command.contains("throw ")
}

#[cfg(any(windows, test))]
fn contains_posix_env_reference(command: &str) -> bool {
    let bytes = command.as_bytes();
    bytes.windows(2).any(|window| {
        window[0] == b'$'
            && (window[1] == b'{' || window[1] == b'_' || window[1].is_ascii_alphabetic())
    })
}

#[cfg(windows)]
fn powershell_shell_command(command: &str) -> Command {
    let executable = if has_pwsh() { "pwsh" } else { "powershell" };
    let mut shell = Command::new(executable);
    shell.args(["-NoProfile", "-NonInteractive", "-Command", command]);
    shell
}

#[cfg(windows)]
fn has_pwsh() -> bool {
    static HAS_PWSH: OnceLock<bool> = OnceLock::new();
    *HAS_PWSH.get_or_init(|| {
        Command::new("pwsh")
            .args(["-NoProfile", "-NonInteractive", "-Command", "exit 0"])
            .status()
            .map(|status| status.success())
            .unwrap_or(false)
    })
}

