    #[test]
    fn effective_task_env_for_backend_expands_workspace_templates_and_preserves_override_precedence()
     {
        let fixture = TempDir::new().expect("tempdir should create");
        let working_dir = fixture.path();
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: tooling
  contexts:
    tooling:
      backend: container
      lifecycle: ephemeral
      container:
        image: node:24-bookworm
      attachments:
        isolated_paths:
          - .npm
tasks:
  api:
    context: tooling
    env:
      NPM_CONFIG_CACHE: ${OTA_WORKSPACE}/custom-npm
      CUSTOM_ROOT: ${OTA_WORKSPACE}/cache
      HOST_ROOT: ${OTA_HOST_WORKSPACE}
      HOST_HOME: ${OTA_HOST_HOME}
      USER_UID: ${OTA_HOST_UID}
    script: ./scripts/api/run.sh
"#,
        )
        .unwrap();

        let env = effective_task_env_for_backend(
            &contract,
            contract.tasks.get("api").unwrap(),
            &ResolvedExecutionBackend::Container {
                context_name: Some(String::from("tooling")),
                shared_local_backend: None,
                image: String::from("node:24-bookworm"),
                engine: String::from("docker"),
                lifecycle: Lifecycle::Ephemeral,
                memory_bytes: None,
                compose_networks: Vec::new(),
                publications: Vec::new(),
                dependency_isolation_paths: vec![String::from(".npm")],
            },
            working_dir,
        );

        assert_eq!(
            env.get("OTA_WORKSPACE").map(String::as_str),
            Some("/workspace")
        );
        assert_eq!(
            env.get("NPM_CONFIG_CACHE").map(String::as_str),
            Some("/workspace/custom-npm")
        );
        assert_eq!(
            env.get("CUSTOM_ROOT").map(String::as_str),
            Some("/workspace/cache")
        );
        assert_eq!(
            env.get("HOST_ROOT").map(String::as_str),
            Some(
                fs::canonicalize(working_dir)
                    .expect("working dir should canonicalize")
                    .to_string_lossy()
                    .as_ref(),
            )
        );
        let expected_home = if cfg!(windows) {
            env::var("USERPROFILE").ok()
        } else {
            env::var("HOME").ok()
        };
        if let Some(expected_home) = expected_home.as_deref().filter(|value| !value.trim().is_empty())
        {
            assert_eq!(
                env.get("HOST_HOME").map(String::as_str),
                Some(expected_home)
            );
            assert_eq!(
                env.get("OTA_HOST_HOME").map(String::as_str),
                Some(expected_home)
            );
        }
        #[cfg(unix)]
        {
            let expected_uid = fs::metadata(working_dir)
                .expect("repo fixture metadata should load")
                .uid()
                .to_string();
            assert_eq!(
                env.get("USER_UID").map(String::as_str),
                Some(expected_uid.as_str())
            );
        }
    }

    #[test]
    fn effective_task_env_for_backend_uses_absolute_host_workspace_for_relative_working_dir() {
        let _cwd_guard = cwd_mutex_lock();
        let _env_guard = env_mutex_lock();
        let root = TempDir::new().expect("tempdir should create");
        let repo_dir = root.path().join("repo");
        fs::create_dir_all(&repo_dir).expect("repo dir should create");
        let original_cwd = env::current_dir().expect("current dir should resolve");
        env::set_current_dir(&repo_dir).expect("current dir should update");

        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: tooling
  contexts:
    tooling:
      backend: container
      lifecycle: ephemeral
      container:
        image: node:24-bookworm
tasks:
  api:
    context: tooling
    env:
      HOST_ROOT: ${OTA_HOST_WORKSPACE}
    script: ./scripts/api/run.sh
"#,
        )
        .unwrap();

        let env = effective_task_env_for_backend(
            &contract,
            contract.tasks.get("api").unwrap(),
            &ResolvedExecutionBackend::Container {
                context_name: Some(String::from("tooling")),
                shared_local_backend: None,
                image: String::from("node:24-bookworm"),
                engine: String::from("docker"),
                lifecycle: Lifecycle::Ephemeral,
                memory_bytes: None,
                compose_networks: Vec::new(),
                publications: Vec::new(),
                dependency_isolation_paths: Vec::new(),
            },
            Path::new("."),
        );

        env::set_current_dir(original_cwd).expect("current dir should restore");

        let expected = fs::canonicalize(&repo_dir)
            .expect("repo dir should canonicalize")
            .display()
            .to_string();
        assert_eq!(
            env.get("OTA_HOST_WORKSPACE").map(String::as_str),
            Some(expected.as_str())
        );
        assert_eq!(
            env.get("HOST_ROOT").map(String::as_str),
            Some(expected.as_str())
        );
    }

