    fn remote_activation_backend_demo_contract(
        task_name: &str,
        port: u16,
        readiness_kind: &str,
        address_view: &str,
        include_host_projection: bool,
    ) -> String {
        let target = format!("sandbox-{task_name}");
        let readiness = match readiness_kind {
            "tcp" => String::from("      readiness:\n        kind: tcp\n        listener: http\n"),
            "http" => String::from(
                "      readiness:\n        kind: http\n        listener: http\n        path: /\n",
            ),
            other => panic!("unsupported readiness kind: {other}"),
        };
        let host_projection = if include_host_projection {
            format!(
                "          project:\n            host:\n              address: 127.0.0.1\n              port:\n                mode: fixed\n                value: {port}\n"
            )
        } else {
            String::new()
        };
        format!(
            r#"
version: 1
project:
  name: ota
extensions:
  backend-demo:
    kind: backend_provider
    command: |
      log_file="${{PWD}}/backend-provider-contexts.log"
      printf '%s\n' "$OTA_BACKEND_PROVIDER_COMMAND_CONTEXT" >> "$log_file"
      case "$OTA_BACKEND_PROVIDER_COMMAND_CONTEXT" in
      activation)
        python3 -m http.server {port} --bind 127.0.0.1 >/dev/null 2>&1 &
        printf '%s\n' "$!" > "${{PWD}}/backend-provider.pid"
        printf '{{"ok":true,"result":{{"exit_code":0,"stdout":"","stderr":"","target":"{target}"}},"errors":[]}}'
        ;;
      activation_probe)
        sh -lc "$OTA_BACKEND_PROVIDER_COMMAND" >/dev/null 2>&1
        status=$?
        printf '{{"ok":true,"result":{{"exit_code":%s,"stdout":"","stderr":"","target":"{target}"}},"errors":[]}}' "$status"
        ;;
      activation_cleanup)
        if [ -f "${{PWD}}/backend-provider.pid" ]; then
          kill "$(cat "${{PWD}}/backend-provider.pid")" 2>/dev/null || true
          rm -f "${{PWD}}/backend-provider.pid"
        fi
        for pid in $(lsof -ti TCP:{port} -sTCP:LISTEN 2>/dev/null || true); do
          kill "$pid" 2>/dev/null || true
        done
        printf '{{"ok":true,"result":{{"exit_code":0,"stdout":"cleaned","stderr":"","target":"{target}"}},"errors":[]}}'
        ;;
      *)
        printf '{{"ok":false,"errors":["unexpected command context"]}}'
        ;;
      esac
    api_version: 1
    activation:
      provider_managed_cleanup: true
execution:
  default_context: remote_app
  contexts:
    remote_app:
      backend: remote
      remote:
        provider: backend-demo
        target: {target}
  shared_backends:
    workbench:
      scope: remote
      backend: remote
      lifecycle: persistent
      context: remote_app
tasks:
  {task_name}:
    run: echo {task_name}
    runtime:
      kind: service
      backend_binding: workbench
{readiness}      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: {port}
{host_projection}  sandbox:
    run: echo sandbox
    runtime:
      kind: service
      backend_binding: workbench
    targets:
      api:
        service:
          task: {task_name}
          listener: http
          address_view: {address_view}
        activation:
          mode: ensure_ready
"#,
            task_name = task_name,
            port = port,
            readiness = readiness,
            host_projection = host_projection,
            address_view = address_view,
            target = target,
        )
    }

    #[cfg(unix)]
    #[test]
    fn ensure_ready_activation_starts_and_cleans_up_shared_remote_internal_target() {
        let _guard = env_mutex_lock();
        let dir = TempDir::new().unwrap();
        let file_path = dir.path().join("ota.yaml");
        let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
        let port = listener
            .local_addr()
            .expect("listener address should resolve")
            .port();
        drop(listener);

        let contents =
            remote_activation_backend_demo_contract("dev_internal", port, "tcp", "internal", false);
        fs::write(&file_path, contents.trim_start()).unwrap();
        let contract = parse_contract_str(&file_path, contents.trim_start()).unwrap();

        let task = contract
            .tasks
            .get("sandbox")
            .expect("sandbox task should exist");
        let target_spec = task
            .targets
            .get("api")
            .expect("target binding should be declared");
        let mut state = TaskRunState::default();
        let run_activation = |state: &mut TaskRunState| {
            super::ensure_target_producer_ready(
                &contract,
                &file_path,
                "sandbox",
                "api",
                target_spec,
                Backend::Remote,
                None,
                TaskExecutionMode::CaptureActivation,
                dir.path(),
                std::env::consts::OS,
                0,
                state,
            )
        };
        let status = match run_activation(&mut state) {
            Ok(status) => status,
            Err(error) if error.to_string().contains("Broken pipe") => {
                std::thread::sleep(std::time::Duration::from_millis(200));
                run_activation(&mut state)
                    .expect("shared remote internal activation should succeed after retry")
            }
            Err(error) => panic!("shared remote internal activation should succeed: {error}"),
        };

        assert_eq!(status, TaskTargetActivationStatus::StartedReady);
        let cleanup_note = super::cleanup_interrupted_activation_started_producers_and_note(
            &contract,
            &file_path,
            dir.path(),
            &mut state,
        );
        assert!(
            cleanup_note
                .as_deref()
                .is_some_and(|note| note.contains("workload cleaned up after interrupt")),
            "{cleanup_note:?}"
        );
    }

