    #[cfg(unix)]
    #[test]
    fn ensure_ready_activation_honors_readiness_retry_budget() {
        let _guard = env_mutex_lock();
        let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
        let port = listener
            .local_addr()
            .expect("listener address should resolve")
            .port();
        let server = thread::spawn(move || {
            listener
                .set_nonblocking(true)
                .expect("readiness probe listener should become nonblocking");
            let deadline = Instant::now() + Duration::from_secs(2);
            let mut handled = 0usize;
            while handled < 3 && Instant::now() < deadline {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        let mut buffer = [0u8; 256];
                        let _ = stream.read(&mut buffer);
                        stream
                            .write_all(b"HTTP/1.1 503 Service Unavailable\r\nContent-Length: 4\r\nConnection: close\r\n\r\nDOWN")
                            .expect("http readiness probe should write response");
                        handled += 1;
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(10));
                    }
                    Err(error) => panic!("http readiness probe should connect: {error}"),
                }
            }
            handled
        });
        let fixture = ContractFixture::new(
            format!(
                r#"
version: 1
project:
  name: ota
tasks:
  dev:
    run: python3 -c "import time; time.sleep(30)"
    runtime:
      kind: service
      readiness:
        kind: http
        listener: http
        path: /health
        success:
          status: [200]
        body:
          contains: "UP"
        interval: 50ms
        timeout: 200ms
        retries: 3
        start_period: 10ms
      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: {port}
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: {port}
  sandbox:
    run: echo sandbox
    targets:
      api:
        service:
          task: dev
          listener: http
          address_view: host
        activation:
          mode: ensure_ready
"#
            )
            .as_str(),
        );
        let task = fixture
            .contract
            .tasks
            .get("sandbox")
            .expect("sandbox task should exist");
        let target_spec = task
            .targets
            .get("api")
            .expect("target binding should be declared");
        let mut state = TaskRunState::default();
        let started_at = Instant::now();
        let error = super::ensure_target_producer_ready(
            &fixture.contract,
            fixture.file_path(),
            "sandbox",
            "api",
            target_spec,
            Backend::Native,
            None,
            TaskExecutionMode::Capture,
            fixture.dir.path(),
            std::env::consts::OS,
            0,
            &mut state,
        )
        .unwrap_err();

        let handled = server
            .join()
            .expect("http readiness probe server should finish");
        assert!(
            (1..=3).contains(&handled),
            "readiness probe should stop within the configured retry budget (handled={handled})"
        );
        assert!(started_at.elapsed() < Duration::from_secs(3));
        assert!(!error.to_string().is_empty());
        let _cleanup_note = super::cleanup_interrupted_activation_started_producers_and_note(
            &fixture.contract,
            fixture.file_path(),
            fixture.dir.path(),
            &mut state,
        );
    }

