    #[test]
    fn monorepo_cross_member_target_binding_resolves_declared_host_service_url() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota-monorepo
workspace:
  type: monorepo
  members:
    - api
    - web
tasks:
  root:
    run: echo root
"#,
        );
        fixture.write(
            "api/ota.yaml",
            r#"
tasks:
  dev:
    context: app
    run: echo api
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 8080
"#,
        );
        fixture.write(
            "web/ota.yaml",
            r#"
tasks:
  sandbox:
    context: app
    run: echo web
    targets:
      api:
        service:
          member: api
          task: dev
          listener: http
          address_view: host
"#,
        );

        let (contract, contract_path) =
            load_contract_for_member(fixture.file_path(), "web").unwrap();
        let target_spec = contract
            .tasks
            .get("sandbox")
            .and_then(|task| task.targets.get("api"))
            .expect("target binding should be declared");
        let task = contract
            .tasks
            .get("sandbox")
            .expect("sandbox task should exist");

        let resolutions = super::resolve_task_target_bindings(
            &contract,
            &contract_path,
            "sandbox",
            task,
            &BTreeSet::new(),
            &mut BTreeMap::new(),
            Backend::Native,
            ExecutionOverrides::default(),
        )
        .expect("target resolution evidence should build");
        assert_eq!(
            resolutions[0]
                .service_ref
                .as_ref()
                .and_then(|service_ref| service_ref.member.as_deref()),
            Some("api")
        );

        let resolved = resolve_task_target_binding_url_with_contract_path(
            &contract,
            &contract_path,
            "sandbox",
            "api",
            target_spec,
            Backend::Native,
            ExecutionOverrides::default(),
        )
        .expect("cross-member host-view target should resolve");

        assert_eq!(resolved, "http://127.0.0.1:8080");
    }

