    #[test]
    #[cfg(unix)]
    fn native_task_execution_preserves_probe_path_without_login_shell() {
        let _guard = env_mutex_lock();
        let temp = TempDir::new().unwrap();
        let bin_dir = temp.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        write_fake_bin(&bin_dir, "node", "#!/bin/sh\nprintf 'v22.22.3\\n'\n");
        write_fake_bin(
            &bin_dir,
            "sh",
            "#!/bin/sh\nif [ \"$1\" = \"-lc\" ]; then\n  PATH='/usr/bin:/bin' exec /bin/sh -c \"$2\"\nfi\nexec /bin/sh \"$@\"\n",
        );

        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: shell-path
tasks:
  check-node:
    run: test "$(node --version)" = "v22.22.3"
    requirements:
      runtimes:
        node: ">=22"
"#,
        );

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        } else {
            path_entries.push(PathBuf::from("/usr/bin"));
            path_entries.push(PathBuf::from("/bin"));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", joined_path);
        }

        let result = run_task_captured(&fixture.contract, fixture.file_path(), "check-node");

        match original_path {
            Some(path) => unsafe { env::set_var("PATH", path) },
            None => unsafe { env::remove_var("PATH") },
        }

        let outcome = result.expect("native task execution should preserve resolved PATH");
        assert_eq!(outcome.exit_code, 0);
    }

    #[test]
    fn task_target_binding_does_not_resolve_listener_from_other_backend_mode() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
tasks:
  dev:
    execution:
      default_mode: native
      modes:
        native:
          run: echo native
          runtime:
            kind: service
            listeners:
              native_http:
                protocol: http
                bind:
                  address: 127.0.0.1
                  port:
                    mode: fixed
                    value: 8081
                project:
                  host:
                    address: 127.0.0.1
                    port:
                      mode: fixed
                      value: 8081
        container:
          run: echo container
          runtime:
            kind: service
            listeners:
              container_http:
                protocol: http
                bind:
                  address: 127.0.0.1
                  port:
                    mode: fixed
                    value: 8080
                project:
                  host:
                    address: 127.0.0.1
                    port:
                      mode: fixed
                      value: 8080
  sandbox:
    inputs:
      base_url:
        required: true
    targets:
      api:
        service:
          task: dev
          listener: container_http
          address_view: topology
        override_input: base_url
    script: |
      printf '%s' "$OTA_INPUT_BASE_URL" > inputs.txt
"#,
        );

        let error = run_task_captured_with_args_with_overrides(
            &fixture.contract,
            fixture.file_path(),
            "sandbox",
            &[],
            ExecutionOverrides::default(),
        )
        .unwrap_err();

        assert!(matches!(error, RunError::TaskTargetResolutionFailed { .. }));
        assert!(
            error
                .to_string()
                .contains("references unknown listener `container_http` on service task `dev`")
        );
    }

