    #[test]
    fn dependency_task_resolves_target_bindings_without_explicit_inputs() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
tasks:
  dev:
    run: echo dev
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: 8080
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 8080
  sandbox:
    inputs:
      base_url:
        required: true
    targets:
      api:
        service:
          task: dev
          listener: http
          address_view: topology
        override_input: base_url
    script: |
      printf '%s' "$OTA_INPUT_BASE_URL" > sandbox_url.txt
  ci:
    run: test -f sandbox_url.txt
    depends_on:
      - sandbox
"#,
        );

        let outcome = run_task_captured_with_args_with_overrides(
            &fixture.contract,
            fixture.file_path(),
            "ci",
            &[],
            ExecutionOverrides::default(),
        )
        .unwrap();

        assert_eq!(outcome.exit_code, 0);
        assert_eq!(
            fs::read_to_string(fixture.dir.path().join("sandbox_url.txt")).unwrap(),
            "http://127.0.0.1:8080"
        );
        let dependency_step = outcome
            .task_steps
            .iter()
            .find(|step| step.name == "sandbox")
            .expect("dependency step should be recorded");
        assert!(
            dependency_step
                .execution_note
                .as_deref()
                .is_some_and(|note| note.contains("target `api` declared `service(dev.http)`"))
        );
        let dependency_index = outcome
            .task_steps
            .iter()
            .position(|step| step.name == "sandbox")
            .expect("dependency step should have an index");
        assert_eq!(
            outcome.task_step_target_resolutions[dependency_index][0].target,
            "api"
        );
    }

    #[test]
    fn target_resolution_note_mentions_workspace_repo_service_identity() {
        let resolution = super::TaskTargetResolutionEvidence {
            target: String::from("api"),
            override_input: None,
            source: TaskTargetResolutionSource::TargetBinding,
            activation: None,
            service_ref: Some(super::TaskTargetResolutionServiceRef {
                member: None,
                repo: Some(String::from("billing")),
                task: String::from("dev"),
                listener: String::from("http"),
                address_view: crate::schema::TaskTargetAddressView::Host,
            }),
            url_ref: None,
            effective_url: String::from("http://127.0.0.1:8080"),
        };

        let note = super::render_target_resolution_note(&resolution);
        assert!(note.contains("service(billing:dev.http)"));
    }

