    #[test]
    fn native_service_run_fails_when_fixed_listener_bind_port_is_already_in_use() {
        let _guard = env_mutex_lock();
        let listener = TcpListener::bind("127.0.0.1:0").expect("reserve a local port");
        let listener_port = listener.local_addr().expect("listener addr").port();

        let fixture = ContractFixture::new(&format!(
            r#"
version: 1
project:
  name: ota
tasks:
  dev:
    run: node -e "setTimeout(() => process.exit(0), 100)"
    runtime:
      kind: service
      listeners:
        site:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: {listener_port}
"#
        ));

        let error = run_task_captured(&fixture.contract, fixture.file_path(), "dev")
            .expect_err("native run should fail when fixed listener bind port is occupied");

        match error {
            RunError::NativeListenerBindConflict {
                task,
                listener,
                address,
                port,
            } => {
                assert_eq!(task, "dev");
                assert_eq!(listener, "site");
                assert_eq!(address, "127.0.0.1");
                assert_eq!(port, listener_port);
            }
            other => panic!("expected native listener bind conflict, got {other}"),
        }
    }

    #[test]
    fn loader_labels_include_execution_class_not_runtime_identity() {
        assert_eq!(
            preparing_loader_label("test", Backend::Native),
            "Preparing test"
        );
        assert_eq!(
            preparing_loader_label("test", Backend::Container),
            "Preparing test (container)"
        );
        assert_eq!(
            preparing_loader_label("test", Backend::Remote),
            "Preparing test (remote)"
        );
        assert_eq!(
            running_loader_label_for_backend("test", Backend::Container),
            "Running test (container)"
        );
        assert_eq!(
            running_loader_label(
                "test",
                &ResolvedExecutionBackend::Container {
                    context_name: None,
                    shared_local_backend: None,
                    image: String::from("rust:1.94-bookworm"),
                    engine: String::from("docker"),
                    lifecycle: Lifecycle::Ephemeral,
                    memory_bytes: None,
                    compose_networks: Vec::new(),
                    publications: Vec::new(),
                    dependency_isolation_paths: Vec::new(),
                }
            ),
            "Running test (container)"
        );
        assert_eq!(
            running_loader_label(
                "test",
                &ResolvedExecutionBackend::Remote {
                    shared_local_backend: None,
                    provider: String::from("ssh"),
                    target: String::from("user@host"),
                    cwd: None,
                    ssh: None,
                }
            ),
            "Running test (remote)"
        );
        assert_eq!(
            activation_loader_label(
                TaskTargetActivationMode::EnsureReady,
                "dev",
                &RuntimeReadinessTarget::Http {
                    address: String::from("127.0.0.1"),
                    port: 8080,
                    request: HttpReadinessRequest {
                        method: TaskRuntimeReadinessHttpMethod::Get,
                        path: String::from("/actuator/health"),
                        headers: BTreeMap::new(),
                        success_statuses: vec![200],
                        body_contains: None,
                    },
                }
            ),
            "Waiting for dev to be ready"
        );
    }

    #[test]
    fn visible_output_detector_ignores_whitespace_and_ansi_only_chunks() {
        assert!(!super::buffer_contains_visible_output(b"\r\n\t"));
        assert!(!super::buffer_contains_visible_output(b"\x1b[2K\r"));
        assert!(super::buffer_contains_visible_output(b"$ cargo test\n"));
    }

    #[test]
    fn stream_phase_clear_sequence_resets_column_after_erasing_line() {
        assert_eq!(super::stream_phase_clear_sequence(), "\r\x1b[2K\x1b[1G");
    }

    #[test]
    fn http_readiness_response_requires_expected_body_when_declared() {
        let request = HttpReadinessRequest {
            method: TaskRuntimeReadinessHttpMethod::Get,
            path: String::from("/actuator/health"),
            headers: BTreeMap::new(),
            success_statuses: vec![200],
            body_contains: Some(String::from("\"status\":\"UP\"")),
        };

        assert!(
            super::response_matches_http_readiness(
                b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{\"status\":\"UP\"}",
                &request,
            )
            .is_ok()
        );
        assert!(
            super::response_matches_http_readiness(
                b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{\"status\":\"DOWN\"}",
                &request,
            )
            .is_err()
        );
    }

    #[test]
    fn http_readiness_response_accepts_declared_status_codes() {
        let request = HttpReadinessRequest {
            method: TaskRuntimeReadinessHttpMethod::Head,
            path: String::from("/ready"),
            headers: BTreeMap::new(),
            success_statuses: vec![200, 204],
            body_contains: None,
        };

        assert!(
            super::response_matches_http_readiness(b"HTTP/1.1 204 No Content\r\n\r\n", &request,)
                .is_ok()
        );
        assert!(
            super::response_matches_http_readiness(
                b"HTTP/1.1 503 Service Unavailable\r\n\r\n",
                &request,
            )
            .is_err()
        );
    }

    #[test]
    fn loopback_tcp_probe_tries_ipv6_for_ipv4_loopback_surface() {
        let listener = match TcpListener::bind("[::1]:0") {
            Ok(listener) => listener,
            Err(_) => return,
        };
        let port = listener
            .local_addr()
            .expect("listener address should resolve")
            .port();

        assert!(
            super::target_probe_endpoint_reachable_with_timeout(
                "127.0.0.1",
                port,
                Some(Duration::from_millis(300))
            ),
            "tcp readiness should accept a loopback service reachable only via ::1"
        );
    }

    #[test]
    fn runtime_readiness_targets_require_all_targets_to_be_ready() {
        let primary = TcpListener::bind(("127.0.0.1", 0)).expect("primary listener should bind");
        let primary_port = primary
            .local_addr()
            .expect("primary address should resolve")
            .port();
        let signal = TcpListener::bind(("127.0.0.1", 0)).expect("signal listener should bind");
        let signal_port = signal
            .local_addr()
            .expect("signal address should resolve")
            .port();

        let targets = vec![
            RuntimeReadinessTarget::Tcp {
                address: String::from("127.0.0.1"),
                port: primary_port,
            },
            RuntimeReadinessTarget::Tcp {
                address: String::from("127.0.0.1"),
                port: signal_port,
            },
        ];
        assert!(
            super::readiness_targets_observed_with_timeout(
                targets.as_slice(),
                Some(Duration::from_millis(100))
            ),
            "all readiness targets should be reachable while both listeners are active"
        );

        drop(signal);
        thread::sleep(Duration::from_millis(20));

        assert!(
            !super::readiness_targets_observed_with_timeout(
                targets.as_slice(),
                Some(Duration::from_millis(100))
            ),
            "readiness should fail when any signal target becomes unreachable"
        );
    }

    #[test]
    fn loopback_http_probe_tries_ipv6_for_ipv4_loopback_surface() {
        let listener = match TcpListener::bind("[::1]:0") {
            Ok(listener) => listener,
            Err(_) => return,
        };
        let port = listener
            .local_addr()
            .expect("listener address should resolve")
            .port();
        let server = thread::spawn(move || {
            if let Ok((mut stream, _)) = listener.accept() {
                let mut request = [0u8; 512];
                let _ = stream.read(&mut request);
                let _ = stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nOK");
            }
        });
        let request = HttpReadinessRequest {
            method: TaskRuntimeReadinessHttpMethod::Get,
            path: String::from("/"),
            headers: BTreeMap::new(),
            success_statuses: vec![200],
            body_contains: None,
        };
        let status = super::http_readiness_endpoint_status(
            "127.0.0.1",
            port,
            &request,
            Some(Duration::from_millis(400)),
        );
        server.join().expect("server thread should join");
        assert_eq!(status, super::HttpReadinessStatus::Passed);
    }

    #[test]
    fn primary_probe_candidate_keeps_declared_connect_timeout() {
        let base = Duration::from_millis(2_000);
        let timeout = super::probe_connect_timeout_for_candidate(base, 0);
        assert_eq!(timeout, base);
    }

    #[test]
    fn fallback_probe_candidates_use_capped_connect_timeout() {
        let timeout = super::probe_connect_timeout_for_candidate(Duration::from_secs(5), 1);
        assert_eq!(timeout, Duration::from_millis(300));
        let timeout_small =
            super::probe_connect_timeout_for_candidate(Duration::from_millis(200), 2);
        assert_eq!(timeout_small, Duration::from_millis(200));
    }

