    #[test]
    fn reruns_after_success_tasks_even_if_completed_as_dependencies() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota-site
tasks:
  setup:
    script: |
      echo setup >> run.log
  build:
    depends_on:
      - setup
    after_success:
      - discoverability:check
    script: |
      echo build >> run.log
  typecheck:
    depends_on:
      - setup
    script: |
      echo typecheck >> run.log
  deadcode:
    depends_on:
      - setup
    script: |
      echo deadcode >> run.log
  discoverability:check:
    depends_on:
      - setup
    script: |
      echo discoverability >> run.log
  ci:
    depends_on:
      - build
      - typecheck
      - deadcode
      - discoverability:check
    script: |
      echo ci >> run.log
  version:bump:
    inputs:
      version:
        default: patch
    run: echo version-bump >> run.log
    depends_on: [ ci, deadcode ]
    after_success:
      - build
"#,
        );

        let outcome = run_task_with_args(
            &fixture.contract,
            fixture.file_path(),
            "version:bump",
            &[String::from("--version"), String::from("patch")],
        )
        .unwrap();

        assert_eq!(outcome.exit_code, 0);
        assert_eq!(
            fs::read_to_string(fixture.dir.path().join("run.log"))
                .unwrap()
                .lines()
                .collect::<Vec<_>>(),
            vec![
                "setup",
                "build",
                "discoverability",
                "typecheck",
                "deadcode",
                "ci",
                "version-bump",
                "setup",
                "build",
                "discoverability",
            ]
        );
        assert_eq!(
            outcome.executed_tasks,
            vec![
                String::from("setup"),
                String::from("build"),
                String::from("discoverability:check"),
                String::from("typecheck"),
                String::from("deadcode"),
                String::from("ci"),
                String::from("version:bump"),
                String::from("setup"),
                String::from("build"),
                String::from("discoverability:check"),
            ]
        );
    }

