    #[cfg(unix)]
    #[test]
    fn clean_execution_discovers_repo_owned_persistent_container_created_with_host_port_override() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/test:latest
tasks:
  dev:
    context: app
    run: printf ready >> prepared.txt
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 3000
              path: /
"#,
        );
        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let docker_path = bin_dir.join("docker");
        install_fake_docker(&docker_path);
        let mut permissions = fs::metadata(&docker_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker_path, permissions).unwrap();

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let _ = run_task_with_overrides(
            &fixture.contract,
            fixture.file_path(),
            "dev",
            ExecutionOverrides {
                host_port: Some(4000),
                ..ExecutionOverrides::default()
            },
        )
        .unwrap();

        let state_dir = bin_dir.join("docker-state");
        assert!(
            fs::read_dir(&state_dir)
                .unwrap()
                .filter_map(Result::ok)
                .any(|entry| entry.file_name().to_string_lossy().ends_with(".path"))
        );

        let cleaned = clean_execution(&fixture.contract, fixture.file_path()).unwrap();

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert!(cleaned);
        assert!(
            !fs::read_dir(&state_dir)
                .unwrap()
                .filter_map(Result::ok)
                .any(|entry| entry.file_name().to_string_lossy().ends_with(".path"))
        );
    }

    #[cfg(unix)]
    #[test]
    fn cleans_container_dependency_isolation_volumes_for_named_context() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/test:latest
      attachments:
        isolated_paths:
          - node_modules
tasks:
  build:
    context: app
    run: printf ready >> prepared.txt
"#,
        );
        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let docker_path = bin_dir.join("docker");
        install_fake_docker(&docker_path);
        let mut permissions = fs::metadata(&docker_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker_path, permissions).unwrap();

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let _ = run_task(&fixture.contract, fixture.file_path(), "build").unwrap();

        let mounts = fs::read_to_string(fixture.dir.path().join("docker-mounts.txt")).unwrap();
        let volume_mount = mounts
            .lines()
            .find(|line| line.ends_with(":/workspace/node_modules"))
            .expect("isolated dependency volume mount should exist");
        let volume_name = volume_mount
            .split_once(':')
            .expect("mount should include source and target")
            .0
            .to_string();
        let state_dir = bin_dir.join("docker-state");
        let volume_marker = state_dir.join(format!("volume.{volume_name}"));
        assert!(volume_marker.exists());
        if super::container_host_user_spec().is_some() {
            let volume_log = fs::read_to_string(state_dir.join("volume-log.txt")).unwrap();
            assert!(
                volume_log.contains("volume-prep"),
                "dependency isolation volume should be ownership-prepared before task startup: {volume_log}"
            );
            assert!(
                volume_log.contains(":/workspace/node_modules"),
                "dependency isolation volume prep should target the container mount path: {volume_log}"
            );
        }

        let cleaned = clean_execution(&fixture.contract, fixture.file_path()).unwrap();

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert!(cleaned);
        assert!(!volume_marker.exists());
    }

