    #[cfg(unix)]
    #[test]
    fn clean_execution_report_classifies_engine_unavailable_failures() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/test:latest
        engines:
          - podman
      attachments:
        isolated_paths:
          - node_modules
tasks:
  build:
    context: app
    run: printf ready >> prepared.txt
"#,
        );
        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let podman_path = bin_dir.join("podman");
        fs::write(
            &podman_path,
            r#"#!/bin/sh
if [ "$1" = "volume" ] && [ "$2" = "ls" ]; then
  echo "Cannot connect to Podman" >&2
  echo "Error: unable to connect to Podman socket: dial tcp 127.0.0.1:57990: connect: connection refused" >&2
  exit 125
fi
exit 0
"#,
        )
        .unwrap();
        let mut permissions = fs::metadata(&podman_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&podman_path, permissions).unwrap();

        let ota_dir = fixture.dir.path().join(".ota");
        fs::create_dir_all(&ota_dir).unwrap();
        fs::create_dir_all(ota_dir.join("state")).unwrap();
        fs::write(ota_dir.join("state").join("ownership-id"), "repo-1").unwrap();

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let error = clean_execution_report(&fixture.contract, fixture.file_path()).unwrap_err();

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        match error {
            super::CleanExecutionError::Cleanup(failure) => {
                assert_eq!(failure.engine, "podman");
                assert_eq!(failure.action, "list");
                assert_eq!(
                    failure.resource_kind,
                    super::CleanExecutionResourceKind::DependencyIsolationVolume
                );
                assert_eq!(
                    failure.reason,
                    super::CleanExecutionFailureReason::EngineUnavailable
                );
                assert!(failure.details.contains("connection refused"));
            }
            other => panic!("expected structured cleanup failure, got {other}"),
        }
    }

    #[test]
    fn classify_clean_execution_failure_reason_matches_windows_docker_pipe_errors() {
        let details = "failed to connect to the docker API at npipe:////./pipe/docker_engine; check if the path is correct and if the daemon is running: open //./pipe/docker_engine: The system cannot find the file specified.";
        assert_eq!(
            super::classify_clean_execution_failure_reason(details),
            super::CleanExecutionFailureReason::EngineUnavailable
        );
    }

    #[test]
    fn clean_execution_scope_for_workflow_excludes_unselected_container_contexts() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: persistent
      container:
        image: node:22-bookworm
        engines:
          - docker
tasks:
  dev:
    context: host
    run: echo host
  dev:app:
    context: app
    run: echo app
workflows:
  default: instant
  instant:
    run:
      task: dev
  app:
    run:
      task: dev:app
"#,
        );

        let scope =
            super::persistent_cleanup_scope_for_workflow(&fixture.contract, Some("instant"));
        assert!(
            !scope.context_names.contains("app"),
            "host-only workflow scope must not include unrelated container context"
        );
        assert!(scope.shared_backend_names.is_empty());

        let app_scope =
            super::persistent_cleanup_scope_for_workflow(&fixture.contract, Some("app"));
        assert!(app_scope.context_names.contains("app"));
    }

