    fn fulfills_direct_ephemeral_container_context_requirements_on_run_path() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: tooling
  contexts:
    tooling:
      backend: container
      lifecycle: ephemeral
      fulfillment: run
      container:
        image: ghcr.io/ota/test:latest
      requirements:
        tools:
          yq: "4.52.5"
tasks:
  test:
    context: tooling
    run: yq --version > fulfilled.txt
"#,
        );
        fixture.write(
            ".ota/org-policy.yaml",
            r#"
policies:
  version_policy:
    tools:
      yq:
        approved_versions:
          - "4.52.5"
  provisioning:
    yq:
      source: apt
      package: yq
      approved_versions:
        - "4.52.5"
      platforms:
        linux:
          source: apt
          package: yq
          approved_versions:
            - "4.52.5"
"#,
        );

        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let docker_path = bin_dir.join("docker");
        install_fake_docker(&docker_path);
        let yq_path = bin_dir.join("yq");
        fs::write(
            &yq_path,
            r#"#!/bin/sh
printf "yq 4.52.5\n"
"#,
        )
        .unwrap();
        let apt_get_path = bin_dir.join("apt-get");
        fs::write(
            &apt_get_path,
            format!(
                r#"#!/bin/sh
printf "apt-get %s\n" "$*" >> "{log}"
if printf "%s" "$*" | grep -q "install -y yq"; then
  cat > "{bin}/yq" <<'EOF'
#!/bin/sh
printf "yq 4.52.5\n"
EOF
  chmod +x "{bin}/yq"
fi
exit 0
"#,
                log = fixture.dir.path().join("apt-log.txt").display(),
                bin = bin_dir.display(),
            ),
        )
        .unwrap();
        for path in [&docker_path, &yq_path, &apt_get_path] {
            let mut permissions = fs::metadata(path).unwrap().permissions();
            permissions.set_mode(0o755);
            fs::set_permissions(path, permissions).unwrap();
        }

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let outcome = run_task(&fixture.contract, fixture.file_path(), "test").unwrap();

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert_eq!(outcome.exit_code, 0);
        let fulfillment_result = outcome
            .backend_fulfillment
            .as_ref()
            .map(|evidence| evidence.result);
        assert!(matches!(
            fulfillment_result,
            Some(
                super::BackendFulfillmentResult::Fulfilled
                    | super::BackendFulfillmentResult::RequirementsSatisfied
            )
        ));
        let fulfilled = fs::read_to_string(fixture.dir.path().join("fulfilled.txt")).unwrap();
        assert!(
            fulfilled.contains("4.52.5"),
            "fulfilled backend version output should include the expected version, got {fulfilled:?}"
        );
        if matches!(
            fulfillment_result,
            Some(super::BackendFulfillmentResult::Fulfilled)
        ) {
            let apt_log = fs::read_to_string(fixture.dir.path().join("apt-log.txt")).unwrap();
            assert!(
                apt_log.contains("install -y yq"),
                "fulfilled run path should install yq via apt, got {apt_log:?}"
            );
        } else {
            assert!(
                !fixture.dir.path().join("apt-log.txt").exists(),
                "requirements-satisfied path should not invoke apt-get"
            );
        }
        let docker_log = fs::read_to_string(fixture.dir.path().join("docker-log.txt")).unwrap();
        assert!(docker_log.contains("start\n"));
        assert!(docker_log.contains("rm\n"));
    }

