    #[test]
    fn reset_compose_service_volume_action_resets_volume_and_restarts_service() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
tasks:
  postgres:reset:
    action:
      kind: reset_compose_service_volume
      service: postgres
      volume: app_postgres-data
      compose:
        files:
          - docker-compose.yml
        project_name: app
"#,
        );

        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let state_dir = fixture.dir.path().join("docker-state");
        fs::create_dir_all(&state_dir).unwrap();
        let docker_path = bin_dir.join("docker");
        fs::write(
            &docker_path,
            format!(
                r#"#!/bin/sh
state_dir="{state_dir}"
mkdir -p "$state_dir"

if [ "$1" = "compose" ] && [ "$2" = "stop" ]; then
  if [ -f "$state_dir/running.$3" ]; then
    rm -f "$state_dir/running.$3"
    exit 0
  fi
  exit 1
fi

if [ "$1" = "compose" ] && [ "$2" = "rm" ] && [ "$3" = "-f" ]; then
  rm -f "$state_dir/container.$4"
  exit 0
fi

if [ "$1" = "compose" ] && [ "$2" = "ps" ] && [ "$3" = "-aq" ]; then
  if [ -f "$state_dir/container.$4" ]; then
    printf '%s\n' "$4-container"
  fi
  exit 0
fi

if [ "$1" = "compose" ] && [ "$2" = "up" ] && [ "$3" = "-d" ]; then
  : > "$state_dir/running.$4"
  : > "$state_dir/container.$4"
  exit 0
fi

if [ "$1" = "container" ] && [ "$2" = "rm" ] && [ "$3" = "-f" ]; then
  rm -f "$state_dir/container.postgres"
  exit 0
fi

if [ "$1" = "ps" ] && [ "$2" = "-aq" ] && [ "$3" = "--filter" ] && [ "$4" = "volume=app_postgres-data" ]; then
  if [ -f "$state_dir/container.postgres" ]; then
    printf '%s\n' "postgres-container"
  fi
  exit 0
fi

if [ "$1" = "volume" ] && [ "$2" = "inspect" ]; then
  if [ -f "$state_dir/volume.$3" ]; then
    exit 0
  fi
  exit 1
fi

if [ "$1" = "volume" ] && [ "$2" = "rm" ] && [ "$3" = "-f" ]; then
  rm -f "$state_dir/volume.$4"
  exit 0
fi

exit 1
"#,
                state_dir = state_dir.display()
            ),
        )
        .unwrap();
        let mut permissions = fs::metadata(&docker_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker_path, permissions).unwrap();
        fs::write(state_dir.join("running.postgres"), "").unwrap();
        fs::write(state_dir.join("container.postgres"), "").unwrap();
        fs::write(state_dir.join("volume.app_postgres-data"), "").unwrap();

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let first = run_task(&fixture.contract, fixture.file_path(), "postgres:reset")
            .expect("reset_compose_service_volume action should run");
        let second = run_task(&fixture.contract, fixture.file_path(), "postgres:reset")
            .expect("reset_compose_service_volume action should stay repeatable");

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert_eq!(first.exit_code, 0);
        assert!(
            first.stdout.contains("stop compose service `postgres`"),
            "{}",
            first.stdout
        );
        assert!(
            first
                .stdout
                .contains("removed docker volume `app_postgres-data`"),
            "{}",
            first.stdout
        );
        assert!(
            first
                .stdout
                .contains("restarted docker compose service `postgres`"),
            "{}",
            first.stdout
        );
        assert!(state_dir.join("running.postgres").is_file());
        assert!(state_dir.join("container.postgres").is_file());
        assert!(!state_dir.join("volume.app_postgres-data").exists());
        assert_eq!(second.exit_code, 0);
        assert!(
            second
                .stdout
                .contains("docker volume `app_postgres-data` was absent; no volume remove needed"),
            "{}",
            second.stdout
        );
    }

    #[test]
    fn reset_compose_service_volume_action_removes_leftover_service_container_before_volume_reset()
    {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
tasks:
  postgres:reset:
    action:
      kind: reset_compose_service_volume
      service: postgres
      volume: app_postgres-data
      compose:
        files:
          - docker-compose.yml
        project_name: app
"#,
        );

        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let state_dir = fixture.dir.path().join("docker-state");
        fs::create_dir_all(&state_dir).unwrap();
        let docker_path = bin_dir.join("docker");
        fs::write(
            &docker_path,
            format!(
                r#"#!/bin/sh
state_dir="{state_dir}"
mkdir -p "$state_dir"

if [ "$1" = "compose" ] && [ "$2" = "stop" ]; then
  rm -f "$state_dir/running.$3"
  exit 0
fi

if [ "$1" = "compose" ] && [ "$2" = "rm" ] && [ "$3" = "-f" ]; then
  # Simulate compose reporting success while leaving the stopped container behind.
  exit 0
fi

if [ "$1" = "compose" ] && [ "$2" = "ps" ] && [ "$3" = "-aq" ]; then
  if [ -f "$state_dir/container.$4" ]; then
    printf '%s\n' "$4-container"
  fi
  exit 0
fi

if [ "$1" = "container" ] && [ "$2" = "rm" ] && [ "$3" = "-f" ]; then
  rm -f "$state_dir/container.postgres"
  exit 0
fi

if [ "$1" = "ps" ] && [ "$2" = "-aq" ] && [ "$3" = "--filter" ] && [ "$4" = "volume=app_postgres-data" ]; then
  exit 0
fi

if [ "$1" = "compose" ] && [ "$2" = "up" ] && [ "$3" = "-d" ]; then
  : > "$state_dir/running.$4"
  : > "$state_dir/container.$4"
  exit 0
fi

if [ "$1" = "volume" ] && [ "$2" = "inspect" ]; then
  if [ -f "$state_dir/volume.$3" ]; then
    exit 0
  fi
  exit 1
fi

if [ "$1" = "volume" ] && [ "$2" = "rm" ] && [ "$3" = "-f" ]; then
  if [ -f "$state_dir/container.postgres" ]; then
    echo "volume still attached" >&2
    exit 1
  fi
  rm -f "$state_dir/volume.$4"
  exit 0
fi

exit 1
"#,
                state_dir = state_dir.display()
            ),
        )
        .unwrap();
        let mut permissions = fs::metadata(&docker_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker_path, permissions).unwrap();
        fs::write(state_dir.join("running.postgres"), "").unwrap();
        fs::write(state_dir.join("container.postgres"), "").unwrap();
        fs::write(state_dir.join("volume.app_postgres-data"), "").unwrap();

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let result = run_task(&fixture.contract, fixture.file_path(), "postgres:reset").expect(
            "reset_compose_service_volume should remove leftover containers before volume reset",
        );

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert_eq!(result.exit_code, 0);
        assert!(
            result
                .stdout
                .contains("removed remaining docker compose service containers for `postgres`: postgres-container"),
            "{}",
            result.stdout
        );
        assert!(!state_dir.join("volume.app_postgres-data").exists());
    }

