    #[test]
    fn run_path_toolchain_fulfillment_runs_rustup_once_per_backend() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
toolchains:
  rust:
    provider: rustup
    version: "1.94.0"
    components:
      - rustfmt
    fulfillment: run
tasks:
  setup:
    requirements:
      toolchains:
        - rust
    run: cargo fetch
"#,
        );
        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let log_path = fixture.dir.path().join("rustup.log");
        let rustup_body = if cfg!(windows) {
            format!(
                "@echo off\r\necho %*>>\"{}\"\r\nexit /b 0\r\n",
                log_path.display()
            )
        } else {
            format!(
                "#!/bin/sh\nprintf '%s\\n' \"$*\" >> '{}'\nexit 0\n",
                log_path.display()
            )
        };
        write_fake_bin(&bin_dir, "rustup", &rustup_body);

        let original_path = env::var_os("PATH");
        let path_entries = vec![bin_dir.clone()];
        unsafe {
            env::set_var("PATH", env::join_paths(path_entries).unwrap());
        }

        let backend = ResolvedExecutionBackend::Native {
            shared_local_backend: None,
        };
        let mut state = TaskRunState::default();
        let first_result = super::maybe_fulfill_toolchains_on_run_path(
            &fixture.contract,
            fixture.file_path(),
            "setup",
            fixture.contract.tasks.get("setup").unwrap(),
            &backend,
            &BTreeMap::new(),
            TaskExecutionMode::Capture,
            current_os(),
            &mut state,
        );
        if let Err(error) = first_result {
            let message = error.to_string();
            // With direct exec (NativeCommand), binary not found produces SpawnFailed.
            // With shell fallback, binary not found produces exit code 127.
            assert!(
                message.contains("`'rustup' 'toolchain' 'install' '1.94.0' '--component' 'rustfmt'` exited with code 127")
                    || message.contains("failed to start task `toolchain-fulfill:rust`"),
                "{message}"
            );
            match original_path {
                Some(path) => unsafe {
                    env::set_var("PATH", path);
                },
                None => unsafe {
                    env::remove_var("PATH");
                },
            }
            return;
        }
        super::maybe_fulfill_toolchains_on_run_path(
            &fixture.contract,
            fixture.file_path(),
            "setup",
            fixture.contract.tasks.get("setup").unwrap(),
            &backend,
            &BTreeMap::new(),
            TaskExecutionMode::Capture,
            current_os(),
            &mut state,
        )
        .unwrap();

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        let output = fs::read_to_string(&log_path).unwrap();
        let lines = output.lines().collect::<Vec<_>>();
        assert_eq!(lines.len(), 1, "{output}");
        assert!(lines[0].contains("toolchain install 1.94.0"), "{output}");
        assert!(lines[0].contains("--component rustfmt"), "{output}");
        let fulfilled = state
            .fulfilled_toolchains
            .get("rust")
            .expect("fulfilled toolchain commands should be recorded");
        assert_eq!(fulfilled.len(), 1, "{fulfilled:?}");
        assert!(
            fulfilled[0].contains("'toolchain' 'install' '1.94.0'"),
            "{fulfilled:?}"
        );
        assert!(
            fulfilled[0].contains("'--component' 'rustfmt'"),
            "{fulfilled:?}"
        );
    }

    #[test]
    fn run_path_toolchain_fulfillment_uses_backend_target_os_for_container() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
toolchains:
  rust:
    provider: rustup
    version: "1.94.0"
    only_on:
      - linux
    platforms:
      linux:
        version: "1.94.1"
        components:
          - rustfmt
    fulfillment: run
tasks:
  setup:
    run: cargo fetch
"#,
        );
        let backend = ResolvedExecutionBackend::Container {
            context_name: None,
            shared_local_backend: None,
            image: String::from("rust:1.94-bookworm"),
            engine: String::from("docker"),
            lifecycle: Lifecycle::Ephemeral,
            memory_bytes: None,
            compose_networks: Vec::new(),
            publications: Vec::new(),
            dependency_isolation_paths: Vec::new(),
        };
        let toolchain = fixture.contract.toolchains.get("rust").unwrap();
        let target_os = super::target_os_for_toolchain_backend(&backend, "windows");

        assert_eq!(target_os, "linux");
        assert!(toolchain.active_for_os(target_os));
        let commands =
            super::toolchain_fulfillment_commands("rust", toolchain, target_os, &backend);
        assert_eq!(commands.len(), 1);
        assert!(commands[0].contains("1.94.1"));
        assert!(!commands[0].contains("1.94.0"));
        assert!(commands[0].contains("rustfmt"));
    }

